# `texture_id` carries the same RenderDoc ResourceId, so it loses the same precision
# on a JavaScript client; tool_scope treats both as resource-id fields already.
_RESOURCE_ID_PARAMETER = re.compile(r"(^|_)(resource|texture)_id$")


def _coerce_transport_resource_id(value: Any, name: str, optional: bool) -> Any:
    """RenderDoc ResourceIds are ~1e18: JavaScript clients lose precision on them.

    Cursor/Node serialise ``1000000000000000755`` as ``1000000000000000800``
    (IEEE-754 double).  Accept the same value as a decimal string so agents
    can pass it losslessly, and keep plain integers working.
    """

    if value is None:
        if optional:
            return None
        raise ValueError("%s is required" % name)
    if isinstance(value, bool):
        raise ValueError("%s must be an integer or a decimal string" % name)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if value.is_integer() and abs(value) < 2 ** 53:
            return int(value)
        raise ValueError("%s lost precision as a float; pass it as a decimal string" % name)
    if isinstance(value, str):
        text = value.strip()
        if text.lower().startswith("resourceid::"):
            text = text[len("resourceid::"):]
        if not text:
            if optional:
                return None
            raise ValueError("%s is required" % name)
        if not text.isdigit() or len(text) > 24:
            raise ValueError("%s must be a decimal integer (as int or string)" % name)
        return int(text)
    raise ValueError("%s must be an integer or a decimal string" % name)


def _accept_string_resource_ids(function: Any) -> Any:
    """Widen every ``*resource_id`` tool parameter from int to int|str (see above)."""

    import functools
    import inspect
    import typing

    try:
        signature = inspect.signature(function)
    except (TypeError, ValueError):
        return function
    # Instrumentation wrappers live in other modules. Resolve postponed types
    # against the original declaration before detaching __wrapped__, otherwise a
    # mixed ResourceId/Literal signature is evaluated in the wrapper's namespace.
    resolved = typing.get_type_hints(inspect.unwrap(function))
    signature = signature.replace(
        parameters=[p.replace(annotation=resolved.get(name, p.annotation))
                    for name, p in signature.parameters.items()],
        return_annotation=resolved.get('return', signature.return_annotation))
    targets: dict[str, bool] = {}
    parameters = []
    for name, parameter in signature.parameters.items():
        annotation = parameter.annotation
        text = annotation if isinstance(annotation, str) else getattr(annotation, "__name__", repr(annotation))
        is_int = annotation is int or text == "int"
        is_optional_int = text in ("int | None", "Optional[int]") or (
            not isinstance(annotation, str) and repr(annotation) in ("int | None", "typing.Optional[int]"))
        if _RESOURCE_ID_PARAMETER.search(name) and (is_int or is_optional_int):
            optional = is_optional_int or parameter.default is None
            targets[name] = optional
            parameters.append(parameter.replace(annotation=int | str | None if optional else int | str))
        else:
            parameters.append(parameter)
    if not targets:
        return function

    def _coerce_bound_args(args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
        bound = signature.bind_partial(*args, **kwargs)
        for name, optional in targets.items():
            if name in bound.arguments:
                bound.arguments[name] = _coerce_transport_resource_id(bound.arguments[name], name, optional)
        return bound

    def _finish_wrapper(wrapper: Any) -> Any:
        wrapper.__signature__ = signature.replace(parameters=parameters)  # type: ignore[attr-defined]
        annotations = dict(resolved)
        for name, optional in targets.items():
            annotations[name] = int | str | None if optional else int | str
        wrapper.__annotations__ = annotations
        # FastMCP must see the widened signature, not follow __wrapped__ to the original.
        del wrapper.__wrapped__
        wrapper.__replaylab_inner__ = function  # type: ignore[attr-defined]
        return wrapper

    if inspect.iscoroutinefunction(function):

        @functools.wraps(function)
        async def async_wrapper(*args: Any, **kwargs: Any) -> Any:
            bound = _coerce_bound_args(args, kwargs)
            return await function(*bound.args, **bound.kwargs)

        return _finish_wrapper(async_wrapper)

    @functools.wraps(function)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        bound = _coerce_bound_args(args, kwargs)
        return function(*bound.args, **bound.kwargs)

    return _finish_wrapper(wrapper)



def _ok(d: Any) -> str:
    # MCP tool results are JSON embedded inside the outer stdio JSON-RPC
    # document. Keep that inner machine string ASCII-only so a legacy Windows
    # stdio intermediary cannot reinterpret Chinese paths using an ANSI code
    # page; consumers recover the exact Unicode value with json.loads().
    return json.dumps(d, ensure_ascii=True, default=str)

def _err(e: Exception) -> str:
    body = {"error": str(e), "type": type(e).__name__}
    timing = getattr(e, "shader_start_timing", None)
    if isinstance(timing, Mapping):
        body["data"] = {"startTiming": dict(timing)}
    return json.dumps(
        body,
        ensure_ascii=True,
        default=str,
    )


def _is_lower_hex_value(value: Any, length: int) -> bool:
    text = str(value or "")
    return (
        len(text) == length
        and all(character in "0123456789abcdef" for character in text)
    )


def _shader_err(error: Exception, phase: str) -> str:
    """Return backward-compatible error text plus a stable recovery category."""

    body = {
        "error": str(error),
        "type": type(error).__name__,
        "diagnostic": classify_shader_failure(error, phase=phase),
    }
    explanation = getattr(error, "abi_explanation", None)
    if isinstance(explanation, Mapping):
        # Where the ABI failed, why, and the HLSL change per finding — the
        # input the repair channel expects.
        body["abiExplanation"] = explanation
        body["whatToFix"] = [
            {"where": item.get("identity"), "why": item.get("message"),
             "how": item.get("hint")}
            for item in (explanation.get("findings") or [])
        ]
    return json.dumps(body, ensure_ascii=True, default=str)

def _scoped_capture_session_id() -> str:
    try:
        scope = json.loads(os.environ.get("REPLAYLAB_TOOL_SCOPE", "") or "{}")
    except (TypeError, ValueError):
        return ""
    value = str(scope.get("capture_session_id", "") or "").strip().lower()
    if len(value) != 32 or any(character not in "0123456789abcdef" for character in value):
        return ""
    return value


_SCOPED_CAPTURE_SESSION_ID = _scoped_capture_session_id()


def _effective_capture_scope_session_id() -> str:
    # Verified replay recovery/open receipts can advance a task-owned IPC
    # session. Keep helper checks aligned with that binding; never rediscover
    # the user's current capture to update it.
    from .ipc_client import _CALL_BINDING
    direct = _CALL_BINDING.get()
    if direct is not None:
        return direct[1]
    return getattr(ipc, "capture_session_id", "") or _SCOPED_CAPTURE_SESSION_ID


def _call(method: str, params: dict = None, timeout: float = None) -> str:
    try:
        payload = dict(params or {})
        session = _effective_capture_scope_session_id()
        if session:
            # Host-owned field, absent from every model-visible MCP schema.
            payload["__replaylab_expected_capture_session_id"] = (
                session
            )
        return _ok(ipc.call(method, payload, timeout=timeout))
    except Exception as e:
        return _err(e)


def _file_sha256(path: str | Path) -> str:
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _bounded_file_sha256(path: str | Path, maximum_bytes: int, label: str) -> str:
    """Hash one regular file without allowing a post-stat growth to go unbounded."""

    target = Path(path)
    before = target.stat()
    if before.st_size <= 0 or before.st_size > maximum_bytes:
        raise RuntimeError("%s size is invalid" % label)
    digest = hashlib.sha256()
    total = 0
    with target.open("rb") as stream:
        while True:
            chunk = stream.read(min(1024 * 1024, maximum_bytes + 1 - total))
            if not chunk:
                break
            total += len(chunk)
            if total > maximum_bytes:
                raise RuntimeError("%s exceeds its size limit" % label)
            digest.update(chunk)
    after = target.stat()
    if (
        total != before.st_size
        or after.st_size != before.st_size
        or after.st_mtime_ns != before.st_mtime_ns
    ):
        raise RuntimeError("%s changed while it was hashed" % label)
    return digest.hexdigest()


