def reverse_shader(event_id: int, stage: str = "fragment") -> str:
    """Inspect a shader using RenderDoc reflection, disassembly, bindings, and live cbuffer values.

    RenderDoc may expose embedded source or a high-level disassembly target, but
    this tool does not guarantee HLSL/GLSL decompilation. Use
    prepare_shader_workspace with a configured external decompiler when an
    editable source workflow is required.

    Args:
        event_id: The event ID of the draw call.
        stage: Shader stage - "vertex", "fragment"/"pixel", "geometry", "compute", "hull"/"tess_ctrl", "domain"/"tess_eval".
    """
    return _call("reverse_shader", {"event_id": event_id, "stage": stage})


@mcp.tool()
def get_current_shader_representation(event_id: int, stage: str = "fragment",
                                      text_mode: str = "preferred",
                                      include_raw_bytes: bool = False) -> str:
    """Read Shader source/instructions for explaining an event or frame, without editing.

    Unlike the DXBC/DXIL executable workspace, this tool needs no capture
    catalog and therefore also covers Vulkan SPIR-V, OpenGL GLSL/program
    binaries, and other formats that RenderDoc can reflect/disassemble. It
    writes only below the process-owned representation root. It never creates a
    Shader Workspace, invokes an external decompiler, compiles, or applies a Shader.
    Use this route for pass/algorithm investigation, including when editable HLSL
    reconstruction is unsupported. Do not prepare/decompile a workspace just to
    explain a frame. Embedded source
    and RenderDoc disassembly are explanatory-ir; if neither exists, it writes
    binary-only identity/hash diagnostics. No result is compile/apply eligible.

    The default text_mode='preferred' reads embedded source when present,
    otherwise the first usable portable RenderDoc disassembly, avoiding duplicate
    hardware ISA. 'all' explicitly requests all available targets. The result
    includes a bounded textPreview and section byte offsets; read the same path
    with read_evidence_file to continue, without replaying the event or preparing
    an editable workspace. include_raw_bytes exports hash-verified binary bytes
    only when explicitly requested; text analysis does not need a Shader catalog.
    """

    try:
        event_value = int(event_id)
        if event_value <= 0:
            raise ValueError("event_id must be a positive integer")
        if not str(stage or "").strip():
            raise ValueError("stage is required")
        if text_mode not in ("preferred", "all"):
            raise ValueError("text_mode must be preferred or all")
        if not isinstance(include_raw_bytes, bool):
            raise ValueError("include_raw_bytes must be boolean")
        response = ipc.call(
            "reverse_shader",
            {"event_id": event_value, "stage": stage, "text_mode": text_mode},
            timeout=300.0,
        )
        if not isinstance(response, dict):
            raise RuntimeError("RenderDoc bridge returned an invalid reverse_shader result")
        raw_bytes, raw_bytes_diagnostic = None, None
        if include_raw_bytes:
            try:
                raw_bytes, raw_bytes_diagnostic = _export_current_shader_raw_bytes(
                    event_value, stage, response
                )
            except Exception as error:
                raw_bytes_diagnostic = {
                    "code": "raw-bytes-export-failed", "message": str(error),
                }
        try:
            capture_status = ipc.call("get_capture_status", {}, timeout=30.0)
        except Exception as error:
            capture_status = {"statusUnavailable": str(error)}
        if not isinstance(capture_status, dict):
            capture_status = {"statusUnavailable": "invalid bridge response"}
        result = publish_current_event_representation(
            _SHADER_REPRESENTATIONS_ROOT,
            event_id=event_value,
            requested_stage=stage,
            bridge_response=response,
            capture_status=capture_status,
            raw_bytes=raw_bytes,
            raw_bytes_diagnostic=raw_bytes_diagnostic,
        )
        return _ok(result)
    except Exception as error:
        return _err(error)

def _read_event_id_or_current(event_id: int | None, *, field: str = "event_id") -> int:
    """Resolve an optional read-only EID from the current RenderDoc selection.

    Read-only inspection tools should not fail merely because an Agent omitted an
    EID that is already unambiguous in qrenderdoc.  Mutation/publication tools do
    not use this fallback: they continue to require an explicit, current physical
    target and perform their own compare-and-swap checks.
    """

    if event_id not in (None, 0, ""):
        if isinstance(event_id, bool):
            raise ValueError("%s must be a positive integer" % field)
        try:
            value = int(event_id)
        except (TypeError, ValueError) as exc:
            raise ValueError("%s must be a positive integer" % field) from exc
        if value <= 0:
            raise ValueError("%s must be a positive integer" % field)
        return value

    context = _active_live_context(
        allow_missing_capture_id=True,
        require_event_state=True,
    )
    events = context.get("events")
    events = events if isinstance(events, Mapping) else {}
    for key in ("selectedEventId", "currentEventId"):
        candidate = events.get(key)
        if isinstance(candidate, bool):
            continue
        try:
            value = int(candidate or 0)
        except (TypeError, ValueError):
            continue
        if value > 0:
            return value
    raise ValueError(
        "%s was omitted and RenderDoc has no positive selected/current event" % field
    )


@mcp.tool()
def get_bound_textures(event_id: int | None = None, stage: str = "fragment") -> str:
    """Get textures bound to a shader stage plus explicitly uncertain role hints.

    For each texture slot, shows shader variable name, actual bound texture,
    and a low-confidence name/slot-based role inference (albedo, normal,
    roughness, metallic, ao, emissive, etc.). Treat ``roleInference`` as a hint,
    never as capture evidence or a verified material semantic.

    Args:
        event_id: The event ID of the draw call. When omitted, this read-only
            tool uses RenderDoc's current selected event.
        stage: Shader stage - "vertex", "fragment"/"pixel", "geometry", "compute", "hull"/"tess_ctrl", "domain"/"tess_eval".
    """
    try:
        resolved_event_id = _read_event_id_or_current(event_id)
        return _call(
            "get_bound_textures",
            {"event_id": resolved_event_id, "stage": stage},
        )
    except Exception as error:
        return _err(error)


# ==================== 6. SEARCH ====================

@mcp.tool()
def find_draws_by_shader(shader_name: str, stage: str = "") -> str:
    """Find all draw calls that use a shader with the given name (partial match).

    Useful for finding which draw calls render a specific material/effect.

    Args:
        shader_name: Partial shader name to search for.
        stage: Optional stage filter ("vertex", "fragment", etc.).
    """
    params = {"shader_name": shader_name}
    if stage: params["stage"] = stage
    return _call("find_by_shader", params)

@mcp.tool()
def find_draws_by_texture(texture_name: str) -> str:
    """Find all draw calls that use a texture with the given name (partial match).

    Useful for finding which draw calls use a specific texture (e.g. "eye").

    Args:
        texture_name: Partial texture name to search for (e.g. "eye", "skin", "hair").
    """
    return _call("find_by_texture", {"texture_name": texture_name})

@mcp.tool()
def find_draws_by_resource(resource_id: int) -> str:
    """Find all draw calls that use a specific resource ID.

    Args:
        resource_id: The exact resource ID to search for.
    """
    return _call("find_by_resource", {"resource_id": resource_id})


# ==================== 7. RESOURCES ====================

@mcp.tool()
def get_textures() -> str:
    """List all textures alive in the capture (dimensions, format, mips, etc.)."""
    return _call("get_textures")

@mcp.tool()
def get_buffers() -> str:
    """List all buffers alive in the capture (size, name)."""
    return _call("get_buffers")

@mcp.tool()
def get_resources() -> str:
    """List ALL resources in the capture (textures, buffers, shaders, pipelines, etc.)."""
    return _call("get_resources")

@mcp.tool()
def get_texture_info(resource_id: int) -> str:
    """Get texture metadata (dimensions, format, mips, etc.).

    Args:
        resource_id: The texture resource ID.
    """
    return _call("get_texture_info", {"resource_id": resource_id})

@mcp.tool()
def get_texture_data(resource_id: int, mip: int = 0, slice: int = 0) -> str:
    """Get texture pixel data.

    Args:
        resource_id: The texture resource ID.
        mip: Mip level (default 0).
        slice: Array slice (default 0).
    """
    return _call("get_texture_data", {"resource_id": resource_id, "mip": mip, "slice": slice})

@mcp.tool()
def get_buffer_contents(resource_id: int, offset: int = 0, length: int = 256) -> str:
    """Get buffer data.

    Args:
        resource_id: The buffer resource ID.
        offset: Byte offset to start reading.
        length: Number of bytes to read (0 = all).
    """
    return _call("get_buffer_data", {"resource_id": resource_id, "offset": offset, "length": length})


# ==================== 8. TEXTURE OPS ====================

@mcp.tool()
def pick_pixel(resource_id: int, x: int, y: int) -> str:
    """Read the RGBA value of a specific pixel from a texture.

    Args:
        resource_id: The texture resource ID.
        x: Pixel X coordinate.
        y: Pixel Y coordinate.
    """
    return _call("pick_pixel", {"resource_id": resource_id, "x": x, "y": y})


def _event_texture_evidence_uint(
    value: Any, field: str, minimum: int, maximum: int
) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("%s must be an integer" % field)
    if value < minimum or value > maximum:
        raise ValueError(
            "%s must be between %d and %d" % (field, minimum, maximum)
        )
    return int(value)


def _event_texture_evidence_number(value: Any, field: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("%s must be a finite number" % field)
    result = float(value)
    if not (-1.0e30 <= result <= 1.0e30):
        raise ValueError("%s must be a finite bounded number" % field)
    return result


def _event_texture_evidence_redirected(path: Path) -> bool:
    try:
        info = os.lstat(path)
    except OSError:
        return True
    if path.is_symlink():
        return True
    return bool(getattr(info, "st_file_attributes", 0) & 0x400)


def _event_texture_evidence_root() -> Path:
    root = Path(_EVENT_TEXTURE_EVIDENCE_ROOT)
    # Create each missing component only after every already-existing boundary
    # has passed the no-symlink/no-reparse check. ``mkdir(parents=True)`` would
    # otherwise follow a redirected ancestor before we could reject it.
    components = list(reversed(root.parents)) + [root]
    for component in components:
        if component.exists() or component.is_symlink():
            if _event_texture_evidence_redirected(component):
                raise RuntimeError(
                    "the Host-managed texture evidence root has a redirected ancestor"
                )
            continue
        os.mkdir(component, 0o700)
        if _event_texture_evidence_redirected(component):
            raise RuntimeError(
                "the Host-managed texture evidence root became redirected"
            )
    if not root.is_dir() or _event_texture_evidence_redirected(root):
        raise RuntimeError("the Host-managed texture evidence root is redirected")
    resolved = root.resolve(strict=True)
    if os.path.normcase(str(root)) != os.path.normcase(str(resolved)):
        raise RuntimeError(
            "the Host-managed texture evidence root has a redirected ancestor"
        )
    return resolved


def _allocate_event_texture_evidence_dir(
    root: Path, event_id: int
) -> tuple[str, Path]:
    for _unused in range(8):
        request_id = uuid.uuid4().hex
        request_dir = root / ("eid-%d-%s" % (event_id, request_id))
        try:
            os.mkdir(request_dir, 0o700)
        except FileExistsError:
            continue
        if (
            request_dir.parent != root
            or not is_within(root, request_dir)
            or _event_texture_evidence_redirected(request_dir)
            or request_dir.resolve(strict=True) != request_dir
        ):
            raise RuntimeError("the allocated texture evidence directory is unsafe")
        return request_id, request_dir
    raise RuntimeError("could not allocate a unique texture evidence directory")


def _cleanup_event_texture_evidence_dir(root: Path, request_dir: Path) -> None:
    """Best-effort cleanup of one exact, flat, Host-allocated request directory."""

    try:
        root = Path(root)
        request_dir = Path(request_dir)
        if (
            request_dir.parent != root
            or _EVENT_TEXTURE_EVIDENCE_REQUEST_DIR.fullmatch(request_dir.name) is None
            or _event_texture_evidence_redirected(root)
            or _event_texture_evidence_redirected(request_dir)
        ):
            return
        children = list(request_dir.iterdir())
        if any(
            child.is_dir()
            or child.is_symlink()
            or _event_texture_evidence_redirected(child)
            for child in children
        ):
            return
        for child in children:
            child.unlink()
        request_dir.rmdir()
    except Exception:
        pass


def _event_texture_evidence_filename(
    event_id: int,
    attachment_kind: str,
    attachment_index: int,
    mip: int,
    array_slice: int,
    sample: int,
    channel: str,
) -> str:
    return "eid-%d-%s%d-m%d-s%d-sample%d-%s.png" % (
        event_id,
        attachment_kind,
        attachment_index,
        mip,
        array_slice,
        sample,
        channel,
    )


def _validate_event_texture_evidence_bridge_result(
    result: Any,
    *,
    request_id: str,
    capture_session_id: str,
    event_id: int,
    original_event_id: int,
    request_dir: Path,
    attachment_kind: str,
    attachment_index: int,
    channel: str,
    mip: int,
    array_slice: int,
    sample: int,
    range_mode: str,
    black_point: float | None,
    white_point: float | None,
    max_dimension: int | None = None,
    value_decode: str = "native",
    flip_y: bool = False,
) -> dict[str, Any]:
    def _display_number(value: Any, field: str) -> float:
        if value_decode != "float32-bits":
            return _event_texture_evidence_number(value, field)
        if type(value) not in (int, float) or not -3.4028234663852886e38 <= value <= 3.4028234663852886e38:
            raise ValueError("%s must be a finite float32 value" % field)
        return float(value)

    if not isinstance(result, dict) or any(
        (
            result.get("schema") != _EVENT_TEXTURE_EVIDENCE_SCHEMA,
            result.get("schemaVersion") != 1,
            result.get("requestId") != request_id,
            result.get("captureSessionId") != capture_session_id,
            result.get("eventId") != event_id,
            result.get("exactEventBinding") is not True,
            result.get("replayMutation") is not False,
        )
    ):
        raise RuntimeError("RenderDoc returned an invalid texture evidence receipt")
    restoration = result.get("restoration")
    if (
        not isinstance(restoration, dict)
        or restoration.get("originalEventId") != original_event_id
        or restoration.get("restored") is not True
    ):
        raise RuntimeError("RenderDoc did not prove restoration of the original EID")
    expected_budgets = {
        "maxTextureByteSize": _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES,
        "maxSubresourcePixels": _MAX_EVENT_TEXTURE_EVIDENCE_PIXELS,
        "maxPngByteSize": _MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES,
    }
    if result.get("budgets") != expected_budgets:
        raise RuntimeError("RenderDoc returned unexpected texture evidence budgets")

    artifact = result.get("artifact")
    if not isinstance(artifact, dict):
        raise RuntimeError("RenderDoc omitted the texture evidence artifact receipt")
    status = artifact.get("status")
    if status not in {"saved", "skipped"}:
        raise RuntimeError("RenderDoc returned an invalid texture evidence status")
    attachment = artifact.get("attachment")
    if not isinstance(attachment, dict) or any(
        (
            attachment.get("kind") != attachment_kind,
            attachment.get("index") != attachment_index,
            attachment.get("mip") != mip,
            attachment.get("slice") != array_slice,
            attachment.get("sample") != sample,
            isinstance(attachment.get("resourceId"), bool),
            not isinstance(attachment.get("resourceId"), int),
            attachment.get("resourceId", 0) <= 0,
            isinstance(attachment.get("textureByteSize"), bool),
            not isinstance(attachment.get("textureByteSize"), int),
            attachment.get("textureByteSize", -1) < 0,
            isinstance(attachment.get("viewWidth"), bool),
            not isinstance(attachment.get("viewWidth"), int),
            attachment.get("viewWidth", 0) <= 0,
            isinstance(attachment.get("viewHeight"), bool),
            not isinstance(attachment.get("viewHeight"), int),
            attachment.get("viewHeight", 0) <= 0,
            isinstance(attachment.get("sampleCount"), bool),
            not isinstance(attachment.get("sampleCount"), int),
            attachment.get("sampleCount", 0) <= sample,
            not isinstance(attachment.get("format"), str),
            not str(attachment.get("format", "")),
            len(str(attachment.get("format", ""))) > 256,
        )
    ):
        raise RuntimeError("RenderDoc returned an invalid bound attachment receipt")
    texture_byte_size = attachment["textureByteSize"]
    if attachment_kind == "present" and attachment.get("presentedBackbuffer") is not True:
        raise RuntimeError("RenderDoc did not prove the Present backbuffer binding")
    pixel_count = attachment["viewWidth"] * attachment["viewHeight"]
    pixel_budget = _MAX_EVENT_TEXTURE_EVIDENCE_PIXELS
    if max_dimension is not None and 16 <= max_dimension <= 2048:
        pixel_budget = max(pixel_budget, 32 * 1024 * 1024)
    descriptor = attachment.get("descriptor")
    if not isinstance(descriptor, dict):
        raise RuntimeError("RenderDoc omitted exact output-view bounds")
    for field in ("firstMip", "numMips", "firstSlice", "numSlices"):
        value = descriptor.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise RuntimeError("RenderDoc returned an invalid output-view bound")
    if (
        descriptor["numMips"] <= 0
        or descriptor["numSlices"] <= 0
        or not descriptor["firstMip"]
        <= mip
        < descriptor["firstMip"] + descriptor["numMips"]
        or not descriptor["firstSlice"]
        <= array_slice
        < descriptor["firstSlice"] + descriptor["numSlices"]
    ):
        raise RuntimeError("RenderDoc did not bind the requested exact subresource")

    if attachment.get("textureDimension") == 3:
        volume_fields = ("resourceDepth", "mipDepth", "depthSlice", "viewSliceFirst", "viewSliceCount")
        if any(type(attachment.get(key)) is not int for key in volume_fields):
            raise RuntimeError("RenderDoc omitted exact volume texture bounds")
        depth = attachment["resourceDepth"]
        if (depth <= 0 or attachment["mipDepth"] != max(1, depth >> mip)
                or attachment.get("sliceKind") != "depth"
                or attachment["depthSlice"] != array_slice
                or attachment["viewSliceFirst"] != descriptor["firstSlice"]
                or attachment["viewSliceCount"] != descriptor["numSlices"]
                or descriptor["firstSlice"] + descriptor["numSlices"] > attachment["mipDepth"]):
            raise RuntimeError("RenderDoc returned inconsistent volume texture bounds")

    display = artifact.get("display")
    expected_extract = {"rgba": -1, "r": 0, "g": 1, "b": 2, "a": 3, "depth": 0}
    if not isinstance(display, dict) or any(
        (
            display.get("channel") != channel,
            display.get("channelExtract") != expected_extract[channel],
            display.get("rangeMode") != range_mode,
            display.get("valueDecode", "native") != value_decode,
            display.get("flipY", False) is not flip_y,
            display.get("depthInterpretation")
            != ("raw-resource-component-0" if channel == "depth" else None),
        )
    ):
        raise RuntimeError("RenderDoc returned invalid channel display metadata")
    output = artifact.get("output")
    skip_reason = artifact.get("skipReason")
    allowed_skip_reasons = {
        "source-size-unavailable",
        "source-size-budget-exceeded",
        "subresource-pixel-budget-exceeded",
        "subresource-range-flat",
        "png-byte-budget-exceeded",
    }
    if status == "saved":
        if skip_reason is not None or not isinstance(output, dict):
            raise RuntimeError(
                "RenderDoc returned invalid saved texture evidence metadata"
            )
        if (
            texture_byte_size <= 0
            or texture_byte_size > _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES
            or pixel_count > pixel_budget
        ):
            raise RuntimeError("RenderDoc saved texture evidence beyond its budget")
    elif skip_reason not in allowed_skip_reasons or output is not None:
        raise RuntimeError("RenderDoc returned an invalid budget skip receipt")

    decoding = display.get("decoding")
    before_decode = status == "skipped" and skip_reason in {
        "source-size-unavailable", "source-size-budget-exceeded",
        "subresource-pixel-budget-exceeded",
    }
    if value_decode == "native":
        if decoding is not None:
            raise RuntimeError("RenderDoc unexpectedly reinterpreted native texture values")
    elif before_decode:
        if decoding is not None:
            raise RuntimeError("RenderDoc claimed value decoding before checking its source budget")
    else:
        if not isinstance(decoding, dict) or any((
            decoding.get("schema") != "bread-texture-value-decode/v1",
            decoding.get("sourceFormat") != "R32_UINT",
            decoding.get("interpretation") != "ieee754-float32-little-endian",
            decoding.get("pixelCount") != pixel_count,
            decoding.get("sourceBytes") != pixel_count * 4,
            decoding.get("fullSubresource") is not True,
            decoding.get("sourceBytesModified") is not False,
            attachment.get("componentCount") != 1,
            attachment["sampleCount"] != 1,
            not isinstance(decoding.get("sourceSha256"), str),
        )):
            raise RuntimeError("RenderDoc omitted complete float-bit decoding evidence")
        digest = decoding["sourceSha256"]
        if len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise RuntimeError("RenderDoc returned an invalid decoded source hash")
        for key in ("pixelCount", "sourceBytes", "finiteCount", "nonFiniteCount", "zeroCount", "nonZeroFiniteCount"):
            if type(decoding.get(key)) is not int or decoding[key] < 0:
                raise RuntimeError("RenderDoc returned invalid decoded sample counts")
        if (decoding["finiteCount"] + decoding["nonFiniteCount"] != pixel_count or
                decoding["zeroCount"] + decoding["nonZeroFiniteCount"] != decoding["finiteCount"]):
            raise RuntimeError("RenderDoc decoded counts do not cover the complete subresource")

    actual_black = display.get("blackPoint")
    actual_white = display.get("whitePoint")
    if range_mode == "native":
        if (
            actual_black != 0.0
            or actual_white != 1.0
            or display.get("subresourceMin") is not None
            or display.get("subresourceMax") is not None
        ):
            raise RuntimeError("RenderDoc changed the native display range")
    elif range_mode == "explicit":
        actual_black = _display_number(actual_black, "blackPoint")
        actual_white = _display_number(actual_white, "whitePoint")
        if (
            actual_black != black_point
            or actual_white != white_point
            or display.get("subresourceMin") is not None
            or display.get("subresourceMax") is not None
        ):
            raise RuntimeError("RenderDoc changed the explicit display range")
    elif range_mode == "visible-distribution":
        deferred_range = status == "skipped" and skip_reason in {
            "source-size-unavailable", "source-size-budget-exceeded",
            "subresource-pixel-budget-exceeded",
        }
        if deferred_range:
            if any(display.get(key) is not None for key in (
                "blackPoint", "whitePoint", "subresourceMin", "subresourceMax", "distribution"
            )):
                raise RuntimeError("RenderDoc claimed a distribution before the texture budget check")
        else:
            actual_black = _display_number(actual_black, "blackPoint")
            actual_white = _display_number(actual_white, "whitePoint")
            if actual_black >= actual_white:
                raise RuntimeError("RenderDoc returned an invalid distribution display range")
            lows, highs = display.get("subresourceMin"), display.get("subresourceMax")
            if (not isinstance(lows, list) or not isinstance(highs, list) or
                    len(lows) != len(highs) or not 1 <= len(lows) <= 4):
                raise RuntimeError("RenderDoc omitted distribution component bounds")
            for lower, upper in zip(lows, highs):
                if lower is not None:
                    _display_number(lower, "subresourceMin")
                if upper is not None:
                    _display_number(upper, "subresourceMax")
                if lower is not None and upper is not None and lower > upper:
                    raise RuntimeError("RenderDoc returned inverted distribution component bounds")
            selected = list(range(min(3, len(lows)))) if channel == "rgba" else [expected_extract[channel]]
            if any(index >= len(lows) for index in selected):
                raise RuntimeError("RenderDoc returned no bounds for the selected channel")
            distribution = display.get("distribution")
            if not isinstance(distribution, dict) or any((
                distribution.get("method") not in (
                    {"whole-subresource-float32-bits-histogram-v1"}
                    if value_decode == "float32-bits" else
                    {"whole-subresource-histogram-percentile-v1", "native-normalized-format-v1"}),
                distribution.get("channels") != [index in selected for index in range(4)],
                distribution.get("percentiles") != [0.005, 0.995],
                distribution.get("excludedZeroComponents") is not True,
                distribution.get("excludedNonFinite") is not True,
                type(distribution.get("histogramCalls")) is not int,
                type(distribution.get("sampleCount")) is not int,
                not isinstance(distribution.get("segments"), list),
            )):
                raise RuntimeError("RenderDoc omitted whole-texture exposure evidence")
            if (not 0 <= distribution["histogramCalls"] <= 66 or
                    not 0 <= distribution["sampleCount"] <= pixel_count * len(selected)):
                raise RuntimeError("RenderDoc returned invalid histogram sample counts")
            segment_count = 0
            for segment in distribution["segments"]:
                if not isinstance(segment, dict) or type(segment.get("sampleCount")) is not int:
                    raise RuntimeError("RenderDoc returned an invalid histogram segment")
                lower = _display_number(segment.get("minimum"), "histogram minimum")
                upper = _display_number(segment.get("maximum"), "histogram maximum")
                if lower >= upper or segment["sampleCount"] <= 0:
                    raise RuntimeError("RenderDoc returned an invalid histogram segment range")
                segment_count += segment["sampleCount"]
            if segment_count != distribution["sampleCount"]:
                raise RuntimeError("RenderDoc histogram segments do not match the sample count")
            if value_decode == "float32-bits" and distribution["sampleCount"] != decoding["nonZeroFiniteCount"]:
                raise RuntimeError("RenderDoc decoded exposure omits finite nonzero texels")
    else:
        deferred_range = status == "skipped" and skip_reason in {
            "source-size-unavailable",
            "source-size-budget-exceeded",
            "subresource-pixel-budget-exceeded",
        }
        if deferred_range:
            if any(
                value is not None
                for value in (
                    actual_black,
                    actual_white,
                    display.get("subresourceMin"),
                    display.get("subresourceMax"),
                )
            ):
                raise RuntimeError(
                    "RenderDoc claimed min/max values for a pre-range budget skip"
                )
        else:
            actual_black = _display_number(
                actual_black, "blackPoint"
            )
            actual_white = _display_number(
                actual_white, "whitePoint"
            )
            minimum_values = display.get("subresourceMin")
            maximum_values = display.get("subresourceMax")
            if (
                not isinstance(minimum_values, list)
                or not isinstance(maximum_values, list)
                or len(minimum_values) != len(maximum_values)
                or not 1 <= len(minimum_values) <= 4
            ):
                raise RuntimeError(
                    "RenderDoc omitted exact subresource min/max values"
                )
            for minimum, maximum in zip(minimum_values, maximum_values):
                minimum = _display_number(
                    minimum, "subresourceMin"
                )
                maximum = _display_number(
                    maximum, "subresourceMax"
                )
                if minimum > maximum:
                    raise RuntimeError(
                        "RenderDoc returned an inverted subresource min/max range"
                    )
            selected_indices = (
                range(min(3, len(minimum_values)))
                if channel == "rgba"
                else [expected_extract[channel]]
            )
            if any(index >= len(minimum_values) for index in selected_indices):
                raise RuntimeError(
                    "RenderDoc returned no min/max value for the selected channel"
                )
            expected_black = min(minimum_values[index] for index in selected_indices)
            expected_white = max(maximum_values[index] for index in selected_indices)
            if actual_black != expected_black or actual_white != expected_white:
                raise RuntimeError(
                    "RenderDoc min/max mapping does not match the selected channel"
                )
            if skip_reason == "subresource-range-flat":
                if status != "skipped" or actual_black != actual_white:
                    raise RuntimeError("RenderDoc returned an invalid flat-range skip")
            elif actual_black >= actual_white:
                raise RuntimeError(
                    "RenderDoc returned an invalid min/max display range"
                )
    if channel == "depth" and actual_black is not None and (
        _display_number(actual_black, "depth blackPoint") < 0.0
        or _display_number(actual_white, "depth whitePoint") > 1.0
    ):
        raise RuntimeError("RenderDoc returned a transformed/out-of-range depth view")

    if status == "skipped":
        skip_matches_budget = {
            "source-size-unavailable": texture_byte_size == 0,
            "source-size-budget-exceeded": (
                texture_byte_size > _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES
            ),
            "subresource-pixel-budget-exceeded": (
                0 < texture_byte_size <= _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES
                and pixel_count > pixel_budget
            ),
            "subresource-range-flat": (
                0 < texture_byte_size <= _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES
                and pixel_count <= pixel_budget
                and range_mode == "subresource-minmax"
                and actual_black == actual_white
            ),
            "png-byte-budget-exceeded": (
                0 < texture_byte_size <= _MAX_EVENT_TEXTURE_EVIDENCE_SOURCE_BYTES
                and pixel_count <= pixel_budget
            ),
        }[skip_reason]
        if not skip_matches_budget:
            raise RuntimeError("RenderDoc returned an invalid budget skip receipt")
        if list(request_dir.iterdir()):
            raise RuntimeError("a skipped texture evidence request left output files")
        return result

    expected_name = _event_texture_evidence_filename(
        event_id,
        attachment_kind,
        attachment_index,
        mip,
        array_slice,
        sample,
        channel,
    )
    expected_path = request_dir / expected_name
    supplied_path = Path(str(output.get("path", "") or ""))
    if (
        not supplied_path.is_absolute()
        or supplied_path != expected_path
        or output.get("mimeType") != "image/png"
        or output.get("noOverwrite") is not True
        or _event_texture_evidence_redirected(supplied_path)
        or not supplied_path.is_file()
        or supplied_path.resolve(strict=True) != supplied_path
        or not is_within(request_dir, supplied_path)
    ):
        raise RuntimeError("RenderDoc returned an unsafe texture evidence path")
    children = list(request_dir.iterdir())
    if children != [expected_path]:
        raise RuntimeError("RenderDoc returned unreported texture evidence files")
    size = output.get("byteSize")
    digest = str(output.get("sha256", "") or "")
    if (
        isinstance(size, bool)
        or not isinstance(size, int)
        or size <= 0
        or size > _MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES
        or len(digest) != 64
        or any(character not in "0123456789abcdef" for character in digest)
        or supplied_path.stat().st_size != size
        or _bounded_file_sha256(
            supplied_path,
            _MAX_EVENT_TEXTURE_EVIDENCE_PNG_BYTES,
            "Event texture evidence PNG",
        )
        != digest
    ):
        raise RuntimeError("RenderDoc returned invalid texture evidence integrity data")
    with supplied_path.open("rb") as stream:
        if stream.read(8) != b"\x89PNG\r\n\x1a\n":
            raise RuntimeError("RenderDoc texture evidence is not a PNG file")
    return result


def _write_event_texture_evidence_manifest(
    request_dir: Path, payload: dict[str, Any]
) -> dict[str, Any]:
    encoded = json.dumps(
        payload,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if not encoded or len(encoded) > _MAX_EVENT_TEXTURE_EVIDENCE_MANIFEST_BYTES:
        raise RuntimeError("texture evidence manifest exceeds its byte budget")
    final_path = request_dir / "manifest.json"
    temporary_path = request_dir / (".manifest-%s.json" % uuid.uuid4().hex)
    if final_path.exists() or final_path.is_symlink():
        raise RuntimeError("texture evidence manifest already exists")
    try:
        with temporary_path.open("xb") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary_path, final_path)
        temporary_path.unlink()
    finally:
        try:
            temporary_path.unlink()
        except FileNotFoundError:
            pass
    if (
        _event_texture_evidence_redirected(final_path)
        or not final_path.is_file()
        or final_path.resolve(strict=True) != final_path
    ):
        raise RuntimeError("texture evidence manifest publication is unsafe")
    digest = _bounded_file_sha256(
        final_path,
        _MAX_EVENT_TEXTURE_EVIDENCE_MANIFEST_BYTES,
        "Event texture evidence manifest",
    )
    return {
        "contentSchema": _EVENT_TEXTURE_EVIDENCE_HOST_SCHEMA,
        "path": str(final_path),
        "mimeType": "application/json",
        "byteSize": len(encoded),
        "sha256": digest,
        "noOverwrite": True,
    }


def _event_texture_crop(crop: Mapping[str, Any] | None) -> dict[str, int] | None:
    """A crop rectangle is four whole pixels or it is nothing."""

    if crop is None:
        return None
    if not isinstance(crop, Mapping):
        raise ValueError("crop must be an object with x, y, width and height")
    rectangle: dict[str, int] = {}
    for name, minimum in (("x", 0), ("y", 0), ("width", 1), ("height", 1)):
        value = crop.get(name)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("crop.%s must be a whole number of pixels" % name)
        number = int(value)
        if number < minimum:
            raise ValueError("crop.%s must be at least %d" % (name, minimum))
        rectangle[name] = number
    return rectangle


@mcp.tool(structured_output=False)
def capture_event_texture_evidence(
    event_id: int,
    attachment_kind: str,
    attachment_index: int = 0,
    channel: str = "rgba",
    mip: int = 0,
    slice: int = 0,
    sample: int = 0,
    range_mode: str = "visible-distribution",
    black_point: float | None = None,
    white_point: float | None = None,
    crop: dict[str, int] | None = None,
    max_dimension: int | None = None,
    stage: str = "fragment",
    inline: bool = True,
    value_decode: str = "native",
    flip_y: bool = False,
) -> list[Any]:
    """Save one exact EID-bound RTV/DSV/UAV/SRV/Present texture PNG as managed evidence.

    The caller never supplies a filesystem path. ``attachment_kind`` is
    exactly ``rtv``, ``dsv``, ``uav``, ``srv`` or ``present``; DSV accepts ``channel=depth`` and remains
    raw resource depth (no linearisation). Channels are ``rgba/r/g/b/a/depth``.
    Range mode defaults to ``visible-distribution``: preserve 0..1 unless the
    measured occupied contents are substantially dark, clipped or unreadable.
    Whole-subresource histogram percentiles ignore empty atlas cells and extreme
    outliers; format names alone never trigger exposure. ``native`` fixes 0..1, ``explicit`` takes
    black/white points, and ``subresource-minmax`` is the exact extrema view.
    ``value_decode=float32-bits`` explicitly interprets complete single-channel
    R32_UINT texels as IEEE float bits, only when Shader/asset evidence establishes
    that encoding. It changes the preview, not captured storage; native is default.
    For comparisons/animations reuse a shared explicit range from the receipt
    so independent automatic exposure cannot disguise changes.
    ``flip_y=True`` mirrors the presentation after cropping, before hashing and
    sending the image. Determine it per texture from screen references and its
    Shader UV/projection/viewport convention, never merely from the API or game.
    It does not change GPU bytes. Native orientation is the default. Slice is a
    depth-plane index for Texture3D, within the selected mip's observed view.
    Mip, slice, and sample identify the exact bound
    subresource. Oversized/unknown resources return a strict skip receipt.
    For SRV/UAV, stage and attachment_index come from inspect_frame_render_stage;
    the index is in the native binding list, not the Shader register number.
    ``present`` requires an exact Present EID, index/mip/slice/sample 0, and
    reads that action's actual presented backbuffer (scene plus UI), never a
    stale bound PS render target or an isolated UI layer.

    Returns the verified receipt AND an actual MCP image by default. The image is
    a bounded RGB preview of that same saved PNG, not another replay or a file path.
    The full-resolution evidence and its manifest remain unchanged. modelImage
    records the preview/source hashes and whether image content was included;
    this proves transport inclusion, not that a provider/model understood it.
    inline=False requests metadata only. A connection which cannot receive image
    tool results must report that limitation rather than claiming visual review.
    """

    try:
        inline = _strict_bool(inline, "inline")
        payload = json.loads(_capture_event_texture_evidence_receipt(
            event_id=event_id, attachment_kind=attachment_kind,
            attachment_index=attachment_index, channel=channel, mip=mip,
            slice=slice, sample=sample, range_mode=range_mode,
            black_point=black_point, white_point=white_point, crop=crop,
            max_dimension=max_dimension, stage=stage, value_decode=value_decode,
            flip_y=flip_y,
        ))
        return _event_texture_model_result(payload, inline=inline)
    except Exception as error:
        return [_err(error)]


def _event_texture_model_result(payload: dict[str, Any], *, inline: bool) -> list[Any]:
    """Attach the exact exported pixels without replacing or re-rendering evidence."""

    from .evidence_image import event_texture_model_image

    receipt, image = event_texture_model_image(payload, inline=inline)
    return [_ok_compact(receipt), *([image] if image is not None else [])]


def _capture_event_texture_evidence_receipt(
    event_id: int, attachment_kind: str, attachment_index: int = 0,
    channel: str = "rgba", mip: int = 0, slice: int = 0, sample: int = 0,
    range_mode: str = "visible-distribution", black_point: float | None = None,
    white_point: float | None = None, crop: dict[str, int] | None = None,
    max_dimension: int | None = None, stage: str = "fragment",
    value_decode: str = "native",
    flip_y: bool = False, preserve_alpha: bool = False,
) -> str:
    """Internal JSON receipt path shared by the two image-returning tools."""

    request_dir: Path | None = None
    root: Path | None = None
    try:
        flip_y = _strict_bool(flip_y, "flip_y")
        exact_event_id = _event_texture_evidence_uint(
            event_id, "event_id", 1, 0xFFFFFFFF
        )
        if not isinstance(attachment_kind, str) or attachment_kind not in {"rtv", "dsv", "uav", "srv", "present"}:
            raise ValueError("attachment_kind must be rtv, dsv, uav, srv, or present")
        if stage not in {"vertex", "hull", "domain", "geometry", "fragment", "compute", "task", "mesh",
                          "raygen", "intersection", "anyhit", "closesthit", "miss", "callable"}:
            raise ValueError("stage must be a canonical Shader stage")
        exact_attachment_index = _event_texture_evidence_uint(
            attachment_index, "attachment_index", 0, 4095 if attachment_kind in {"uav", "srv"} else 7
        )
        if attachment_kind in {"dsv", "present"} and exact_attachment_index != 0:
            raise ValueError("a DSV or Present attachment_index must be 0")
        if not isinstance(channel, str) or channel not in {
            "rgba", "r", "g", "b", "a", "depth"
        }:
            raise ValueError("channel must be rgba, r, g, b, a, or depth")
        if attachment_kind == "dsv" and channel != "depth":
            raise ValueError("DSV evidence only supports raw depth")
        if attachment_kind != "dsv" and channel == "depth":
            raise ValueError("depth evidence requires a DSV")
        if value_decode not in ("native", "float32-bits"):
            raise ValueError("value_decode must be native or float32-bits")
        if value_decode != "native" and (channel not in ("r", "rgba") or attachment_kind == "dsv"):
            raise ValueError("float32-bits requires a single-channel color texture preview")
        exact_mip = _event_texture_evidence_uint(mip, "mip", 0, 0x7FFFFFFF)
        exact_slice = _event_texture_evidence_uint(slice, "slice", 0, 0x7FFFFFFF)
        exact_sample = _event_texture_evidence_uint(
            sample, "sample", 0, 0x7FFFFFFF
        )
        if attachment_kind == "present" and (exact_mip or exact_slice or exact_sample):
            raise ValueError("Present evidence requires mip, slice and sample 0")
        if not isinstance(range_mode, str) or range_mode not in {
            "native", "explicit", "subresource-minmax", "visible-distribution"
        }:
            raise ValueError(
                "range_mode must be native, explicit, subresource-minmax, or visible-distribution"
            )
        if range_mode == "explicit":
            exact_black = _event_texture_evidence_number(
                black_point, "black_point"
            )
            exact_white = _event_texture_evidence_number(
                white_point, "white_point"
            )
            if exact_black >= exact_white:
                raise ValueError("black_point must be less than white_point")
            if channel == "depth" and (exact_black < 0.0 or exact_white > 1.0):
                raise ValueError("raw depth display range must remain within [0, 1]")
        else:
            if black_point is not None or white_point is not None:
                raise ValueError(
                    "black_point and white_point are only valid for explicit range"
                )
            exact_black = None
            exact_white = None

        context = _active_live_context(allow_missing_capture_id=True, require_event_state=True)
        capture = context["capture"]
        capture_session_id = _strict_lower_hex(
            capture.get("captureSessionId"), 32, "capture.captureSessionId"
        )
        scoped_session = _effective_capture_scope_session_id()
        if scoped_session and capture_session_id != scoped_session:
            raise RuntimeError(
                "the scoped capture session changed before texture evidence capture"
            )
        events = context.get("events")
        if not isinstance(events, dict):
            raise RuntimeError("RenderDoc current context omitted the visible EID")
        original_event_id = _event_texture_evidence_uint(
            events.get("currentEventId"), "events.currentEventId", 0, 0xFFFFFFFF
        )

        root = _event_texture_evidence_root()
        request_id, request_dir = _allocate_event_texture_evidence_dir(
            root, exact_event_id
        )
        bridge_result = ipc.call(
            "capture_event_texture_evidence",
            {
                "event_id": exact_event_id,
                "attachment_kind": attachment_kind,
                "attachment_index": exact_attachment_index,
                "stage": stage,
                "channel": channel,
                "mip": exact_mip,
                "slice": exact_slice,
                "sample": exact_sample,
                "range_mode": range_mode,
                "value_decode": value_decode,
                "flip_y": flip_y,
                **({"preserve_alpha": True} if preserve_alpha else {}),
                "black_point": exact_black,
                "white_point": exact_white,
                "request_id": request_id,
                "artifact_dir": str(request_dir),
                # Cropping and scaling happen before publication, so the hash and the
                # byte budget apply to the file that is actually kept.
                "crop": _event_texture_crop(crop),
                "max_dimension": (None if max_dimension is None
                                  else max(16, min(int(max_dimension), 8192))),
                "expected_capture_session_id": capture_session_id,
                "__replaylab_expected_capture_session_id": capture_session_id,
            },
            timeout=300.0,
        )
        validated = _validate_event_texture_evidence_bridge_result(
            bridge_result,
            request_id=request_id,
            capture_session_id=capture_session_id,
            event_id=exact_event_id,
            original_event_id=original_event_id,
            request_dir=request_dir,
            attachment_kind=attachment_kind,
            attachment_index=exact_attachment_index,
            channel=channel,
            mip=exact_mip,
            array_slice=exact_slice,
            sample=exact_sample,
            range_mode=range_mode,
            black_point=exact_black,
            white_point=exact_white,
            max_dimension=max_dimension,
            value_decode=value_decode,
            flip_y=flip_y,
        )
        if preserve_alpha and validated["artifact"]["status"] == "saved":
            if validated["artifact"].get("display", {}).get("alphaMode") != "preserved":
                raise RuntimeError("The texture receipt did not preserve the requested channels")
        if (attachment_kind in {"uav", "srv"}
                and validated["artifact"].get("attachment", {}).get("stage") != stage):
            raise RuntimeError("The texture receipt does not match the requested Shader stage")
        restored_context = _require_same_active_capture(
            context, allow_missing_capture_id=True, require_event_state=True
        )
        if (
            not isinstance(restored_context.get("events"), dict)
            or restored_context["events"].get("currentEventId")
            != original_event_id
        ):
            raise RuntimeError("RenderDoc did not restore the original visible EID")
        manifest_payload = {
            "schema": _EVENT_TEXTURE_EVIDENCE_HOST_SCHEMA,
            "schemaVersion": 1,
            "requestId": request_id,
            "capture": {
                "captureId": str(capture.get("captureId", "") or ""),
                "captureSessionId": capture_session_id,
                "path": str(capture.get("path", "") or ""),
                "api": str(capture.get("api", "") or ""),
            },
            "eventId": exact_event_id,
            "status": validated["artifact"]["status"],
            "artifact": validated["artifact"],
            "restoration": validated["restoration"],
            "budgets": validated["budgets"],
            "policy": {
                "hostManagedPath": True,
                "callerSuppliedPath": False,
                "uniqueNoOverwrite": True,
                "exactEventBinding": True,
                "rtvDsvOnly": attachment_kind in {"rtv", "dsv"},
                "depthInterpretation": "raw-only",
                "replayMutation": False,
            },
        }
        manifest = _write_event_texture_evidence_manifest(
            request_dir, manifest_payload
        )
        final_context = _require_same_active_capture(
            context, allow_missing_capture_id=True, require_event_state=True
        )
        if (
            not isinstance(final_context.get("events"), dict)
            or final_context["events"].get("currentEventId")
            != original_event_id
        ):
            raise RuntimeError("the visible EID changed while publishing evidence")
        response = dict(manifest_payload)
        response["manifest"] = manifest
        return _ok(response)
    except Exception as error:
        if root is not None and request_dir is not None:
            _cleanup_event_texture_evidence_dir(root, request_dir)
        return _err(error)


@mcp.tool()
def fingerprint_event_outputs(event_id: int, grid_size: int = 12) -> str:
    """Hash and sample all MRT/depth outputs for observational A/B validation.

    Bounded whole-subresource SHA-256 detects byte-exact equality. Large or
    unknown-size outputs skip materialisation to protect qrenderdoc and retain
    the deterministic pixel grid for explicit tolerance comparisons. This
    observes one captured event and never proves equivalence for every input.
    """

    try:
        if isinstance(event_id, bool) or int(event_id) <= 0:
            raise ValueError("event_id must be a positive integer")
        if isinstance(grid_size, bool) or not isinstance(grid_size, int):
            raise ValueError("grid_size must be an integer")
        if grid_size < 2 or grid_size > 32:
            raise ValueError("grid_size must be between 2 and 32")
        live = ipc.call("get_capture_status", {}, timeout=30.0)
        if not isinstance(live, dict) or live.get("loaded") is not True:
            raise RuntimeError("No capture is loaded in RenderDoc")
        capture_session_id = str(live.get("captureSessionId", "") or "")
        if len(capture_session_id) != 32 or any(
            character not in "0123456789abcdef"
            for character in capture_session_id
        ):
            raise RuntimeError("active capture has no valid session identity")
        result = ipc.call(
            "fingerprint_event_outputs",
            {
                "event_id": int(event_id),
                "grid_size": grid_size,
                "expected_capture_session_id": capture_session_id,
            },
            timeout=300.0,
        )
        if not isinstance(result, dict) or any(
            (
                result.get("schema") != "replaylab-event-output-fingerprint/v1",
                result.get("schemaVersion") != 1,
                result.get("captureSessionId") != capture_session_id,
                result.get("eventId") != int(event_id),
                result.get("gridSize") != grid_size,
                result.get("observationalOnly") is not True,
                result.get("semanticEquivalenceVerified") is not False,
            )
        ):
            raise RuntimeError("RenderDoc returned an invalid output fingerprint")
        outputs = result.get("outputs")
        if not isinstance(outputs, list) or len(outputs) > 9:
            raise RuntimeError("RenderDoc returned invalid output fingerprint targets")
        seen = set()
        for output in outputs:
            if not isinstance(output, dict):
                raise RuntimeError("RenderDoc returned an invalid output fingerprint item")
            key = (output.get("kind"), output.get("index"))
            raw_sha256_value = output.get("rawSha256")
            raw_byte_size = output.get("rawByteSize")
            raw_hash_status = output.get("rawHashStatus")
            samples = output.get("samples")
            if (
                key in seen
                or key[0] not in {"color", "depth"}
                or not isinstance(key[1], int)
                or not isinstance(output.get("resourceId"), int)
                or raw_hash_status not in {
                    "hashed",
                    "skipped-texture-too-large",
                    "skipped-size-unavailable",
                }
                or not isinstance(output.get("textureByteSize"), int)
                or output.get("textureByteSize") < 0
                or not isinstance(output.get("fullHashByteLimit"), int)
                or output.get("fullHashByteLimit") <= 0
                or not isinstance(samples, list)
                or len(samples) > grid_size * grid_size
            ):
                raise RuntimeError("RenderDoc returned invalid output fingerprint metadata")
            if raw_hash_status == "hashed":
                raw_sha256 = str(raw_sha256_value or "")
                if (
                    len(raw_sha256) != 64
                    or any(
                        character not in "0123456789abcdef"
                        for character in raw_sha256
                    )
                    or not isinstance(raw_byte_size, int)
                    or raw_byte_size < 0
                ):
                    raise RuntimeError(
                        "RenderDoc returned invalid exact output hash evidence"
                    )
            elif raw_sha256_value is not None or raw_byte_size is not None:
                raise RuntimeError(
                    "RenderDoc returned bytes for a skipped output hash"
                )
            seen.add(key)
            for sample in samples:
                value = sample.get("value") if isinstance(sample, dict) else None
                if (
                    not isinstance(sample, dict)
                    or not isinstance(sample.get("x"), int)
                    or not isinstance(sample.get("y"), int)
                    or not isinstance(value, list)
                    or len(value) != 4
                    or any(
                        not isinstance(component, (int, float, str))
                        or isinstance(component, bool)
                        for component in value
                    )
                ):
                    raise RuntimeError("RenderDoc returned an invalid output sample")
        result["capturePath"] = str(live.get("capturePath", "") or "")
        result["validationScope"] = "single-captured-event-output-observation"
        return _ok(result)
    except Exception as error:
        return _err(error)

@mcp.tool()
def get_texture_minmax(resource_id: int) -> str:
    """Get the min and max pixel values in a texture.

    Args:
        resource_id: The texture resource ID.
    """
    return _call("get_texture_minmax", {"resource_id": resource_id})

# Legacy direct-path export helper retained only for non-MCP compatibility.
# Managed resource-export workflows own Agent-visible artifact writes.
def save_texture(resource_id: int, output_path: str, mip: int = 0, slice: int = -1,
                 crop: dict[str, int] | None = None,
                 max_dimension: int | None = None) -> str:
    """Save a texture to disk. Supports PNG, JPG, BMP, TGA, HDR, EXR, DDS.

    Auto-detects CubeMap textures (arraysize=6) and handles them appropriately:
    - DDS format: saves all 6 faces in a single native cubemap file
    - PNG/JPG/etc: saves 6 individual face files (e.g. texture_face0_posX.png through face5_negZ.png)
    - Use slice=0..5 to export a specific face only

    CubeMap face order: 0=+X(Right), 1=-X(Left), 2=+Y(Up), 3=-Y(Down), 4=+Z(Front), 5=-Z(Back)

    Args:
        resource_id: The texture resource ID.
        output_path: File path to save to (format inferred from extension).
        mip: Mip level (default 0).
        slice: For CubeMap: -1=all faces (default), 0-5=specific face. Ignored for 2D textures.
        crop: Optional {x, y, width, height} in pixels, applied before scaling.
        max_dimension: Optional longest-side limit; the image is scaled down to fit.

    ``crop`` and ``max_dimension`` exist because a 4K texture spends a reader's whole
    context on pixels that say nothing. They apply to a single-file 2D save; a cubemap
    written as six files is left alone.
    """
    return _call("save_texture", {
        "resource_id": resource_id,
        "output_path": output_path,
        "mip": mip,
        "slice": slice,
        "crop": _event_texture_crop(crop),
        "max_dimension": (None if max_dimension is None
                          else max(16, min(int(max_dimension), 8192))),
    })


# ==================== 9. PIXEL HISTORY ====================

@mcp.tool()
def pixel_history(resource_id: int, x: int, y: int, event_id: int) -> str:
    """Get pixel modifications through one explicit frozen event.

    This is not automatically the whole-frame final history. ``event_id`` is
    the exact cutoff and does not depend on the user's later UI selection.
    For object attribution prefer inspect_pixel_object, which retains Passed(),
    depth/discard flags, primitive IDs and Shader outputs. This legacy list of
    pre/post colors alone cannot distinguish failed attempts from visible writes.

    Args:
        resource_id: The render target texture resource ID.
        x: Pixel X coordinate.
        y: Pixel Y coordinate.
        event_id: Frozen positive cutoff event ID.
    """
    return _call(
        "pixel_history",
        {"resource_id": resource_id, "x": x, "y": y, "event_id": event_id},
    )


@mcp.tool()
def inspect_pixel_object(
    texture_id: int,
    x: int,
    y: int,
    event_id: int,
    mip: int = 0,
    slice: int = 0,
    sample: int = 0,
    prefer_geometry: bool = True,
) -> str:
    """Inspect a clicked render-target pixel and return event/fragment evidence.

    The result records its selected-event cutoff and separates the last recorded modification,
    passed write candidates, the last confirmed non-direct write, passed raster geometry, and
    potential direct shader writes. A passed item is not automatically a visible contributor
    after later opaque overwrites. It deliberately does not invent an engine object or instance
    ID: fullscreen/post-process draws, direct/compute writes, and transparent overdraw may not
    have one unique owner.

    This is an expensive replay operation. Invoke it only for an explicit click, never for hover
    or continuous mouse-move polling. A UI integration should run it asynchronously and show a
    pending state.

    Args:
        texture_id: Render target or depth texture resource ID.
        x: Pixel X coordinate in the selected mip.
        y: Pixel Y coordinate in the selected mip.
        event_id: Frozen positive PixelHistory cutoff event ID.
        mip: Mip level (default 0).
        slice: Array slice (default 0).
        sample: Multisample index (default 0).
        prefer_geometry: Prefer the last passed raster fragment over a non-geometry last writer.
    """
    return _call(
        "inspect_pixel_object",
        {
            "texture_id": texture_id,
            "x": x,
            "y": y,
            "event_id": event_id,
            "mip": mip,
            "slice": slice,
            "sample": sample,
            "prefer_geometry": prefer_geometry,
        },
        timeout=120.0,
    )


# ==================== 10. SHADER DEBUG ====================

@mcp.tool()
def debug_pixel(
    x: int,
    y: int,
    event_id: int = 0,
    sample: int = 0,
    primitive_id: int = -1,
    view: int = 0,
) -> str:
    """Debug a pixel shader invocation, optionally selecting its event and fragment.

    Returns the first 50 steps inline and a reusable traceArtifact with actual late variable
    changes. Read traceArtifact.path using read_evidence_file; stepIndex entries are byte
    offsets for later steps, so there is no need to rerun debug to inspect the tail.
    Check complete/executionComplete/truncationReasons before calling the trace complete.
    Artifact retention is bounded to 24 hours and the latest 16 traces.

    Args:
        x: Pixel X coordinate.
        y: Pixel Y coordinate.
        event_id: Event to debug; 0 keeps the current RenderDoc event.
        sample: Multisample index.
        primitive_id: Primitive reported by inspect_pixel_object; -1 lets RenderDoc choose.
        view: Layered/multiview view index.
    """
    return _call(
        "debug_pixel",
        {
            "x": x,
            "y": y,
            "event_id": event_id,
            "sample": sample,
            "primitive_id": primitive_id,
            "view": view,
        },
        timeout=120.0,
    )

@mcp.tool()
def debug_vertex(vertex_id: int, instance_id: int = 0) -> str:
    """Debug the vertex shader execution for a specific vertex. Must set_event first.

    Returns a bounded inline preview plus traceArtifact.path. Use read_evidence_file with
    traceArtifact.stepIndex offsets to inspect later actual values without rerunning execution.
    The artifact explicitly records completion or truncation and expires after 24 hours
    or when displaced by 16 newer debug traces.

    Args:
        vertex_id: The vertex ID to debug.
        instance_id: Instance ID (default 0).
    """
    return _call("debug_vertex", {"vertex_id": vertex_id, "instance_id": instance_id}, timeout=120.0)


# ==================== 11. PERF COUNTERS ====================

@mcp.tool()
def enumerate_counters() -> str:
    """List all available GPU performance counters for the current capture."""
    return _call("enumerate_counters")

@mcp.tool()
def fetch_counters(counter_ids: str) -> str:
    """Fetch values for specific GPU performance counters.

    Args:
        counter_ids: Comma-separated list of counter IDs (e.g. "1,2,3").
    """
    try:
        ids = [int(item.strip()) for item in str(counter_ids or "").split(",")
               if item.strip()]
        if not ids:
            raise ValueError(
                "counter_ids must be a comma-separated list of numeric ids from "
                "enumerate_counters, for example \"1,2,3\"")
    except ValueError as error:
        # Every other tool answers with the error envelope; raising here reaches the
        # Agent as a bare protocol error it cannot act on, and spends a report round.
        return _err(error)
    return _call("fetch_counters", {"counter_ids": ids})


# ==================== 12. MESH & DEBUG MSGS ====================

@mcp.tool()
def get_post_vs_data(event_id: int = 0, instance: int = 0, view: int = 0,
                     stage: Literal["vs-out", "gs-out"] = "vs-out",
                     max_vertices: Annotated[int, Field(ge=1, le=16384)] = 4096,
                     max_indices: Annotated[int, Field(ge=1, le=49152)] = 12288) -> str:
    """Read actual bounded post-transform positions/indices at one captured EID.

    event_id=0 preserves the legacy current-event selection. Prefer an exact EID.
    stage is vs-out or gs-out (the final geometry/mesh output where supported).
    The native transaction restores the visible event. Inspect complete and
    limitations: this is one instance/view, not visibility or depth-test proof.
    Unsupported position formats are reported, never guessed. For a picture,
    capture_mesh_image returns an actual wireframe image to the model.
    max_vertices is 1..16384; max_indices is 1..49152. Larger meshes return
    an explicitly incomplete prefix; do not retry with values above these caps.
    """
    return _call("get_post_vs_data", {"event_id": event_id, "instance": instance,
                 "view": view, "stage": stage, "max_vertices": max_vertices,
                 "max_indices": max_indices}, timeout=120.0)

@mcp.tool()
def get_debug_messages() -> str:
    """Get API validation/debug messages from the graphics driver."""
    return _call("get_debug_messages")

@mcp.tool()
def get_action_timings(event_ids: str = "", marker_filter: str = "") -> str:
    """Get GPU timing information for actions.

    Args:
        event_ids: Comma-separated event IDs (empty = all).
        marker_filter: Only actions under matching markers.
    """
    params = {}
    if event_ids: params["event_ids"] = [int(x.strip()) for x in event_ids.split(",")]
    if marker_filter: params["marker_filter"] = marker_filter
    return _call("get_action_timings", params)


# ==================== 13. EXPORT ====================

# Legacy direct-path export helpers retained only for non-MCP compatibility.
def export_drawcall(event_id: int, output_dir: str) -> str:
    """One-shot export of a draw call: shaders + textures + cbuffer values to disk.

    Exports shader disassembly, source code, all bound textures as PNG, and a summary JSON.

    Args:
        event_id: The event ID of the draw call to export.
        output_dir: Directory to save all exported files.
    """
    return _call("export_drawcall", {"event_id": event_id, "output_dir": output_dir}, timeout=60)


def export_to_unity(event_id: int, output_dir: str, mesh_name: str = "exported_mesh") -> str:
    """Export a draw call's mesh and shader data as Unity-ready assets.

    This is the ultimate tool for bringing RenderDoc captures into Unity:
    - Exports the 3D mesh as .obj AND .fbx (positions, normals, UVs, indices)
    - Collects all bound texture info with role detection (use save_texture to export textures separately)
    - Generates a Unity material definition JSON with property mappings
    - Maps shader parameters to Unity Standard/URP/HDRP material properties

    The output folder can be directly copied into a Unity project's Assets folder.

    Args:
        event_id: The event ID of the draw call to export.
        output_dir: Directory to save all exported Unity-ready files.
        mesh_name: Name for the exported mesh and material (default: "exported_mesh").
    """
    return _call("export_to_unity", {
        "event_id": event_id,
        "output_dir": output_dir,
        "mesh_name": mesh_name,
    }, timeout=60)


# ==================== 14. SYMBOL RESOLVER ====================

def _event_id_list(event_ids: str) -> list[int]:
    if not event_ids.strip():
        return []
    return [int(value.strip()) for value in event_ids.split(",") if value.strip()]


@mcp.tool()
def export_capture_symbol_catalog(output_dir: str, event_ids: str = "") -> str:
    """Export a lossless, versioned shader/constant-buffer catalog from RenderDoc.

    The bridge writes native shader blobs to ``output_dir/blobs`` instead of
    placing large binary data in MCP/IPC messages. No AI inference is performed.

    Args:
        output_dir: Directory for shader_catalog.v1.json and native shader blobs.
        event_ids: Optional comma-separated Draw/Dispatch event IDs; empty scans all actions.
    """
    return _call(
        "export_shader_catalog",
        {"output_dir": output_dir, "event_ids": _event_id_list(event_ids)},
        timeout=300.0,
    )


@mcp.tool()
def scan_asset_symbols(
    asset_root: str,
    database_path: str = "",
    build_id: str = "",
    max_files: int = 200000,
    max_file_size_mb: int = 2048,
    provider_id: str = "",
    include_recovery_candidates: bool = False,
) -> str:
    """Deterministically inventory an unpacked asset tree and index embedded DXBC/DXIL.

    This stage uses fixed parsers and hashes only. It also imports versioned JSON
    symbol manifests when present. Optional recovery discovery is deliberately
    opt-in so this legacy scan response does not unexpectedly contain a large
    source/IR/binary candidate inventory. It never asks AI to parse or execute
    asset code, and discovery never authorises workspace seeding/apply.

    Args:
        asset_root: Root of the unpacked game assets.
        database_path: Optional SQLite path; a stable LocalAppData path is used if empty.
        build_id: Optional game build/version identity used to separate releases.
        max_files: Safety limit for recursive files.
        max_file_size_mb: Per-file scan limit.
        provider_id: Optional ID from the fixed per-user trusted-provider registry.
            The MCP contract never accepts a registry path, executable, argv, or env.
        include_recovery_candidates: Also discover and value untrusted Shader
            source/IR/binary candidates under the same root.
    """
    try:
        if not isinstance(include_recovery_candidates, bool):
            raise TypeError("include_recovery_candidates must be a boolean")
        service = SymbolService.for_asset_root(asset_root, database_path or None)
        result = service.scan(
            asset_root,
            build_id=build_id,
            max_files=max_files,
            max_file_size_mb=max_file_size_mb,
            provider_id=provider_id,
        )
        if not isinstance(result, dict):
            raise RuntimeError("asset scanner returned an invalid result")
        result = dict(result)
        if include_recovery_candidates:
            result["recoveryInventory"] = discover_recovery_assets(
                asset_root,
                max_files=max(1, min(int(max_files), 50_000)),
                max_file_size_bytes=(
                    max(1, min(int(max_file_size_mb), 64)) * 1024 * 1024
                ),
                max_total_read_bytes=512 * 1024 * 1024,
                max_candidates=_RECOVERY_LEGACY_SCAN_CANDIDATES,
            )
        else:
            result["recoveryInventory"] = None
        return _ok(result)
    except Exception as error:
        return _err(error)


@mcp.tool()
def inspect_asset_shader_recovery(
    asset_root: str,
    capture_facts_json: str = "",
    max_files: int = 50000,
    max_file_size_mb: int = 64,
    max_total_read_mb: int = 512,
    max_candidates: int = _RECOVERY_INSPECT_DEFAULT_CANDIDATES,
) -> str:
    """Discover and value untrusted Shader recovery inputs below an asset root.

    Recognised inputs include common HLSL/GLSL/WGSL/Slang/MSL/engine source,
    SPIR-V assembly, embedded DXBC/DXIL, whole-file SPIR-V, and MetalLib.  This
    tool only reads, parses, hashes, and ranks; it never executes asset code,
    invokes a compiler, seeds a workspace, or applies a Shader.

    Args:
        asset_root: Absolute or relative unpacked-asset root to inspect.
        capture_facts_json: Optional JSON object with stage/profile/entryPoint
            and raw/code/interface/layout hashes used for deterministic ranking.
        max_files: Maximum regular files considered.
        max_file_size_mb: Maximum complete size of one file read.
        max_total_read_mb: Aggregate read budget.
        max_candidates: Maximum source/IR/binary candidates returned.
    """

    try:
        max_files = _recovery_server_limit(
            max_files, "max_files", _RECOVERY_INSPECT_MAX_FILES
        )
        max_file_size_mb = _recovery_server_limit(
            max_file_size_mb,
            "max_file_size_mb",
            _RECOVERY_INSPECT_MAX_FILE_SIZE_MB,
        )
        max_total_read_mb = _recovery_server_limit(
            max_total_read_mb,
            "max_total_read_mb",
            _RECOVERY_INSPECT_MAX_TOTAL_READ_MB,
        )
        max_candidates = _recovery_server_limit(
            max_candidates,
            "max_candidates",
            _RECOVERY_INSPECT_MAX_CANDIDATES,
        )
        capture_facts = None
        if (
            len(capture_facts_json.encode("utf-8", errors="replace"))
            > _RECOVERY_MAX_CAPTURE_FACTS_JSON_BYTES
        ):
            raise ValueError("capture_facts_json exceeds the fixed 64 KiB limit")
        if capture_facts_json.strip():
            capture_facts = json.loads(capture_facts_json)
            if not isinstance(capture_facts, dict):
                raise ValueError("capture_facts_json must decode to a JSON object")
        return _ok(
            discover_recovery_assets(
                asset_root,
                capture_facts,
                max_files=max_files,
                max_file_size_bytes=max_file_size_mb * 1024 * 1024,
                max_total_read_bytes=max_total_read_mb * 1024 * 1024,
                max_candidates=max_candidates,
            )
        )
    except Exception as error:
        return _err(error)


def _one_shot_recovery_context(
    catalog_path: str | Path, workspace: Path
) -> dict[str, Any]:
    """Read only bounded Shader identity fields from the bridge-owned catalog."""

    raw_path = Path(catalog_path).expanduser()
    if raw_path.exists() and raw_path.is_symlink():
        raise RuntimeError("exported Shader catalog must not be a symlink")
    path = raw_path.resolve()
    workspace_root = workspace.resolve()
    if not is_within(workspace_root, path) or not path.is_file():
        raise RuntimeError("exported Shader catalog escaped the one-shot workspace")
    before = path.stat()
    if before.st_size <= 0 or before.st_size > 64 * 1024 * 1024:
        raise RuntimeError("exported Shader catalog size is invalid")
    payload = path.read_bytes()
    after = path.stat()
    if (
        len(payload) != before.st_size
        or after.st_size != before.st_size
        or after.st_mtime_ns != before.st_mtime_ns
    ):
        raise RuntimeError("exported Shader catalog changed while reading")
    try:
        value = json.loads(payload.decode("utf-8-sig", errors="strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("exported Shader catalog is not UTF-8 JSON") from exc
    shaders = value.get("shaders") if isinstance(value, dict) else None
    if not isinstance(shaders, list) or len(shaders) > 4096:
        raise RuntimeError("exported Shader catalog has an invalid Shader array")

    bound: list[dict[str, Any]] = []
    for shader in shaders:
        if not isinstance(shader, dict):
            continue
        if len(bound) >= _RECOVERY_REPORT_MAX_BOUND_SHADERS:
            break
        raw_hash = str(shader.get("rawSha256", "") or "").casefold()
        code_hash = str(shader.get("codeSha256", "") or "").casefold()
        interface_hash = str(shader.get("interfaceHash", "") or "").casefold()
        layout_hash = str(shader.get("layoutHash", "") or "").casefold()
        for name, digest in (
            ("rawSha256", raw_hash),
            ("codeSha256", code_hash),
            ("interfaceHash", interface_hash),
            ("layoutHash", layout_hash),
        ):
            if digest and (
                len(digest) != 64
                or any(character not in "0123456789abcdef" for character in digest)
            ):
                raise RuntimeError("exported Shader catalog %s is invalid" % name)
        try:
            resource_id = int(
                shader.get("shaderResourceId", shader.get("resourceId", 0))
            )
        except (TypeError, ValueError, OverflowError):
            resource_id = 0
        target_profile = shader.get("targetProfile", shader.get("profile", ""))
        if isinstance(target_profile, dict):
            target_profile = target_profile.get("profile", "")
        bound.append(
            {
                "stage": str(shader.get("stage", "") or "")[:64],
                "resourceId": resource_id,
                "entryPoint": str(
                    shader.get("entryPoint", shader.get("entry", "")) or ""
                )[:256],
                "targetProfile": str(target_profile or "")[:128],
                "rawSha256": raw_hash,
                "codeSha256": code_hash,
                "interfaceHash": interface_hash,
                "layoutHash": layout_hash,
                "debugName": str(
                    shader.get("debugName", shader.get("displayName", "")) or ""
                )[:512],
                "debugPath": str(
                    shader.get("debugPath", shader.get("sourcePath", "")) or ""
                )[:2048],
            }
        )
    return {
        "shaders": {"bound": bound},
        "recoveryShaderInputCount": len(shaders),
        "recoveryReportScope": "one-shot capture catalog + asset root",
    }


@mcp.tool()
def match_capture_assets(
    asset_root: str,
    catalog_path: str,
    scan_id: str = "",
    database_path: str = "",
    build_id: str = "",
    rescan: bool = True,
    provider_id: str = "",
) -> str:
    """Match a capture catalog to an unpacked asset tree using programmatic evidence.

    Unique full-blob matches and unique executable+complete-interface+layout
    matches are committed.
    Ambiguous/hashless/layout-only cases are returned as ``NeedsAI`` and are not
    applied to RenderDoc.

    Args:
        asset_root: Root of unpacked assets.
        catalog_path: shader_catalog.v1.json produced by export_capture_symbol_catalog.
        scan_id: Existing scan ID when rescan is false.
        database_path: Optional symbol SQLite path.
        build_id: Game build/version identity.
        rescan: Re-index assets before matching.
        provider_id: Optional registered provider ID used only when rescanning.
    """
    try:
        service = SymbolService.for_asset_root(asset_root, database_path or None)
        if rescan or not scan_id:
            scan = service.scan(
                asset_root,
                build_id=build_id,
                provider_id=provider_id,
            )
            scan_id = scan["scanId"]
        result = service.match(catalog_path, scan_id)
        result["databasePath"] = str(service.database_path)
        return _ok(result)
    except Exception as error:
        return _err(error)


@mcp.tool()
def resolve_capture_symbols(
    asset_root: str,
    output_dir: str = "",
    database_path: str = "",
    build_id: str = "",
    event_ids: str = "",
    apply_verified: bool = True,
    provider_id: str = "",
) -> str:
    """Run capture export, asset scan, deterministic match, table export, and UI reload.

    This is an optional one-shot convenience. Only program-verified aliases are
    applied automatically. The response includes unresolved cases plus a
    bounded, untrusted Shader-recovery inventory summary, capture-Shader top
    candidates, and hash-revalidated source previews for later AI review.

    Args:
        asset_root: Root of unpacked game assets.
        output_dir: Working directory; defaults to a stable LocalAppData workspace.
        database_path: Optional SQLite path.
        build_id: Game build/version identity.
        event_ids: Optional comma-separated event IDs; empty scans all Draw/Dispatch actions.
        apply_verified: Load verified resource aliases into RenderDoc after matching.
        provider_id: Optional ID from the fixed per-user trusted-provider registry.
            No command, executable, registry path, or environment override is accepted.
    """
    try:
        service = SymbolService.for_asset_root(asset_root, database_path or None)
        workspace = (
            Path(output_dir).expanduser().resolve()
            if output_dir
            else default_workspace(asset_root) / "capture"
        )
        workspace.mkdir(parents=True, exist_ok=True)
        exported = ipc.call(
            "export_shader_catalog",
            {
                "output_dir": str(workspace),
                "event_ids": _event_id_list(event_ids),
            },
            timeout=300.0,
        )
        catalog_path = exported.get("catalogPath") or exported.get("path")
        if not catalog_path:
            raise RuntimeError("RenderDoc bridge did not return catalogPath")
        run = service.run(
            asset_root,
            catalog_path,
            build_id=build_id,
            provider_id=provider_id,
        )
        recovery_context = _one_shot_recovery_context(catalog_path, workspace)
        recovery_inventory = discover_recovery_assets(
            asset_root,
            max_files=50_000,
            max_file_size_bytes=64 * 1024 * 1024,
            max_total_read_bytes=512 * 1024 * 1024,
            max_candidates=_RECOVERY_ONE_SHOT_CANDIDATES,
        )
        asset_recovery = _active_asset_recovery_report(
            recovery_inventory, recovery_context, asset_root
        )
        capture_id = run["match"]["captureId"]
        alias_path = workspace / "symbol_aliases.json"
        alias_result = service.export_alias_table(
            capture_id,
            alias_path,
            verified_only=True,
            scan_id=run["scan"]["scanId"],
        )
        applied = None
        if apply_verified:
            applied = ipc.call(
                "load_symbol_aliases",
                {
                    "path": str(alias_path),
                    "confirmed_only": True,
                    "expected_sha256": _file_sha256(alias_path),
                },
                timeout=60.0,
            )
        unresolved = service.unresolved(capture_id)
        return _ok(
            {
                "schema": "renderdoc-ultra-resolve-result/v1",
                "databasePath": str(service.database_path),
                "captureExport": exported,
                "scan": run["scan"],
                "match": run["match"],
                "aliasTable": alias_result,
                "applied": applied,
                "unresolved": unresolved,
                "assetShaderRecovery": asset_recovery,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def get_symbol_match_cases(database_path: str, capture_id: str) -> str:
    """Return only unresolved candidates and their evidence for AI review.

    AI must select a listed ``candidateId``; it may not invent offsets, hashes,
    register bindings, or asset identities.
    """
    try:
        return _ok(SymbolService(database_path).unresolved(capture_id))
    except Exception as error:
        return _err(error)


@mcp.tool()
def get_symbol_match_evidence(
    database_path: str,
    capture_id: str,
    shader_resource_id: int,
    stage: str,
    entry_point: str,
    candidate_id: int = 0,
    top_k: int = 10,
) -> str:
    """Get bounded file strings, asset metadata, runtime layout and hash evidence.

    This fixed program reads at most 512 KiB around an embedded shader and never
    executes asset content. Use it before an AI proposes a candidate.
    """
    try:
        return _ok(
            SymbolService(database_path).evidence(
                capture_id,
                shader_resource_id,
                stage,
                entry_point,
                candidate_id=candidate_id or None,
                top_k=top_k,
            )
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def list_symbol_matches(database_path: str, capture_id: str) -> str:
    """List all deterministic and reviewed candidate associations for a capture."""
    try:
        return _ok(SymbolService(database_path).list_matches(capture_id))
    except Exception as error:
        return _err(error)


@mcp.tool()
def submit_symbol_match(
    database_path: str,
    capture_id: str,
    scan_id: str,
    shader_resource_id: int,
    stage: str,
    entry_point: str,
    candidate_id: int,
    confidence: float,
    rationale: str,
    evidence_id: str,
) -> str:
    """Submit one AI candidate selection for deterministic re-validation.

    A model can only select a candidate previously returned by
    get_symbol_match_cases and must cite its evidence_id. Model/MCP input is not
    a user-authority boundary, so every AI-resolved ambiguity remains provisional
    and is never exported or applied. Rejected physical evidence cannot be forced.
    """
    try:
        service = SymbolService(database_path)
        return _ok(
            service.submit_decision(
                capture_id,
                scan_id,
                shader_resource_id,
                stage,
                entry_point,
                candidate_id,
                confidence,
                rationale,
                evidence_id,
            )
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def export_symbol_alias_table(
    database_path: str,
    capture_id: str,
    output_path: str,
    scan_id: str = "",
) -> str:
    """Export only program-verified, capture-bound aliases for RenderDoc."""
    try:
        return _ok(
            SymbolService(database_path).export_alias_table(
                capture_id,
                output_path,
                verified_only=True,
                scan_id=scan_id,
            )
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def apply_symbol_alias_table(
    database_path: str,
    capture_id: str,
    scan_id: str = "",
) -> str:
    """Re-export verified DB aliases and load those exact bytes into RenderDoc.

    An MCP caller cannot provide an alias-manifest path or self-declare
    ``programVerified``. The service re-derives the table from its local symbol
    database, chooses the output path, and binds the exact file digest into the
    bridge request. This protects the model/MCP trust boundary; it is not a
    defence against a malicious same-user process that controls the IPC folder.
    """
    try:
        service = SymbolService(database_path)
        output_dir = service.database_path.parent / "applied-aliases"
        output_name = hashlib.sha256(capture_id.encode("utf-8")).hexdigest()
        alias_path = output_dir / (output_name + ".v1.json")
        exported = service.export_alias_table(
            capture_id,
            alias_path,
            verified_only=True,
            scan_id=scan_id,
        )
        if (
            not isinstance(exported, dict)
            or exported.get("schema") != "renderdoc-ultra-aliases/v1"
            or exported.get("schemaVersion") != 1
            or exported.get("verifiedOnly") is not True
            or exported.get("captureId") != capture_id
            or Path(str(exported.get("path", "") or "")).resolve()
            != alias_path.resolve()
            or type(exported.get("aliasCount")) is not int
            or exported["aliasCount"] < 0
        ):
            raise RuntimeError("verified alias export returned invalid policy evidence")
        expected_sha256 = _file_sha256(alias_path)
        applied = ipc.call(
            "load_symbol_aliases",
            {
                "path": str(alias_path),
                "confirmed_only": True,
                "expected_sha256": expected_sha256,
                "strict_atomic": True,
            },
            timeout=60.0,
        )
        counts = applied.get("counts") if isinstance(applied, dict) else None
        count_names = (
            "manifestAliases",
            "deterministicAliases",
            "liveBoundAliases",
            "activeValidatedAliases",
            "renamedShaders",
            "skipped",
            "conflicts",
        )
        valid_counts = isinstance(counts, dict) and all(
            type(counts.get(field)) is int and counts[field] >= 0
            for field in count_names
        )
        applied_session_id = str(
            applied.get("captureSessionId", "") if isinstance(applied, dict) else ""
        )
        applied_items = applied.get("applied") if isinstance(applied, dict) else None
        applied_resource_ids = (
            [item.get("resourceId") for item in applied_items]
            if isinstance(applied_items, list)
            and all(isinstance(item, dict) for item in applied_items)
            else []
        )
        valid_applied_items = bool(
            isinstance(applied_items, list)
            and len(applied_items) <= 100000
            and all(
                set(item) == {"resourceId", "displayName"}
                and type(item.get("resourceId")) is int
                and item["resourceId"] > 0
                and isinstance(item.get("displayName"), str)
                and bool(item["displayName"].strip())
                and len(item["displayName"]) <= 512
                for item in applied_items
            )
            and len(applied_resource_ids) == len(set(applied_resource_ids))
        )
        if (
            not isinstance(applied, dict)
            or applied.get("schema") != "renderdoc-ultra-aliases/v1"
            or applied.get("schemaVersion") != 1
            or applied.get("captureId") != capture_id
            or not _is_lower_hex_value(applied_session_id, 32)
            or Path(str(applied.get("path", "") or "")).resolve()
            != alias_path.resolve()
            or applied.get("confirmedOnly") is not True
            or applied.get("strictAtomic") is not True
            or applied.get("atomicity") != "complete-or-recovery-required"
            or applied.get("physicalAtomic") is not False
            or applied.get("recoveryRequired") is not False
            or applied.get("rollbackAvailable") is not True
            or applied.get("recoveryLedgerPublished") is not True
            or not _is_lower_hex_value(
                str(applied.get("transactionId", "") or ""), 32
            )
            or type(applied.get("recoveryResourceCount")) is not int
            or applied.get("recoveryResourceCount") < 0
            or applied.get("committed") is not True
            or not valid_counts
            or counts["skipped"] != 0
            or counts["conflicts"] != 0
            or counts["manifestAliases"]
            != counts["deterministicAliases"]
            or counts["manifestAliases"] != counts["liveBoundAliases"]
            or counts["manifestAliases"] != counts["activeValidatedAliases"]
            or counts["manifestAliases"] != exported["aliasCount"]
            or not valid_applied_items
            or len(applied_items) != counts["renamedShaders"]
            or applied.get("recoveryResourceCount") < counts["renamedShaders"]
            or applied.get("skipped") != []
            or applied.get("conflicts") != []
        ):
            raise RuntimeError(
                "RenderDoc did not prove a complete alias commit with a "
                "capture-bound recovery ledger"
            )
        return _ok(
            {
                "schema": "renderdoc-ultra-alias-apply/v1",
                "aliasTable": exported,
                "manifestSha256": expected_sha256,
                "applied": applied,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def rollback_symbol_alias_table(
    capture_id: str, expected_transaction_id: str = ""
) -> str:
    """Restore and verify all aliases owned by the exact active capture.

    The caller supplies no path or resource list. The bridge accepts only its
    own bounded recovery ledger (or a machine-verifiable already-restored
    state) for the matching capture identity.
    """
    try:
        capture_id = str(capture_id or "").strip().lower()
        if not _is_lower_hex_value(capture_id, 64):
            raise ValueError("capture_id must be a lowercase SHA-256")
        transaction = str(expected_transaction_id or "").strip().lower()
        params = {"expected_capture_id": capture_id}
        if transaction:
            params["expected_transaction_id"] = _strict_lower_hex(
                transaction, 32, "expected_transaction_id"
            )
        rollback = ipc.call("rollback_symbol_aliases", params, timeout=60.0)
        session_id = str(
            rollback.get("captureSessionId", "") if isinstance(rollback, dict) else ""
        )
        transaction_id = str(
            rollback.get("transactionId", "") if isinstance(rollback, dict) else ""
        )
        if (
            not isinstance(rollback, dict)
            or rollback.get("schema") != "renderdoc-ultra-alias-rollback/v1"
            or rollback.get("schemaVersion") != 1
            or str(rollback.get("captureId", "") or "").casefold() != capture_id
            or not _is_lower_hex_value(session_id, 32)
            or not _is_lower_hex_value(transaction_id, 32)
            or (transaction and transaction_id != transaction)
            or rollback.get("status") not in {"restored", "already-restored"}
            or rollback.get("restored") is not True
            or rollback.get("alreadyRestored") is not (
                rollback.get("status") == "already-restored"
            )
            or rollback.get("verified") is not True
            or rollback.get("strictReceipt") is not True
            or rollback.get("captureTokenVerified") is not True
            or rollback.get("originalNamesVerified") is not True
            or rollback.get("physicalAtomic") is not False
            or rollback.get("recoveryRequired") is not False
            or rollback.get("overlayRestored") is not True
            or rollback.get("renameLedgerRestored") is not True
            or type(rollback.get("resourceCount")) is not int
            or rollback["resourceCount"] < 0
            or rollback.get("failures") != []
        ):
            raise RuntimeError(
                "RenderDoc did not return a strict capture-bound alias rollback receipt"
            )
        return _ok(rollback)
    except Exception as error:
        return _err(error)


# ==================== 15. EXTERNAL SHADER TOOLCHAINS / WORKSPACE ====================

@mcp.tool()
def get_shader_repair_context(workspace_path: str) -> str:
    """Locate the exact saved data and extensible local repair interfaces.

    Use only when a compiler/adapter/reflection capability actually fails.
    This reads metadata once: no replay, compilation, config write or grant.
    Native file/shell tools or configured Python MCP can inspect these files,
    author a repair adapter and update a backed-up owner tool registry within
    the user's task authorization. Tool registries pin executables/scripts;
    changed configurations are picked up by the normal service fingerprint.
    Refresh the affected workspace compile binding with
    migrate_shader_workspace_toolchain(in_place=true), then use the ordinary
    compile/ABI/replay/output comparison path. Never forge a validation result.
    """
    try:
        service = _shader_workspace_artifact_service()
        status_error = None
        try:
            status = service.status(workspace_path)
        except Exception as error:
            # A diagnostic entry point must not require the broken execution
            # binding it is meant to explain. This independently checks local
            # workspace/original bytes and returns no replay/compile authority.
            status_error = str(error)[:2048]
            status = service.source_edit_status(workspace_path)
        root = Path(status["workspacePath"]).resolve()
        runtime = Path(sys.executable).resolve().parent
        application = runtime.parent if getattr(sys, "frozen", False) else Path(__file__).resolve().parents[3]
        bridge = application / "integrations/replaylab/python/renderdoc_mcp_bridge"
        if not getattr(sys, "frozen", False):
            bridge = Path(__file__).resolve().parents[2] / "renderdoc_mcp_bridge"
        def artifact(item):
            relative = item.get("path", "") if isinstance(item, Mapping) else ""
            if relative and Path(relative).is_absolute():
                relative = Path(relative).resolve().relative_to(root).as_posix()
            return str(_workspace_file_target(root, relative)) if relative else None
        return _ok({
            "schema": "bread-shader-repair-context/v1", "instanceId": ipc.instance_id,
            "workspacePath": str(root), "workspaceId": status["workspaceId"],
            "stage": status.get("stage"), "entryPoint": status.get("entryPoint"),
            "capture": status.get("capture"), "shader": status.get("shader"),
            "statusDiagnostic": status_error,
            "baseline": {"path": artifact(status.get("baseline")),
                         "rawSha256": status.get("baseline", {}).get("rawSha256"),
                         "abiStatus": status.get("baseline", {}).get("abiStatus")},
            "source": {"path": artifact(status.get("source")),
                       "sha256": status.get("source", {}).get("currentSha256")
                           or status.get("source", {}).get("sha256")},
            "ownerConfiguration": {"tools": str(_shader_tools_config_path()),
                "routes": str(_SHADER_TOOLCHAINS_CONFIG_PATH), "reload": "content-fingerprint",
                "executionPermission": "connection-native-tools-or-enabled-local-execution-policy"},
            "bridgeSourceRoot": str(bridge) if bridge.is_dir() else None,
            "repairMethods": ["plan_shader_recovery", "repair_shader_workspace_source_abi",
                "migrate_shader_workspace_toolchain", "compile_shader_workspace",
                "validate_shader_workspace_candidate", "diagnose_shader_organization_candidate",
                "apply_shader_workspace_shared_resource"],
            "unchangedEvidenceReusable": True, "grantsExecution": False,
            "applyOrCompilePerformed": False,
        })
    except Exception as error:
        return _shader_err(error, "repair-context")


@mcp.tool()
def get_shader_toolchain_capabilities(stage: str) -> str:
    """Report hash-verified format routes and validators for one shader stage.

    Executables, arguments, and both config paths are fixed by the server
    process owner. This read-only probe performs fresh SHA-256 checks but does
    not run a compiler/decompiler and does not modify RenderDoc replay state.
    """
    try:
        return _ok(_shader_toolchain_catalog().diagnostic_matrix(stage))
    except Exception as error:
        return _shader_err(error, "capability-probe")


@mcp.tool()
def plan_shader_toolchain_route(
    shader_path: str,
    stage: str,
    editable_format: str = "",
    capture_encoding: str = "",
    target_api: str = "",
    allow_reconstructed: bool = True,
) -> str:
    """Deterministically plan captured binary -> editable text -> same binary.

    The content is detected and cross-checked with optional capture metadata.
    Exactly tied best routes, format/API contradictions, missing physical target
    profiles, and unavailable hash-pinned operations all fail closed. Returned
    reconstructed source capabilities are candidates, never original-source or
    semantic-equivalence claims.
    """
    try:
        if not isinstance(allow_reconstructed, bool):
            raise ValueError("allow_reconstructed must be a boolean")
        result = _shader_toolchain_catalog().select_round_trip_for_file(
            shader_path,
            stage,
            editable_format=editable_format or None,
            capture_encoding=capture_encoding or None,
            target_api=target_api or None,
            allow_reconstructed=allow_reconstructed,
        )
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "route-plan")


@mcp.tool()
def plan_shader_recovery(
    shader_path: str,
    stage: str,
    editable_format: str = "",
    capture_encoding: str = "",
    target_api: str = "",
    allow_reconstructed: bool = True,
) -> str:
    """Plan deterministic fallback from captured binary to a safe workspace.

    The result distinguishes a full round trip, a compile-only recovery lane,
    and evidence-only handling. It enumerates only process-owned, hash-verified
    route IDs and finite actions. AI may choose one emitted action and may author
    provisional source only when the plan proves a fixed reverse compiler route;
    it can never supply a command/executable or authorize replay apply.
    """

    try:
        if not isinstance(allow_reconstructed, bool):
            raise ValueError("allow_reconstructed must be a boolean")
        result = _shader_toolchain_catalog().plan_recovery_for_file(
            shader_path,
            stage,
            editable_format=editable_format or None,
            capture_encoding=capture_encoding or None,
            target_api=target_api or None,
            allow_reconstructed=allow_reconstructed,
        )
        memory = _shader_route_memory()
        if memory is not None and isinstance(result, dict):
            from .shader_workspace.route_memory import route_key

            key = route_key(
                target_api=result.get("targetApi") or target_api,
                capture_encoding=result.get("captureEncoding") or capture_encoding,
                stage=result.get("stage") or stage,
                target_profile=result.get("targetProfile"),
                editable_format=result.get("editableFormat"),
            )
            result, memo = memory.prefer(result, key)
            result["routeMemory"] = memo
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "recovery-plan")


@mcp.tool()
def run_shader_toolchain_round_trip_smoke(
    shader_path: str,
    output_directory: str,
    stage: str,
    editable_format: str,
    entry_point: str = "main",
    capture_encoding: str = "",
    target_api: str = "",
    allow_reconstructed: bool = True,
) -> str:
    """Run a strict format round trip with fixed, hash-pinned local tools.

    The output directory must not already exist. The input's DirectX target
    profile is parsed from its physical executable token and cannot be supplied
    or overridden by the caller. API-sensitive routes also require the target
    API exported by capture metadata; SPIR-V API/environment is never inferred
    from its module header. Success proves process/output-format checks and
    configured validators only; semantic and RenderDoc replay ABI fields remain
    false until their independent gates run.
    """
    try:
        if not isinstance(allow_reconstructed, bool):
            raise ValueError("allow_reconstructed must be a boolean")
        result = _shader_toolchain_catalog().round_trip_smoke(
            shader_path,
            editable_format,
            output_directory,
            stage,
            entry_point,
            input_format_hint=capture_encoding or None,
            target_api=target_api or None,
            allow_reconstructed=allow_reconstructed,
        )
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "round-trip-smoke")

@mcp.tool()
def create_shader_workspace(
    catalog_path: str,
    shader_key: str,
    workspace_path: str,
    decompiler_tool_id: str = "",
    compiler_tool_id: str = "",
    editable_format: str = "",
) -> str:
    """Create an isolated workspace from one exact capture-catalog shader.

    The executable, fixed-file hashes, argument templates, timeouts, and
    environment policy come only from the server process's trusted local tool
    registry. An MCP caller can select registered tool IDs but cannot provide a
    command, executable, argument list, environment, or registry path.

    This operation copies and hashes the captured baseline. It neither
    decompiles nor changes replay state.

    Args:
        catalog_path: shader_catalog.v1.json exported by the RenderDoc bridge.
        shader_key: Exact catalog shaderKey string.
        workspace_path: New directory to create; an existing path is rejected.
        decompiler_tool_id: Optional legacy registered decompiler tool ID. Leave
            both tool IDs empty to bind the complete trusted automatic route.
        compiler_tool_id: Optional legacy registered compiler tool ID. Leave
            both tool IDs empty to bind the complete trusted automatic route.
        editable_format: Optional routed text format. Empty prefers HLSL for
            DirectX and GLSL for SPIR-V, then selects a complete same-family
            DXBC/DXIL or SPIR-V instruction/IR round trip only when the preferred
            lane is statically incomplete during planning. Native SPIR-V
            assembly additionally requires one integrity-valid, unambiguous
            spirv-val binding and successful baseline/candidate validation. It
            does not cross formats after a selected high-level route fails at
            runtime. An explicit value never switches formats behind the caller.
    """
    try:
        _enforce_active_project_workspace_location(
            Path(workspace_path).expanduser().resolve(), operation="create_shader_workspace"
        )
        result = _shader_workspace_service().create(
            catalog_path,
            shader_key,
            workspace_path,
            decompiler_tool_id or None,
            compiler_tool_id or None,
            editable_format=editable_format,
        )
        return _shader_workspace_response("create", result)
    except Exception as error:
        return _shader_err(error, "workspace-create")


class ShaderWorkspaceLocationError(RuntimeError):
    """A Shader workspace was requested outside the active project."""


def _enforce_active_project_workspace_location(
    workspace: Path, *, operation: str, source_workspace: Path | None = None
) -> dict[str, Any] | None:
    """With an active project, every Shader workspace lives under its root.

    A workspace created elsewhere (for example under ``%LOCALAPPDATA%``) can be
    compiled but never registered, restored or reviewed as project knowledge,
    which silently forces a second full pass later.  Refuse early and name the
    right place.  Without an active project nothing is enforced.
    """

    try:
        status = _active_project_service().status()
    except Exception:
        return None
    paths = status.get("paths")
    if not isinstance(paths, dict) or not paths.get("shaderWorkspaces"):
        return None
    root = Path(str(paths["shaderWorkspaces"])).expanduser().resolve()
    if is_within(root, workspace):
        return {"activeProject": status.get("name"), "workspaceRoot": str(root)}
    if source_workspace is not None and is_within(root, source_workspace.resolve()):
        suggestion = str(source_workspace.resolve().parent / workspace.name)
        hint = "place recovery attempts next to their source workspace"
    else:
        suggestion = str(root / workspace.name)
        hint = (
            "call get_active_shader_workspace_path for the deterministic managed path, "
            "or use a directory under the project Shader workspace root"
        )
    raise ShaderWorkspaceLocationError(
        "%s refused: the active project '%s' owns Shader workspaces under %s, but %s was "
        "requested. Workspaces outside the project cannot be registered, restored or "
        "reviewed, so %s (for example %s)."
        % (operation, status.get("name"), root, workspace, hint, suggestion)
    )


def _shader_recovery_reconstruction_receipt(
    created: Mapping[str, Any],
    execution: Mapping[str, Any],
    representation: Mapping[str, Any],
    workspace_status: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Bind an internally completed recovery decompile to exact Host state."""

    if execution.get("succeeded") is not True:
        return None
    decompiled = execution.get("result")
    recovery_attempt = created.get("recoveryAttempt")
    route_plan = created.get("routePlan")
    status_route_plan = workspace_status.get("routePlan")
    source = workspace_status.get("source")
    capture = workspace_status.get("capture")
    baseline = workspace_status.get("baseline")
    shader = workspace_status.get("shader")
    if not all(
        isinstance(value, Mapping)
        for value in (
            decompiled,
            recovery_attempt,
            route_plan,
            status_route_plan,
            source,
            capture,
            baseline,
            shader,
        )
    ):
        raise RuntimeError(
            "successful Shader recovery omitted its strict reconstruction state"
        )
    workspace_path = str(Path(created.get("workspacePath", "")).expanduser().resolve())
    source_path = str(Path(decompiled.get("sourcePath", "")).expanduser().resolve())
    source_sha256 = str(decompiled.get("sourceSha256", "") or "").strip().lower()
    source_revision = decompiled.get("revision")
    workspace_id = str(created.get("workspaceId", "") or "").strip().lower()
    source_workspace_id = str(
        recovery_attempt.get("sourceWorkspaceId", "") or ""
    ).strip().lower()
    source_plan_sha256 = str(
        recovery_attempt.get("sourceRecoveryPlanSha256", "") or ""
    ).strip().lower()
    target_plan_sha256 = str(route_plan.get("planSha256", "") or "").strip().lower()
    baseline_raw_sha256 = str(
        created.get("baselineRawSha256", "") or ""
    ).strip().lower()
    capture_id = str(created.get("captureId", "") or "").strip().lower()
    decompile_index = recovery_attempt.get("decompileCandidateIndex")
    compile_index = recovery_attempt.get("compileCandidateIndex")
    if not (
        execution.get("attempted") is True
        and _is_lower_hex_value(workspace_id, 32)
        and _is_lower_hex_value(source_workspace_id, 32)
        and _is_lower_hex_value(source_plan_sha256, 64)
        and _is_lower_hex_value(target_plan_sha256, 64)
        and _is_lower_hex_value(baseline_raw_sha256, 64)
        and _is_lower_hex_value(capture_id, 64)
        and _is_lower_hex_value(source_sha256, 64)
        and type(decompile_index) is int
        and decompile_index >= 0
        and type(compile_index) is int
        and compile_index >= 0
        and type(source_revision) is int
        and source_revision >= 0
        and _capture_path_key(decompiled.get("workspacePath"))
        == _capture_path_key(workspace_path)
        and _capture_path_key(workspace_status.get("workspacePath"))
        == _capture_path_key(workspace_path)
        and workspace_status.get("workspaceId") == workspace_id
        and workspace_status.get("revision") == source_revision
        and recovery_attempt.get("targetWorkspaceId") == workspace_id
        and recovery_attempt.get("targetRoutePlanSha256") == target_plan_sha256
        and status_route_plan.get("planSha256") == target_plan_sha256
        and capture.get("captureId") == capture_id
        and baseline.get("rawSha256") == baseline_raw_sha256
        and decompiled.get("baselineCompileVerified") is True
        and decompiled.get("requiresReplayAbiValidation") is True
        and source.get("present") is True
        and _capture_path_key(source.get("path")) == _capture_path_key(source_path)
        and source.get("currentSha256") == source_sha256
        and source.get("decompiledSha256") == source_sha256
        and source.get("modifiedSinceDecompile") is False
        and source.get("lane") == "executable-editable"
        and source.get("origin") == "trusted-decompile-route"
        and source.get("compileEligible") is True
        and source.get("baselineCompileVerified") is True
        and source.get("semanticEquivalenceVerified") is False
        and representation.get("present") is True
        and representation.get("lane") == "executable-editable"
        and _capture_path_key(representation.get("path"))
        == _capture_path_key(source_path)
        and representation.get("sha256") == source_sha256
        and representation.get("compileEligible") is True
        and representation.get("baselineCompileVerified") is True
        and representation.get("semanticEquivalenceVerified") is False
    ):
        raise RuntimeError(
            "successful Shader recovery reconstruction receipt is inconsistent"
        )
    return {
        "schema": "renderdoc-ultra-shader-recovery-reconstruction/v1",
        "schemaVersion": 1,
        "status": "succeeded",
        "sourceWorkspacePath": recovery_attempt.get("sourceWorkspacePath"),
        "workspacePath": workspace_path,
        "sourceWorkspaceId": source_workspace_id,
        "workspaceId": workspace_id,
        "sourceRecoveryPlanSha256": source_plan_sha256,
        "targetRoutePlanSha256": target_plan_sha256,
        "baselineRawSha256": baseline_raw_sha256,
        "captureId": capture_id,
        "shaderResourceId": shader.get("resourceId"),
        "stage": shader.get("stage"),
        "entryPoint": shader.get("entryPoint"),
        "decompileCandidateIndex": decompile_index,
        "compileCandidateIndex": compile_index,
        "sourceRevision": source_revision,
        "sourcePath": source_path,
        "sourceSha256": source_sha256,
        "representationLane": "executable-editable",
        "representationSha256": source_sha256,
        "baselineCompileVerified": True,
    }


@mcp.tool()
def try_shader_workspace_recovery_candidate(
    source_workspace_path: str,
    workspace_path: str,
    expected_recovery_plan_sha256: str,
    expected_source_workspace_id: str,
    expected_baseline_raw_sha256: str,
    expected_capture_id: str,
    decompile_candidate_index: int | None = None,
    compile_candidate_index: int = 0,
) -> str:
    """Try one program-listed alternative toolchain in a new workspace.

    The indices address only ``recoveryPlan.decompileCandidates`` and
    ``compileCandidates`` from the source workspace. The expected workspace,
    baseline raw and capture identities prevent a plan hash from being reused
    for another Shader. A null decompile index is accepted only when the plan
    has no decompile candidates. The server revalidates the current fixed route
    catalog, policy and executable hashes, creates a separate attempt, and runs
    the selected route once. Callers and AI cannot provide route IDs, commands,
    executables, arguments, or environment values. Failure produces a
    non-executable explanatory/binary representation in the new workspace; it
    never mutates or applies replay state.
    """

    try:
        service = _shader_workspace_service()
        _enforce_active_project_workspace_location(
            Path(workspace_path).expanduser().resolve(),
            operation="try_shader_workspace_recovery_candidate",
            source_workspace=Path(source_workspace_path).expanduser(),
        )
        created = service.create_recovery_attempt(
            source_workspace_path,
            workspace_path,
            expected_recovery_plan_sha256=expected_recovery_plan_sha256,
            expected_source_workspace_id=expected_source_workspace_id,
            expected_baseline_raw_sha256=expected_baseline_raw_sha256,
            expected_capture_id=expected_capture_id,
            decompile_candidate_index=decompile_candidate_index,
            compile_candidate_index=compile_candidate_index,
        )
        route_plan = created.get("routePlan")
        decompile_path = (
            route_plan.get("decompile")
            if isinstance(route_plan, Mapping)
            else None
        )
        execution: dict[str, Any] = {
            "attempted": bool(decompile_path),
            "succeeded": False,
            "result": None,
        }
        if decompile_path:
            try:
                execution["result"] = service.decompile(workspace_path)
                execution["succeeded"] = True
            except Exception as error:
                # The isolated target and its tool job/history are intentional
                # recovery evidence.  Keep them inspectable so the caller can
                # select another finite candidate without confusing this
                # failure with the source workspace.
                execution["error"] = str(error)
                execution["type"] = type(error).__name__
                execution["diagnostic"] = classify_shader_failure(
                    error, phase="recovery-decompile-or-baseline-compile-probe"
                )
                _remember_route_decompile_failure(workspace_path, error)
        else:
            execution["reason"] = (
                "the selected recovery plan has no decompile route; a reviewed "
                "source must be promoted before compilation"
            )
        representation = service.representation(
            workspace_path,
            # A failed candidate was already dispatched exactly once above.
            # Materialize its bounded fallback without replaying the same
            # external process under the guise of representation lookup.
            attempt_decompile=execution["succeeded"],
        )
        workspace_status = service.status(workspace_path)
        # A failed external route is still a valid, inspectable attempt result;
        # it is not a successful reconstruction receipt.  Keep its jobs,
        # diagnostics and fallback representation available so orchestration
        # can advance to another listed pair without turning the whole tool
        # response into an invalid-receipt exception.
        reconstruction_receipt = None
        if execution["succeeded"]:
            reconstruction_receipt = _shader_recovery_reconstruction_receipt(
                created,
                execution,
                representation,
                workspace_status,
            )
        return _shader_workspace_response(
            "recovery-candidate-attempt",
            {
                "sourceWorkspacePath": str(
                    Path(source_workspace_path).expanduser().resolve()
                ),
                "workspacePath": str(Path(workspace_path).expanduser().resolve()),
                "created": created,
                "execution": execution,
                "representation": representation,
                "workspaceStatus": workspace_status,
                "reconstructionReceipt": reconstruction_receipt,
                "applied": False,
            },
        )
    except Exception as error:
        return _shader_err(error, "recovery-candidate-attempt")


@mcp.tool()
def prepare_shader_workspace(
    event_id: int,
    stage: str,
    workspace_path: str,
    catalog_output_dir: str = "",
    editable_format: str = "",
    expected_resource_id: int | str | None = None,
    expected_entry_point: str = "",
    expected_raw_sha256: str = "",
    expected_capture_id: str = "",
    expected_capture_session_id: str = "",
    admit_existing: bool = False,
    attempt_reconstruction: bool = False,
) -> str:
    """Export, uniquely select, and bind one event/stage shader workspace for editing.

    For read-only event/frame/algorithm explanation use
    get_current_shader_representation instead. This operation creates a managed
    editing artifact; missing HLSL is not a reason to use it during frame analysis.

    The bridge export is restricted to exactly ``event_id`` and ``stage``.
    Preparation fails closed unless the resulting catalog has exactly one
    physically verified shader use for that pair. Missing embedded or original
    HLSL is expected and never requires user clarification. By default this
    operation returns the bound workspace and available routes without running
    a decompiler, RenderDoc reverse disassembly, or provisional reconstruction.
    The Agent can then choose an explicit reconstruction operation. Set
    ``attempt_reconstruction=true`` only for a deliberate one-shot preparation.
    Empty format selection prefers HLSL, then selects a complete same-family
    native assembly/IR lane when the high-level lane is statically unavailable.
    SPIR-V assembly additionally requires one integrity-valid, unambiguous
    spirv-val binding and actual baseline/candidate validation. An explicit
    format is never changed.

    An opted-in runtime failure is returned as a conclusive observation with the
    complete hash-bound candidate inventories. This tool does not traverse or
    rank the remaining compiler/decompiler pairs. The Agent owns the next
    technical decision and may call ``try_shader_workspace_recovery_candidate``
    with any still-untried registered pair, generate a reviewed provisional
    source, change representation, or choose another available capability.
    Assembly remains instruction text, not reconstructed HLSL. Only when
    reconstruction is explicitly requested and the selected route fails can
    this operation publish RenderDoc disassembly and a hash-bound provisional
    candidate path. The default source-empty representation is a captured
    binary view; ``get_shader_workspace_representation`` can explicitly fetch
    RenderDoc disassembly. Promotion, compilation and fresh replay ABI
    validation are separate operations. Only the executable-editable lane may
    later compile; nothing is applied here.

    If the uncreated managed path already has an exact current-session live
    owner, or a current same-capture source under another catalog/tool layout,
    reuse that workspace and preserve its source and language. Format choices
    apply to newly created artifacts; converting existing source is separate.
    The result names both the requested path and actual workspace path. Existing
    explicitly selected workspaces and drafts are never redirected.

    Args:
        event_id: Draw/dispatch event containing the bound shader.
        stage: Shader stage, for example vertex, fragment/pixel, or compute.
        workspace_path: New workspace directory to create.
        catalog_output_dir: Optional export directory. If empty, a unique sibling
            directory is generated beside the workspace.
        editable_format: Explicit text target. Empty lets fixed program routing
            prefer HLSL/GLSL and then select a complete same-family native
            assembly/IR round trip when the high-level route is statically
            unavailable. SPIR-V native assembly is eligible only with its strict
            spirv-val gate. Missing original HLSL selects a route without
            executing it unless attempt_reconstruction is true.
            Runtime route failures stay in the selected editable format and
            expose the registered candidate inventories for Agent-owned
            replanning; an explicit value never changes the emitted editable
            format behind the caller.
        expected_resource_id: Optional frozen captured Shader ResourceId.
        expected_entry_point: Optional frozen captured entry point.
        expected_raw_sha256: Optional frozen original executable SHA-256.
        expected_capture_id: Optional frozen catalog SHA-256.
        expected_capture_session_id: Optional frozen loaded-capture lifecycle ID.
        admit_existing: Re-admit an existing active-project deterministic
            workspace without overwriting its source or compiled revisions.
        attempt_reconstruction: Explicitly run the selected reconstruction
            route and RenderDoc fallback during preparation. Defaults to false.
    """
    _prepare_started = time.monotonic()
    _prepare_marks: list[tuple[str, float]] = []

    def _mark(label: str) -> None:
        _prepare_marks.append((label, time.monotonic()))

    try:
        event_value = int(event_id)
        if event_value <= 0:
            raise ValueError("event_id must be a positive integer")
        if not str(stage or "").strip():
            raise ValueError("stage is required")
        if type(admit_existing) is not bool:
            raise ValueError("admit_existing must be a boolean")
        if type(attempt_reconstruction) is not bool:
            raise ValueError("attempt_reconstruction must be a boolean")
        # Validate the immutable tool/route catalogs before exporting any
        # capture bytes. A configuration error must remain a zero-effect
        # capability failure, not leave a catalog directory that later causes
        # the Agent to infer an uncertain workspace mutation.
        service = _shader_workspace_service()
        workspace = Path(workspace_path).expanduser().resolve()
        active_binding = _active_capture_catalog_binding()
        if active_binding is not None and catalog_output_dir:
            raise RuntimeError(
                "an active-project Shader cannot bypass its full catalog or "
                "deterministic managed workspace with catalog_output_dir"
            )
        if active_binding is None:
            _enforce_active_project_workspace_location(
                workspace, operation="prepare_shader_workspace"
            )
            if admit_existing and workspace.is_dir() and not catalog_output_dir:
                # A new task Host has no in-memory catalog binding even when
                # the project already owns this workspace. Rebuild that exact
                # event/stage binding using the normal identity-checked route,
                # instead of asking the Agent to manufacture a full-frame
                # catalog or abandon the editable source.
                recovered = json.loads(get_active_shader_workspace_path(
                    event_value, stage,
                    expected_resource_id=expected_resource_id,
                    expected_entry_point=expected_entry_point or None,
                    expected_raw_sha256=expected_raw_sha256,
                    expected_capture_session_id=expected_capture_session_id,
                ))
                if recovered.get("error"):
                    raise RuntimeError(str(recovered["error"]))
                active_binding = _active_capture_catalog_binding()
        cached_selection = (
            None
            if catalog_output_dir
            else _active_capture_catalog_selection(event_value, stage)
        )
        expected_binding_sha256 = ""
        if cached_selection is not None:
            (
                exported,
                catalog_path,
                selected,
                expected_binding_sha256,
            ) = cached_selection
        elif catalog_output_dir:
            catalog_dir = Path(catalog_output_dir).expanduser().resolve()
        else:
            catalog_dir = (
                workspace.parent
                / ".renderdoc-ultra-catalogs"
                / (
                    "%s-e%d-%s"
                    % (workspace.name, event_value, uuid.uuid4().hex)
                )
            ).resolve()
        if cached_selection is None:
            exported = ipc.call(
                "export_shader_catalog",
                {
                    "output_dir": str(catalog_dir),
                    "event_ids": [event_value],
                    "stages": [stage],
                },
                timeout=300.0,
            )
            if not isinstance(exported, dict):
                raise RuntimeError("RenderDoc bridge returned an invalid catalog result")
            catalog_path = exported.get("catalogPath") or exported.get("path")
            if not catalog_path:
                raise RuntimeError("RenderDoc bridge did not return catalogPath")
            selected = select_unique_shader_for_use(
                catalog_path, event_value, stage
            )
        capture_session_id = _strict_lower_hex(
            exported.get("captureSessionId"),
            32,
            "catalog export captureSessionId",
        )
        expected_raw = str(expected_raw_sha256 or "").strip().lower()
        expected_entry = str(expected_entry_point or "")
        expected_capture = str(expected_capture_id or "").strip().lower()
        expected_session = str(expected_capture_session_id or "").strip().lower()
        expected_resource = _coerce_resource_id(expected_resource_id, "expected_resource_id")
        if not _resource_id_matches(expected_resource, selected.key.resource_id):
            raise RuntimeError(_resource_id_mismatch(
                "expected_resource_id", expected_resource_id, selected.key.resource_id))
        if expected_entry and selected.key.entry_point != expected_entry:
            raise RuntimeError(
                "selected Shader entry point does not match expected_entry_point"
            )
        if expected_raw and (
            _strict_lower_hex(expected_raw, 64, "expected_raw_sha256")
            != selected.key.raw_sha256
        ):
            raise RuntimeError(
                "selected Shader bytes do not match expected_raw_sha256"
            )
        if expected_capture and (
            _strict_lower_hex(expected_capture, 64, "expected_capture_id")
            != selected.capture_id
        ):
            raise RuntimeError(
                "selected Shader catalog does not match expected_capture_id"
            )
        if expected_session and (
            _strict_lower_hex(
                expected_session, 32, "expected_capture_session_id"
            )
            != capture_session_id
        ):
            raise RuntimeError(
                "selected Shader lifecycle does not match expected_capture_session_id"
            )
        requested_workspace = workspace
        resolved_live_owner = None
        if active_binding is not None and not catalog_output_dir:
            # New workspaces use the deterministic allocation path. An Agent
            # may explicitly admit existing source from an earlier catalog;
            # the admission below verifies its original physical Shader and
            # immutable catalog independently of the current route policy.
            (
                unused_active_context,
                active_status,
                active_record,
                unused_active_catalog,
            ) = active_binding
            deterministic_workspace = _active_project_service().shader_workspace_path(
                capture_id=selected.capture_id,
                catalog_sha256=_strict_lower_hex(
                    active_record.get("catalogSha256"),
                    64,
                    "active catalogSha256",
                ),
                route_binding_sha256=_active_shader_route_binding_sha256(),
                stage=selected.key.stage,
                shader_resource_id=selected.key.resource_id,
                raw_sha256=selected.key.raw_sha256,
                create=False,
            ).resolve()
            if (workspace == deterministic_workspace and not workspace.exists()
                    and not workspace.is_symlink()):
                # Creating the newly calculated catalog path must not fork an
                # already applied physical Shader into a second workspace.
                # Existing/explicit alternative paths retain their draft semantics.
                resolved_live_owner = _active_applied_shader_workspace(
                    active_status, selected.capture_id, capture_session_id,
                    selected.capture_path, selected.api,
                    {"resourceId": selected.key.resource_id,
                     "rawSha256": selected.key.raw_sha256,
                     "stage": selected.key.stage,
                     "entryPoint": selected.key.entry_point},
                )
                if resolved_live_owner is not None:
                    workspace = resolved_live_owner[0]
                    admit_existing = True
                else:
                    project = _active_project_service()
                    registered = []
                    if active_status.get("scopeConfigured") is True:
                        reuse = project.future_frame_plan(selected.capture_id, active_record["catalogSha256"])
                        registered, unused_diagnostics = _existing_project_shader_sources(
                            project, active_status, reuse, selected.capture_id,
                            {"resourceId": selected.key.resource_id, "rawSha256": selected.key.raw_sha256,
                             "stage": selected.key.stage, "entryPoint": selected.key.entry_point})
                    canonical, unused_diagnostics = _canonical_managed_shader_source(
                        active_status, selected.capture_path, selected.api,
                        {"resourceId": selected.key.resource_id, "rawSha256": selected.key.raw_sha256,
                         "stage": selected.key.stage, "entryPoint": selected.key.entry_point},
                        capture_session_id, registered)
                    if canonical is not None:
                        workspace = Path(canonical["workspacePath"])
                        admit_existing = True
            if workspace != deterministic_workspace and not (
                admit_existing and workspace.is_dir() and not workspace.is_symlink()
                and is_within(_active_project_workspace_root(active_status), workspace)
            ):
                # A current-session replacement may still own the exact
                # original Shader through a workspace created from an earlier
                # catalog revision. Admit that already-existing owner after
                # checking both its manifest and the Bridge's live mutation.
                applied_workspace = _active_applied_shader_workspace(
                    active_status, selected.capture_id, capture_session_id,
                    selected.capture_path, selected.api,
                    {
                        "resourceId": selected.key.resource_id,
                        "rawSha256": selected.key.raw_sha256,
                        "stage": selected.key.stage,
                        "entryPoint": selected.key.entry_point,
                    },
                )
                if applied_workspace is None or workspace != applied_workspace[0]:
                    raise RuntimeError(
                        "workspace_path is not the active project's deterministic "
                        "path, an explicitly admitted existing workspace, or its exact "
                        "live applied Shader workspace"
                    )
            if not is_within(
                _active_project_workspace_root(active_status), workspace
            ):
                raise RuntimeError(
                    "deterministic Shader workspace escaped the active project"
                )
        reused_existing = workspace.exists() or workspace.is_symlink()
        if reused_existing:
            if not admit_existing:
                raise RuntimeError(
                    "workspace already exists; set admit_existing only for an "
                    "active-project workspace with the exact original Shader identity"
                )
            if catalog_output_dir or active_binding is None:
                raise RuntimeError(
                    "existing workspace admission requires the active project's "
                    "verified catalog for the selected event and stage"
                )
            unused_context, active_status, unused_record, unused_catalog = active_binding
            if not is_within(_active_project_workspace_root(active_status), workspace):
                raise RuntimeError(
                    "existing workspace is outside the active project workspace root"
                )
            _mark("admission-checks")
            created = service.status(workspace)
            _mark("status-existing")
            _ensure_workspace_capture_catalog_identity(str(workspace), status=created)
            _mark("catalog-identity")
            existing_shader = created.get("shader")
            existing_capture = created.get("capture")
            existing_baseline = created.get("baseline")
            existing_route_plan = created.get("routePlan")
            owner_identity_verified = False
            # Catalog IDs identify exported scopes, not another source owner.
            # A same-file original with unchanged resource/bytes/API may keep
            # its historical catalog and source without a live replacement.
            from .shader_workspace.canonical_source import capture_path_identity
            if (isinstance(existing_capture, dict) and isinstance(existing_shader, dict)
                    and isinstance(existing_baseline, dict)
                    and capture_path_identity(existing_capture.get("capturePath")) == capture_path_identity(selected.capture_path)
                    and _active_api_key(existing_capture.get("api")) == _active_api_key(selected.api)
                    and existing_shader.get("resourceId") == selected.key.resource_id
                    and existing_shader.get("rawSha256") == selected.key.raw_sha256
                    and existing_baseline.get("rawSha256") == selected.key.raw_sha256):
                owner_identity_verified = True
            if (isinstance(existing_capture, dict) and isinstance(existing_shader, dict)
                    and (existing_capture.get("captureId") != selected.capture_id
                         or existing_shader.get("resourceId") != selected.key.resource_id)
                    and not owner_identity_verified):
                applied_owner = resolved_live_owner or _active_applied_shader_workspace(
                    active_status, selected.capture_id, capture_session_id,
                    selected.capture_path, selected.api,
                    {"resourceId": selected.key.resource_id,
                     "rawSha256": selected.key.raw_sha256,
                     "stage": selected.key.stage,
                     "entryPoint": selected.key.entry_point},
                )
                owner_identity_verified = bool(
                    applied_owner is not None and applied_owner[0] == workspace
                    and applied_owner[1].get("workspaceId") == created.get("workspaceId")
                    and applied_owner[1].get("capture") == existing_capture
                    and applied_owner[1].get("shader") == existing_shader
                )
            if (
                created.get("schema")
                != "renderdoc-ultra-shader-workspace-status/v1"
                or not isinstance(existing_shader, dict)
                or not isinstance(existing_capture, dict)
                or not isinstance(existing_baseline, dict)
                or not isinstance(existing_route_plan, dict)
                or existing_route_plan.get("schema")
                != "renderdoc-ultra-shader-workspace-route-plan/v2"
                or existing_route_plan.get("schemaVersion") != 2
                or _capture_path_key(created.get("workspacePath"))
                != _capture_path_key(str(workspace))
                or created.get("workspaceId") is None
                or capture_path_identity(existing_capture.get("capturePath"))
                != capture_path_identity(selected.capture_path)
                or _active_api_key(existing_capture.get("api")) != _active_api_key(selected.api)
                or (existing_capture.get("captureId") != selected.capture_id
                    and not owner_identity_verified)
                or (existing_shader.get("resourceId") != selected.key.resource_id
                    and not owner_identity_verified)
                or normalize_stage(existing_shader.get("stage"))
                != selected.key.stage
                or existing_shader.get("entryPoint")
                != selected.key.entry_point
                or existing_shader.get("rawSha256")
                != selected.key.raw_sha256
                or existing_baseline.get("rawSha256")
                != selected.key.raw_sha256
            ):
                raise RuntimeError(
                    "existing workspace does not match the exact selected Shader"
                )
            created = dict(created)
            created["admittedExisting"] = True
            created["sourcePreserved"] = True
        else:
            # A language preference must not replace a project's organized
            # GLSL with freshly reconstructed HLSL from the captured baseline.
            # Restore the exact saved document first; Convert to HLSL then
            # migrates its current contents into a separate validated editor.
            preferred_existing_format = editable_format
            if (not preferred_existing_format and selected.encoding == "spirv"
                    and active_binding is not None
                    and active_binding[1].get("scopeConfigured") is True):
                project_replay = _active_project_service().replay_service()
                reuse = project_replay.reuse_plan(selected.capture_id,
                    active_binding[2]["catalogSha256"])
                matching_sources = [candidate for match in reuse.get("matches", [])
                    if (match.get("shader", {}).get("resourceId") == selected.key.resource_id
                        and match.get("shader", {}).get("stage") == selected.key.stage
                        and match.get("shader", {}).get("entryPoint", "") == selected.key.entry_point
                        and match.get("shader", {}).get("rawSha256") == selected.key.raw_sha256)
                    for candidate in match.get("workspaceCandidates", [])
                    if candidate.get("sourceSeedEligible") is True
                    and candidate.get("activeCandidate") is True
                    and candidate.get("matchMode") in {"raw-exact", "code-interface-layout-exact"}]
                if len(matching_sources) == 1:
                    knowledge = project_replay.get_workspace_knowledge(matching_sources[0]["knowledgeId"])
                    preferred_existing_format = knowledge.get("sourceFormat", "hlsl")
            created = service.create(
                catalog_path,
                selected.key.catalog_key,
                workspace,
                editable_format=preferred_existing_format,
                probe_route_features=attempt_reconstruction,
            )
            created["admittedExisting"] = False
            created["sourcePreserved"] = False
        project_source_reuse = None
        if (active_binding is not None and active_binding[1].get("scopeConfigured") is True
                and created.get("routePlan", {}).get("editableFormat") in {"hlsl", "glsl"}):
            # An admitted existing workspace was not written since its status
            # above; a full re-validation here only repeats that work.
            fresh_status = created if reused_existing else service.status(workspace)
            _mark("status-fresh")
            from .shader_workspace.project_source import can_import_project_source
            if can_import_project_source(fresh_status):
                project_replay = _active_project_service().replay_service()
                # Workspace provenance hashes the original exported file; the
                # project indexes its normalized catalog bytes. A retry after
                # failed reconstruction may also admit a standalone export
                # which was never imported into the project at all.
                catalog_revision = ReplayProjectService._capture_status_catalog_sha256(
                    fresh_status["capture"])
                try:
                    reuse = project_replay.reuse_plan(selected.capture_id, catalog_revision)
                except ReplayProjectError as error:
                    if str(error) not in {"capture_id is not imported in this project",
                                          "catalog revision is not imported in this project"}:
                        raise
                    active_project = _active_project_service()
                    # Replay/context checks cross the Host boundary. Keep an
                    # identity snapshot here; import_capture holds its own
                    # short selection lock when publishing the catalog.
                    with active_project.snapshot_active_project(
                        str(active_binding[1].get("workspaceId", "")),
                        str(active_binding[1].get("projectRoot", "")),
                    ):
                        _require_same_active_project(active_binding[1])
                        _ensure_active_workspace_project_capture(
                            active_project, fresh_status,
                            _workspace_active_capture_context(str(workspace), status=fresh_status))
                    reuse = project_replay.reuse_plan(selected.capture_id, catalog_revision)
                candidates = [
                    candidate for match in reuse.get("matches", [])
                    if (match.get("shader", {}).get("resourceId") == selected.key.resource_id
                        and match.get("shader", {}).get("stage") == selected.key.stage
                        and match.get("shader", {}).get("entryPoint", "") == selected.key.entry_point
                        and match.get("shader", {}).get("rawSha256") == selected.key.raw_sha256)
                    for candidate in match.get("workspaceCandidates", [])
                    if candidate.get("sourceSeedEligible") is True
                    and candidate.get("activeCandidate") is True
                    and candidate.get("matchMode") in {"raw-exact", "code-interface-layout-exact"}
                ]
                if len(candidates) == 1:
                    bundle = project_replay.prepare_workspace_source(candidates[0]["knowledgeId"], fresh_status)
                    project_source_reuse = service.import_project_source(workspace, bundle)
        admitted_representation = created.get("representation")
        if (reused_existing and project_source_reuse is None
                and isinstance(admitted_representation, Mapping)
                and admitted_representation.get("lane") == "executable-editable"):
            # status() has already validated this unchanged admitted source and
            # its compiler provenance. representation() would run that complete
            # validation again merely to return the same editable projection.
            representation = dict(admitted_representation)
        else:
            representation = service.representation(
                workspace, attempt_decompile=attempt_reconstruction
            )
        _mark("representation")
        reconstruction_receipt = None
        provisional_reconstruction = None
        if attempt_reconstruction and representation.get("lane") != "executable-editable":
            try:
                bridge_representation = ipc.call(
                    "reverse_shader",
                    {"event_id": event_value, "stage": stage},
                    timeout=300.0,
                )
                if not isinstance(bridge_representation, dict):
                    bridge_representation = {
                        "error": "RenderDoc bridge returned an invalid reverse_shader result"
                    }
            except Exception as error:
                bridge_representation = {"error": str(error)}
            representation = service.representation(
                workspace,
                bridge_response=bridge_representation,
                bridge_event_id=event_value,
            )
            status_for_provisional = service.status(workspace)
            recovery_for_provisional = status_for_provisional.get("recoveryPlan")
            if (
                isinstance(recovery_for_provisional, Mapping)
                and recovery_for_provisional.get("sourceConstructionEligible") is True
            ):
                provisional_reconstruction = (
                    service.prepare_provisional_reconstruction(workspace)
                )
        if exported.get("reusedActiveProjectCatalog") is True:
            # Creation/decompilation can take long enough for the active
            # project or capture to change. Revalidate both before publishing
            # the workspace response; a changed binding fails closed.
            current_binding = _active_capture_catalog_binding()
            if current_binding is None:
                raise RuntimeError("active full-catalog binding disappeared")
            unused_context, unused_project, record, unused_path = current_binding
            if (
                not expected_binding_sha256
                or _active_capture_catalog_binding_sha256(record)
                != expected_binding_sha256
            ):
                raise RuntimeError(
                    "active full-catalog binding changed during workspace preparation"
                )
        # Same reasoning: nothing wrote to an admitted workspace whose source was
        # already an editable lane, so the admission status is still current.
        workspace_status = (
            created
            if reused_existing and project_source_reuse is None
            and representation.get("lane") == "executable-editable"
            and reconstruction_receipt is None and provisional_reconstruction is None
            else service.status(workspace)
        )
        _mark("status-final")
        recovery_plan = workspace_status.get("recoveryPlan")
        decompile_candidates = (
            recovery_plan.get("decompileCandidates", [])
            if isinstance(recovery_plan, Mapping)
            else []
        )
        compile_candidates = (
            recovery_plan.get("compileCandidates", [])
            if isinstance(recovery_plan, Mapping)
            else []
        )
        executable_ready = representation.get("lane") == "executable-editable"
        selectable_alternatives = max(
            0,
            (
                len(decompile_candidates) * max(1, len(compile_candidates))
                if isinstance(decompile_candidates, list)
                and isinstance(compile_candidates, list)
                else 0
            )
            - int(attempt_reconstruction),
        )
        if executable_ready:
            recovery_status = "editable-source-present"
        elif selectable_alternatives:
            recovery_status = "route-candidates-available"
        elif (isinstance(recovery_plan, Mapping)
              and recovery_plan.get("sourceConstructionEligible") is True):
            recovery_status = "source-construction-available"
        else:
            recovery_status = "evidence-only"
        recovery_decision = {
            "schema": "renderdoc-ultra-shader-agent-recovery/v1",
            "schemaVersion": 1,
            "status": recovery_status,
            "editableSourcePresent": executable_ready,
            "reconstructionRequested": attempt_reconstruction,
            "primaryAttemptSucceeded": bool(
                attempt_reconstruction and representation.get("decompileResult")
            ),
            "registeredDecompileCandidateCount": (
                len(decompile_candidates)
                if isinstance(decompile_candidates, list)
                else 0
            ),
            "registeredCompileCandidateCount": (
                len(compile_candidates)
                if isinstance(compile_candidates, list)
                else 0
            ),
            "untriedAlternativePairCount": selectable_alternatives,
        }
        prepared_binding = {
            "schema": "renderdoc-ultra-prepared-shader-workspace-binding/v1",
            "schemaVersion": 1,
            "workspacePath": str(workspace),
            "workspaceId": workspace_status["workspaceId"],
            "captureId": workspace_status["capture"]["captureId"],
            "captureSessionId": capture_session_id,
            "eventId": event_value,
            "stage": selected.key.stage,
            "entryPoint": selected.key.entry_point,
            "originalResourceId": selected.key.resource_id,
            "originalRawSha256": selected.key.raw_sha256,
        }
        _mark("plan")
        timings: dict[str, float] = {}
        previous = _prepare_started
        for label, at in _prepare_marks:
            timings[label] = round(timings.get(label, 0.0) + (at - previous), 3)
            previous = at
        timings["total"] = round(time.monotonic() - _prepare_started, 3)
        try:
            emit_console_event(
                "shader", "info",
                "prepare_shader_workspace 用时 %.1f 秒：%s" % (
                    timings["total"],
                    "、".join("%s %.1fs" % (label, seconds) for label, seconds in timings.items()
                              if label != "total")),
                phase="准备", code="shaderWorkspacePrepareTimings",
                context={"operation": "prepare_shader_workspace"})
        except Exception:
            pass
        return _shader_workspace_response(
            "prepare",
            {
                "workspacePath": str(workspace),
                "timings": timings,
                "requestedWorkspacePath": str(requested_workspace),
                "reusedLiveOwner": resolved_live_owner is not None,
                "reusedExistingSource": reused_existing,
                "binding": prepared_binding,
                "workspaceStatus": workspace_status,
                "catalogExport": exported,
                "selectedShader": selected.key.as_dict(),
                "created": created,
                "recoveryDecision": recovery_decision,
                "reconstructionReceipt": reconstruction_receipt,
                "provisionalReconstruction": provisional_reconstruction,
                "projectSourceReuse": project_source_reuse,
                # Retained for older clients; the object now also carries the
                # explicit representation lane contract.
                "decompiled": representation,
                "representation": representation,
            },
        )
    except Exception as error:
        return _shader_err(error, "workspace-prepare")


@mcp.tool()
def decompile_shader_workspace(workspace_path: str, reference_only: bool = False,
                               validate_for_apply: bool = True,
                               apply_shared_resource: bool = False) -> str:
    """Reconstruct, repair and validate an editable Shader delivery by default.

    The final grouped check compiles, validates ABI, and compares the captured
    original with the reconstructed candidate. Failure preserves source and
    returns a repair-required delivery, never a completed result. Persistent
    replacement occurs only with ``apply_shared_resource=true``. Explicit
    ``validate_for_apply=false`` is a source-only intermediate operation.
    No executable or arguments can be supplied by this request. A repeated
    decompile reuses the pristine, fixed-program source already produced by
    ``prepare_shader_workspace``. Edited, promoted, or migrated source is never
    relabelled as a fresh decompile and remains protected from overwrite.

    With ``reference_only=true``, reconstruct the captured original binary into
    an independent reference file even when the current source is edited. It
    preserves source, organization drafts and compiled candidates; no compile
    or replay operation runs. Read the returned relativePath in complete/file
    mode and incorporate useful code into the proposal. Identical binary/route
    inputs reuse their hash-checked reference instead of running again.

    For explanation of an event, pass, or frame use
    get_current_shader_representation: it reads existing source/native IR without
    this external reconstruction step or an editable workspace. An unsupported
    decompiler is not a blocker for read-only algorithm investigation.
    """
    try:
        if any(type(value) is not bool for value in (reference_only, validate_for_apply, apply_shared_resource)):
            raise ValueError("reference_only, validate_for_apply and apply_shared_resource must be booleans")
        if reference_only and apply_shared_resource:
            raise ValueError("a decompile reference cannot apply a Shader replacement")
        service = _shader_workspace_service()
        if reference_only:
            return _shader_workspace_response(
                "decompile-reference", service.decompile_reference(workspace_path))
        organization_id = (_require_organization_source_review(workspace_path)
                           if validate_for_apply or apply_shared_resource else "")
        result = service.reuse_pristine_decompiled_source(workspace_path)
        if result is None:
            try:
                result = service.decompile(workspace_path)
            except Exception as error:
                _remember_route_decompile_failure(workspace_path, error)
                raise
            result["reusedPreparedSource"] = False
        delivery = (_shader_source_delivery_result(
            workspace_path, str(result.get("sourceSha256") or ""), apply_shared_resource)
            if validate_for_apply or apply_shared_resource else {
                "schema": "bread-shader-delivery/v1", "complete": False,
                "sourceReady": True, "compileValidated": False, "abiValidated": False,
                "outputValidated": False, "readyForApply": False, "applied": False,
                "repairRequired": False, "validationDeferred": True,
                "nextAction": "validate-delivery-after-source-edits"})
        if isinstance(delivery.get("candidate"), dict):
            result["latestCompiled"] = delivery.pop("candidate")
        if delivery.get("abiValidated") is True:
            result.update(requiresReplayAbiValidation=False, replayAbiValidated=True)
        _shader_delivery_organization_state(delivery, organization_id)
        result["delivery"] = delivery
        return _shader_workspace_response("decompile", result)
    except Exception as error:
        response = json.loads(_shader_err(error, "decompile"))
        response.update(ok=False, delivery={"schema": "bread-shader-delivery/v1",
            "complete": False, "readyForApply": False, "applied": False,
            "repairRequired": True, "reason": str(error)[:2000],
            "nextAction": "inspect-reconstruction-diagnostics-and-repair-source"})
        return _ok(response)


def _shader_source_delivery_result(workspace_path: str, expected_source_sha256: str,
                                   apply_shared_resource: bool) -> dict[str, Any]:
    delivery = _shader_organization_manager().validate_source_delivery(
        workspace_path, expected_source_sha256=expected_source_sha256)
    delivery["applyRequested"] = apply_shared_resource
    if apply_shared_resource and delivery.get("readyForApply") is True:
        delivery["applyAttempted"] = True
        try:
            raw = apply_shader_workspace_shared_resource(workspace_path,
                expected_revision=delivery["expectedRevision"],
                expected_candidate_raw_sha256=delivery["expectedCandidateRawSha256"])
            applied = json.loads(raw) if isinstance(raw, str) else raw
            delivery["apply"] = applied
            delivery["applied"] = _shader_delivery_apply_succeeded(applied)
            if not delivery["applied"]:
                reason = ((applied.get("error") or applied.get("reason"))
                          if isinstance(applied, dict) else None)
                raise RuntimeError(str(reason or "replacement returned no valid replacement identity"))
        except Exception as error:
            delivery.update(complete=False, applied=False, repairRequired=True,
                            phase="apply", reason=str(error)[:2000], nextAction="repair-apply-and-retry")
    return delivery


def _shader_delivery_apply_succeeded(value: Any) -> bool:
    if not isinstance(value, Mapping) or value.get("applied") is not True or value.get("error"):
        return False
    replacement = value.get("replacement")
    token = replacement.get("replacementId") if isinstance(replacement, Mapping) else None
    return isinstance(token, str) and re.fullmatch(r"[0-9a-f]{32}", token) is not None


def _shader_delivery_organization_state(delivery: dict[str, Any], organization_id: str) -> None:
    # Validating an executable does not publish/close its organization draft.
    delivery["organizationStillOpen"] = bool(organization_id)
    if organization_id:
        delivery["organizationId"] = organization_id
        if delivery.get("complete") is True:
            delivery["nextAction"] = "finish-reviewed-draft"


@mcp.tool()
def validate_shader_workspace_delivery(workspace_path: str, apply_shared_resource: bool = False) -> str:
    """Validate repaired current source without decompiling or discarding edits.

    Reuse current compile/ABI evidence, compare against the captured original,
    and report exact delivery readiness. Failed source remains editable with
    actionable diagnostics. Apply only when explicitly requested here.
    """
    try:
        if type(apply_shared_resource) is not bool:
            raise ValueError("apply_shared_resource must be a boolean")
        organization_id = _require_organization_source_review(workspace_path)
        delivery = _shader_source_delivery_result(workspace_path, "", apply_shared_resource)
        _shader_delivery_organization_state(delivery, organization_id)
        return _ok_compact({"schema": "bread-shader-delivery-result/v1", "workspacePath": workspace_path,
                    "ok": delivery.get("complete") is True, "delivery": delivery,
                    **({"numericRecovery": delivery["numericRecovery"]}
                       if isinstance(delivery.get("numericRecovery"), dict) else {}),
                    "applied": delivery.get("applied") is True,
                    "state": "validated-source" if delivery.get("complete") else "delivery-repair-required"})
    except Exception as error:
        response = json.loads(_shader_err(error, "source-delivery"))
        response.update(ok=False, delivery={"schema": "bread-shader-delivery/v1",
            "complete": False, "readyForApply": False, "applied": False,
            "repairRequired": True, "reason": str(error)[:2000],
            "nextAction": "repair-current-source-and-revalidate"})
        return _ok(response)


@mcp.tool()
def get_shader_workspace_representation(
    workspace_path: str,
    event_id: int = 0,
    stage: str = "",
    retry_decompile: bool = False,
) -> str:
    """Materialize a non-empty Shader representation with an explicit lane.

    The order is deterministic: tracked executable routed text,
    RenderDoc-native disassembly, then a hash-bound captured binary byte view.
    ``explanatory-ir`` and ``binary-only`` artifacts are facts for human/AI
    explanation and can never be compiled, watched, or applied. Supplying an
    event lets the server obtain and identity-check RenderDoc disassembly; the
    caller cannot inject disassembly text.
    """

    try:
        event_value = int(event_id)
        if event_value < 0:
            raise ValueError("event_id must be zero or a positive integer")
        bridge_response = None
        if event_value:
            if not str(stage or "").strip():
                raise ValueError("stage is required when event_id is supplied")
            try:
                bridge_response = ipc.call(
                    "reverse_shader",
                    {"event_id": event_value, "stage": stage},
                    timeout=300.0,
                )
                if not isinstance(bridge_response, dict):
                    bridge_response = {
                        "error": "RenderDoc bridge returned an invalid reverse_shader result"
                    }
            except Exception as error:
                bridge_response = {"error": str(error)}
        result = _shader_workspace_service().representation(
            workspace_path,
            bridge_response=bridge_response,
            bridge_event_id=event_value or None,
            retry_decompile=retry_decompile,
        )
        return _shader_workspace_response("representation", result)
    except Exception as error:
        return _shader_err(error, "representation")


@mcp.tool()
def promote_shader_workspace_explanation(
    workspace_path: str,
    expected_representation_sha256: str,
    expected_source_sha256: str,
    acknowledge_semantic_equivalence_unverified: bool,
) -> str:
    """Promote a reviewed fixed-language explanation candidate into source.

    Both evidence and candidate hashes are exact race guards. Promotion does
    not compile, validate, or apply anything, and explicitly records that
    semantic equivalence is unverified. The ordinary same-profile compiler,
    complete replay ABI gate, and separately authorized apply remain required.
    """

    try:
        result = _shader_workspace_service().promote_explanatory_source(
            workspace_path,
            expected_representation_sha256=expected_representation_sha256,
            expected_source_sha256=expected_source_sha256,
            acknowledge_semantic_equivalence_unverified=(
                acknowledge_semantic_equivalence_unverified
            ),
        )
        return _shader_workspace_response("promote-explanation", result)
    except Exception as error:
        return _shader_err(error, "source-promotion")


@mcp.tool()
def diagnose_shader_organization_candidate(
    workspace_path: str, source_text: str, expected_source_sha256: str, label: str = "",
) -> str:
    """Compare an isolated unfinished numeric-localization trial to the original.

    After a failed final output comparison, supply a compilable dependency-coherent
    source variant. This diagnostic does not require a complete source-quality
    review, publish source/revisions, apply a persistent replacement or start live
    editing. The exact canonical source hash is a race guard. Physical ABI checks
    and fixed output tolerances still apply; replay is restored after comparison.
    """
    compiled: dict[str, Any] | None = None
    comparison_completed = False
    try:
        service = _shader_workspace_service()
        status = service.status(workspace_path)
        binding = _ensure_workspace_capture_catalog_identity(workspace_path, status=status)
        session = _strict_lower_hex(binding.get("captureSessionId"), 32, "capture session")
        compiled = service.compile_diagnostic_candidate(
            workspace_path, source_text, expected_source_sha256, label)
        if compiled.get("ok") is not True:
            return _ok_compact(compiled)
        params = dict(compiled["comparisonParams"])
        params.update({
            "expected_capture_id": status["capture"]["captureId"],
            "expected_capture_session_id": session,
            "event_id": _shader_organization_anchor_event(status),
            "expected_original_resource_id": status["shader"]["resourceId"],
            "expected_original_sha256": status["baseline"]["rawSha256"],
            "baseline": compiled["baseline"],
            "candidate": {"path": compiled["candidateBlobPath"], "rawSha256": compiled["rawSha256"]},
        })
        result = ipc.call("compare_shader_organization_candidates", params, timeout=300.0)
        if (not isinstance(result, dict)
                or result.get("captureId") != params["expected_capture_id"]
                or result.get("captureSessionId") != session
                or result.get("eventId") != params["event_id"]):
            raise RuntimeError("diagnostic observation returned a different capture binding")
        if result.get("replayRestored") is not True:
            raise RuntimeError("diagnostic observation did not confirm replay restoration")
        comparison_completed = True
        if _bounded_file_sha256(Path(status["source"]["path"]), 64 * 1024 * 1024,
                                "canonical Shader source") != expected_source_sha256:
            raise RuntimeError("canonical source changed during diagnostic comparison")
        receipt = {key: value for key, value in compiled.items()
                   if key not in {"comparisonParams", "capture", "shader", "baseline"}}
        receipt.update(ok=True, phase="comparison", comparisonCompleted=True,
                       observation=result, accepted=result.get("accepted") is True,
                       replayAbiChecked=(int(result.get("sampleCount") or 0) > 0
                                         and (result.get("metrics") or {}).get("coverage") != "unsupported"),
                       applied=False, published=False, sourcePreserved=True,
                       validationScope="diagnostic-captured-event-output")
        atomic_write_shader_json(Path(compiled["receiptPath"]), receipt)
        return _ok_compact(receipt)
    except Exception as error:
        response = json.loads(_shader_err(error, "numeric-diagnostic"))
        response.update(ok=False, diagnosticOnly=True, applied=False, published=False,
                        comparisonCompleted=comparison_completed,
                        phase="comparison" if compiled and compiled.get("compiled") else "compile")
        if isinstance(compiled, dict) and compiled.get("compiled") is True:
            receipt = {key: value for key, value in compiled.items()
                       if key not in {"comparisonParams", "capture", "shader", "baseline"}}
            receipt.update(response)
            receipt["compiled"] = True
            receipt["replayAbiChecked"] = False
            try:
                receipt["sourcePreserved"] = (
                    _bounded_file_sha256(Path(status["source"]["path"]), 64 * 1024 * 1024,
                                         "canonical Shader source") == expected_source_sha256)
            except Exception:
                receipt["sourcePreserved"] = None
            try:
                atomic_write_shader_json(Path(compiled["receiptPath"]), receipt)
            except Exception as persistence_error:
                receipt["receiptPersistenceError"] = str(persistence_error)[:500]
            response = receipt
        return _ok_compact(response)


@mcp.tool()
def compile_shader_workspace(workspace_path: str, prefer_native: bool = True) -> str:
    """Prefer RenderDoc's native source compiler, then its compatible fixed route.

    A native compiler diagnostic or unsupported source capability falls back
    without changing source. Set prefer_native=false when native compilation
    produced an ABI/numeric mismatch and the fixed compiler is the supported
    recovery route. This changes only the compiler, never validation tolerances.

    The source may be HLSL, GLSL, or native editable IR as admitted by the
    manifest's pinned toolchain route. Output is structurally validated as
    exactly one DXBC/DXIL container or one SPIR-V module. A native SPIR-V
    assembly lane additionally requires its hash-bound spirv-val gate. These
    checks prove only the reported structure, tool provenance, and validator
    result—not semantic equivalence. Candidates always remain unapplied here.
    Replay ABI validation and replacement cover D3D11/D3D12 DXBC/DXIL plus
    checked Vulkan/OpenGL native SPIR-V paths for conventional graphics and
    compute stages. Ray/Library replacement remains fail-closed until its
    state-object, shader-group/SBT, and per-export ABI transaction is available.
    """
    try:
        _require_organization_source_review(workspace_path)
        service = _shader_workspace_service()
        result = (service.compile(workspace_path) if prefer_native is True else
                  service.compile(workspace_path, prefer_native=prefer_native))
        return _shader_workspace_response("compile", result)
    except Exception as error:
        return _shader_err(error, "compile")


@mcp.tool()
def convert_shader_workspace_to_hlsl(
    source_workspace_path: str,
    expected_source_sha256: str,
    workspace_path: str = "",
) -> str:
    """Convert the current saved GLSL to a separate editable HLSL workspace.

    The source hash is a mandatory race guard. The old document, candidates and
    complete original comments remain intact. Empty target creates a unique
    sibling workspace. Compile current GLSL, reconstruct HLSL with explicit
    Vulkan locations, compile the result and obtain fresh replay ABI validation.
    Does not apply a replacement or claim output equivalence. Unsupported APIs
    retain their existing native-language route without rewriting user source.
    """
    try:
        result = _shader_workspace_service().convert_to_hlsl(
            source_workspace_path, workspace_path,
            expected_source_sha256=expected_source_sha256,
            host_instance_id=os.environ.get("REPLAYLAB_HOST_INSTANCE_ID"))
        try:
            unused_service, after, unused_request, validated = _fresh_shader_candidate_validation(
                result["workspacePath"], expected_revision=result["compiled"]["revision"],
                expected_candidate_raw_sha256=result["compiled"]["rawSha256"])
            result["abiValidation"] = validated
            result["status"] = after
            result["readyForEditing"] = result["status"].get("abiCompatible") is True
        except Exception as error:
            result["abiValidation"] = {"abiCompatible": False, "error": str(error)}
            result["readyForEditing"] = False
        return _shader_workspace_response("language-convert", result)
    except Exception as error:
        return _shader_err(error, "language-convert")


@mcp.tool()
def migrate_shader_workspace_toolchain(
    source_workspace_path: str,
    workspace_path: str,
    expected_route_plan_sha256: str,
    expected_source_sha256: str,
    recover_legacy_source_lease: bool = False,
    in_place: bool = False,
) -> str:
    """Migrate exact source bytes to the current fixed Shader toolchain.

    Set ``in_place=true`` with identical source and target paths to keep the
    document/workspace identity and refresh only its current compile binding.
    This preserves user edits, archives previous provenance, and invalidates
    all old compiled/ABI evidence. Compile and validate again before applying;
    changing Host versions alone does not require source copies or AI review.

    With the default ``in_place=false``, the source workspace is left unchanged
    and retained as the archive. The new
    workspace starts at revision zero with no imported candidate and may use
    only the same route IDs, input/output formats, and Shader stage as the old
    route plan. Both hashes are mandatory race guards. This operation never
    trusts or imports old candidate/revision/ABI evidence, claims semantic
    equivalence, validates ABI, or applies a Shader replacement.

    ``recover_legacy_source_lease`` supports a controlled recovery of an exact
    token-only legacy ``.workspace-watch.lock`` when no source transaction
    residue is present. The singleton Host archives that lock; malformed,
    current-generation, or journal-bearing leases remain blocked.
    """

    try:
        result = _shader_workspace_service().migrate_toolchain(
            source_workspace_path,
            workspace_path,
            expected_route_plan_sha256=expected_route_plan_sha256,
            expected_source_sha256=expected_source_sha256,
            # This is process-owned singleton-host state, not an MCP argument.
            host_instance_id=os.environ.get("REPLAYLAB_HOST_INSTANCE_ID"),
            recover_legacy_source_lease=recover_legacy_source_lease,
            in_place=in_place,
        )
        return _shader_workspace_response("toolchain-migrate", result)
    except Exception as error:
        return _shader_err(error, "toolchain-migrate")


@mcp.tool()
def get_shader_workspace_status(workspace_path: str) -> str:
    """Report source, candidate and durable draft state for a workspace."""
    try:
        result = _shader_workspace_artifact_service().status(workspace_path)
        try:
            root = Path(str(result.get("workspacePath", "")))
            result["organization"] = _shader_organization_manager().resume_summary(root, result)
        except Exception as error:  # noqa: BLE001 - preserve source status and the recovery failure
            result["organization"] = None
            result["organizationDiagnostic"] = {
                "code": "organization-resume-unavailable",
                "message": (type(error).__name__ + ": " + str(error))[:4096],
            }
        return _shader_workspace_response("status", result)
    except Exception as error:
        return _shader_err(error, "workspace-status")


@mcp.tool()
def show_shader_workspace_source(workspace_path: str) -> str:
    """Show current saved source, reusing its existing matching editor.

    Organization state and old proposal-preview receipts do not identify the
    current saved Source. This operation reads its actual declared bytes and
    does not resave, compile, start live edit or replace replay.
    A clean matching canonical editor keeps its current editability; otherwise
    an editable source draft preserves any independent or unsaved document.
    Saving that draft does not implicitly compile or apply it. Use the
    returned workspaceId and readOnly facts for native UI readback.
    """
    return _show_saved_shader_workspace_source(workspace_path)


def _show_project_shader_source(workspace_path: str, source_sha256: str, *,
                                project_id: str, knowledge_id: str,
                                identity: Mapping[str, Any], capture_id: str,
                                capture_path: str, capture_session_id: str,
                                replay_source: Mapping[str, Any] | None = None,
                                activate_window: bool = True) -> str:
    """Attach a verified restore match to its project source's presentation.

    This Host-only route receives the exact inventory match already checked by
    project restore. Capture-local resource/EID values are presentation routing,
    never source ownership, compile or replacement authority.
    """
    try:
        active_service = _active_project_service()
        active = active_service.status()
        if (active.get("replayProject") or {}).get("projectId") != project_id:
            raise RuntimeError("project changed before saved Shader display")
        replay = active_service.replay_service()
        knowledge = replay.get_workspace_knowledge(knowledge_id)
        if (knowledge.get("rawSha256") != identity.get("rawSha256")
                or knowledge.get("stage") != identity.get("stage")
                or knowledge.get("entryPoint", "") != identity.get("entryPoint", "")):
            raise RuntimeError("saved project source differs from the matched original Shader")
        if knowledge.get("sourceSha256") != source_sha256:
            raise RuntimeError("project source changed before saved Shader display")
        resource_id = identity.get("resourceId")
        anchor = identity.get("anchorEventId")
        if (type(resource_id) is not int or resource_id <= 0
                or (anchor is not None and (type(anchor) is not int or anchor <= 0))):
            raise ValueError("project Shader display resource or EID is invalid")
        # A saved inventory's GPU resource ID is not durable across reopening.
        # Resolve only its exact EID/stage and original program, never search
        # another Shader by filename or redirect from the current UI selection.
        from .ipc_client import _CALL_BINDING
        scoped = _CALL_BINDING.get()
        scoped_session = scoped[1] if scoped is not None and scoped[1] else _effective_capture_scope_session_id()
        if scoped_session and scoped_session != capture_session_id:
            raise RuntimeError("capture session changed before project Shader display")
        if anchor is None:
            raise RuntimeError("project Shader source display needs its representative EID")
        located = json.loads(get_active_shader_workspace_path(anchor, identity["stage"],
            expected_entry_point=identity.get("entryPoint", ""),
            expected_raw_sha256=identity["rawSha256"],
            expected_capture_session_id=capture_session_id))
        if (located.get("error") or located.get("captureSessionId") != capture_session_id
                or located.get("eventId") != anchor or located.get("stage") != identity["stage"]
                or located.get("entryPoint", "") != identity.get("entryPoint", "")
                or located.get("rawSha256") != identity["rawSha256"]
                or type(located.get("shaderResourceId")) is not int or located["shaderResourceId"] <= 0):
            raise RuntimeError("project Shader source target could not be resolved in the current capture")
        resource_id = located["shaderResourceId"]
        capture_id = located["captureId"]
        # Prefer an existing current-target editable source with identical
        # actual bytes. Its manifest now also routes later save/validate/apply;
        # stale origin-workspace metadata remains only source provenance.
        root = _project_source_editor_workspace(active_service, active, replay, knowledge,
            located, source_sha256, capture_session_id)
        binding = {
            "schema": "replaylab-project-shader-display-binding/v1",
            "projectId": _strict_lower_hex(project_id, 32, "project ID"),
            "knowledgeId": _strict_lower_hex(knowledge_id, 32, "knowledge ID"),
            "sourceSha256": _strict_lower_hex(source_sha256, 64, "project source SHA-256"),
            "captureId": _strict_lower_hex(capture_id, 64, "matched capture ID"),
            "capturePath": str(capture_path),
            "captureSessionId": _strict_lower_hex(capture_session_id, 32, "capture session ID"),
            "resourceId": resource_id, "anchorEventId": anchor,
            "stage": identity["stage"], "entryPoint": identity.get("entryPoint", ""),
            "originalRawSha256": _strict_lower_hex(identity.get("rawSha256"), 64, "original Shader SHA-256"),
        }
        if replay_source is not None:
            binding["replaySource"] = {
                "knowledgeId": _strict_lower_hex(replay_source.get("knowledgeId"), 32, "replay source knowledge ID"),
                "sourceSha256": _strict_lower_hex(replay_source.get("sourceSha256"), 64, "replay source SHA-256"),
                "applied": replay_source.get("applied") is True,
            }
        return _show_saved_shader_workspace_source(str(root), project_source_binding=binding,
                                                   activate_window=activate_window)
    except Exception as error:
        return _shader_err(error, "project-source-display")


def _project_source_editor_workspace(active_service: Any, active: Mapping[str, Any], replay: Any,
    knowledge: Mapping[str, Any], located: Mapping[str, Any], source_sha256: str, session: str) -> Path:
    """Open exact current bytes or materialize immutable project text without replay."""
    def matches(path: Path) -> bool:
        if not path.is_absolute() or not (path / "manifest.json").is_file():
            return False
        root = _require_managed_active_workspace(active, str(path))
        manifest = read_json_object(root / "manifest.json", _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
                                    "current project source workspace")
        shader, source = manifest.get("shader") or {}, manifest.get("source") or {}
        if not source.get("path"):
            return False
        source_path = _workspace_file_target(root, source["path"])
        if not source_path.is_file():
            return False
        return bool(shader.get("resourceId") == located["shaderResourceId"]
            and shader.get("rawSha256") == located["rawSha256"]
            and manifest.get("stage") == located["stage"]
            and manifest.get("entryPoint", "") == located.get("entryPoint", "")
            and (manifest.get("capture") or {}).get("captureId") == located["captureId"]
            and _bounded_file_sha256(source_path,
                _WORKSPACE_FILE_MAX_BYTES, "current project source") == source_sha256)

    existing = Path(str(located.get("workspacePath", "")))
    if matches(existing):
        return existing
    # Capture-bound immutable inputs can outlive their original working file.
    # Create a current-target working copy from project knowledge; never use
    # an obsolete manifest as the later compile/apply target or overwrite a
    # divergent working buffer/file merely to show the shared project head.
    selection = _active_capture_catalog_selection(located["eventId"], located["stage"])
    if selection is None:
        raise RuntimeError("project source has no current exact Shader catalog")
    exported, catalog, selected, unused_binding = selection
    if (exported.get("captureSessionId") != session or selected.capture_id != located["captureId"]
            or selected.key.resource_id != located["shaderResourceId"]
            or selected.key.raw_sha256 != located["rawSha256"] or selected.key.stage != located["stage"]
            or selected.key.entry_point != located.get("entryPoint", "")):
        raise RuntimeError("project source target changed before creating its working copy")
    base = active_service.shader_workspace_path(capture_id=located["captureId"],
        catalog_sha256=located.get("activeCatalogSha256", located.get("catalogSha256", "")),
        route_binding_sha256=located["routeBindingSha256"], stage=located["stage"],
        shader_resource_id=located["shaderResourceId"], raw_sha256=located["rawSha256"], create=False)
    base = Path(base).resolve()
    if not is_within(_active_project_workspace_root(dict(active)), base):
        raise RuntimeError("project source working copy escaped the active project")
    # A source revision is not a new editor owner. Keep the path bounded on
    # Windows and stable across publications, retaining legacy slots as hints.
    legacy_target = base.with_name(base.name + "-project-source-" + knowledge["knowledgeId"])
    if matches(legacy_target):
        return legacy_target
    target = base.with_name(_canonical_sha256({
        "domain": "replaylab-project-source-editor/v2", "base": base.name,
        "rawSha256": knowledge["rawSha256"],
        "sourceFormat": knowledge.get("sourceFormat", "hlsl"),
    }))
    service = _shader_workspace_service()
    # Same named copy is reused on reopening. If the user edited that copy,
    # preserve it and derive another deterministic slot from those exact bytes.
    for attempt in range(16):
        if target.is_symlink():
            raise RuntimeError("project source working copy is redirected")
        if matches(target):
            return target
        if not target.exists():
            break
        saved = read_json_object(target / "manifest.json", _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
                                 "preserved project source workspace")
        tracked = saved.get("source")
        if tracked is None:
            # Only a never-populated workspace accepts an initial import.
            # A removed tracked file remains a user-owned, incomplete draft.
            service.status(target)
            break
        tracked_path = _workspace_file_target(target, tracked.get("path"))
        if not tracked_path.is_file():
            digest = "missing:" + _strict_lower_hex(
                tracked.get("sha256"), 64, "preserved draft source SHA-256")
        else:
            status = service.status(target)
            current = status.get("source") or {}
            digest = _strict_lower_hex(current.get("currentSha256"), 64, "preserved draft source SHA-256")
        target = base.with_name(hashlib.sha256((str(target) + digest).encode("utf-8")).hexdigest())
    else:
        raise RuntimeError("too many independently edited project source copies; all edits were preserved")
    with active_service.pin_active_project(str(active["workspaceId"]), str(active["projectRoot"])):
        if not target.exists():
            service.create(catalog, selected.key.catalog_key, target,
                           editable_format=knowledge.get("sourceFormat", "hlsl"))
        empty = service.status(target)
        if ((empty.get("capture") or {}).get("captureId") != located["captureId"]
                or (empty.get("shader") or {}).get("resourceId") != located["shaderResourceId"]
                or (empty.get("baseline") or {}).get("rawSha256") != located["rawSha256"]
                or empty.get("stage") != located["stage"]
                or empty.get("entryPoint", "") != located.get("entryPoint", "")):
            raise RuntimeError("empty project source working copy belongs to a different current Shader")
        bundle = replay.prepare_workspace_source(knowledge["knowledgeId"], empty)
        if bundle.get("sourceSha256") != source_sha256:
            raise RuntimeError("project source head changed before creating its working copy")
        service.import_project_source(target, bundle)
    if not matches(target):
        raise RuntimeError("project source working copy did not preserve the exact saved source")
    return target


def _show_saved_shader_workspace_source(workspace_path: str, *,
                                        project_source_binding: Mapping[str, Any] | None = None,
                                        activate_window: bool = True) -> str:
    try:
        if type(activate_window) is not bool:
            raise ValueError("Shader window activation must be a boolean")
        active_service = _active_project_service()
        active_status = active_service.status()
        root = _require_managed_active_workspace(
            active_status, workspace_path
        )
        manifest = read_json_object(
            root / "manifest.json", _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
            "Shader workspace manifest",
        )
        source = manifest.get("source")
        if not isinstance(source, Mapping):
            raise RuntimeError("shader workspace saved source is unavailable")
        source_path = _workspace_file_target(root, source.get("path"))
        source_sha = _bounded_file_sha256(
            source_path, _WORKSPACE_FILE_MAX_BYTES, "Shader workspace saved source"
        )
        if project_source_binding and source_sha != project_source_binding["sourceSha256"]:
            raise RuntimeError("project source changed before saved Shader display")
        # Display has no replay authority. A project Source may originate in
        # another capture; only the current UI session owns this presentation.
        from .ipc_client import _CALL_BINDING

        direct_binding = _CALL_BINDING.get()
        scoped_session = (
            direct_binding[1] if direct_binding is not None and direct_binding[1]
            else _effective_capture_scope_session_id()
        )
        if project_source_binding:
            capture_session_id = project_source_binding["captureSessionId"]
            if scoped_session and scoped_session != capture_session_id:
                raise RuntimeError("capture session changed before project Shader display")
        elif scoped_session:
            # A Host-owned scope already fixes the requested session. The
            # preview RPC checks the actual loaded capture binding on Qt both
            # before reading Source and immediately before displaying it. A
            # second identity RPC only repeats that read; a stale scope must
            # fail in the Bridge rather than retarget the current capture.
            capture_session_id = _strict_lower_hex(
                scoped_session, 32, "current capture session ID"
            )
        else:
            context = ipc.call("get_current_renderdoc_context", {"identity_only": True}, timeout=30.0)
            capture = context.get("capture") if isinstance(context, Mapping) else None
            if not isinstance(capture, Mapping) or capture.get("loaded") is not True:
                raise RuntimeError("Shader Workspace display requires a current capture")
            capture_session_id = _strict_lower_hex(
                capture.get("captureSessionId"), 32, "current capture session ID"
            )
        if project_source_binding is None and isinstance(active_status.get("replayProject"), Mapping):
            # A registered source must retain the current project head and its
            # exact event binding. An unbound saved-source preview otherwise
            # competes with the old restored project document in the tree.
            shader = manifest.get("shader") or {}
            head = active_service.replay_service().find_current_workspace_source_head(
                source_sha256=source_sha, raw_sha256=shader.get("rawSha256", ""),
                stage=manifest.get("stage", ""), entry_point=manifest.get("entryPoint", ""),
                workspace_id=manifest.get("workspaceId"),
                capture_id=(manifest.get("capture") or {}).get("captureId"),
                target_profile=manifest.get("targetProfile"),
                baseline_abi_sha256=(manifest.get("baseline") or {}).get("abiSha256", ""),
            )
            if head is not None:
                capture = manifest.get("capture") or {}
                return _show_project_shader_source(
                    str(root), source_sha, project_id=head["projectId"],
                    knowledge_id=head["knowledge"]["knowledgeId"],
                    identity={"rawSha256": shader["rawSha256"], "stage": manifest["stage"],
                              "entryPoint": manifest.get("entryPoint", ""),
                              "resourceId": shader["resourceId"],
                              "anchorEventId": _shader_organization_anchor_event(manifest)},
                    capture_id=capture["captureId"], capture_path=capture["capturePath"],
                    capture_session_id=capture_session_id,
                    activate_window=activate_window,
                )
        params = {
            "workspace_path": str(root), "canonical_source": True,
            "expected_source_sha256": source_sha,
            "expected_capture_session_id": capture_session_id,
        }
        if project_source_binding:
            params["project_source_binding"] = dict(project_source_binding)
        if not activate_window:
            # Background project restoration populates editors without changing
            # the user's current tool dock (including a restored frame diagram).
            params["activate_window"] = False
        result = ipc.call("show_shader_organization_preview", params, timeout=30.0)
        if (project_source_binding and isinstance(result, Mapping)
                and result.get("redirectedToCurrentSource") is not True):
            result = {**result, "sourceWorkspacePath": str(root),
                      "projectSourceBinding": dict(project_source_binding)}
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "workspace-source-display")


@mcp.tool()
def read_shader_workspace_source(
    workspace_id: str, capture_session_id: str, source_sha256: str,
    start_line: int = 1, end_line: int = 0, offset: int = 0, limit: int = 12000,
) -> str:
    """Read exact editor source referenced by a Shader chat attachment.

    Attachments contain locations, not code. Use their workspace ID, capture
    session and source SHA-256 to retrieve the retained revision, including
    unsaved text. Select the attachment's line range or each calculation span;
    start_line=1/end_line=0 reads the whole source in pages. offset/nextOffset
    count Unicode characters within the requested range, not bytes or lines.
    Keep identity and range unchanged while following nextOffset until null.
    Each page is at most 24,000 characters on every API/ACP/native connection.
    This tool never saves, recompiles, applies or selects a different EID.

    A snapshot from an old capture session remains historical source evidence;
    currentCaptureMatches does not authorize replay of that old event. Missing
    or expired revisions are explicit errors: do not substitute saved disk text
    or a newer buffer. An equivalent managed saved file must have the exact
    requested source SHA-256; otherwise the intended revision must be reattached.
    """
    try:
        if not isinstance(workspace_id, str) or not re.fullmatch(r"[0-9a-f]{32,64}", workspace_id):
            raise ValueError("workspace_id must be the attachment's Shader workspace ID")
        session = _strict_lower_hex(capture_session_id, 32, "capture_session_id")
        digest = _strict_lower_hex(source_sha256, 64, "source_sha256")
        if any(type(value) is not int for value in (start_line, end_line, offset, limit)):
            raise ValueError("Source range and paging arguments must be integers")
        if start_line < 1 or end_line < 0 or offset < 0 or not 1 <= limit <= 24000:
            raise ValueError("Invalid source range or paging limit (1-24000 characters)")
        return _ok(ipc.call("read_shader_workspace_source", {
            "workspace_id": workspace_id, "capture_session_id": session,
            "source_sha256": digest, "start_line": start_line, "end_line": end_line,
            "offset": offset, "limit": limit}, timeout=30.0))
    except Exception as error:
        return _shader_err(error, "workspace-source-reference")


@mcp.tool()
def get_shader_workspace_ui_state(workspace_id: str = "") -> str:
    """Read the actual Shader Workspace tree and selected editor identity.

    Replay apply, project registration and live-edit startup are separate
    effects. This read-only receipt states whether the native UI has actually
    projected a particular workspace; an absent panel is a delivery diagnostic,
    never a reason to block independent source work or replay validation.
    """
    try:
        target_id = (
            _strict_lower_hex(workspace_id, 32, "workspace_id")
            if workspace_id else ""
        )
        state = ipc.call("get_shader_workspace_ui_state", {}, timeout=30.0)
        if not isinstance(state, Mapping):
            raise RuntimeError("Shader Workspace UI returned an invalid state")
        workspaces = state.get("workspaces")
        if not isinstance(workspaces, list) or len(workspaces) > 512:
            raise RuntimeError("Shader Workspace UI returned an invalid tree")
        target = None
        if target_id:
            matches = [item for item in workspaces
                       if isinstance(item, Mapping)
                       and item.get("workspaceId") == target_id]
            if len(matches) > 1:
                raise RuntimeError("Shader Workspace UI returned a duplicate identity")
            observed = matches[0] if matches else {}
            target = {
                "workspaceId": target_id,
                "found": bool(matches),
                "visibleInWorkspaceTree":
                    observed.get("visibleInWorkspaceTree") is True,
                "editorEligible": observed.get("editorEligible") is True,
                "autoApplyReady": observed.get("autoApplyReady") is True,
                "openInTab": observed.get("openInTab") is True,
                "selected": state.get("selectedWorkspaceId") == target_id,
                "captureId": observed.get("captureId"),
                "stage": observed.get("stage"),
                "entryPoint": observed.get("entryPoint"),
                "resourceId": observed.get("resourceId"),
            }
        return _ok({
            "schema": "replaylab-shader-workspace-ui-state/v1",
            "schemaVersion": 1,
            "observedUnixMs": int(time.time() * 1000),
            "ui": dict(state),
            "target": target,
            "applied": False,
        })
    except Exception as error:
        return _shader_err(error, "workspace-ui-state")


def _shader_organization_semantic_context(
    workspace_path: str, event_id: int, *, include_live_binding_evidence: bool = False
) -> dict[str, Any]:
    """Bind a draft to its exact Shader use; optionally read auxiliary live facts."""

    service = _shader_workspace_service()
    from .shader_workspace.organization import _draft_status
    status = _draft_status(service, workspace_path)
    baseline = status.get("baseline")
    interface = baseline.get("compiledInterface") if isinstance(baseline, dict) else None
    if not isinstance(interface, dict):
        interface = {}
    reconstruction_fidelity = status.get("reconstructionFidelity")
    if not isinstance(reconstruction_fidelity, dict):
        reconstruction_fidelity = {}
    if isinstance(event_id, bool):
        raise TypeError("event_id must be zero or a positive integer")
    event_value = int(event_id)
    if event_value < 0:
        raise ValueError("event_id must be zero or a positive integer")
    if not event_value:
        try:
            event_value = _shader_organization_anchor_event(status)
        except (RuntimeError, ValueError):
            # Incomplete captured annotations must not block opening the text
            # draft. The Agent can supply an exact EID for resource matching.
            event_value = 0
    live: dict[str, Any] = {
        "available": False,
        "eventId": 0,
        "boundTextures": None,
        "pipelineState": None,
        "evidenceStatus": {
            "boundTextures": {"status": "notFetched"},
            "pipelineState": {"status": "notFetched"},
        },
    }
    if event_value:
        from .shader_workspace.errors import CatalogUseNotCoveredError
        try:
            selected = select_unique_shader_for_use(
                status["capture"]["catalogPath"], event_value, status["stage"])
            event_shader = {"resourceId": selected.key.resource_id, "stage": selected.key.stage,
                           "entryPoint": selected.key.entry_point, "rawSha256": selected.key.raw_sha256}
        except CatalogUseNotCoveredError:
            # An existing source may have been created from a smaller export.
            # A new EID does not require another source or changing that catalog.
            # Resolve this one use from the current immutable catalog, or the
            # exact live event when no covering catalog exists.
            from .shader_workspace.canonical_source import api_family, capture_path_identity
            current = _active_live_context(allow_missing_capture_id=True)
            if (capture_path_identity(current["capture"].get("path")) !=
                    capture_path_identity(status["capture"].get("capturePath"))
                    or api_family(current["capture"].get("api")) !=
                    api_family(status["capture"].get("api"))):
                raise ShaderOrganizationError("organization event_id requires the workspace capture")
            event_shader = _active_bound_shader(current, event_value, status["stage"])
            _require_same_active_capture(current, allow_missing_capture_id=True)
        if (event_shader.get("resourceId") != status["shader"]["resourceId"]
                or event_shader.get("stage") != status["stage"]
                or event_shader.get("entryPoint") != status["entryPoint"]
                or event_shader.get("rawSha256") != status["baseline"]["rawSha256"]):
            raise ShaderOrganizationError(
                "organization event_id is not an exact use of the workspace Shader"
            )
        live = {
            "available": False,
            "identityVerified": True,
            "eventId": event_value,
            "captureId": status["capture"]["captureId"],
            "boundTextures": None,
            "pipelineState": None,
            "evidenceStatus": {
                "boundTextures": {"status": "notFetched"},
                "pipelineState": {"status": "notFetched"},
            },
        }
        if include_live_binding_evidence:
            live_before = _workspace_active_capture_context(workspace_path, status=status)
            live_identity = _active_capture_transport_identity(live_before)
            live["captureSessionId"] = live_identity[0]
            # The EID/Shader match above is authoritative. Bound resources and
            # pipeline state are optional interpretation hints: a failed read
            # must not prevent the AI from editing the exact captured source.
            # These older Bridge reads lack expected_capture_id, so discard
            # their results if the live capture/session changes during either.
            for name, method, params, expected_type, max_items in (
                ("boundTextures", "get_bound_textures",
                 {"event_id": event_value, "stage": status["stage"]}, list, 4096),
                ("pipelineState", "get_pipeline_state",
                 {"event_id": event_value}, dict, None),
            ):
                try:
                    evidence = ipc.call(method, params, timeout=60.0)
                    if not isinstance(evidence, expected_type) or (
                        max_items is not None and len(evidence) > max_items
                    ):
                        raise ValueError("invalid %s response" % method)
                    if len(json.dumps(evidence, ensure_ascii=False).encode("utf-8")) > 512 * 1024:
                        raise ValueError("oversized %s response" % method)
                    diagnostic = {"status": "available"}
                except Exception as error:
                    evidence = None
                    diagnostic = {
                        "status": "unavailable",
                        "reason": ("%s: %s" % (type(error).__name__, error))[:800],
                    }
                live_after = _active_live_context(allow_missing_capture_id=True)
                if _active_capture_transport_identity(live_after) != live_identity:
                    raise ShaderOrganizationError(
                        "RenderDoc capture session changed while collecting organization %s"
                        % name
                    )
                live[name] = evidence
                live["evidenceStatus"][name] = diagnostic
            live["available"] = all(
                item["status"] == "available"
                for item in live["evidenceStatus"].values()
            )
    return {
        "schema": "renderdoc-ai-shader-semantic-context/v1",
        "schemaVersion": 1,
        "workspaceId": status["workspaceId"],
        "captureId": status["capture"]["captureId"],
        "shader": status["shader"],
        "stage": status["stage"],
        "entryPoint": status["entryPoint"],
        "rawSha256": str(baseline.get("rawSha256") or ""),
        "targetProfile": status["targetProfile"],
        "reconstructionFidelity": dict(reconstruction_fidelity),
        "interface": {
            "inputSignature": interface.get("inputSignature", []),
            "outputSignature": interface.get("outputSignature", []),
            "readOnlyResources": interface.get("readOnlyResources", []),
            "readWriteResources": interface.get("readWriteResources", []),
            "samplers": interface.get("samplers", []),
            "constantBlocks": interface.get("constantBlocks", []),
        },
        "liveBindingEvidence": live,
        "includeLiveBindingEvidence": include_live_binding_evidence,
        "anchorEventId": event_value,
        "authority": {
            "physicalInterface": "StoredCapturedMetadata",
            "currentReplayAbiValidation": "DeferredUntilFinalPublication",
            "resourceNames": "AIProvisionalUnlessVerifiedBySymbols",
            "parameterNames": "AIProvisionalUnlessVerifiedBySymbols",
            "aiMayChangeRegistersOffsetsOrSemantics": False,
        },
    }


def _local_shader_asset_project() -> tuple[Any, Path, dict[str, Any]]:
    """Read naming configuration without replay validation or catalog scanning."""
    service = _active_project_service()
    snapshot = service._bound_project_snapshot()
    if snapshot is not None:
        return service, snapshot.project_root, json.loads(snapshot.manifest_json)
    root, manifest = service._live_active(validate_shared_artifacts=False)
    selection = service._read_selection()
    if (Path(selection["projectRoot"]).resolve() != root
            or selection["workspaceId"] != manifest["workspaceId"]):
        raise RuntimeError("active project changed while reading naming configuration")
    return service, root, manifest


def _shader_material_context_preparation(
    workspace: Path, target: Mapping[str, Any], service: Any,
    project_root: Path, manifest: Mapping[str, Any], remembered: Mapping[str, Any],
) -> dict[str, Any]:
    """Reuse local semantic vocabulary; never import another draw's offsets."""
    from .shader_asset_semantics import assess_material_semantic_context, semantic_context_summary

    project_id = str(manifest.get("workspaceId") or "")
    root = str(manifest.get("assetRoot") or "")
    local = remembered.get("materialSemanticContext")
    assessed = ([assess_material_semantic_context(
        local, identity=target, project_id=project_id, asset_root=root)]
        if isinstance(local, Mapping) else [])
    usable = [candidate for candidate in assessed if candidate["reuse"]["scope"] != "stale"]
    # Existing project memory is a small exact-Shader lookup, not retrieval.
    # It also covers a fresh workspace for another RDC of the same project.
    database = (Path(service._paths(project_root)["sharedDictionaries"]) / "assets"
                / SHADER_ASSET_RESOLUTIONS_FILENAME)
    if not usable and database.is_file() and not database.is_symlink():
        store = shader_asset_retrieval.ShaderAssetResolutionStore(database)
        memory = store.lookup(_shader_asset_game_key(manifest, Path(root)),
                              str(target.get("rawSha256") or ""), "",
                              str(target.get("stage") or ""), str(target.get("entryPoint") or ""))
        for row in memory.get("resolutions") or []:
            candidate = (row.get("evidence") or {}).get("materialSemanticContext")
            if isinstance(candidate, Mapping):
                assessed.append(assess_material_semantic_context(
                    candidate, identity=target, project_id=project_id, asset_root=root))
    usable = [candidate for candidate in assessed if candidate["reuse"]["scope"] != "stale"]
    if not usable:
        return ({"materialSemanticContextSummary": semantic_context_summary(assessed[0])}
                if assessed else {})
    # Keep other material associations visible as alternatives, never silently
    # merge their fields into one supposedly confirmed material.
    selected = usable[0]
    if len(usable) > 1:
        selected = dict(selected)
        selected["alternativeMaterialContexts"] = [semantic_context_summary(item) for item in usable[1:8]]
    record_path = _workspace_asset_resolution_path(workspace)
    if local != selected:
        _write_workspace_asset_resolution(workspace, {"materialSemanticContext": selected})
    return {"materialSemanticContextSummary": semantic_context_summary(selected, str(record_path)),
            "materialSemanticContextPath": str(record_path)}


def _shader_asset_naming_preparation(
    workspace_path: str, context: Mapping[str, Any], event_id: int
) -> dict[str, Any]:
    """Expose bounded local naming leads without replay reads or asset matching.

    A workspace mirror and a remembered reader selection are useful starting
    points, not proof that resource bytes are unchanged or names were applied.
    In particular, never call the full project status, asset authorization or
    retrieval paths here: they can validate replay artifacts or acquire texture
    pixels before the Agent has even opened its editable draft.
    """
    from .asset_reader_routing import normalize_engine, selected_reader, selection_for_root

    target = {
        "eventId": int(event_id or context.get("anchorEventId") or
                       (context.get("liveBindingEvidence") or {}).get("eventId") or 0),
        "stage": normalize_stage(context.get("stage")),
        "entryPoint": str(context.get("entryPoint") or ""),
        "captureId": str(context.get("captureId") or ""),
        "rawSha256": str(context.get("rawSha256") or "").lower(),
    }
    result: dict[str, Any] = {
        "schema": "bread-shader-asset-naming-preparation/v1",
        "state": "unknown",
        "target": target,
        "assetRootConfigured": None,
        "assetRootAvailable": None,
        "reader": {"state": "not-selected", "availabilityVerified": False},
        "retainedMapping": {
            "state": "absent", "contentFreshness": "not-checked",
            "sourceNamesApplied": "not-checked", "liveAliasesApplied": "not-checked",
        },
        "namingWorkflow": {
            "phases": ["reuse-or-resolve-asset-context", "organize-source-using-material-context",
                       "reconcile-cbuffer-names-and-semantic-fields"],
            "retainedContextIsPublishedNames": False,
            "partialAssetMatchesUsable": True,
            "semanticInferenceAllowed": True,
            "panelTool": "publish_cbuffer_aliases",
            "panelGroupingArgument": "semantic_fields_json",
            "panelGroupingEffect": "display-only",
            "completionEvidence": "publication receipt, or unresolved fields and reasons",
            "recompileForPanelOnlyChanges": False,
        },
        "tools": {
            "project": "get_active_replay_project_status",
            "reader": "verify_unpacked_asset_readers",
            "search": "retrieve_shader_asset_candidates",
            "names": "propose_shader_names_from_asset",
            "source": "rename_shader_workspace_symbols",
            "textures": "publish_shader_resource_names",
            "cbuffers": "publish_cbuffer_aliases",
        },
        "diagnostics": [],
    }
    diagnostics = result["diagnostics"]
    try:
        service, project_root, manifest = _local_shader_asset_project()
        workspace = Path(workspace_path).resolve()
        if not is_within(project_root, workspace):
            raise RuntimeError("Shader workspace is outside the active project; naming context was not reused")
        # A retained material dictionary is not a panel publication. Expose the
        # actual local receipt separately, without replaying or recompiling to
        # rediscover names already persisted by the previous organization.
        naming_receipt_path = workspace / "ai" / "cbuffer-name-publication.json"
        if (not naming_receipt_path.parent.is_symlink()
                and not naming_receipt_path.is_symlink() and naming_receipt_path.is_file()):
            try:
                naming_receipt = read_json_object(naming_receipt_path, 64 * 1024, "CBuffer naming receipt")
                if naming_receipt.get("schema") == "replaylab-cbuffer-name-publication-receipt/v1":
                    counts = naming_receipt.get("counts")
                    counts = counts if isinstance(counts, Mapping) else {}
                    result["retainedPanelPublication"] = {
                        "recordPath": str(naming_receipt_path),
                        "relativePath": "ai/cbuffer-name-publication.json",
                        "operationId": str(naming_receipt.get("operationId") or "")[:128],
                        "appliedAtPublication": naming_receipt.get("applied") is True,
                        "partialAtPublication": naming_receipt.get("partial") is True,
                        "requestedSemanticFields": counts.get("requestedSemanticFields", 0)
                            if type(counts.get("requestedSemanticFields")) is int else 0,
                        "writtenSemanticFields": counts.get("writtenSemanticFields", 0)
                            if type(counts.get("writtenSemanticFields")) is int else 0,
                        "currentDisplayFreshness": "not-checked",
                    }
                    try:
                        delivery = _shader_cbuffer_semantic_delivery(str(workspace))
                        result["retainedPanelPublication"]["sourceFreshness"] = (
                            "current" if delivery["status"] == "complete" else "stale-or-incomplete")
                        result["retainedPanelPublication"]["semanticSourceSha256"] = str(
                            naming_receipt.get("semanticSourceSha256") or "")[:64]
                    except (OSError, ValueError, RuntimeError):
                        result["retainedPanelPublication"]["sourceFreshness"] = "unavailable"
            except (OSError, ValueError) as receipt_error:
                diagnostics.append("retained panel publication: " + str(receipt_error)[:300])
        root_text = str(manifest.get("assetRoot") or "")
        result["assetRootConfigured"] = bool(root_text)
        if not root_text:
            result.update(state="unconfigured", assetRootAvailable=False)
            return result
        root = Path(root_text)
        result["assetRootIdentity"] = hashlib.sha256(str(root.resolve()).replace("\\", "/").casefold().encode("utf-8")).hexdigest()
        available = bool(root.is_dir() and not root.is_symlink()
                         and not getattr(root, "is_junction", lambda: False)())
        result.update(assetRoot=root_text, assetRootAvailable=available,
                      state="needs-resolution" if available else "unavailable")

        try:
            selection_path = Path(service._paths(project_root)["sharedDictionaries"]) / "assets" / ASSET_READER_SELECTION_FILENAME
            if selection_path.exists():
                selected = selection_for_root(
                    read_json_object(selection_path, 1024 * 1024, "asset reader selection"), root)
                engine = normalize_engine(selected.get("engine"))
                readers = {cap: selected_reader(selected, engine, cap)
                           for cap in ("properties", "references")}
                readers = {cap: value for cap, value in readers.items() if value}
                result["reader"] = {
                    "state": "recorded-selection" if readers else "not-selected",
                    "engine": engine, "selectedReaders": readers,
                    "selectionPath": str(selection_path), "availabilityVerified": False,
                }
        except Exception as error:
            result["reader"]["state"] = "unavailable"
            diagnostics.append("reader selection: " + str(error)[:300])

        try:
            remembered = {}
            record_path = _workspace_asset_resolution_path(workspace)
            if record_path.parent.is_symlink():
                raise ValueError("workspace asset record directory is redirected")
            if record_path.exists():
                remembered = read_json_object(record_path, 1024 * 1024, "workspace asset resolution")
                event = remembered.get("eventId")
                assets = remembered.get("resolvedAssets")
                assets = assets if isinstance(assets, list) else []
                matching_rows = [item for item in assets if isinstance(item, Mapping)
                                 and type(item.get("eventId")) is int
                                 and item["eventId"] > 0 and item["eventId"] == target["eventId"]
                                 and normalize_stage(item.get("stage")) == target["stage"]]
                top_target_matches = bool(type(event) is int and event > 0
                                          and event == target["eventId"]
                                          and normalize_stage(remembered.get("stage")) == target["stage"])
                # Older records stored event/stage only on each resolved asset.
                # Keep those usable as local leads without treating a missing
                # root or content binding as a verified match.
                legacy_target_matches = bool("eventId" not in remembered and "stage" not in remembered
                                             and matching_rows)
                recorded_capture = str(remembered.get("captureId") or "")
                capture_matches = (recorded_capture == target["captureId"]
                                   if recorded_capture and target["captureId"] else None)
                target_matches = bool(
                    (top_target_matches or legacy_target_matches) and target["rawSha256"]
                    and str(remembered.get("shaderRawSha256") or "").lower() == target["rawSha256"]
                    and capture_matches is not False
                )
                binding = remembered.get("assetBinding")
                binding = binding if isinstance(binding, Mapping) else {}
                bound_root = str(binding.get("assetRoot") or "")
                root_matches = Path(bound_root).resolve() == root.resolve() if bound_root else None
                mapping = result["retainedMapping"]
                mapping.update(
                    state="same-target-record" if target_matches else "different-target-record",
                    recordPath=str(record_path), targetMatches=target_matches,
                    targetMatchBasis="shader-bytes-and-recorded-event-stage",
                    captureIdentityMatches=capture_matches,
                    matchingTargetAssetCount=(len(matching_rows) if legacy_target_matches
                                              else len(assets) if top_target_matches else 0),
                    assetRootMatches=root_matches, resolvedAssetCount=len(assets),
                    linksPresent=any(isinstance(item, Mapping) and bool(item.get("links")) for item in assets),
                    priorNoSupportedMatch=bool(remembered.get("noSupportedMatch")),
                    workspaceMirrorAuthority=False,
                )
                if available and target_matches and root_matches is not False:
                    result["state"] = "recorded-evidence"
            result.update(_shader_material_context_preparation(
                workspace, target, service, project_root, manifest, remembered))
        except Exception as error:
            result["retainedMapping"]["state"] = "unavailable"
            diagnostics.append("retained mapping: " + str(error)[:300])
    except Exception as error:
        diagnostics.append("project naming context: " + str(error)[:300])

    # Never cut a path into an unusable argument. Oversized names/paths can be
    # recovered through the existing project/source tools; state stays honest.
    if len(json.dumps(result, ensure_ascii=False).encode("utf-8")) > 4096:
        result.pop("assetRoot", None)
        result["reader"].pop("selectionPath", None)
        result["retainedMapping"].pop("recordPath", None)
        if "retainedPanelPublication" in result:
            result["retainedPanelPublication"].pop("recordPath", None)
        result["pathsOmitted"] = True
        diagnostics.append("long paths omitted; use the project tool and workspace ai/asset-resolution.json")
    if len(json.dumps(result, ensure_ascii=False).encode("utf-8")) > 4096:
        result["reader"] = {"state": result["reader"]["state"], "availabilityVerified": False,
                            "detailsOmitted": True}
        result["diagnostics"] = ["oversized optional naming details omitted; inspect the project and retained record"]
    return result


def _proposal_editing_capabilities(proposal_sha256: str) -> dict[str, Any]:
    """Describe existing draft inputs beside their exact current content hash."""
    return {
        "tool": "write_shader_workspace_organization_file",
        "proposalSha256": proposal_sha256,
        "availableInputs": ["edits", "source_file", "content"],
        "atomicEdits": {
            "fields": ["old_text", "new_text"],
            "requiresCurrentProposalHash": True,
            "hashArgument": "expected_proposal_sha256",
            "uniqueSequentialMatches": True,
            "requiresRestructureAnalysis": False,
        },
        "sourceFile": {
            "scope": "current-run-owned-agent-workspace",
            "acceptsArbitraryPaths": False,
        },
        "draftOnly": True,
    }


def _shader_source_review_delivery(snapshot: Mapping[str, Any]) -> dict[str, Any]:
    """Persist complete local facts; the bounded receipt is only a preview.

    This runs beside an existing begin/save, never compiles or reads replay.
    The review gate regenerates facts from source bytes, not this editable file.
    """
    from .shader_organization_review import _regular_path
    from .source_review_observations import source_review_catalog, source_review_observations
    from .shader_workspace.io import atomic_write_bytes

    catalog = source_review_catalog(snapshot)
    raw = json.dumps(catalog, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    root = Path(str(snapshot["workspacePath"]))
    # source_snapshot already authenticated the session. Reject a redirected
    # destination as well; do not turn an optional evidence write into a source edit.
    folder = Path(str(snapshot["reviewPath"])).parent
    _regular_path(root, str(folder / "session.json"))
    target = folder / "source-review-catalog.json"
    if target.is_symlink() or (hasattr(target, "is_junction") and target.is_junction()):
        raise ValueError("Shader source review catalog path is redirected")
    if not target.is_file() or target.read_bytes() != raw:
        atomic_write_bytes(target, raw)
    result = source_review_observations(snapshot)
    result["catalog"].update(relativePath=target.relative_to(root).as_posix(), bytes=len(raw))
    return result


@mcp.tool()
def begin_shader_workspace_organization(
    workspace_path: str,
    event_id: int = 0,
    stage: str = "",
    restart: bool = False,
    include_live_binding_evidence: bool = False,
    agent_file_name: str = "",
) -> str:
    """Open a durable shader draft bound to the current captured source.

    The caller chooses which EID and shader to work on. ``restart`` archives an
    earlier Bread-managed draft without modifying the canonical source. This
    call creates an editable proposal and never compiles or applies it. Live
    texture/pipeline hints are fetched only when explicitly requested; their
    availability is diagnostic and does not gate draft creation.
    ``agent_file_name`` optionally copies the complete current proposal into
    this run's owned Agent directory for local editing and one ``source_file``
    import. A reused draft copies its current proposal, including prior edits.
    The copy's hash is the import CAS; copying does not mean the Agent read it.
    This task must read the current proposal before its first edit. Source reads
    can paginate even for mode=complete: follow nextOffset until null. A final
    finish needs a new complete source review in this task, not an older receipt.
    ``assetNamingPreparation`` reports configured unpacked assets, remembered
    readers and retained mapping references without scanning, live reads or
    compilation. Inspect and reuse already adapted source/evidence first; this
    advisory receipt does not prove names were applied or require rematching.
    """

    try:
        if type(restart) is not bool:
            raise ValueError("restart must be a boolean")
        if type(include_live_binding_evidence) is not bool:
            raise ValueError("include_live_binding_evidence must be a boolean")
        requested_stage = normalize_stage(stage)
        context = _shader_organization_semantic_context(
            workspace_path, event_id,
            include_live_binding_evidence=include_live_binding_evidence,
        )
        actual_stage = normalize_stage(context.get("stage"))
        if requested_stage and requested_stage != actual_stage:
            raise RuntimeError(
                "organization stage differs from the workspace's captured Shader stage"
            )
        result = _shader_organization_manager().begin(
            workspace_path, context, restart=restart
        )
        try:
            result["assetNamingPreparation"] = _shader_asset_naming_preparation(
                str(result.get("workspacePath") or workspace_path), context, event_id)
            for key in ("materialSemanticContextSummary", "materialSemanticContextPath"):
                if key in result["assetNamingPreparation"]:
                    result[key] = result["assetNamingPreparation"].pop(key)
        except Exception as error:
            # Optional naming configuration must not hide a successful draft.
            result["assetNamingPreparation"] = {
                "schema": "bread-shader-asset-naming-preparation/v1", "state": "unknown",
                "diagnostics": [str(error)[:400]],
            }
        from .shader_resource_naming_review import prepare as prepare_resource_naming
        try:
            prepare_resource_naming(result["workspacePath"], result["assetNamingPreparation"])
        except (OSError, ValueError) as naming_record_error:
            result["resourceNamingPreparationDiagnostic"] = str(naming_record_error)[:400]
        result["proposalEditing"] = _proposal_editing_capabilities(result["proposalSourceSha256"])
        try:
            result["cbufferSemanticDelivery"] = _shader_cbuffer_semantic_delivery(
                result["workspacePath"], source_path=str(result.get("sourcePath") or ""))
        except Exception as error:
            result["cbufferSemanticDelivery"] = {"required": True, "status": "pending",
                "reason": "naming-source-inspection-unavailable", "diagnostic": str(error)[:300],
                "recompileRequired": False}
        review_snapshot = None
        try:
            from .shader_organization_review import source_scope_catalog, source_snapshot
            review_snapshot = source_snapshot(str(result["workspacePath"]), str(result["organizationId"]))
            if review_snapshot["sourceSha256"] != result["proposalSourceSha256"]:
                raise RuntimeError("proposal changed before collecting source review facts")
            result["sourceReviewScope"] = source_scope_catalog(review_snapshot)
        except Exception as error:
            # The durable draft is still usable; an unsupported scope inventory
            # must not erase its identity or imply a successful quality review.
            result["sourceReviewScopeError"] = str(error)
        try:
            if review_snapshot is None or review_snapshot["sourceSha256"] != result["proposalSourceSha256"]:
                raise RuntimeError("proposal changed or is unavailable for this begin receipt's source review facts")
            result["sourceReviewObservations"] = _shader_source_review_delivery(review_snapshot)
        except Exception as error:
            # Advisory source facts must never turn a successful draft into an error.
            result["sourceReviewObservationsError"] = str(error)
        if agent_file_name:
            try:
                root = Path(result["workspacePath"]).resolve()
                proposal = Path(result["proposalSourcePath"])
                relative = proposal.relative_to(root).as_posix()
                raw = _read_workspace_text_bytes(_workspace_file_target(root, relative))
                if hashlib.sha256(raw).hexdigest() != result["proposalSourceSha256"]:
                    raise RuntimeError("proposal changed before copying; read the current proposal again")
                result["agentFile"] = _copy_workspace_file_to_agent(
                    agent_file_name, raw, root, relative)
                result["agentFile"].update(
                    organizationId=result["organizationId"],
                    expectedProposalSha256=result["proposalSourceSha256"],
                )
            except Exception as error:
                # Draft creation already succeeded. Preserve its identity and
                # report the copy failure instead of hiding a durable session.
                result["agentFile"] = None
                result["agentFileError"] = str(error)
            compacted = json.loads(_ok_compact(result))
            for key in ("agentFile", "agentFileError", "sourceReviewScope", "sourceReviewScopeError",
                        "sourceReviewObservations", "sourceReviewObservationsError", "proposalEditing",
                        "assetNamingPreparation", "materialSemanticContextSummary", "materialSemanticContextPath",
                        "cbufferSemanticDelivery"):
                if key in result:
                    compacted[key] = result[key]
            return _ok(compacted)
        compacted = json.loads(_ok_compact(result))
        for key in ("sourceReviewScope", "sourceReviewScopeError",
                    "sourceReviewObservations", "sourceReviewObservationsError", "proposalEditing",
                    "assetNamingPreparation", "materialSemanticContextSummary", "materialSemanticContextPath",
                    "cbufferSemanticDelivery"):
            if key in result:
                compacted[key] = result[key]
        return _ok(compacted)
    except Exception as error:
        return _shader_err(error, "organization-begin")


@mcp.tool()
def repair_shader_workspace_source_abi(
    workspace_path: str,
    expected_source_sha256: str,
    source: str,
    acknowledge_semantic_equivalence_unverified: bool,
) -> str:
    """Submit AI-authored HLSL that restores the captured physical ABI.

    Use this when the decompiled workspace source compiles but fails the
    replay ABI gate (``organization-abi-failed`` / ``abi-mismatch``) and the Host's fixed
    SPIRV-Cross repair could not fix it. Read the current source with
    ``read_shader_workspace_file`` and the captured interface from
    ``get_shader_workspace_status`` (``baseline.compiledInterface``,
    ``lastAbiAttempt.comparison``), then send the complete repaired file with
    the exact hash of the source you read. The Host compile-checks it, swaps
    it in, compiles and replay-validates it. Only a candidate whose fresh
    reflection matches the captured ABI stays; otherwise the previous bytes
    are restored and the diagnostics / ABI differences are returned so the
    next attempt can be corrected. Nothing is applied to RenderDoc; semantic
    equivalence stays unverified until separately checked.
    """

    try:
        store = current_task_report_store()
        if store.shader_source_read_required(workspace_path):
            from .shader_organization_review import source_snapshot
            from .shader_source_reads import require_current
            root = Path(workspace_path).resolve()
            target = next((row for row in store.shader_organization_review_state()["targets"]
                           if Path(row["workspacePath"]).resolve() == root), None)
            if target is None:
                raise RuntimeError("current Shader organization source-read target is unavailable")
            organization = target["organizationId"]
            snapshot = source_snapshot(str(root), organization)
            # A draft can differ from the canonical ABI baseline being repaired.
            # Gate the current organization bytes; the repair's own CAS still
            # independently requires expected_source_sha256 for the canonical file.
            require_current(store, str(root), organization, snapshot["sourceSha256"])
        result = _shader_organization_manager().repair_baseline_source(
            workspace_path,
            expected_source_sha256,
            source,
            acknowledge_semantic_equivalence_unverified=(
                acknowledge_semantic_equivalence_unverified
            ),
        )
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "abi-source-repair")


def _project_workspace_knowledge_identity(
    knowledge: Mapping[str, Any]
) -> dict[str, Any]:
    """Project the normal workspace writer record onto its immutable identity."""

    fields = (
        "workspaceId",
        "captureId",
        "originCatalogSha256",
        "originResourceId",
        "stage",
        "entryPoint",
        "rawSha256",
        "codeSha256",
        "layoutHash",
        "interfaceHash",
        "interfaceComplete",
        "baselineAbiSha256",
        "targetProfile",
        "sourceSha256",
        "analysisSha256",
    )
    if any(field not in knowledge for field in fields):
        raise RuntimeError(
            "active project workspace registration omitted identity fields"
        )
    identity = {field: copy.deepcopy(knowledge[field]) for field in fields}
    source_format = knowledge.get("sourceFormat", "hlsl")
    if source_format not in {"hlsl", "glsl"}:
        raise RuntimeError("active project workspace source language is invalid")
    if source_format != "hlsl":
        identity["sourceFormat"] = source_format
    publication_mode = knowledge.get("publicationMode")
    if publication_mode is not None:
        from .shader_source_publication import SOURCE_ONLY_PUBLICATION
        if publication_mode != SOURCE_ONLY_PUBLICATION:
            raise RuntimeError("active project workspace publication mode is invalid")
        identity["publicationMode"] = publication_mode
    compiler = knowledge.get("compilerBinding")
    if compiler is not None:
        if not isinstance(compiler, Mapping):
            raise RuntimeError(
                "active project workspace compiler binding is invalid"
            )
        identity["compilerBinding"] = copy.deepcopy(dict(compiler))
    disassembly = knowledge.get("assemblyDisassemblyArtifacts")
    if disassembly is not None:
        if (
            not isinstance(disassembly, list)
            or len(disassembly) > 2
            or any(not isinstance(item, Mapping) for item in disassembly)
        ):
            raise RuntimeError(
                "active project workspace disassembly identity is invalid"
            )
        clean_disassembly = []
        for item in disassembly:
            clean = copy.deepcopy(dict(item))
            clean.pop("path", None)
            clean.pop("artifactPath", None)
            clean_disassembly.append(clean)
        if clean_disassembly:
            identity["assemblyDisassemblyArtifacts"] = clean_disassembly
    compiled = knowledge.get("compiledCandidate")
    if compiled is not None:
        if not isinstance(compiled, Mapping):
            raise RuntimeError(
                "active project workspace compiled identity is invalid"
            )
        clean_compiled = copy.deepcopy(dict(compiled))
        clean_compiled.pop("artifactPath", None)
        identity["compiledCandidate"] = clean_compiled
    return identity


def _current_workspace_publication_binding(
    status: Mapping[str, Any], *, require_current_candidate: bool = True,
) -> tuple[str, str]:
    """Check the on-disk source, and candidate only for executable publication."""

    root = Path(str(status.get("workspacePath", ""))).resolve()
    source = status.get("source")
    latest = status.get("latestCompiled")
    if not isinstance(source, Mapping):
        raise RuntimeError("project publication needs current source")
    declared_source = Path(str(source.get("path", "")))
    source_path = declared_source.resolve()
    source_sha = _strict_lower_hex(source.get("currentSha256"), 64, "current source SHA-256")
    if (
        source.get("present") is not True
        or source.get("lane") != "executable-editable"
        or source.get("format") not in {"hlsl", "glsl"}
        or declared_source.is_symlink()
        or not source_path.is_file()
        or not is_within(root, source_path)
        or _bounded_file_sha256(source_path, 64 * 1024 * 1024, "workspace source") != source_sha
    ):
        raise RuntimeError("project publication source changed or is not current")
    if not require_current_candidate:
        return source_sha, ""
    if not isinstance(latest, Mapping):
        raise RuntimeError("project publication needs a current compiled candidate")
    abi = latest.get("abiGate")
    declared_candidate = Path(str(latest.get("candidateBlobPath", "")))
    candidate_path = declared_candidate.resolve()
    candidate_sha = _strict_lower_hex(latest.get("rawSha256"), 64, "compiled candidate SHA-256")
    if (
        not isinstance(abi, Mapping)
        or abi.get("status") != "compatible"
        or latest.get("replayAbiValidated") is not True
        or latest.get("abiCompatible") is not True
        or latest.get("requiresReplayAbiValidation") is not False
        or latest.get("validationScope") != "replay-reflection-abi-compatible"
        or status.get("replayAbiValidated") is not True
        or status.get("abiCompatible") is not True
        or latest.get("sourceSha256") != source_sha
        or latest.get("revision") != status.get("revision")
        or declared_candidate.is_symlink()
        or not candidate_path.is_file()
        or not is_within(root, candidate_path)
        or latest.get("byteSize") != candidate_path.stat().st_size
        or _bounded_file_sha256(candidate_path, 512 * 1024 * 1024, "compiled candidate") != candidate_sha
    ):
        raise RuntimeError("project publication candidate ABI or source binding is stale")
    return source_sha, candidate_sha


def _register_reviewed_workspace_with_readback(
    project: Any, workspace_service: Any, workspace_path: str,
    *, before_publish: Callable[[dict[str, Any]], None] | None = None,
    source_only_draft: bool = False,
) -> dict[str, Any]:
    """Publish a source draft or the current ABI-validated source with readback."""

    located = workspace_service.status(workspace_path)
    root = Path(str(located.get("workspacePath", ""))).resolve()
    if root != Path(workspace_path).expanduser().resolve():
        raise RuntimeError("project publication workspace identity changed")
    # Project knowledge is source/candidate evidence, not proof that the Agent
    # followed a particular organization workflow. The project writer verifies
    # the current compiled candidate, while this lease and readback protect the
    # exact workspace revision against a concurrent edit.
    lease = WorkspaceSourceTransactionLease(root)
    lease.acquire()
    try:
        status = workspace_service.status(str(root))
        binding = _current_workspace_publication_binding(
            status, require_current_candidate=not source_only_draft
        )
        if before_publish is not None:
            before_publish(status)
            ready = workspace_service.status(str(root))
            if ready != status or _current_workspace_publication_binding(
                ready, require_current_candidate=not source_only_draft
            ) != binding:
                raise RuntimeError(
                    "workspace changed before project publication"
                )

        publication_options = {
            "require_current_candidate": not source_only_draft,
        }
        if source_only_draft:
            publication_options["include_compiled_candidate"] = False
        from .shader_final_publication import preserve_historical_artifacts
        publication_status = preserve_historical_artifacts(project, status)
        historical = publication_status.get("historicalPublicationEvidence")
        if historical:
            publication_options["expected_head"] = historical["expectedHead"]
        raw_result = project.register_workspace(publication_status, **publication_options)
        knowledge = (
            raw_result.get("knowledge")
            if isinstance(raw_result, Mapping)
            else None
        )
        knowledge_id = (
            str(knowledge.get("knowledgeId", "") or "").strip().lower()
            if isinstance(knowledge, Mapping)
            else ""
        )
        _strict_lower_hex(knowledge_id, 32, "knowledge.knowledgeId")
        published = project.get_workspace_knowledge(knowledge_id)

        status_after = workspace_service.status(str(root))
        if status_after != status or _current_workspace_publication_binding(
            status_after, require_current_candidate=not source_only_draft
        ) != binding:
            raise RuntimeError(
                "workspace changed during project publication"
            )
        return _validated_active_workspace_registration(
            raw_result, status_after, published,
            source_only_draft=source_only_draft,
            allow_historical_manifest=bool(historical),
        )
    finally:
        lease.release()


def _validated_active_workspace_registration(
    result: Any,
    status: Mapping[str, Any],
    published: Any,
    *, source_only_draft: bool = False, allow_historical_manifest: bool = False,
) -> dict[str, Any]:
    """Require publication evidence for the exact on-disk workspace revision.

    ``ReplayProjectService`` performs the publication transaction.  This
    projection is deliberately strict as well: an adapter or test double may
    not turn a bare knowledge id and an arbitrary source digest into proof that
    the shared HLSL, workspace manifest, or current ABI-validated binary was
    actually registered.
    """

    if (
        not isinstance(result, dict)
        or not isinstance(status, Mapping)
        or not isinstance(published, Mapping)
    ):
        raise RuntimeError(
            "active project workspace registration returned invalid evidence"
        )
    knowledge = result.get("knowledge")
    source = status.get("source")
    capture = status.get("capture")
    shader = status.get("shader")
    baseline = status.get("baseline")
    policy = result.get("policy")
    flowcharts = result.get("flowchartArtifacts")
    if not all(
        isinstance(value, Mapping)
        for value in (knowledge, source, capture, shader, baseline, policy)
    ) or not isinstance(flowcharts, list):
        raise RuntimeError(
            "active project workspace registration omitted provenance"
        )
    knowledge_id = str(knowledge.get("knowledgeId", "") or "").strip().lower()
    _strict_lower_hex(knowledge_id, 32, "knowledge.knowledgeId")
    if dict(published) != dict(knowledge):
        raise RuntimeError(
            "active project workspace publication could not be read back exactly"
        )
    identity = _project_workspace_knowledge_identity(knowledge)
    if _canonical_json_sha256(
        identity, "workspace project knowledge identity"
    )[:32] != knowledge_id:
        raise RuntimeError(
            "active project workspace knowledgeId does not match its contents"
        )
    workspace_root = Path(str(status.get("workspacePath", ""))).resolve()
    source_path = Path(str(source.get("path", ""))).resolve()
    manifest_path = Path(str(status.get("manifestPath", ""))).resolve()
    if (
        not workspace_root.is_dir()
        or workspace_root.is_symlink()
        or source.get("present") is not True
        or source.get("lane") != "executable-editable"
        or source.get("format") not in {"hlsl", "glsl"}
        or source_path.is_symlink()
        or not source_path.is_file()
        or not is_within(workspace_root, source_path)
        or manifest_path != (workspace_root / "manifest.json").resolve()
        or manifest_path.is_symlink()
        or not manifest_path.is_file()
    ):
        raise RuntimeError(
            "active project workspace registration source/manifest provenance is invalid"
        )
    source_file_sha256 = _bounded_file_sha256(
        source_path, 64 * 1024 * 1024, "workspace HLSL source"
    )
    manifest_sha256 = _bounded_file_sha256(
        manifest_path, 64 * 1024 * 1024, "workspace manifest"
    )
    if allow_historical_manifest:
        # The caller recovered exact immutable source/candidate/profile evidence
        # and holds a current-head CAS. A restore may update incidental manifest
        # metadata; keep the old record's original digest rather than rewriting
        # its history. All current source/candidate/path checks below still run.
        _strict_lower_hex(knowledge.get("workspaceManifestSha256"), 64, "historical workspace manifest SHA-256")
    source_sha256 = _strict_lower_hex(
        source.get("currentSha256"), 64, "workspace.source.currentSha256"
    )
    expected_source_relative = "knowledge/workspaces/%s.%s" % (knowledge_id, source["format"])
    if (
        result.get("applied") is not False
        or type(result.get("idempotent")) is not bool
        or knowledge.get("workspaceId") != status.get("workspaceId")
        or knowledge.get("captureId") != capture.get("captureId")
        or knowledge.get("originResourceId") != shader.get("resourceId")
        or normalize_stage(knowledge.get("stage"))
        != normalize_stage(status.get("stage", shader.get("stage")))
        or str(knowledge.get("entryPoint", "") or "")
        != str(status.get("entryPoint", shader.get("entryPoint", "")) or "")
        or knowledge.get("rawSha256") != baseline.get("rawSha256")
        or knowledge.get("sourceSha256") != source_sha256
        or knowledge.get("sourceFormat", "hlsl") != source.get("format")
        or source_sha256 != source_file_sha256
        or knowledge.get("sourcePath") != expected_source_relative
        or Path(str(knowledge.get("sourceOriginPath", ""))).resolve()
        != source_path
        or (not allow_historical_manifest and knowledge.get("workspaceManifestSha256") != manifest_sha256)
        or Path(str(knowledge.get("workspacePath", ""))).resolve()
        != workspace_root
        or knowledge.get("targetProfile") != status.get("targetProfile")
        or not isinstance(knowledge.get("registeredAt"), str)
        or not str(knowledge.get("registeredAt", "")).strip()
        or len(flowcharts) > 16
        or policy.get("flowchartExplanatoryOnly") is not True
        or policy.get("physicalEvidence") is not False
        or policy.get("applyAuthorization") is not False
    ):
        raise RuntimeError(
            "active project workspace registration did not match the exact workspace"
        )

    if source_only_draft:
        if (knowledge.get("compiledCandidate") is not None
                or knowledge.get("publicationMode") != "source-only-draft"):
            raise RuntimeError(
                "source-only project draft omitted its durable no-auto-apply restriction"
            )
        return dict(result)

    latest = status.get("latestCompiled")
    expected_compiled: dict[str, Any] | None = None
    if latest is not None and not isinstance(latest, Mapping):
        raise RuntimeError(
            "active project workspace registration compiled status is invalid"
        )
    if isinstance(latest, Mapping):
        fully_validated = all(
            (
                latest.get("replayAbiValidated") is True,
                latest.get("abiCompatible") is True,
                latest.get("requiresReplayAbiValidation") is False,
                latest.get("validationScope")
                == "replay-reflection-abi-compatible",
                latest.get("semanticEquivalenceVerified") is False,
                status.get("replayAbiValidated") is True,
                status.get("abiCompatible") is True,
                latest.get("revision") == status.get("revision"),
            )
        )
        if fully_validated and latest.get("sourceSha256") == source_sha256:
            abi_gate = latest.get("abiGate")
            candidate_path = Path(
                str(latest.get("candidateBlobPath", ""))
            ).resolve()
            if (
                not isinstance(abi_gate, Mapping)
                or abi_gate.get("status") != "compatible"
                or candidate_path.is_symlink()
                or not candidate_path.is_file()
                or not is_within(workspace_root, candidate_path)
            ):
                raise RuntimeError(
                    "active project workspace registration compiled provenance is invalid"
                )
            candidate_sha256 = _bounded_file_sha256(
                candidate_path,
                512 * 1024 * 1024,
                "workspace compiled candidate",
            )
            candidate_raw_sha256 = _strict_lower_hex(
                latest.get("rawSha256"),
                64,
                "workspace.latestCompiled.rawSha256",
            )
            if (
                candidate_raw_sha256 != candidate_sha256
                or latest.get("byteSize") != candidate_path.stat().st_size
            ):
                raise RuntimeError(
                    "active project workspace registration compiled bytes differ"
                )
            expected_compiled = {
                "schema": "renderdoc-ultra-project-compiled-candidate/v1",
                "schemaVersion": 1,
                "rawSha256": candidate_raw_sha256,
                "codeSha256": _strict_lower_hex(
                    latest.get("codeSha256"),
                    64,
                    "workspace.latestCompiled.codeSha256",
                ),
                "byteSize": latest.get("byteSize"),
                "kind": latest.get("kind"),
                "sourceSha256": source_sha256,
                "sourceRevision": status.get("revision"),
                "targetProfile": status.get("targetProfile"),
                "originBaselineAbiSha256": _strict_lower_hex(
                    abi_gate.get("baselineAbiSha256"),
                    64,
                    "workspace.latestCompiled.abiGate.baselineAbiSha256",
                ),
                "originCandidateAbiSha256": _strict_lower_hex(
                    abi_gate.get("candidateAbiSha256"),
                    64,
                    "workspace.latestCompiled.abiGate.candidateAbiSha256",
                ),
                "originAbiReportSha256": _strict_lower_hex(
                    abi_gate.get("reportSha256"),
                    64,
                    "workspace.latestCompiled.abiGate.reportSha256",
                ),
                "originRequestId": str(abi_gate.get("requestId", "") or ""),
                "validationScope": "replay-reflection-abi-compatible",
                "semanticEquivalenceVerified": False,
                "artifactPath": (
                    "knowledge/workspaces/binaries/%s.bin"
                    % candidate_raw_sha256
                ),
            }
            if not expected_compiled["originRequestId"]:
                raise RuntimeError(
                    "active project workspace registration omitted the ABI request id"
                )
        elif any(
            (
                latest.get("replayAbiValidated") is True,
                latest.get("abiCompatible") is True,
                latest.get("validationScope")
                == "replay-reflection-abi-compatible",
            )
        ) and latest.get("sourceSha256") == source_sha256:
            raise RuntimeError(
                "active project workspace registration has inconsistent ABI validation"
            )

    published_compiled = knowledge.get("compiledCandidate")
    if expected_compiled is None:
        raise RuntimeError(
            "active project publication requires the current ABI-validated "
            "compiled candidate"
        )
    elif not isinstance(published_compiled, Mapping) or dict(
        published_compiled
    ) != expected_compiled:
        raise RuntimeError(
            "active project compiled candidate does not match the exact workspace"
        )
    return dict(result)


def _shader_cbuffer_semantic_delivery(workspace_path: str, candidate_sha256: str = "",
                                     source_path: str = "", *,
                                     display_identity: Mapping[str, Any] | None = None,
                                     original_shader_sha256: str = "") -> dict:
    from .shader_workspace.naming_delivery import semantic_delivery, source_context
    from .shader_organization_review import canonical_source_path, _read_bytes
    from .shader_semantic_delivery import MAX_RECEIPT_BYTES, load_display_identity

    root = Path(workspace_path).resolve()
    source = source_path or canonical_source_path(str(root))
    _, raw = _read_bytes(root, source, 4 * 1024 * 1024)
    receipt = None
    path = root / "ai" / "cbuffer-name-publication.json"
    if path.is_file() and not path.is_symlink() and not path.parent.is_symlink():
        try:
            receipt = read_json_object(path, MAX_RECEIPT_BYTES, "CBuffer naming receipt")
        except (OSError, ValueError):
            pass
    from .shader_resource_naming_review import aggregate
    context = source_context(root, raw, source)
    if display_identity is None:
        display_identity = load_display_identity(str(root))
    return aggregate(semantic_delivery(raw, receipt, candidate_sha256, context=context,
        display_identity=display_identity, original_shader_sha256=original_shader_sha256), root, raw, context)


def _shader_cbuffer_display_observation(status: Mapping[str, Any]) -> dict[str, Any]:
    """Read current UI/cache identity, never select an EID or execute replay."""
    original = str((status.get("baseline") or {}).get("rawSha256") or
                   (status.get("shader") or {}).get("rawSha256") or "")
    observation = {"status": "refresh-required", "originalRawSha256": original,
                   "refreshTool": "publish_cbuffer_aliases"}
    bound_capture = status.get("capture") or {}
    bound_shader = status.get("shader") or {}
    if (not re.fullmatch(r"[0-9a-f]{64}", original) or
            not re.fullmatch(r"[0-9a-f]{64}", str(bound_capture.get("captureId") or "")) or
            not str(bound_shader.get("resourceId") or "").isdigit() or
            int(bound_shader.get("resourceId") or 0) <= 0):
        return observation
    try:
        context = _active_live_context(require_event_state=False)
        capture = context.get("capture") or {}
        if capture.get("captureId") != (status.get("capture") or {}).get("captureId"):
            return observation
        result = ipc.call("get_shader_cbuffer_display_identity", {
            "expected_capture_id": capture["captureId"],
            "expected_capture_session_id": capture["captureSessionId"],
            "expected_original_resource_id": (status.get("shader") or {}).get("resourceId"),
            "expected_original_sha256": original, "stage": status.get("stage"),
            "entry_point": status.get("entryPoint") or ""}, timeout=10.0)
        if (isinstance(result, Mapping) and result.get("originalRawSha256") == original
                and result.get("captureSessionId") == capture["captureSessionId"]
                and result.get("replayMutation") is False and result.get("replayRead") is False):
            observation = dict(result)
    except Exception as error:
        observation["reason"] = str(error)[:300]
    return observation


def _shader_cbuffer_delivery_from_status(status: Mapping[str, Any]) -> dict[str, Any]:
    """Expose presentation freshness without adding replay reads or validation."""
    source = status.get("source")
    source = source if isinstance(source, Mapping) else {}
    latest = status.get("latestCompiled")
    latest = latest if isinstance(latest, Mapping) else {}
    candidate_sha = str(latest.get("rawSha256") or "")
    try:
        from .shader_semantic_delivery import save_display_identity
        observation = _shader_cbuffer_display_observation(status)
        save_display_identity(str(status.get("workspacePath") or ""), observation)
        return _shader_cbuffer_semantic_delivery(str(status.get("workspacePath") or ""),
            candidate_sha, str(source.get("path") or ""), display_identity=observation,
            original_shader_sha256=str((status.get("baseline") or {}).get("rawSha256") or ""))
    except (OSError, ValueError, RuntimeError) as error:
        # This separate display effect cannot retroactively fail a successful
        # compile/apply or erase the already validated replay replacement.
        return {"required": True, "status": "pending", "recompileRequired": False,
                "reason": "naming-source-inspection-unavailable",
                "diagnostic": str(error)[:300],
                "nextAction": "inspect-current-source-and-publish-semantic-fields"}


def _finished_shader_ui_readback(preview: Mapping[str, Any], source_sha: str,
                                registration: Mapping[str, Any], *, workspace_path: str = "") -> dict[str, Any]:
    """Check the final visible, editable document after project/apply callbacks."""
    if (preview.get("shown") is not True or preview.get("sourceSha256") != source_sha
            or preview.get("readOnly") is not False):
        raise RuntimeError("final Shader display did not acknowledge the editable saved source")
    state = ipc.call("get_shader_workspace_ui_state", {}, timeout=30.0)
    if not isinstance(state, Mapping):
        raise RuntimeError("final Shader UI readback is unavailable")
    workspace_id = preview.get("workspaceId")
    rows = [row for row in state.get("workspaces", []) if isinstance(row, Mapping)
            and row.get("workspaceId") == workspace_id]
    docs = [doc for doc in state.get("documents", []) if isinstance(doc, Mapping)
            and doc.get("workspaceId") == workspace_id]
    knowledge_id = registration["result"]["knowledge"]["knowledgeId"]
    source_hashes = {source_sha}
    if workspace_path:
        from .shader_overview_delivery import saved_source_hashes
        source_hashes = saved_source_hashes(workspace_path, source_sha)
    if (len(rows) != 1 or len(docs) != 1 or state.get("selectedWorkspaceId") != workspace_id
            or rows[0].get("visibleInWorkspaceTree") is not True
            or rows[0].get("editorEligible") is not True
            or rows[0].get("openInTab") is not True
            or (rows[0].get("projectSourceIdentity") or {}).get("knowledgeId") != knowledge_id
            or docs[0].get("available") is not True or docs[0].get("readOnly") is not False
            or docs[0].get("dirty") is not False
            or docs[0].get("loadedSourceSha256") != source_sha
            or (docs[0].get("sourceSha256") is not None
                and docs[0].get("sourceSha256") not in source_hashes)
            or (state.get("captureBinding") or {}).get("captureSessionId") != preview.get("captureSessionId")):
        raise RuntimeError("final Shader editor is hidden, stale, unbound or differs from the saved source")
    result = {"ok": True, "workspaceId": workspace_id, "sourceSha256": source_sha,
            "knowledgeId": knowledge_id, "shown": True, "readOnly": False,
            "selected": True, "visibleInWorkspaceTree": True}
    if workspace_path:
        from .shader_overview_delivery import display_receipt
        directory = display_receipt(workspace_path, source_sha, state, workspace_id)
        # Source parsing is asynchronous. Wait only for its matching outstanding
        # projection, not for missing metadata or a wrong document to fix itself.
        deadline = time.monotonic() + 3.0
        while not directory["complete"] and directory.get("pending") and time.monotonic() < deadline:
            time.sleep(0.05)
            state = ipc.call("get_shader_workspace_ui_state", {}, timeout=30.0)
            if (not isinstance(state, Mapping) or (state.get("captureBinding") or {}).get("captureSessionId") != preview.get("captureSessionId")):
                raise RuntimeError("capture session changed during calculation-directory display verification")
            directory = display_receipt(workspace_path, source_sha, state, workspace_id)
        result["semanticOverviewDelivery"] = directory
        if not directory["complete"]:
            result.update(ok=False, error=directory.get("reason", "Calculation-directory display is incomplete"))
    return result


@mcp.tool()
def finish_shader_workspace_organization(
    workspace_path: str,
    organization_id: str,
    apply_shared_resource: bool = False,
    start_live_edit: bool = False,
    generate_flow_graph: bool = False,
    validate_for_apply: bool | None = None,
    show_in_workspace: bool = False,
    publication_mode: Literal["final", "checkpoint"] = "final",
    source_review_policy: Literal["advisory", "strict"] = "advisory",
) -> str:
    """Deliver the whole organized source after final compile/ABI/output checks.

    Final publication validates by default. Explicit ``validate_for_apply=false``
    saves only an intermediate draft, whose delivery remains incomplete. Apply
    always requires the full final validation regardless of that flag. Compile
    and ABI evidence from the same source/include revision is reused.
    ``show_in_workspace`` reuses a
    clean matching canonical editor or displays an editable working copy of the
    content-bound preview without starting live edit or applying replay. Display failure
    is returned separately from the save; its receipt reports editability.
    Source-quality review annotations are advisory by default. They report
    missing assessment without blocking compile/ABI/output validation or transfer.
    An explicitly requested strict review can use source_review_policy="strict".
    Actual source identity and physical replacement checks remain enforced.
    With an active project, ``apply_shared_resource=true`` also registers the
    source, reviewed documents, candidate and derived association once.
    A successful ``replacementRegistration`` needs no separate registration
    call. A late persistence failure preserves the applied candidate and gives
    exact metadata-only recovery arguments; retry does not compile or apply.
    ``publication_mode=checkpoint`` persists only the working proposal. It
    never changes canonical source, compiles, validates ABI or applies replay;
    physical-effect flags are rejected. Plain save needs no review.
    """

    try:
        if publication_mode not in {"final", "checkpoint"}:
            raise ValueError("publication_mode must be final or checkpoint")
        if source_review_policy not in {"advisory", "strict"}:
            raise ValueError("source_review_policy must be advisory or strict")
        if validate_for_apply is not None and type(validate_for_apply) is not bool:
            raise ValueError("validate_for_apply must be a boolean or null")
        validate_for_apply = (publication_mode == "final" if validate_for_apply is None else validate_for_apply)
        if publication_mode == "checkpoint" and (validate_for_apply or apply_shared_resource or start_live_edit):
            raise ValueError("proposal checkpoint cannot validate, apply or start live edit; complete whole-source self-review before final physical actions")
        if apply_shared_resource or start_live_edit:
            validate_for_apply = True
        reviewed_source = ""
        review_observations = {"policy": source_review_policy, "diagnosticsOnly": source_review_policy == "advisory"}
        if publication_mode == "final" and current_task_report_store().enabled:
            from .shader_source_reads import require_current
            from .shader_organization_review import source_snapshot
            read_snapshot = source_snapshot(workspace_path, organization_id)
            try:
                require_current(current_task_report_store(), workspace_path, organization_id,
                                read_snapshot["sourceSha256"], require_begin=True)
            except ValueError as error:
                if source_review_policy == "strict":
                    raise
                review_observations["taskAssessmentDiagnostic"] = str(error)
            reviewed_source = read_snapshot["sourceSha256"]
        if validate_for_apply or apply_shared_resource or start_live_edit:
            from .shader_organization_review import publication_review
            review = publication_review(workspace_path, organization_id)
            review_observations["assessment"] = review
            if not review["ready"] and source_review_policy == "strict":
                metadata_only = review.get("metadataOnlyRepair") is True
                return _ok({
                    "schema": "replaylab-shader-organization-finish/v1", "schemaVersion": 1,
                    "ok": False, "state": "source-review-pending", "recoverable": True,
                    "workspacePath": workspace_path, "organizationId": organization_id,
                    "draftPreserved": True, "promoted": False, "applied": False,
                    "wholeSourceValidated": False, "sourceReview": review,
                    "delivery": {"schema": "bread-shader-delivery/v1", "complete": False,
                                 "readyForApply": False, "applied": False, "repairRequired": False,
                                 "recompileRequired": False,
                                 "nextAction": ("update-semantic-overview-without-recompiling" if metadata_only
                                                else "complete-source-organization-and-self-review")},
                    "reason": ("The source assessment is current; repair only its independent calculation directory with get_shader_semantic_overview_context and update_shader_semantic_overview using this organization_id. Preserve source and existing compile/ABI evidence."
                               if metadata_only else "Continue full-scope source edits and self-review in the same working copy; import and record a current complete source review before final validation/apply. Source quality complete does not require compilation. Checkpoints save proposal bytes only."),
                })
            if review.get("ready"):
                reviewed_source = review["sourceSha256"]
        manager = _shader_organization_manager()
        finish_options: dict[str, Any] = {"generate_flow_graph": generate_flow_graph}
        if reviewed_source:
            finish_options["expected_reviewed_source_sha256"] = reviewed_source
        finished = (
            manager.save_proposal(workspace_path, organization_id)
            if publication_mode == "checkpoint" else
            manager.finish_draft(
                workspace_path, organization_id,
                **finish_options,
            )
            if validate_for_apply
            else manager.save_draft(
                workspace_path, organization_id,
                **finish_options,
            )
        )
        if not isinstance(finished, dict) or finished.get("ok") is not True:
            if isinstance(finished, dict):
                finished["sourceReviewObservations"] = review_observations
                finished.update(delivery={"schema": "bread-shader-delivery/v1", "complete": False,
                    "readyForApply": False, "applied": False, "repairRequired": True,
                    "nextAction": "repair-current-proposal-and-repeat-final-validation"}, recoverable=True)
            return _ok(finished)
        payload = dict(finished)
        payload["sourceReviewObservations"] = review_observations
        payload["publicationMode"] = publication_mode
        payload["delivery"] = {"schema": "bread-shader-delivery/v1",
            "complete": bool(validate_for_apply and finished.get("wholeSourceValidated")),
            "readyForApply": bool(validate_for_apply and finished.get("wholeSourceValidated")),
            "applied": False, "repairRequired": False,
            "validationScope": "organization-baseline-equivalence" if validate_for_apply else "source-save-only",
            "equivalenceLevel": finished.get("equivalenceLevel", "not-run"),
            "nextAction": "apply-if-requested" if validate_for_apply else "complete-source-and-validate"}
        if apply_shared_resource:
            try:
                revision = int(finished["expectedRevision"])
                candidate_sha = str(finished["expectedCandidateRawSha256"])
                applied_raw = apply_shader_workspace_shared_resource(
                    workspace_path,
                    expected_revision=revision,
                    expected_candidate_raw_sha256=candidate_sha,
                )
                applied = json.loads(applied_raw) if isinstance(applied_raw, str) else applied_raw
                payload["apply"] = applied
                payload["applied"] = _shader_delivery_apply_succeeded(applied)
            except Exception as apply_error:
                payload["applied"] = False
                payload["apply"] = {
                    "ok": False,
                    "error": str(apply_error)[:800],
                }
        validated_final = bool(publication_mode == "final" and validate_for_apply
                               and finished.get("wholeSourceValidated"))
        if validated_final:
            try:
                completed_publication = None
                if payload.get("applied") is True:
                    import sys
                    from .shader_final_publication import publish_finished_replacement
                    completed_publication = publish_finished_replacement(
                        sys.modules[__name__], workspace_path, finished, payload["apply"])
                if completed_publication is None:
                    payload["registration"] = _register_active_project_workspace_receipt(
                        workspace_path, expected_finish=finished)
                else:
                    payload.update(completed_publication)
                    if payload["replacementRegistration"].get("ok") is not True:
                        payload.update(ok=False, state="project-publication-failed-source-preserved", recoverable=True)
                        payload["delivery"].update(complete=False, repairRequired=True,
                            nextAction="register-applied-replacement-without-recompiling",
                            recovery=payload["replacementRegistration"]["recovery"])
            except Exception as registration_error:
                payload["registration"] = {"ok": False, "error": str(registration_error)[:800]}
                payload.update(ok=False, state="project-publication-failed-source-preserved", recoverable=True)
                payload["delivery"].update(complete=False, repairRequired=True,
                    nextAction="register-validated-source-without-recompiling")
        # Project publication takes a source lease. Start the watcher only
        # after that single final transaction has released the same lease.
        if start_live_edit and payload.get("applied") is True:
            try:
                live_raw = start_shader_workspace_live_edit(workspace_path)
                live = json.loads(live_raw) if isinstance(live_raw, str) else live_raw
                payload["liveEdit"] = live
            except Exception as live_error:
                payload["liveEdit"] = {"ok": False, "error": str(live_error)[:800]}
        elif start_live_edit:
            payload["liveEdit"] = {"started": False,
                                   "reason": "replay-replacement-not-applied"}
        if show_in_workspace and publication_mode == "checkpoint":
            payload["preview"] = {"shown": False, "readOnly": True,
                                  "reason": "proposal-only-checkpoint",
                                  "proposalSourcePath": finished["proposalSourcePath"],
                                  "replayApplied": False}
        elif show_in_workspace and validated_final:
            if payload["registration"].get("ok") is False:
                payload["preview"] = {"shown": False, "reason": "project-publication-incomplete"}
            else:
                try:
                    shown_raw = show_shader_workspace_source(workspace_path)
                    payload["preview"] = json.loads(shown_raw) if isinstance(shown_raw, str) else shown_raw
                    source_sha = finished.get("sourceSha256") or (finished.get("finalBinding") or {}).get("sourceSha256")
                    payload["uiReadback"] = _finished_shader_ui_readback(
                        payload["preview"], source_sha, payload["registration"], workspace_path=workspace_path)
                    payload["semanticOverviewDelivery"] = payload["uiReadback"]["semanticOverviewDelivery"]
                except Exception as preview_error:
                    payload.setdefault("preview", {"shown": False})
                    payload["uiReadback"] = {"ok": False, "error": str(preview_error)[:800]}
        elif show_in_workspace:
            try:
                # UI visibility needs only the saved source and current
                # capture, never compiler availability or a replay grant.
                preview_status = _alias_publication_workspace_status(workspace_path)
                context = _workspace_active_capture_context(
                    workspace_path, status=preview_status,
                    status_loader=_alias_publication_workspace_status,
                )
                capture_id, capture_session_id = _active_capture_identity(context)
                source_sha = _strict_lower_hex(
                    finished.get("sourceSha256") or
                    (finished.get("finalBinding") or {}).get("sourceSha256"),
                    64, "saved source SHA-256",
                )
                payload["preview"] = ipc.call(
                    "show_shader_organization_preview",
                    {"workspace_path": workspace_path,
                     "organization_id": organization_id,
                     "expected_source_sha256": source_sha,
                     "expected_capture_id": capture_id,
                     "expected_capture_session_id": capture_session_id},
                    timeout=30.0,
                )
            except Exception as preview_error:
                payload["preview"] = {
                    "shown": False, "readOnly": True,
                    "error": str(preview_error)[:800],
                    "replayApplied": False,
                }
        payload["delivery"]["applied"] = payload.get("applied") is True
        if apply_shared_resource and payload.get("applied") is not True:
            payload.update(ok=False, state="apply-failed-source-preserved", recoverable=True)
            payload["delivery"].update(complete=False, repairRequired=True,
                                      nextAction="repair-apply-and-retry")
        if start_live_edit and (not isinstance(payload.get("liveEdit"), Mapping)
                               or payload["liveEdit"].get("ok") is False
                               or payload["liveEdit"].get("error")
                               or payload["liveEdit"].get("started") is False):
            payload.update(ok=False, state="live-edit-not-started", recoverable=True)
            payload["delivery"].update(complete=False, repairRequired=True,
                                      nextAction="repair-live-edit-and-retry")
        if (show_in_workspace and publication_mode == "final"
                and not (validated_final and payload["registration"].get("ok") is False) and (
                not isinstance(payload.get("preview"), Mapping)
                or payload["preview"].get("shown") is not True
                or (validated_final and (payload.get("uiReadback") or {}).get("ok") is not True))):
            payload.update(ok=False, state="preview-not-shown-source-preserved", recoverable=True)
            payload["delivery"].update(complete=False, repairRequired=True,
                                      nextAction="show-saved-source-without-recompiling")
            payload["delivery"]["recompileRequired"] = False
        if publication_mode == "final":
            try:
                # A manual UI replacement can change since publication. Read
                # its current cached reflection/owner before final delivery;
                # compiling a candidate is not evidence of that display.
                from .shader_workspace.organization import _draft_status
                naming_status = _draft_status(_shader_workspace_service(), workspace_path)
                payload["cbufferSemanticDelivery"] = _shader_cbuffer_delivery_from_status(naming_status)
            except Exception as naming_error:
                payload["cbufferSemanticDelivery"] = {"required": True, "status": "pending",
                    "reason": "naming-source-inspection-unavailable",
                    "diagnostic": str(naming_error)[:300], "recompileRequired": False}
            metadata = payload["cbufferSemanticDelivery"]
            payload["delivery"]["sourceDeliveryComplete"] = payload["delivery"]["complete"]
            payload["delivery"]["metadataComplete"] = not metadata.get("required") or metadata.get("status") == "complete"
            payload["delivery"]["wholeTaskComplete"] = bool(payload["delivery"]["complete"] and payload["delivery"]["metadataComplete"])
            if payload["delivery"]["sourceDeliveryComplete"] and not payload["delivery"]["metadataComplete"]:
                payload["delivery"].update(complete=False, nextAction="complete-resource-naming-without-recompiling",
                                          recompileRequired=False)
        return _ok(payload)
    except Exception as error:
        response = json.loads(_shader_err(error, "organization-finish"))
        response.update(ok=False, delivery={"schema": "bread-shader-delivery/v1",
            "complete": False, "readyForApply": False, "applied": False,
            "repairRequired": True, "reason": str(error)[:2000],
            "nextAction": "inspect-final-validation-diagnostics-and-repair-current-draft"})
        return _ok(response)


_WORKSPACE_FILE_MAX_BYTES = 4 * 1024 * 1024
_WORKSPACE_FILE_MAX_CHARS = 120_000
_ALIAS_WORKSPACE_MANIFEST_MAX_BYTES = 16 * 1024 * 1024
_ORGANIZATION_FILE_KINDS = {
    "proposal": ("proposalSourcePath", 4 * 1024 * 1024, "editable shader source"),
    "analysis": ("analysisPath", 256 * 1024, "optional human-readable analysis"),
    "flowchart": ("flowchartPath", 256 * 1024, "optional Agent-authored Mermaid flowchart"),
}

def _alias_publication_workspace_status(workspace_path: str) -> dict[str, Any]:
    """Validate only immutable workspace/capture facts needed by alias writes.

    Display-name publication never executes, compiles or decompiles a Shader.
    Loading the process Shader tool registry here would therefore make an
    unrelated stale compiler/decompiler block a physically safe alias write.
    This bounded reader proves the managed project path, manifest, captured
    baseline bytes and catalog binding without consulting any execution tool.
    Live EID/resource/layout checks remain in the publication-specific paths.
    """

    active_status = _active_project_service().status()
    root = _require_managed_active_workspace(active_status, workspace_path)
    manifest_path = root / "manifest.json"
    if manifest_path.is_symlink() or not manifest_path.is_file():
        raise RuntimeError("shader workspace manifest is unavailable or redirected")
    manifest_before = _bounded_file_sha256(
        manifest_path,
        _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
        "Shader workspace manifest",
    )
    try:
        manifest = read_json_object(
            manifest_path,
            _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
            "Shader workspace manifest",
        )
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc
    if (
        manifest.get("schema") != "renderdoc-ultra-shader-workspace/v1"
        or manifest.get("schemaVersion") != 1
    ):
        raise RuntimeError("unsupported shader workspace manifest schema/version")

    workspace_id = _strict_lower_hex(
        manifest.get("workspaceId"), 32, "workspaceId"
    )
    capture = manifest.get("capture")
    shader = manifest.get("shader")
    baseline = manifest.get("baseline")
    if not all(isinstance(item, Mapping) for item in (capture, shader, baseline)):
        raise RuntimeError("shader workspace physical identity is incomplete")

    stage = normalize_stage(manifest.get("stage"))
    if not stage or manifest.get("stage") != stage:
        raise RuntimeError("shader workspace stage is invalid")
    entry_point = str(manifest.get("entryPoint") or "")
    if len(entry_point) > 512 or "\x00" in entry_point:
        raise RuntimeError("shader workspace entry point is invalid")
    resource_id = shader.get("resourceId")
    if type(resource_id) is not int or resource_id <= 0:
        raise RuntimeError("shader workspace ResourceId is invalid")
    shader_raw_sha256 = _strict_lower_hex(
        shader.get("rawSha256"), 64, "workspace shader rawSha256"
    )
    if (
        normalize_stage(shader.get("stage")) != stage
        or shader.get("stage") != stage
        or str(shader.get("entryPoint") or "") != entry_point
        or shader.get("shaderKey")
        != "%d:%s:%s:%s"
        % (resource_id, stage, entry_point, shader_raw_sha256)
    ):
        raise RuntimeError("shader workspace Shader identity is inconsistent")

    capture_id = _strict_lower_hex(
        capture.get("captureId"), 64, "workspace captureId"
    )
    catalog_sha256 = _strict_lower_hex(
        capture.get("catalogSha256"), 64, "workspace catalogSha256"
    )
    for field in ("capturePath", "catalogPath", "api"):
        value = str(capture.get(field) or "")
        if not value or "\x00" in value or len(value) > 32768:
            raise RuntimeError("shader workspace capture.%s is invalid" % field)

    baseline_raw_sha256 = _strict_lower_hex(
        baseline.get("rawSha256"), 64, "workspace baseline rawSha256"
    )
    baseline_path_text = str(baseline.get("path") or "")
    baseline_size = baseline.get("byteSize")
    if (
        baseline_raw_sha256 != shader_raw_sha256
        or not baseline_path_text
        or "\x00" in baseline_path_text
        or len(baseline_path_text) > 32768
        or type(baseline_size) is not int
        or baseline_size <= 0
        or baseline_size > MAX_SHADER_BYTES
    ):
        raise RuntimeError("shader workspace baseline identity is invalid")
    unresolved_baseline = Path(baseline_path_text).expanduser()
    baseline_path = (
        unresolved_baseline
        if unresolved_baseline.is_absolute()
        else root / unresolved_baseline
    )
    if baseline_path.is_symlink():
        raise RuntimeError("shader workspace baseline is redirected")
    try:
        baseline_path = baseline_path.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise RuntimeError("shader workspace baseline is unavailable") from exc
    if (
        not baseline_path.is_file()
        or not is_within(root, baseline_path)
        or baseline_path.stat().st_size != baseline_size
        or _bounded_file_sha256(
            baseline_path, MAX_SHADER_BYTES, "Shader workspace captured baseline"
        )
        != baseline_raw_sha256
    ):
        raise RuntimeError("shader workspace baseline bytes changed")

    manifest_after = _bounded_file_sha256(
        manifest_path,
        _ALIAS_WORKSPACE_MANIFEST_MAX_BYTES,
        "Shader workspace manifest",
    )
    if manifest_after != manifest_before:
        raise RuntimeError("shader workspace manifest changed during alias preflight")
    return {
        "workspacePath": str(root),
        "workspaceId": workspace_id,
        "capture": copy.deepcopy(dict(capture)),
        "shader": copy.deepcopy(dict(shader)),
        "stage": stage,
        "entryPoint": entry_point,
        "baseline": copy.deepcopy(dict(baseline)),
        "source": copy.deepcopy(manifest.get("source") or {}),
        "aliasPhysicalIdentity": {
            "captureId": capture_id,
            "catalogSha256": catalog_sha256,
            "shaderRawSha256": shader_raw_sha256,
            "baselineRawSha256": baseline_raw_sha256,
        },
    }


def _workspace_file_context(workspace_path: str) -> tuple[Path, dict]:
    """Validate once for this file request and retain its complete status.

    This is request-local reuse, not a workspace status cache. The next request
    still validates the managed document and observes its current source.
    Compile paths retain their own toolchain and candidate freshness checks.
    """

    from .shader_workspace.organization import _draft_status
    status = _draft_status(_shader_workspace_service(), workspace_path)
    declared = Path(str(status.get("workspacePath", "") or ""))
    root = declared.resolve()
    if not declared or declared.is_symlink() or not root.is_dir():
        raise RuntimeError("shader workspace root is not a managed directory")
    return root, status


def _workspace_root_for_files(workspace_path: str) -> Path:
    """Resolve a managed Shader workspace root; anything else is refused."""

    root, _status = _workspace_file_context(workspace_path)
    return root


def _workspace_file_target(root: Path, relative_path: str) -> Path:
    relative = str(relative_path or "").strip().replace("\\", "/")
    if not relative or relative.startswith("/") or ".." in relative.split("/"):
        raise ValueError("relative_path must point inside the workspace (no '..', no absolute path)")
    target = (root / relative).resolve()
    if not is_within(root, target):
        raise ValueError("relative_path escapes the workspace")
    return target


def _read_workspace_text_bytes(target: Path) -> bytes:
    if target.is_symlink() or not target.is_file():
        raise FileNotFoundError("no such regular file in the workspace: %s" % target.name)
    with target.open("rb") as stream:
        raw = stream.read(_WORKSPACE_FILE_MAX_BYTES + 1)
    if len(raw) > _WORKSPACE_FILE_MAX_BYTES:
        raise ValueError("file exceeds the readable size limit (4 MiB)")
    if b"\0" in raw:
        raise ValueError("file is binary")
    return raw


def _copy_workspace_file_to_agent(name: str, raw: bytes, root: Path, relative: str) -> dict:
    from .agent_workspace_files import copy_text_to_agent_workspace
    result = copy_text_to_agent_workspace(name, raw)
    result.update(sourceWorkspacePath=str(root), sourceRelativePath=relative,
                  sourceSha256=hashlib.sha256(raw).hexdigest())
    return result


@mcp.tool()
def read_shader_workspace_file(
    workspace_path: str, relative_path: str, offset: int = 0, limit: int = 60_000,
    agent_file_name: str = "",
    mode: Literal["range", "complete", "file"] = "range",
) -> str:
    """Read a UTF-8 text file inside a managed Shader workspace.

    Use it for ``source/shader.hlsl`` (the decompiler output), the proposal
    files opened by ``begin_shader_workspace_organization``, ``ai/*.json`` and
    the semantic context. ``mode='range'`` uses character ``offset``/``limit``
    (60,000 default, 120,000 maximum). Explicit ``mode='complete'`` returns the
    entire UTF-8 text up to 4 MiB in one result, ignoring ``limit``; choose it
    only when your context budget can hold the whole source. ``mode='file'``
    returns only metadata plus a complete owned working copy, defaulting its
    name to the source basename. Complete/file modes require offset=0. Coverage
    describes text actually returned, never bytes merely copied to a file.
    Binary files and files outside the workspace are refused.
    During a current organization, source delivery is bounded to stay inline for
    all connections. Even mode=complete may return one page: follow nextOffset
    (Unicode character offset) with mode=range until null. Coverage reports actual
    UTF-8 bytes delivered; file copies and output pointers do not count as reads.
    ``agent_file_name`` optionally copies the complete UTF-8 file into this
    run's Agent working directory for native file editing, without changing
    canonical Source. The returned ``agentFile`` is an editable working copy,
    not replay evidence; an existing working file is preserved under its name.
    """

    try:
        if mode not in {"range", "complete", "file"}:
            raise ValueError("mode must be range, complete, or file")
        if mode != "range" and offset != 0:
            raise ValueError("complete/file mode requires offset=0")
        root, status = _workspace_file_context(workspace_path)
        target = _workspace_file_target(root, relative_path)
        raw = _read_workspace_text_bytes(target)
        size = len(raw)
        text = raw.decode("utf-8", errors="strict")
        start = max(0, int(offset))
        span = max(1, min(int(limit), _WORKSPACE_FILE_MAX_CHARS))
        chunk = text if mode == "complete" else "" if mode == "file" else text[start : start + span]
        agent_file = None
        relative = str(target.relative_to(root)).replace("\\", "/")
        if agent_file_name or mode == "file":
            agent_file = _copy_workspace_file_to_agent(
                agent_file_name or target.name, raw, root, relative)
        explanation_provenance = None
        if relative in {"ai/analysis.md", "ai/flowchart.mmd"} or (
                relative.startswith("ai/organization-sessions/")
                and target.name in {"analysis.md", "analysis.txt", "flowchart.mmd"}):
            from .shader_workspace.explanations import source_binding_metadata
            explanation_provenance = source_binding_metadata(
                root, target, raw, status)
        elif target.name == "flow-spec.json" and relative.startswith("ai/"):
            # Review ranges are historical evidence. The current UI graph is
            # separately bound by ai/flow-graph.json; ranges cannot prove that
            # this old spec describes the current Source.
            explanation_provenance = {
                "role": "historical-flow-spec", "currentSourceMatches": None,
                "currentUiGraphSource": "ai/flow-graph.json",
                "acceptanceAuthorization": False,
                "sourceBindingAvailable": False, "declaredSourceSha256": None,
            }
            try:
                historical_spec = json.loads(text)
                if isinstance(historical_spec, Mapping):
                    historical_binding = historical_spec.get("binding") or {}
                    declared_sha = historical_spec.get("sourceSha256") or (
                        historical_binding.get("sourceSha256")
                        if isinstance(historical_binding, Mapping) else None)
                    if isinstance(declared_sha, str) and re.fullmatch(r"[0-9a-f]{64}", declared_sha):
                        explanation_provenance.update(sourceBindingAvailable=True, declaredSourceSha256=declared_sha)
            except (ValueError, UnicodeError):
                pass
        payload = {
                "schema": "renderdoc-ai-shader-workspace-file/v1",
                "mode": mode,
                "workspacePath": str(root),
                "relativePath": relative,
                "sizeBytes": size,
                "sha256": hashlib.sha256(raw).hexdigest(),
                "totalChars": len(text),
                "offset": start,
                "chars": len(chunk),
                "truncated": start + len(chunk) < len(text),
                "coverage": {
                    "byteOffset": len(text[:start].encode("utf-8")),
                    "returnedBytes": len(chunk.encode("utf-8")),
                    "complete": mode != "file" and start == 0 and chunk == text,
                },
                "text": chunk,
                "agentFile": agent_file,
                "explanationProvenance": explanation_provenance,
                "applied": False,
            }
        # A read counts only when the actual source text can survive every
        # connector's inline-output budget. File/copy mode is never a read.
        requirement = getattr(current_task_report_store(), "shader_source_read_required", None)
        if mode != "file" and callable(requirement) and requirement(str(root)):
            from .shader_source_reads import bounded_read_payload
            payload = bounded_read_payload(payload, text)
        return _ok(payload)
    except Exception as error:
        return _shader_err(error, "workspace-status")


@mcp.tool()
def get_shader_workspace_outline(
    workspace_path: str,
    relative_path: str = "",
    function: str = "",
    lines: str = "",
    symbols: list[str] | None = None,
    region: str = "",
    section: str = "summary",
    offset: int = 0,
    limit: int = 32,
    selector: str = "",
) -> str:
    """Return bounded HLSL/GLSL structure, quality, slices and region IO.

    With neither ``function``, ``lines``, ``symbols``, ``selector`` nor ``region`` it returns
    a bounded outline. The default ``section='summary'`` reports counts and
    page metadata without embedding every declaration. The
    ``declarations``, ``functions`` and ``symbols`` sections use a stable cursor
    contract through ``page.nextOffset`` and ``page.hasMore``. Declaration rows
    include exact CBuffer/member/resource ``renameSelector`` values and generated
    rows include deterministic neutral names. ``page.items`` is the sole item
    list, so rows are never duplicated under convenience keys.
    Limit is 1-64 and defaults to 32. Function pages contain ranges, call edges
    and quality counts; use ``function``/``region``/``symbols`` for their bounded
    detail. ``function=<name>`` returns that function's
    source with line numbers; ``lines=<start>-<end>`` returns a bounded range.
    ``symbols=["_8737"]`` returns bounded exact
    references (up to 16 identifiers), useful for finding local definitions
    and uses across a large body. ``region="start-end"`` inspects up to 400
    lines before an edit: complete statement boundaries, typed inputs/inouts,
    live-outs, external references and full enclosing-function reference/write
    counts. Location samples may be truncated; counts remain complete. Unknown
    calls, directives and escaping control flow produce actionable diagnostics.
    IO is available even above the ordinary extractor's parameter budget.
    ``selector="Function::local"`` returns that one declaration's lexical
    visibility range and bound references, tied to ``sourceSha256``. It does
    not claim a runtime lifetime or complete data-flow dependencies.
    ``section="symbol-table"`` pages source-bound global declarations; combine
    it with ``function="MainPS"`` for that function's lexical references,
    simple read/write sites and candidate direct-assignment inputs. These are
    conservative hints, not control-flow or runtime-liveness proof.
    ``section="cbuffer-semantics"`` pages all declared CBuffer bindings with
    their physical member offsets and direct source alias/vector candidates.
    These are source-bound naming suggestions, not automatic semantic approval;
    review consumers, split unrelated controls and retain literal padding only
    in source, never as invented physical channels. No replay read is needed.
    Function quality
    and physical-placeholder coverage are source facts; alias existence is not
    inferred. Choose one of function/lines/symbols/selector/region. This never edits,
    compiles or grants semantic/ABI/apply authority; GLSL capability gates stay
    unchanged; resource evaluation locations are reported as source facts.
    """

    try:
        from .shader_workspace.outline import MAX_SLICE_LINES, function_slice, line_slice, paged_outline, symbol_slices

        if sum((bool(function.strip()), bool(lines.strip()), symbols is not None,
                bool(selector.strip()), bool(region.strip()))) > 1:
            raise ValueError("choose only one of function, lines, symbols, selector, or region")
        symbol_table = section.strip().lower() == "symbol-table"
        if symbol_table and (lines.strip() or symbols is not None or selector.strip() or region.strip()):
            raise ValueError("symbol-table section may be combined only with function")

        root, status = _workspace_file_context(workspace_path)
        if not relative_path:
            declared = Path(str((status.get("source") or {}).get("path") or ""))
            relative_path = str(declared.relative_to(root)) if declared.is_absolute() else str(declared)
        target = _workspace_file_target(root, relative_path)
        if target.is_symlink() or not target.is_file():
            raise FileNotFoundError("no such regular file in the workspace: %s" % relative_path)
        if target.stat().st_size > _WORKSPACE_FILE_MAX_BYTES:
            raise ValueError("file exceeds the readable size limit")
        raw = target.read_bytes()
        if b"\0" in raw[:4096]:
            raise ValueError("file is binary")
        # Symbol identities must match the exact bytes reported in sourceSha256.
        # Other outline modes keep their legacy replacement-decoding behavior.
        text = raw.decode("utf-8", errors="strict" if symbol_table else "replace")
        base = {"workspacePath": str(root), "relativePath": str(target.relative_to(root)).replace("\\", "/"),
                "sourceSha256": hashlib.sha256(raw).hexdigest(), "applied": False}
        if region.strip():
            from .shader_workspace.inspection import inspect_region
            match = re.fullmatch(r"\s*(\d+)\s*[-:]\s*(\d+)\s*", region)
            if match is None:
                raise ValueError("region must look like 120-260 and contain at most 400 lines")
            result = inspect_region(text, int(match.group(1)), int(match.group(2)))
        elif selector.strip():
            from .shader_workspace.equivalence import inspect_symbol
            result = inspect_symbol(text, selector.strip(), limit=limit)
        elif symbols is not None:
            result = symbol_slices(text, symbols)
        elif symbol_table:
            from .shader_workspace.symbol_graph import inspect_source_symbol_table
            result = inspect_source_symbol_table(
                text, function=function.strip() or None, offset=offset, limit=limit,
            )
        elif section.strip().lower() == "cbuffer-semantics":
            from .shader_workspace.semantic_coverage import source_inventory
            rows = source_inventory(text)
            start = max(0, int(offset))
            count = max(1, min(64, int(limit)))
            result = {"section": "cbuffer-semantics", "semanticReviewRequired": True,
                      "page": {"items": rows[start:start + count], "total": len(rows),
                               "offset": start, "hasMore": start + count < len(rows),
                               "nextOffset": start + count if start + count < len(rows) else None}}
        elif section.strip().lower() == "resource-naming":
            from .shader_resource_naming_review import inventory, delivery_state as resource_naming_state
            from .shader_workspace.naming_delivery import source_context
            context = source_context(root, raw, str(target))
            result = {"section": "resource-naming", **inventory(raw, context),
                      "resourceNamingDelivery": resource_naming_state(root, raw, context)}
        elif function.strip():
            try:
                result = function_slice(text, function.strip())
            except KeyError as exc:
                raise FileNotFoundError(str(exc)) from exc
        elif lines.strip():
            match = re.fullmatch(r"\s*(\d+)\s*[-:]\s*(\d+)\s*", lines)
            if match is None:
                raise ValueError("lines must look like 120-260 (at most %d lines)" % MAX_SLICE_LINES)
            result = line_slice(text, int(match.group(1)), int(match.group(2)))
        else:
            entry = str(status.get("entryPoint") or "")
            result = paged_outline(
                text, entry_point=entry, section=section, offset=offset, limit=limit
            )
        result.update(base)
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "workspace-status")


def _organization_write_transaction(function: Any) -> Any:
    """Keep draft writes and their private checkpoint one short Host transaction."""
    from functools import wraps

    @wraps(function)
    def serialized(*args: Any, **kwargs: Any) -> Any:
        with _shader_organization_manager()._guard:
            return function(*args, **kwargs)
    return serialized


@mcp.tool()
def record_task_review(
    verdict: Literal["needs_work", "complete", "blocked"],
    criteria: list[dict[str, str]],
    findings: list[str],
    next_actions: list[str],
    blocker: str = "",
    decision_request: dict[str, Any] | None = None,
    visual_review: str = '',
    visual_checks: dict[str, str] | None = None,
    reviewed_answer: dict[str, Any] | None = None,
) -> str:
    """Record the main Agent's self-review against the current user request.

    Each criterion contains requirement, status (satisfied/unmet/blocked), and
    evidence strings. Use existing evidence; no preparatory tool or repeated
    validation is required. An ordinary answer can use one criterion. Submit
    after the last meaningful operation: subsequent work invalidates this
    assessment. Complete requires all criteria satisfied and no unresolved
    findings/actions/blocker. Use needs_work and continue improving, or blocked
    with the concrete reason work cannot proceed. Shader criteria may reference
    the specialized source review. Only the main Agent records the whole-task
    verdict; subagents provide evidence. This verifies structure and current
    task/work identity only, never answer quality or all produced artifacts.
    If only a real user choice remains, save concrete results and supply blocked
    with decision_request={question, options:[2-3 choices], evidence:[saved facts]}.
    Present that question and wait; automatic recovery must not resume behind it.
    For a published visual answer, include visual_review after assessing the actual
    overview, images, diagram relationships/results, stage code, precise links and
    relevance against the question and loaded presentation rules. Correct feasible
    omissions first. For a multi-layer marked effect, visual_checks must cover
    overview, contributions, display, flow, source, links and inactive with concrete
    evidence for each. Submit the standalone reviewed_answer with an overview,
    steps [{text,events:[EID]}], combined result, and optional inactive explanation.
    This records your presentation judgment, not a Host quality score.
    """
    try:
        return _ok(current_task_report_store().record_task_review(
            verdict, criteria, findings, next_actions, blocker, decision_request, visual_review, visual_checks,
            reviewed_answer))
    except Exception as error:
        return _err(error)


@mcp.tool()
@_organization_write_transaction
def record_shader_organization_review(
    workspace_path: str,
    expected_source_sha256: str,
    verdict: Literal["needs_work", "complete", "blocked"],
    checks: dict[str, str],
    findings: list[str],
    next_actions: list[str],
    blocker: str = "",
    organization_id: str = "",
    no_change_reason: str = "",
    scope_review: dict | None = None,
    resource_naming_review: dict | None = None,
    semantic_overview: dict | None = None,
) -> str:
    """Record the Agent's self-review of the exact Shader workspace source.

    Review readability, Unity-style internal structure, meaningful function
    calls and redundant temporaries. Inspect opportunities to combine same-role
    component calculations into vectors, express recognized math with suitable
    intrinsics, and organize actual calls like a directory hierarchy: major
    operations own sub-operations and concrete algorithms. Inspect every
    requested branch and business-function body; representative paths summarize
    evidence but do not replace checking siblings or fallbacks. Shared helpers
    may have multiple callers. Cite rewritten expressions and paths, plus reasons for
    retained scalar sequences or flat helpers; renaming alone is not sufficient.
    Do not impose a fixed hierarchy or duplicate this assessment in extra tool
    rounds. Each checks entry needs source-specific evidence, not a boolean.
    This tool checks only source identity and record
    shape; it never judges code quality, compiles or replays. A complete review
    has no unresolved findings/actions. Use needs_work and continue editing,
    or blocked with the concrete unavailable prerequisite. A later source edit
    invalidates this receipt. Keep the captured HLSL/ABI; Unity style does not
    mean wrapping replay source in ShaderLab. Pass the proposal hash before
    publication or the saved source hash afterwards.
    If full-scope review finds the existing source already meets the request,
    supply no_change_reason and report that no new rewrite was made. Never make
    meaningless edits merely to change the hash or skip the four source checks.
    Complete requires scope_review={baseline_source_sha256,plan,results,
    observation_dispositions}. Each
    plan row has id, requirement and functions from begin.sourceReviewScope's
    initialFunctions. Each matching result has id, status (satisfied/unmet/blocked),
    source_functions, evidence, branches [{path,status,evidence}],
    retained_intermediates and remaining_work. Cover all initial and current
    functions; related unchanged functions may share a scope. Review every
    requested branch within each scope, including fallback paths and helper
    bodies. Complete cannot leave any scope/branch unmet or work remaining.
    For broad organization, reconsider existing function boundaries as well as
    bodies. In each computation scope's existing evidence, record the actual
    outcome or a specific retention reason for body simplification,
    responsibility/call design, shared algorithm implementations and shared
    computed results. Inspect remaining expressions, unchanged helpers and
    related variants; another improved example cannot offset a feasible gap.
    Such a gap keeps its scope unmet and requires repair in the same task.
    Reusing a helper is distinct from reusing its result with unchanged inputs
    under valid evaluation conditions. A genuinely clear body can remain
    unchanged with a source-specific reason; do not invent reuse or call layers.
    These decisions use the existing evidence fields and assessment call, not
    extra review rounds. Respect narrower requested scope and affected
    dependencies; this tool does not require rewriting an explain-only Shader.
    Review interleaved channel families, repeated function bodies, dense
    assignments and misplaced/missing function summaries, using source-bound
    observations as navigation. A zero detector count does not prove absence
    of those gaps. Simplify value lifetimes and use named vector contributions;
    local precision constraints do not require retaining an entire scalar forest.
    In observation_dispositions, assess every candidateId in the complete
    source catalog linked by begin/write sourceReviewObservations.catalog.relativePath.
    Read it once with read_shader_workspace_file(mode=complete); inline examples
    are a preview and do not define the review scope. Each item contains
    {candidate_id,scope_ids:[matching scope ids],status:retained|needs_work,evidence}.
    A retained item also needs alternative (the concrete simpler form considered)
    and source_anchor={start_line,end_line,text}: exact current source lines tied
    to this candidate's calculation. evidence explains why that alternative
    changes the actual contract or is less readable here. A function signature,
    unrelated example or blanket precision claim is not a local source anchor.
    Current candidates cannot be marked resolved; repair feasible gaps first.
    Complete covers the entire catalog, including entries omitted from inline
    previews. Assignment examples are explicitly top-eight navigation only;
    all bodies and branches still need semantic review. Zero matches proves no
    quality verdict. Reuse source knowledge and the latest catalog; no tool call,
    reread or compile per candidate. Legacy reviews lacking complete evidence
    remain readable but cannot authorize final validation.
    This is coverage of the Agent's assessment, not Host semantic approval.

    Complete requires semantic_overview={stages:[{id,title,description?,anchors:
    [{function,startLine?,endLine?}],helperSignatures?:[]}],review:{source_sha256,
    granularity_evidence,data_flow_evidence,remaining_work:[],scope_mappings:
    [{scope_id,stage_ids,disposition,evidence}]}}. Match all source-review scopes;
    each stage must be represented. disposition is represented/supporting/inactive;
    supporting work maps to an owner; inactive source needs a concrete reason.
    The independent directory uses short titles for meaningful calculations;
    inspect inside coarse entry orchestration instead of copying its direct calls.
    Prefer useful detail over broad groups that hide independently explainable
    major calculations or meaningful intermediate results. Use mesh/texture/state
    observations as working hypotheses, then confirm the actual expressions and
    consumers. Apply the same granularity to the corresponding function-graph
    level; small supporting operations remain with their owner.
    Review data flow and appropriate granularity from the actual full program;
    no fixed stage count, technique list or all-helper expansion is required.
    group supporting address math, taps and terms with their owner. Multiple
    anchors can cover one effect across functions. Function-only anchors cover
    the whole function; optional lines must name a real range inside it. Review
    duplicates, missing effects and the actual draw/mesh/texture context. Do not
    write @overview/@stage metadata or provenance banners into Shader source.
    The Host derives token anchors from these exact reviewed bytes, allowing
    navigation to follow later edits without trusting stale line numbers.
    An old navigation-only sidecar cannot satisfy a new complete review. If only
    directory metadata is missing, get_shader_semantic_overview_context and
    update_shader_semantic_overview repair it without rewriting or recompiling.
    """
    try:
        from .shader_organization_review import make_review, source_snapshot, _read_bytes
        # One normal workspace validation, followed only by bounded local
        # reads. No compiler, replay, UI context or full catalog per criterion.
        root = _workspace_root_for_files(workspace_path)
        organization = str(organization_id or "")
        targets = current_task_report_store().shader_organization_review_state()["targets"]
        if not organization:
            organization = next((str(row["organizationId"]) for row in targets
                                 if Path(row["workspacePath"]).resolve() == root), "")
        snapshot = source_snapshot(str(root), organization)
        task_target = next((row for row in targets if row.get("organizationId") == organization
                            and Path(row["workspacePath"]).resolve() == root), None)
        if task_target is not None:
            snapshot["taskSourceChanged"] = bool(task_target.get("initialSourceSha256")
                                                 and snapshot["sourceSha256"] != task_target["initialSourceSha256"])
        if verdict == "complete":
            from .shader_source_reads import require_current
            require_current(current_task_report_store(), str(root), organization, snapshot["sourceSha256"])
        if snapshot["sourceSha256"] != expected_source_sha256:
            raise ValueError("Shader source changed since the Agent reviewed it; review the current bytes")
        overview = None
        if semantic_overview is not None:
            from .shader_workspace.semantic_overview import prepare_reviewed_overview
            if not isinstance(semantic_overview, dict) or not isinstance(semantic_overview.get("stages"), list):
                raise ValueError("semantic_overview must contain ordered stages")
            _, source_bytes = _read_bytes(root, snapshot["sourcePath"], 4 * 1024 * 1024)
            if hashlib.sha256(source_bytes).hexdigest() != expected_source_sha256:
                raise RuntimeError("Shader source changed before overview publication")
            session = read_json_object(root / "ai" / "organization-sessions" / organization / "session.json",
                                       2 * 1024 * 1024, "Shader organization session")
            overview = prepare_reviewed_overview(source_bytes.decode("utf-8"), semantic_overview,
                                                 str(session.get("entryPoint") or ""), scope_review)
            overview.update(organizationId=organization,
                            originalRawSha256=str(session.get("shaderRawSha256") or
                                                  session.get("originalRawSha256") or ""))
            overview_path = root / "ai" / "semantic-overview.json"
            if overview_path.is_symlink() or overview_path.parent.is_symlink() or not is_within(root, overview_path.resolve()):
                raise RuntimeError("Shader overview path is redirected")
        receipt = make_review(snapshot, expected_source_sha256, verdict,
                              checks, findings, next_actions, blocker, no_change_reason,
                              scope_review, require_scope=True, prepared_overview=overview,
                              require_overview=True)
        # Recheck before publication; the runtime checks again at end_turn.
        if source_snapshot(str(root), organization)["sourceSha256"] != expected_source_sha256:
            raise RuntimeError("Shader source changed during self-review publication")
        review_path = Path(receipt["reviewPath"])
        if review_path.is_symlink():
            raise RuntimeError("Shader self-review path is redirected")
        if overview is not None:
            atomic_write_shader_json(overview_path, overview)
        atomic_write_shader_json(review_path, receipt)
        if resource_naming_review is not None:
            from .shader_resource_naming_review import record as record_resource_naming
            _, source_bytes = _read_bytes(root, snapshot["sourcePath"], 4 * 1024 * 1024)
            receipt["resourceNamingDelivery"] = record_resource_naming(root, source_bytes, resource_naming_review)
        return _ok(receipt)
    except Exception as error:
        return _shader_err(error, "organization-self-review")


def _semantic_overview_context(workspace_path: str, organization_id: str = "") -> tuple:
    from .shader_organization_review import canonical_source_path, source_snapshot, _read_bytes
    from .shader_workspace.semantic_overview import overview_analysis_context
    root = _workspace_root_for_files(workspace_path)
    snapshot = source_snapshot(str(root), organization_id) if organization_id else None
    path = snapshot["sourcePath"] if snapshot else canonical_source_path(str(root))
    source_path, source = _read_bytes(root, path, 4 * 1024 * 1024)
    manifest = read_json_object(root / "manifest.json", 2 * 1024 * 1024, "Shader workspace manifest")
    session = (read_json_object(root / "ai" / "organization-sessions" / organization_id / "session.json",
                               2 * 1024 * 1024, "Shader organization session") if snapshot else {})
    overview, receipt, diagnostics = None, None, []
    for target, label in (("ai/semantic-overview.json", "overview"),
                          ((snapshot or {}).get("reviewPath", ""), "review")):
        if not target:
            continue
        try:
            _, raw = _read_bytes(root, target, 256 * 1024)
            value = json.loads(raw)
            if not isinstance(value, dict):
                raise ValueError("Stored Shader " + label + " must be an object")
            if label == "overview":
                overview = value
            else:
                receipt = value
        except FileNotFoundError:
            pass
        except (OSError, ValueError, TypeError) as error:
            # Broken old metadata is the reason to use this repair route, not
            # a prerequisite that prevents replacing it. Source remains strict.
            diagnostics.append({"artifact": label, "reason": str(error)[:500]})
    context = overview_analysis_context(source.decode("utf-8"),
                                       str(session.get("entryPoint") or manifest.get("entryPoint") or ""), overview)
    context.update(workspacePath=str(root), sourcePath=str(source_path), organizationId=organization_id,
                   sourceReview=receipt, navigationOnly=True, metadataDiagnostics=diagnostics)
    return root, source, snapshot, context, manifest, session


@mcp.tool()
def get_shader_semantic_overview_context(workspace_path: str, organization_id: str = "") -> str:
    """Read current source locations and existing calculation-directory evidence.

    No Shader edits, compilation, replay or inferred stage list. Read the whole
    source via read_shader_workspace_file before authoring the independent
    directory. Optional organization_id selects its current proposal; otherwise
    this reads saved source. Existing sourceReview scopes can be reused as
    evidence when still current. Function locations are navigation, not a
    prescribed semantic stage list or proof of complete source analysis.
    """
    try:
        return _ok(_semantic_overview_context(workspace_path, organization_id)[3])
    except Exception as error:
        return _shader_err(error, "semantic-overview-context")


def _publish_semantic_overview_metadata(root: Path, overview: dict, source_path: str) -> dict:
    """Share source-bound navigation under the owning active project only."""
    from .shader_workspace.semantic_overview_storage import publish_overview
    from .shader_organization_review import _read_bytes
    result = {"updatedLocal": True, "projectShared": False, "projectStatus": "skipped"}
    try:
        active = _active_project_service()
        status = active.status()
        project = str(status.get("projectRoot") or "")
        if not project:
            result["reason"] = "no-active-project"
            return result
        with active.pin_active_project(str(status.get("workspaceId") or ""), project):
            _require_managed_active_workspace(status, str(root))
            _, source = _read_bytes(root, source_path, 4 * 1024 * 1024)
            if hashlib.sha256(source).hexdigest() != overview["sourceSha256"]:
                raise RuntimeError("Shader source changed before project overview sharing")
            shared = publish_overview(Path(project), root, overview["originalRawSha256"], overview["sourceSha256"])
            result.update(projectShared=shared, projectStatus="published" if shared else "skipped")
    except Exception as error:
        result["reason"] = str(error)[:500]
    return result


@mcp.tool()
@_organization_write_transaction
def update_shader_semantic_overview(workspace_path: str, expected_source_sha256: str,
                                   semantic_overview: dict, organization_id: str = "") -> str:
    """Publish an independently reviewed calculation directory without editing/recompiling source.

    Use for an absent, coarse or stale directory after reading the full current
    Shader. semantic_overview has stages plus review={source_sha256,
    granularity_evidence,data_flow_evidence,remaining_work:[],scope_mappings:
    [{scope_id,stage_ids,source_functions,disposition,evidence}]}. Explain the
    independent meaningful calculations and their data flow; neither the entry's
    direct calls nor every helper is a sufficient default. disposition is
    represented/supporting/inactive; supporting work maps to an owning stage,
    inactive source needs specific evidence. No prescribed technique or count.
    Cover current source functions, allow several calculations in one function
    or several functions per stage, and use stable anchors as in source review.
    Revisit broad groups that hide independently explainable major calculations
    and useful intermediate results. Initial mesh/texture/draw-state hypotheses
    must be checked against the actual source. Keep the directory and relevant
    function-graph level informative without listing every supporting operation.
    With organization_id, reuse its current source-review scope ids/functions.
    A current valid source review can receive this new directory receipt without
    recompilation; missing/stale source assessment remains pending separately.
    """
    try:
        from .shader_workspace.semantic_overview import prepare_reviewed_overview, overview_digest
        from .shader_organization_review import make_review, _read_bytes
        root, source, snapshot, context, manifest, session = _semantic_overview_context(workspace_path, organization_id)
        if context["sourceSha256"] != expected_source_sha256:
            raise ValueError("Shader source changed since calculation overview analysis")
        prior = context.get("sourceReview") or {}
        scopes = prior.get("scopeReview") if prior.get("sourceSha256") == expected_source_sha256 else None
        overview = prepare_reviewed_overview(source.decode("utf-8"), semantic_overview, context["entryPoint"], scopes)
        overview.update(organizationId=organization_id,
                        originalRawSha256=str(session.get("shaderRawSha256") or session.get("originalRawSha256")
                                              or (manifest.get("baseline") or {}).get("rawSha256")
                                              or manifest.get("originalRawSha256") or ""))
        receipt = None
        if snapshot and scopes and prior.get("verdict") == "complete":
            from .shader_source_reads import require_current
            require_current(current_task_report_store(), str(root), organization_id, expected_source_sha256)
            receipt = make_review(snapshot, expected_source_sha256, prior["verdict"], prior["checks"],
                                  prior["findings"], prior["nextActions"], prior.get("blocker", ""),
                                  prior.get("noChangeReason", ""), scopes, require_scope=True,
                                  prepared_overview=overview, require_overview=True)
        target = root / "ai" / "semantic-overview.json"
        if target.is_symlink() or target.parent.is_symlink() or not is_within(root, target.resolve()):
            raise RuntimeError("Shader overview path is redirected")
        _, current = _read_bytes(root, context["sourcePath"], 4 * 1024 * 1024)
        if current != source:
            raise RuntimeError("Shader source changed during overview publication")
        if receipt and Path(receipt["reviewPath"]).is_symlink():
            raise RuntimeError("Shader self-review path is redirected")
        atomic_write_shader_json(target, overview)
        publication = _publish_semantic_overview_metadata(root, overview, context["sourcePath"])
        if receipt:
            atomic_write_shader_json(Path(receipt["reviewPath"]), receipt)
            receipt["overviewPublication"] = publication
            return _ok(receipt)
        return _ok({"workspacePath": str(root), "organizationId": organization_id,
                    "sourceSha256": expected_source_sha256, "path": str(target),
                    "overviewSha256": overview_digest(overview), "stageCount": len(overview["stages"]),
                    "navigationOnly": True, "sourceUnchanged": True, "overviewPublication": publication})
    except Exception as error:
        return _shader_err(error, "semantic-overview-update")


@mcp.tool()
@_organization_write_transaction
def record_shader_resource_naming_review(
    workspace_path: str, expected_source_sha256: str, review: dict, organization_id: str = "",
) -> str:
    """Record one batch of Agent resource decisions; no scan, compile or replay.

    Reuse this optional review in record_shader_organization_review when ready
    before finish. Otherwise finish the source once, publish display names and
    record this batch afterwards. Review has assets={status,evidence,usage},
    textures=[{selector,status,evidence,operation_id}], reconciliation (text).
    Asset status is not-configured/matched/reused/partial/no-match/reader-unavailable.
    Explain actual matched assets and their use, or a concrete unavailable reason.
    Matched/reused assets additionally require evidence_paths with readable
    workspace evidence files (normally ai/asset-resolution.json); their exact
    bytes and known target/root identities are checked, without repeating scans.
    Texture selectors come from outline(section='resource-naming'); cover every
    declaration. Status is published (requires the committed
    publish_shader_resource_names operation_id), retained (an existing meaningful
    name deliberately kept), or unresolved (explain unknown/no live binding).
    Unknowns do not require invented names. CBuffer completion separately requires
    publish_cbuffer_aliases for every active binding. A source/target/root change
    invalidates this review; reuse matching assets without scanning again.
    """
    try:
        from .shader_organization_review import canonical_source_path, source_snapshot, _read_bytes
        from .shader_resource_naming_review import record
        root = _workspace_root_for_files(workspace_path)
        source_path = (source_snapshot(str(root), organization_id)["sourcePath"]
                       if organization_id else canonical_source_path(str(root)))
        _, source = _read_bytes(root, source_path, 4 * 1024 * 1024)
        if hashlib.sha256(source).hexdigest() != expected_source_sha256:
            raise ValueError("Shader source changed before resource naming review")
        return _ok({"workspacePath": str(root), "resourceNamingDelivery": record(root, source, review),
                    "cbufferSemanticDelivery": _shader_cbuffer_semantic_delivery(str(root), source_path=source_path)})
    except Exception as error:
        return _shader_err(error, "resource-naming-review")


@mcp.tool()
@_organization_write_transaction
def write_shader_workspace_organization_file(
    workspace_path: str,
    organization_id: str,
    kind: Literal["proposal", "analysis", "flowchart"],
    content: str = "",
    expected_proposal_sha256: str = "",
    expected_source_sha256: str = "",
    source_file: str = "",
    expected_canonical_sha256: str = "",
    edits: list[dict[str, str]] | None = None,
) -> str:
    """Write the current shader draft, analysis or Mermaid flowchart.

    For related local changes, edit the owned ``agentFile`` with native tools
    and import ``source_file``, or submit one atomic ``edits`` batch against
    the current proposal hash. ``content`` supports a genuine whole-file
    replacement. ``source_file`` accepts only this run's owned Agent working
    files, not arbitrary filesystem paths. Draft text edits do not use the
    restructure tool's static semantic/extraction analysis and may save an
    incomplete working draft; they do not compile, validate ABI or apply replay.

    `kind` is `proposal`, `analysis` or `flowchart`. Explanatory artifacts may
    also be written after closing the session: they are bound to the current
    saved Source in a derived sidecar and published to ``ai/analysis.md`` or
    ``ai/flowchart.mmd`` without reopening its acceptance receipt. Publication
    compares the observed documents and current Source; concurrent edits are
    preserved. The returned ``canonicalPublication`` names the public artifact.
    To merge an externally edited public document, read it with
    ``read_shader_workspace_file`` and supply its actual SHA-256 as
    ``expected_canonical_sha256``. This content check permits replacing an old
    derived sidecar without accepting stale or concurrent document edits.
    `expected_source_sha256` optionally checks that observed Source. A proposal write may include the SHA-256
    of the bytes read earlier to reject a stale overwrite. This call saves the
    draft; it does not compile, judge readability or alter replay.
    Instead of embedding the entire text in ``content``, ``source_file`` may
    import a UTF-8 working file from this run's Agent directory. For proposal
    drafts, ``edits=[{"old_text": "...", "new_text": "..."}]`` avoids resending
    the whole file and requires ``expected_proposal_sha256``. Each old_text
    must match exactly once after preceding edits; replacements are applied in
    order and all are saved together only if every edit succeeds. Include
    enough surrounding text to distinguish repeated calculations. Use exactly
    one input: content, source_file or edits. The same current proposal/source
    guards and final publication checks apply; text edits do not judge
    algorithms or require compile/ABI checks.
    """

    try:
        input_file = None
        if sum((bool(content), bool(source_file), edits is not None)) != 1:
            raise ValueError("Supply exactly one of content, source_file or edits")
        if source_file:
            from .agent_workspace_files import read_agent_text_file
            content, input_file = read_agent_text_file(source_file)
        selected_kind = str(kind or "").strip().lower()
        selected = _ORGANIZATION_FILE_KINDS.get(selected_kind)
        if selected is None:
            raise ValueError("kind must be proposal, analysis or flowchart")
        if edits is not None and selected_kind != "proposal":
            raise ValueError("edits apply only to proposal drafts")
        if edits is not None and not expected_proposal_sha256:
            raise ValueError("edits require expected_proposal_sha256")
        if edits is None and (not isinstance(content, str) or not content.strip() or "\x00" in content):
            raise ValueError("content must be non-empty NUL-free text")
        organization = _strict_lower_hex(organization_id, 32, "organization_id")
        from .shader_workspace.organization import _draft_status
        status = _draft_status(_shader_workspace_service(), workspace_path)
        root = Path(status["workspacePath"]).resolve()
        session_dir = (root / "ai" / "organization-sessions" / organization).resolve()
        if not is_within(root, session_dir) or not session_dir.is_dir():
            raise FileNotFoundError("organization session does not exist in this workspace")
        session = read_json_object(
            session_dir / "session.json", 2 * 1024 * 1024, "organization session"
        )
        if session.get("organizationId") != organization:
            raise RuntimeError("organization session id mismatch")
        manager = _shader_organization_manager()
        closed_session = session.get("state") not in {"drafting", "awaiting-proposal-review"}
        expected_canonical = (_strict_lower_hex(expected_canonical_sha256, 64, "expected_canonical_sha256")
                              if expected_canonical_sha256 else "")
        if expected_canonical and (not closed_session or selected_kind == "proposal"):
            raise ValueError("expected_canonical_sha256 applies to closed-session explanations")
        source_binding = None
        source_path = None
        if closed_session:
            if selected_kind == "proposal":
                raise RuntimeError("organization draft is no longer editable")
            if (not manager._same_shader_program(session, status)
                    or normalize_stage(session.get("stage")) != normalize_stage(status.get("stage"))
                    or session.get("entryPoint", "") != status.get("entryPoint", "")):
                raise RuntimeError("organization explanation belongs to a different captured Shader program")
            source = status.get("source")
            if not isinstance(source, Mapping) or source.get("present") is not True:
                raise RuntimeError("workspace Source is unavailable")
            source_path = Path(str(source.get("path") or ""))
            if source_path.is_symlink() or not source_path.is_file() or not is_within(root, source_path.resolve()):
                raise RuntimeError("workspace Source path is invalid or redirected")
            source_sha256 = _bounded_file_sha256(source_path, _WORKSPACE_FILE_MAX_BYTES, "workspace Source")
            if source.get("currentSha256") != source_sha256:
                raise RuntimeError("workspace Source changed during explanation binding")
            if expected_source_sha256 and source_sha256 != _strict_lower_hex(
                    expected_source_sha256, 64, "expected_source_sha256"):
                raise RuntimeError("workspace Source differs from the supplied explanation binding")
            final_binding = session.get("finalBinding")
            final_binding = final_binding if isinstance(final_binding, Mapping) else {}
            source_binding = {
                "schema": "renderdoc-ai-shader-explanation-source-binding/v1",
                "sourcePath": str(source_path.resolve()),
                "sourceSha256": source_sha256,
                "sourceRevision": status.get("revision"),
                "originalRawSha256": str((status.get("baseline") or {}).get("rawSha256") or ""),
                "stage": status.get("stage"), "entryPoint": status.get("entryPoint", ""),
                "organizationFinalSourceSha256": final_binding.get("sourceSha256"),
                "matchesOrganizationFinalSource": final_binding.get("sourceSha256") == source_sha256,
                "acceptanceAuthorization": False,
            }
        else:
            if expected_source_sha256:
                expected_source = _strict_lower_hex(expected_source_sha256, 64, "expected_source_sha256")
                current_status = status
                current_source = current_status.get("source") or {}
                current_path = Path(str(current_source.get("path") or ""))
                if (current_path.is_symlink() or not current_path.is_file()
                        or not is_within(root, current_path.resolve())
                        or _bounded_file_sha256(current_path, _WORKSPACE_FILE_MAX_BYTES, "workspace Source") != expected_source):
                    raise RuntimeError("workspace Source differs from the supplied explanation binding")
            requirement = getattr(current_task_report_store(), "shader_source_read_required", None)
            if selected_kind == "proposal" and callable(requirement) and requirement(str(root)):
                from .shader_organization_review import source_snapshot
                from .shader_source_reads import require_current
                read_snapshot = source_snapshot(str(root), organization)
                require_current(current_task_report_store(), str(root), organization,
                                read_snapshot["sourceSha256"])
            manager.authorize_edit(str(root), organization, status=status)
        session_key, limit, description = selected
        declared_path = Path(str(session.get(session_key, "") or ""))
        target = (declared_path.resolve() if declared_path.is_absolute()
                  else _workspace_file_target(root, str(declared_path)))
        if not is_within(root / "ai", target):
            raise RuntimeError("draft path is outside the AI-editable tree")
        if closed_session and (
                target.parent != session_dir
                or target.name not in ({"analysis.md", "analysis.txt"} if selected_kind == "analysis" else {"flowchart.mmd"})):
            raise RuntimeError("closed-session explanation path is not its declared explanation artifact")
        previous_proposal_sha256 = (
            _bounded_file_sha256(target, limit, "organization proposal")
            if selected_kind == "proposal" else ""
        )
        if selected_kind == "proposal" and expected_proposal_sha256:
            expected = _strict_lower_hex(
                expected_proposal_sha256, 64, "expected_proposal_sha256"
            )
            if previous_proposal_sha256 != expected:
                raise RuntimeError("proposal changed since it was read")
        if edits is not None:
            from .shader_workspace.io import apply_exact_text_edits
            with target.open("rb") as stream:
                original = stream.read(limit + 1)
            if len(original) > limit or hashlib.sha256(original).hexdigest() != previous_proposal_sha256:
                raise RuntimeError("proposal changed while preparing text edits")
            content = apply_exact_text_edits(original.decode("utf-8", errors="strict"), edits,
                                            maximum_bytes=limit)
            if not content.strip() or "\x00" in content:
                raise ValueError("edited proposal must be non-empty NUL-free text")
        data = content.encode("utf-8")
        if len(data) > limit:
            raise ValueError("%s exceeds its size limit (%d bytes)" % (selected_kind, limit))
        from .shader_workspace.io import atomic_write_bytes
        if source_binding is not None and _bounded_file_sha256(
                source_path, _WORKSPACE_FILE_MAX_BYTES, "workspace Source") != source_binding["sourceSha256"]:
            raise RuntimeError("workspace Source changed before explanation write")
        canonical_publication = None
        if source_binding is None:
            if selected_kind == "proposal" and _bounded_file_sha256(
                    target, limit, "organization proposal") != previous_proposal_sha256:
                raise RuntimeError("proposal changed before draft write")
            atomic_write_bytes(target, data)
            manager.checkpoint(str(root), organization, status=status)
        else:
            from .shader_workspace.explanations import publish_closed_explanation
            source_binding, canonical_publication = publish_closed_explanation(
                store_root=manager._mutation_store, root=root,
                organization_id=organization, session_artifact=target,
                kind=selected_kind, data=data, source_binding=source_binding,
                status=status, expected_canonical_sha256=expected_canonical,
            )
        result = {
            "schema": "renderdoc-ai-shader-organization-file/v1",
            "workspacePath": str(root),
            "organizationId": organization,
            "kind": selected_kind,
            "path": str(target),
            "bytes": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
            "previousProposalSha256": previous_proposal_sha256,
            "description": description,
            "sourceBinding": source_binding,
            "canonicalPublication": canonical_publication,
            "inputFile": input_file,
            "textEditsApplied": len(edits) if edits is not None else 0,
            "artifactOnly": selected_kind != "proposal",
            "applied": False,
        }
        if selected_kind == "proposal":
            result["proposalEditing"] = _proposal_editing_capabilities(result["sha256"])
            try:
                from .shader_organization_review import source_snapshot
                observation_snapshot = source_snapshot(str(root), organization)
                if observation_snapshot["sourceSha256"] != result["sha256"]:
                    raise RuntimeError("proposal changed before observing the saved draft")
                result["sourceReviewObservations"] = _shader_source_review_delivery(observation_snapshot)
            except Exception as observation_error:
                result["sourceReviewObservationsError"] = str(observation_error)
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "organization-file-write")


@mcp.tool()
async def restructure_shader_workspace_source(
    workspace_path: str,
    organization_id: str,
    operation: str,
    operation_id: str = "",
    start_line: int = 0,
    end_line: int = 0,
    name: str = "",
    new_name: str = "",
    comment: str = "",
    expected_proposal_sha256: str = "",
    edits: list[dict[str, Any]] | None = None,
    wait_seconds: float = 5.0,
) -> str:
    """Host-applied structural refactoring of the organization proposal.

    ``operation="extract"``: lines ``start_line..end_line`` of the *current*
    proposal (1-based, a complete statement range inside one function) become
    a new function ``name``. Choose a cohesive range from syntax and available
    model context rather than a fixed line count; a reading window may be
    smaller than the complete calculation. Defer an unfinished trailing
    expression or branch to the next calculation. The Host infers
    inputs, inout and out parameters
    or the single return value from data flow, re-indents, replaces the range
    with a call, places the function above its caller with ``comment`` as its
    header, applies recorded operations to the durable proposal and statically
    checks the result — a range that is not provably safe (a ``return``
    inside it, an escaping ``break``/``continue``, a cut through if/else or a
    multi-line statement, array locals) is refused with the reason and the
    session is unchanged. Draft extraction does not run full-source compile or
    replay ABI; reserve those checks for final validation. A targeted draft check
    is available when a concrete source risk requires it. ``undo`` drops
    the last operation, ``remove``
    drops the operation that created ``name``, ``rename_function`` renames
    an extracted function (``name`` -> ``new_name``), ``note`` records your
    one-sentence purpose for function ``name`` (in ``comment``), ``list``
    reports a current whole-source ``ledger`` and ``structure`` metrics.
    Local extract, rewrite and note edits return their receipt and source hash
    without computing those whole-source summaries; their ``ledger`` is null
    and ``structure.available`` is false. Line numbers change after each
    source edit. The read-only list operation provides current summaries when
    they are useful for a whole-program view.
    Draft refactoring does not touch replay state.

    The Host generates and returns ``operationId`` when omitted. A caller may
    provide an ID to recover an identical first request after a lost response.
    Reuse a returned ID or poll ``get_shader_workspace_mutation_status`` after
    a timeout. Read-only ``operation="list"`` needs no operation ID.

    ``operation="rewrite"`` is HLSL-only: provide the current proposal's exact
    ``expected_proposal_sha256`` and ``edits``. A transaction ``name`` is
    optional; the Host returns a unique ledger label when needed. Edits are
    [{startLine,endLine,replacement}], all using current 1-based inclusive lines.
    At most 16 non-overlapping complete statement/function/struct edits, 400 affected
    lines and 64 KiB combined before+after text are accepted. One transaction can
    change an internal helper signature and all its calls, merge duplicate
    formulas or inline single-use temporaries. Pure internal computation structs
    can be introduced or changed together with their helpers and callers. Actual
    resource/CB/interface struct layouts, other global declarations, the entry
    signature and preprocessor directives are protected. Internal struct fields
    may use scalar/vector/matrix or other pure structs, without arrays, resource
    types, semantics or bindings. Larger proposals can use the full proposal-file
    writer; these patch limits do not prescribe a refactoring route.
    All edits receive one static safety check
    before proposal or ledger publication; failure/cancellation leaves the
    prior state intact. Full compile/ABI belongs to final validation.
    Canonical token anchors preserve later rename/extract/undo/remove composition;
    removing an operation needed by a later one is refused instead of guessing
    a new range. This draft operation does not validate replay compatibility;
    final validation uses the current compiled candidate and captured ABI. Use the returned
    proposalSourceSha256 and ledger before the next rewrite; read only affected
    ranges when the next decision needs source text.
    """

    try:
        normalized_operation = str(operation or "").strip().lower()
        if normalized_operation not in {
            "extract", "rewrite", "undo", "remove",
            "rename_function", "note", "list",
        }:
            raise ValueError(
                "operation must be one of: extract, rewrite, undo, remove, "
                "rename_function, note, list"
            )
        request_edits = copy.deepcopy(edits)
        request = {
            "tool": "restructure_shader_workspace_source",
            "workspacePath": str(workspace_path or ""),
            "organizationId": str(organization_id or ""),
            "operation": normalized_operation,
            "startLine": int(start_line or 0),
            "endLine": int(end_line or 0),
            "name": str(name or ""),
            "newName": str(new_name or ""),
            "comment": str(comment or ""),
            "expectedProposalSha256": str(expected_proposal_sha256 or ""),
            "edits": request_edits,
        }
        # ``list`` is a bounded read of the existing Host ledger.  It neither
        # needs an operation id nor mutates the draft.
        if normalized_operation == "list":
            result = await asyncio.to_thread(
                lambda: _shader_organization_manager().restructure(
                    workspace_path,
                    organization_id,
                    normalized_operation,
                    start_line=request["startLine"],
                    end_line=request["endLine"],
                    name=request["name"],
                    new_name=request["newName"],
                    comment=request["comment"],
                    expected_proposal_sha256=request["expectedProposalSha256"],
                    edits=request_edits,
                )
            )
            return _ok(result)

        from .shader_workspace.mutation_jobs import (
            normalize_operation_id,
            start_shader_mutation_job,
            wait_for_shader_mutation_job,
        )
        requirement = getattr(current_task_report_store(), "shader_source_read_required", None)
        read_store = None
        if callable(requirement) and requirement(workspace_path):
            from .shader_organization_review import source_snapshot
            from .shader_source_reads import require_current
            read_snapshot = source_snapshot(workspace_path, organization_id)
            require_current(current_task_report_store(), workspace_path, organization_id,
                            read_snapshot["sourceSha256"])
            request["expectedProposalSha256"] = request["expectedProposalSha256"] or read_snapshot["sourceSha256"]
            read_store = current_task_report_store()
        resolved_operation_id = normalize_operation_id(operation_id)
        request_sha, compatible_request_shas = workspace_bound_request_hashes(
            request, workspace_path
        )

        def _runner() -> dict[str, Any]:
            slot = LongToolSlot(
                "restructure_shader_workspace_source",
                {
                    "operation": normalized_operation,
                    "organization_id": organization_id,
                    "operation_id": resolved_operation_id,
                },
            )
            # This is a draft file mutation. Its workspace transaction and job
            # ledger serialize actual writers; the global progress display is
            # telemetry, not a reason to reject unrelated source work.
            ok = False
            try:
                slot.update(
                    "restructuring",
                    operation=normalized_operation,
                    operationId=resolved_operation_id,
                    detail="operation=%s" % normalized_operation,
                    summary="restructure operation=%s" % normalized_operation,
                )
                result = _shader_organization_manager().restructure(
                    workspace_path,
                    organization_id,
                    normalized_operation,
                    start_line=request["startLine"],
                    end_line=request["endLine"],
                    name=request["name"],
                    new_name=request["newName"],
                    comment=request["comment"],
                    expected_proposal_sha256=request["expectedProposalSha256"],
                    edits=request_edits,
                    operation_id=resolved_operation_id,
                    request_sha256=request_sha,
                    compatible_request_sha256=compatible_request_shas,
                )
                if read_store is not None:
                    read_store.record_shader_source_edit(workspace_path, organization_id,
                        request["expectedProposalSha256"], str(result.get("proposalSourceSha256") or ""))
                ok = True
                runtime = slot.close(ok=True)
                return attach_runtime(dict(result or {}), runtime if runtime is not None else {"ok": True})
            finally:
                if not ok:
                    slot.close(ok=False)

        job = start_shader_mutation_job(
            tool="restructure_shader_workspace_source",
            workspace_path=workspace_path,
            organization_id=organization_id,
            request_sha256=request_sha,
            compatible_request_sha256=compatible_request_shas,
            operation_id=resolved_operation_id,
            runner=_runner,
        )
        waited = max(0.0, min(float(wait_seconds or 0.0), 5.0))
        if waited and job.get("status") not in {"busy", "done", "failed"}:
            job = await asyncio.to_thread(
                wait_for_shader_mutation_job,
                str(job.get("operationId") or ""),
                waited,
            ) or job
        return _ok(_shader_mutation_tool_result(job))
    except Exception as error:
        return _shader_err(error, "organization-restructure")


@mcp.tool()
def rename_shader_workspace_symbols(
    workspace_path: str,
    organization_id: str,
    renames: dict,
    operation_id: str = "",
    comments: dict | None = None,
    asset_name_authorization: dict | None = None,
    wait_seconds: float = 5.0,
) -> str:
    """Rename identifiers and add function comments — applied by the Host.

    ``renames`` maps old identifier -> new identifier (cbuffers, cbuffer
    fields, textures, samplers, buffers, struct fields, functions, locals).
    ``comments`` maps function name -> one or two sentences placed above its
    definition.  The Host edits the baseline HLSL at the token level, so the
    result is *rename-only equivalent* by construction and the review accepts
    it even though DXIL metadata (and therefore the executable hash) changes
    with resource names.  Keywords, types, intrinsics, semantics and register
    slots are refused; collisions are reported by name. Maps accumulate over
    the session and are validated with the final draft when it is applied.

    This tool changes source tokens only. It never writes RenderDoc CBuffer
    panel aliases and never treats a source rename as a panel-publication
    receipt. Publish panel display names separately with
    ``publish_cbuffer_aliases``; it binds chosen names to current reflected
    offsets and can retain optional naming provenance. A supplied same-platform
    ``compiledLayoutReceipt`` is checked strictly. Failure or unavailability of the
    panel publication does not invalidate an otherwise valid source rename.

    Generated CBuffer blocks/members and Texture/Buffer/Sampler declarations
    must use the exact ``renameSelector`` returned by the outline. The Agent
    chooses semantic names from the evidence it has read; the Host validates
    only the current source selector, identifier safety and collisions. The
    legacy ``asset_name_authorization`` argument is accepted but ignored so an
    old caller cannot turn an asset/session receipt into workflow authority.
    The Host creates a returned operation ID when omitted. Supply one when
    recovering a lost first response, or reuse the returned ID to poll/retry
    that same request without duplicating the mutation.
    """

    try:
        if not isinstance(renames, dict):
            raise ValueError("renames must be an object {old: new}")
        if comments is not None and not isinstance(comments, dict):
            raise ValueError("comments must be an object {function: text}")
        if asset_name_authorization is not None and not isinstance(asset_name_authorization, dict):
            raise ValueError("asset_name_authorization must be an object when supplied")
        read_store, read_sha = None, ""
        requirement = getattr(current_task_report_store(), "shader_source_read_required", None)
        if callable(requirement) and requirement(workspace_path):
            from .shader_organization_review import source_snapshot
            from .shader_source_reads import require_current
            read_store = current_task_report_store()
            read_sha = source_snapshot(workspace_path, organization_id)["sourceSha256"]
            require_current(read_store, workspace_path, organization_id, read_sha)
        from .shader_workspace.mutation_jobs import (
            normalize_operation_id,
            start_shader_mutation_job,
            wait_for_shader_mutation_job,
        )
        resolved_operation_id = normalize_operation_id(operation_id)

        request_renames = copy.deepcopy(renames)
        request_comments = copy.deepcopy(comments or {})
        request = {
            "tool": "rename_shader_workspace_symbols",
            "workspacePath": str(workspace_path or ""),
            "organizationId": str(organization_id or ""),
            "renames": request_renames,
            "comments": request_comments,
        }
        request_sha, compatible_request_shas = workspace_bound_request_hashes(
            request, workspace_path
        )
        # A durable result written by a pre-change caller included the legacy
        # authorization object in its request hash. Accept that exact replay,
        # but never inspect the object or use it as permission for a new write.
        legacy_request = {
            **request,
            "assetNameAuthorization": copy.deepcopy(asset_name_authorization),
        }
        legacy_sha, legacy_compatible = workspace_bound_request_hashes(
            legacy_request, workspace_path
        )
        compatible_request_shas = list(dict.fromkeys([
            *compatible_request_shas,
            legacy_sha,
            *legacy_compatible,
        ]))

        def _runner() -> dict[str, Any]:
            slot = LongToolSlot(
                "rename_shader_workspace_symbols",
                {
                    "organization_id": organization_id,
                    "operation_id": resolved_operation_id,
                },
            )
            # Preserve an unrelated long tool's telemetry owner while this
            # workspace mutation uses its own CAS/transaction/job identity.
            ok = False
            try:
                slot.update(
                    "renaming",
                    operationId=resolved_operation_id,
                    detail="Host token rename only; panel aliases use explicit publication",
                )
                if read_store is not None:
                    require_current(read_store, workspace_path, organization_id,
                                    source_snapshot(workspace_path, organization_id)["sourceSha256"])
                result = _shader_organization_manager().rename(
                    workspace_path,
                    organization_id,
                    request_renames,
                    request_comments,
                    None,
                    operation_id=resolved_operation_id,
                    request_sha256=request_sha,
                    compatible_request_sha256=compatible_request_shas,
                )
                if read_store is not None:
                    read_store.record_shader_source_edit(workspace_path, organization_id,
                        read_sha, str(result.get("proposalSourceSha256") or ""))
                # Source-token mutation and panel/display publication are
                # deliberately separate effects.  A rename must not create
                # alias-store writes or material-family rules, including when
                # replaying a durable result after a Host restart.
                result.setdefault("memberRules", {
                    "recorded": 0,
                    "reason": (
                        "source rename has no panel-alias side effect; use "
                        "publish_cbuffer_aliases with current physical binding"
                    ),
                })
                ok = True
                runtime = slot.close(ok=True)
                return attach_runtime(result, runtime if runtime is not None else {"ok": True})
            finally:
                if not ok:
                    slot.close(ok=False)

        job = start_shader_mutation_job(
            tool="rename_shader_workspace_symbols",
            workspace_path=workspace_path,
            organization_id=organization_id,
            request_sha256=request_sha,
            compatible_request_sha256=compatible_request_shas,
            operation_id=resolved_operation_id,
            runner=_runner,
        )
        waited = max(0.0, min(float(wait_seconds or 0.0), 5.0))
        if waited and job.get("status") not in {"busy", "done", "failed"}:
            job = wait_for_shader_mutation_job(
                str(job.get("operationId") or ""), waited
            ) or job
        return _ok(_shader_mutation_tool_result(job))
    except Exception as error:
        return _shader_err(error, "organization-begin")


def _shader_mutation_tool_result(job: Mapping[str, Any]) -> dict[str, Any]:
    """Keep fast-call compatibility while always attaching the operation receipt."""

    snapshot = dict(job or {})
    status = str(snapshot.get("status") or "")
    result = snapshot.get("result")
    if status in {"done", "failed"} and isinstance(result, Mapping):
        payload = dict(result)
        payload["mutation"] = {
            key: value for key, value in snapshot.items() if key != "result"
        }
        payload.setdefault("operationId", snapshot.get("operationId"))
        payload.setdefault("requestSha256", snapshot.get("requestSha256"))
        payload.pop("allowedActions", None)
        if isinstance(payload.get("mutation"), dict):
            payload["mutation"].pop("allowedActions", None)
        return payload
    return {
        "schema": "replaylab-shader-workspace-mutation-started/v1",
        "schemaVersion": 1,
        "started": status in {"queued", "running"},
        "applied": False,
        "operationId": snapshot.get("operationId"),
        "requestSha256": snapshot.get("requestSha256"),
        "mutation": {key: value for key, value in snapshot.items()
                     if key != "allowedActions"},
    }


@mcp.tool()
def get_shader_workspace_mutation_status(operation_id: str) -> str:
    """Read a retained Shader mutation receipt by its idempotency key.

    Rename, structural rewrite, texture-name publication, and CBuffer-alias
    publication return an ``operationId`` before slow work finishes. Poll that
    identity rather than repeating the mutation after an MCP timeout. Terminal
    results remain in a bounded Host ledger and include the original request
    digest; publication tools additionally keep a restart-safe disk receipt.
    """

    try:
        from .shader_workspace.mutation_jobs import get_shader_mutation_job

        snapshot = get_shader_mutation_job(operation_id)
        if snapshot is None:
            return _ok({
                "schema": "replaylab-shader-workspace-mutation/v1",
                "schemaVersion": 1,
                "found": False,
                "status": "unknown",
                "operationId": str(operation_id or ""),
                "applied": False,
            })
        payload = _shader_mutation_tool_result(snapshot)
        payload["found"] = True
        return _ok(payload)
    except Exception as error:
        return _shader_err(error, "organization-mutation-status")


def _remember_member_rules(workspace_path: str, rename_result: Mapping[str, Any]) -> dict[str, Any]:
    """Turn confirmed cbuffer member renames into rules for the shader's material family.

    Fires only when this shader was resolved to an unpacked asset; the rule
    binds material family + Host resolution + reflected ABI shape + semantic
    offsets. The fixed repair can therefore project it onto a later variant's
    current slot across APIs, while ambiguous or changed layouts stay unnamed.
    """

    # Retained as a compatibility shim for old in-process extensions. Source
    # rename results no longer contain publication authority, and therefore
    # can never seed reusable panel/member rules. The explicit
    # publish_cbuffer_aliases operation owns the only valid semantic alias
    # receipt and current reflected physical binding. A supplied compiled
    # layout receipt is additionally validated, but is not required.
    return {
        "recorded": 0,
        "reason": (
            "source rename cannot seed CBuffer alias rules; use explicit "
            "publish_cbuffer_aliases with current physical binding"
        ),
    }

    # Legacy implementation retained below for source-level compatibility;
    # the fail-closed return above makes it unreachable.

    alias_result = rename_result.get("cbufferAliases") or {}
    members = (alias_result.get("memberRenames") or []) if isinstance(alias_result, Mapping) else []
    if not members:
        return {"recorded": 0, "reason": "no cbuffer member renames with known offsets"}
    try:
        status = _shader_workspace_service().status(workspace_path)
        memory = _shader_asset_memory(
            str(status.get("baseline", {}).get("rawSha256") or ""), str(status.get("stage") or ""),
            str(status.get("entryPoint") or ""))
    except Exception as error:
        return {"recorded": 0, "reason": "workspace status unavailable: %s" % str(error)[:160]}
    if memory is None:
        return {"recorded": 0, "reason": "no indexed asset root for the active project"}
    if not memory["familyKeys"]:
        return {"recorded": 0, "reason": "shader has no remembered asset resolution; submit_shader_asset_resolution first",
                "gameKey": memory["gameKey"]}
    confidence = max((float(item.get("confidence") or 0.0) for item in memory["resolutions"]), default=0.5)
    # Bind each semantic offset to the complete physical block shape.  The
    # resulting rule can follow the same material/ABI block when another API or
    # Shader variant assigns a different descriptor set/register, while a shape
    # collision remains withheld unless the semantic block name disambiguates it.
    interface = status.get("baseline", {}).get("compiledInterface")
    interface = interface if isinstance(interface, Mapping) else {}
    reflected_blocks = [
        block for block in (interface.get("constantBlocks") or [])
        if isinstance(block, Mapping)
    ]
    alias_blocks = [
        block for block in (alias_result.get("blocks") or [])
        if isinstance(block, Mapping)
    ] if isinstance(alias_result, Mapping) else []

    def reflected_slot(block: Mapping[str, Any]) -> tuple[int, int] | None:
        try:
            space = int(block.get("space", 0) or 0)
            bind = int(block.get("bind"))
        except (TypeError, ValueError):
            return None
        return (space, bind) if space >= 0 and bind >= 0 else None

    enriched_members: list[dict[str, Any]] = []
    for raw in members:
        if not isinstance(raw, Mapping):
            continue
        row = dict(raw)
        try:
            row_space = int(row.get("space", 0) or 0)
            row_bind = int(row.get("bind"))
        except (TypeError, ValueError):
            enriched_members.append(row)
            continue
        matched = [
            block for block in reflected_blocks
            if reflected_slot(block) == (row_space, row_bind)
        ]
        if len(matched) == 1:
            block = matched[0]
            shape = shader_asset_retrieval.abi_block_shape_sha256(block)
            if shape:
                row["abiShapeSha256"] = shape
                row["blockByteSize"] = int(block.get("byteSize") or 0)
                semantic = ""
                records = [
                    item for item in alias_blocks
                    if reflected_slot(item) == (row_space, row_bind)
                ]
                if len(records) == 1:
                    block_alias = records[0].get("blockAlias")
                    if isinstance(block_alias, Mapping):
                        semantic = str(block_alias.get("alias") or "")
                    semantic = semantic or str(
                        records[0].get("sourceBlock")
                        or records[0].get("block") or ""
                    )
                if not semantic:
                    semantic = str(block.get("name") or "")
                if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", semantic):
                    row["semanticBlock"] = semantic
        enriched_members.append(row)
    written = memory["store"].record_member_rules(
        game_key=memory["gameKey"], family_keys=memory["familyKeys"], members=enriched_members,
        source="ai-rename", confidence=confidence,
        shader_raw_sha256=str(status.get("baseline", {}).get("rawSha256") or ""),
        family_authorities=memory.get("familyAuthorities") or {},
        proof_signer=_seal_member_rule_proof,
    )
    return {"recorded": written, "familyKeys": memory["familyKeys"], "confidence": confidence,
            "note": ("later shaders of these material families receive these member names at decompile time "
                     "when their current reflected ABI shape selects one exact block, regardless of API slot")}


@mcp.tool()
def validate_shader_workspace_candidate(
    workspace_path: str,
    expected_revision: int | None = None,
    expected_candidate_raw_sha256: str = "",
) -> str:
    """Reflect and strictly validate a supported native candidate ABI.

    The service revalidates its trusted
    manifest, capture catalog, baseline, tool provenance, revision, and exact
    candidate bytes before asking RenderDoc to build/reflect a temporary target
    shader. Every physical ABI field must match; the temporary target is always
    freed and no replay replacement is attempted. Save-watcher callers may bind
    both an exact expected revision and candidate raw SHA-256; either both match
    or validation fails before accepting another revision.
    """
    try:
        unused_service, status, request, validated = (
            _fresh_shader_candidate_validation(
                workspace_path,
                expected_revision,
                expected_candidate_raw_sha256,
            )
        )
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-abi-validation-mcp/v1",
                "operation": "validate",
                "binding": request["binding"],
                "validation": validated,
                "candidateState": {
                    "present": True,
                    "requiresReplayAbiValidation": validated[
                        "requiresReplayAbiValidation"
                    ],
                    "replayAbiValidated": validated["replayAbiValidated"],
                    "applied": False,
                },
                "renderDocReplacement": {
                    "attempted": False,
                    "applied": False,
                    "eventScoped": True,
                },
                "workspace": {
                    "workspacePath": status["workspacePath"],
                    "workspaceId": status["workspaceId"],
                    "captureId": status["capture"]["captureId"],
                    "captureSessionId": validated["captureSessionId"],
                    "revision": status["revision"],
                    "candidateRawSha256": request["binding"][
                        "candidateRawSha256"
                    ],
                    "stage": status["shader"]["stage"],
                    "entryPoint": status["shader"]["entryPoint"],
                    "originalResourceId": status["shader"]["resourceId"],
                    "originalRawSha256": status["baseline"]["rawSha256"],
                },
                # On an incompatible verdict the Host says where and why in
                # identity terms (semantic / register / cbuffer offset) with a
                # concrete HLSL hint per finding, so the repair can start at
                # once instead of asking what the difference list means.
                "explanation": (
                    (status.get("lastAbiAttempt") or {}).get("explanation")
                    if validated.get("compatible") is not True
                    else None
                ),
                "availableCapabilities": (
                    ["repair_shader_workspace_source_abi"]
                    if validated.get("compatible") is not True else []
                ),
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def apply_shader_workspace_candidate(
    workspace_path: str,
    event_id: int,
    expected_revision: int,
    expected_candidate_raw_sha256: str,
) -> str:
    """ABI-validate and apply a candidate to one D3D11 draw/dispatch event.

    Each call obtains fresh replay reflection, revalidates the candidate bytes
    and immutable baseline/catalog provenance, then verifies the event's live
    shader resource, entry point, and raw DXBC hash. RenderDoc builds a target
    shader and configures ``SetEventShaderOverride``; global ``ReplaceResource``
    is never used. An incompatible candidate is returned as rejected and is not
    applied.
    """
    try:
        event_value = int(event_id)
        if event_value <= 0:
            raise ValueError("event_id must be a positive integer")
        service, status, request, validated = _fresh_shader_candidate_validation(
            workspace_path,
            expected_revision,
            expected_candidate_raw_sha256,
        )
        if validated.get("replayAbiValidated") is not True:
            return _ok(
                {
                    "schema": "renderdoc-ultra-shader-apply-mcp/v1",
                    "operation": "apply",
                    "binding": request["binding"],
                    "validation": validated,
                    "applied": False,
                    "reason": "candidate ABI is not exactly compatible",
                }
            )

        # An event must be an exact use of this physical shader in the trusted
        # catalog. This prevents a caller from repurposing a workspace as an
        # arbitrary shader injector for an unrelated draw.
        selected = select_unique_shader_for_use(
            status["capture"]["catalogPath"],
            event_value,
            status["stage"],
        )
        if selected.key.catalog_key != status["shader"]["shaderKey"]:
            raise RuntimeError(
                "event_id does not bind the workspace's exact captured shader"
            )

        # Final just-in-time validation immediately before the mutating RPC.
        status_now = service.status(workspace_path)
        _require_shader_candidate_binding(status_now, None)
        request_now = service.candidate_reflection_request(workspace_path)
        if request_now != request:
            raise RuntimeError(
                "Shader workspace changed after ABI validation; apply again"
            )
        latest = status_now.get("latestCompiled") or {}
        gate = latest.get("abiGate") or {}
        report_sha256 = str(validated.get("abiReportSha256", "") or "")
        if any(
            (
                status_now["workspaceId"] != request["binding"]["workspaceId"],
                status_now["revision"] != request["binding"]["revision"],
                latest.get("rawSha256")
                != request["binding"]["candidateRawSha256"],
                gate.get("status") != "compatible",
                gate.get("requestId") != request["requestId"],
                gate.get("reportSha256") != report_sha256,
            )
        ):
            raise RuntimeError("Shader candidate ABI audit binding changed")

        apply_params = dict(request_now["params"])
        apply_params.update(
            {
                "expected_capture_id": request["binding"]["captureId"],
                "event_id": event_value,
                "expected_original_resource_id": status_now["shader"][
                    "resourceId"
                ],
                "expected_original_sha256": status_now["baseline"][
                    "rawSha256"
                ],
                "workspace_id": status_now["workspaceId"],
                "revision": status_now["revision"],
                "abi_request_id": request["requestId"],
                "abi_report_sha256": report_sha256,
            }
        )
        applied = ipc.call(
            "apply_shader_candidate_override", apply_params, timeout=300.0
        )
        try:
            applied = _validated_shader_apply_response(
                applied,
                status=status_now,
                request=request_now,
                event_id=event_value,
                report_sha256=report_sha256,
            )
        except Exception:
            # A malformed success response must never leave an untracked live
            # target shader behind. Roll it back if it contains a usable token.
            if isinstance(applied, dict) and applied.get("idempotent") is False:
                possible_id = str(applied.get("overrideId", "") or "")
                if len(possible_id) == 32 and all(
                    c in "0123456789abcdef" for c in possible_id
                ):
                    try:
                        ipc.call(
                            "rollback_shader_candidate_override",
                            {
                                "override_id": possible_id,
                                "expected_capture_id": request["binding"][
                                    "captureId"
                                ],
                            },
                            timeout=60.0,
                        )
                    except Exception:
                        pass
            raise

        record = {
            "overrideId": applied["overrideId"],
            "captureId": applied["captureId"],
            "captureSessionId": applied.get("captureSessionId"),
            "workspaceId": applied["workspaceId"],
            "workspacePath": status_now["workspacePath"],
            "revision": applied["revision"],
            "eventId": applied["eventId"],
            "stage": applied["stage"],
            "entryPoint": applied["entryPoint"],
            "api": applied["api"],
            "encoding": applied["encoding"],
            "originalResourceId": applied["originalResourceId"],
            "originalRawSha256": applied["originalRawSha256"],
            "candidateRawSha256": applied["candidateRawSha256"],
            "physicalAbiSha256": applied["physicalAbiSha256"],
            "shaderFamilyId": applied["shaderFamilyId"],
            "targetResourceId": applied["targetResourceId"],
        }
        with _SHADER_OVERRIDE_GUARD:
            superseded = applied.get("supersededOverrideId")
            if isinstance(superseded, str):
                _SHADER_OVERRIDE_RECORDS.pop(superseded, None)
            _SHADER_OVERRIDE_RECORDS[applied["overrideId"]] = record
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-apply-mcp/v1",
                "operation": "apply",
                "binding": request["binding"],
                "validation": validated,
                "override": applied,
                "applied": True,
                "rollback": {
                    "tool": "rollback_shader_workspace_override",
                    "workspacePath": status_now["workspacePath"],
                    "overrideId": applied["overrideId"],
                },
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def list_shader_workspace_family_uses(
    workspace_path: str, offset: int = 0, limit: int = 256
) -> str:
    """List trusted catalog events using the workspace's exact captured Shader.

    Results match ResourceId, stage, entry point, raw bytes and complete ABI;
    equal bytecode under another captured ResourceId is not included. Pagination
    never changes or truncates the underlying total.
    """
    try:
        status = _shader_workspace_service().status(workspace_path)
        if isinstance(offset, bool) or isinstance(limit, bool):
            raise ValueError("offset and limit must be integers")
        offset_value = int(offset)
        limit_value = int(limit)
        if offset_value < 0:
            raise ValueError("offset must be non-negative")
        if limit_value <= 0 or limit_value > 256:
            raise ValueError("limit must be between 1 and 256")
        event_ids = list_exact_shader_family_uses(
            status["capture"]["catalogPath"], status["shader"]["shaderKey"]
        )
        page = event_ids[offset_value : offset_value + limit_value]
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-family-uses/v1",
                "workspaceId": status["workspaceId"],
                "captureId": status["capture"]["captureId"],
                "shader": status["shader"],
                "scope": "all-exact-uses",
                "total": len(event_ids),
                "offset": offset_value,
                "limit": limit_value,
                "eventIds": page,
                "hasMore": offset_value + len(page) < len(event_ids),
                "truncated": False,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def apply_shader_workspace_candidate_family(
    workspace_path: str,
    expected_revision: int,
    expected_candidate_raw_sha256: str,
    event_ids: list[int] | None = None,
    scope: str = "all-exact-uses",
) -> str:
    """Atomically apply one candidate to events sharing one captured Shader RID.

    This is the advanced selected-event operation when several draw/dispatch
    events use the same Shader in the capture. The Host validates the candidate ABI once,
    verifies every catalog event uses the workspace's exact original
    ResourceId/stage/entry/raw bytes/ABI, then asks the Bridge to build or reuse
    one target Shader. If any event fails, the whole batch is restored.

    The AI MCP client, an embedded chat action, or a RenderDoc button calls this
    tool. Users should not loop ``apply_shader_workspace_candidate`` themselves
    when preserving a captured Shader family matters.
    """
    try:
        service, status, request, validated = _fresh_shader_candidate_validation(
            workspace_path,
            expected_revision,
            expected_candidate_raw_sha256,
        )
        if validated.get("replayAbiValidated") is not True:
            return _ok(
                {
                    "schema": "renderdoc-ultra-shader-family-apply-mcp/v1",
                    "operation": "apply-family",
                    "binding": request["binding"],
                    "validation": validated,
                    "applied": False,
                    "reason": "candidate ABI is not exactly compatible",
                }
            )
        scope_value = str(scope or "").strip().lower()
        if scope_value not in ("all-exact-uses", "explicit"):
            raise ValueError("scope must be all-exact-uses or explicit")
        selected_event_ids = list(event_ids or [])
        if not selected_event_ids:
            if scope_value == "explicit":
                raise ValueError("explicit scope requires event_ids")
            selected_event_ids = list_exact_shader_family_uses(
                status["capture"]["catalogPath"],
                status["shader"]["shaderKey"],
            )
            if len(selected_event_ids) > 256:
                raise RuntimeError(
                    "Shader family has %d exact uses; call "
                    "list_shader_workspace_family_uses with pagination and pass "
                    "an explicit subset of at most 256 EventIds" %
                    len(selected_event_ids)
                )
        event_bindings = _shader_family_event_bindings(
            status=status, request=request, event_ids=selected_event_ids
        )

        # Repeat every mutable workspace binding check immediately before the
        # one transactional Bridge RPC.
        status_now = service.status(workspace_path)
        _require_shader_candidate_binding(status_now, None)
        request_now = service.candidate_reflection_request(workspace_path)
        if request_now != request:
            raise RuntimeError(
                "Shader workspace changed after ABI validation; apply again"
            )
        latest = status_now.get("latestCompiled") or {}
        gate = latest.get("abiGate") or {}
        report_sha256 = str(validated.get("abiReportSha256", "") or "")
        if any(
            (
                status_now["workspaceId"] != request["binding"]["workspaceId"],
                status_now["revision"] != request["binding"]["revision"],
                latest.get("rawSha256")
                != request["binding"]["candidateRawSha256"],
                gate.get("status") != "compatible",
                gate.get("requestId") != request["requestId"],
                gate.get("reportSha256") != report_sha256,
            )
        ):
            raise RuntimeError("Shader candidate ABI audit binding changed")

        apply_params = dict(request_now["params"])
        apply_params.update(
            {
                "expected_capture_id": request["binding"]["captureId"],
                "expected_original_sha256": status_now["baseline"][
                    "rawSha256"
                ],
                "workspace_id": status_now["workspaceId"],
                "revision": status_now["revision"],
                "abi_request_id": request["requestId"],
                "abi_report_sha256": report_sha256,
                "events": [
                    {
                        "event_id": item["eventId"],
                        "expected_original_resource_id": item[
                            "originalResourceId"
                        ],
                        "expected_original_sha256": item[
                            "originalRawSha256"
                        ],
                    }
                    for item in event_bindings
                ],
            }
        )
        applied = ipc.call(
            "apply_shader_candidate_overrides", apply_params, timeout=300.0
        )
        try:
            applied = _validated_shader_family_apply_response(
                applied,
                status=status_now,
                request=request_now,
                event_bindings=event_bindings,
                report_sha256=report_sha256,
            )
        except Exception:
            possible_ids = []
            if isinstance(applied, dict):
                for item in list(applied.get("overrides", []) or []):
                    if not isinstance(item, dict) or item.get("idempotent") is not False:
                        continue
                    possible_id = str(
                        item.get("overrideId", "")
                    ).strip().lower()
                    if len(possible_id) == 32 and all(
                        character in "0123456789abcdef"
                        for character in possible_id
                    ):
                        possible_ids.append(possible_id)
            if possible_ids:
                try:
                    ipc.call(
                        "rollback_shader_candidate_overrides",
                        {
                            "override_ids": possible_ids,
                            "expected_capture_id": request["binding"][
                                "captureId"
                            ],
                        },
                        timeout=60.0,
                    )
                except Exception:
                    pass
            raise

        with _SHADER_OVERRIDE_GUARD:
            for override in applied["overrides"]:
                superseded = override.get("supersededOverrideId")
                if isinstance(superseded, str):
                    _SHADER_OVERRIDE_RECORDS.pop(superseded, None)
                _SHADER_OVERRIDE_RECORDS[override["overrideId"]] = {
                    "overrideId": override["overrideId"],
                    "captureId": override["captureId"],
                    "captureSessionId": override.get("captureSessionId"),
                    "workspaceId": override["workspaceId"],
                    "workspacePath": status_now["workspacePath"],
                    "revision": override["revision"],
                    "eventId": override["eventId"],
                    "stage": override["stage"],
                    "entryPoint": override["entryPoint"],
                    "api": override["api"],
                    "encoding": override["encoding"],
                    "originalResourceId": override["originalResourceId"],
                    "originalRawSha256": override["originalRawSha256"],
                    "candidateRawSha256": override["candidateRawSha256"],
                    "physicalAbiSha256": override["physicalAbiSha256"],
                    "shaderFamilyId": override.get("shaderFamilyId"),
                    "targetResourceId": override["targetResourceId"],
                }
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-family-apply-mcp/v1",
                "operation": "apply-family",
                "binding": request["binding"],
                "validation": validated,
                "family": applied,
                "scope": (
                    "explicit" if event_ids else "all-exact-uses"
                ),
                "applied": True,
                "rollback": {
                    "tool": "rollback_shader_workspace_override_family",
                    "workspacePath": status_now["workspacePath"],
                    "overrideIds": [
                        item["overrideId"] for item in applied["overrides"]
                    ],
                },
            }
        )
    except Exception as error:
        return _err(error)


def _shared_live_abi_lease(workspace_path: str) -> dict[str, Any] | None:
    """Return one same-process, same-workspace initial ABI lease if active.

    The lease exists only after the ordinary shared-resource path completed a
    fresh replay reflection, persisted its immutable ABI report, and installed
    a Bridge-owned replacement.  It is intentionally process/capture local and
    disappears when the capture session changes.
    """

    workspace_key = _capture_path_key(workspace_path)
    with _SHADER_OVERRIDE_GUARD:
        matches = [
            copy.deepcopy(record)
            for record in _SHARED_SHADER_REPLACEMENT_RECORDS.values()
            if _capture_path_key(record.get("workspacePath", "")) == workspace_key
        ]
    if len(matches) != 1:
        return None
    record = matches[0]
    required_hex = (
        ("replacementId", 32),
        ("captureId", 64),
        ("captureSessionId", 32),
        ("workspaceId", 32),
        ("candidateRawSha256", 64),
        ("abiLeaseRequestId", 64),
        ("abiLeaseReportSha256", 64),
        ("abiLeaseCandidateRawSha256", 64),
        ("physicalAbiSha256", 64),
    )
    for name, length in required_hex:
        value = str(record.get(name, "") or "")
        if len(value) != length or any(
            character not in "0123456789abcdef" for character in value
        ):
            return None
    revision = record.get("abiLeaseRevision")
    if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
        return None
    anchor_event_id = record.get("anchorEventId")
    if (
        isinstance(anchor_event_id, bool)
        or not isinstance(anchor_event_id, int)
        or anchor_event_id < 1
    ):
        return None
    return record


def _shared_live_abi_lease_is_current(lease: Mapping[str, Any]) -> bool:
    """Read Bridge-owned metadata; another Host can retire our cached lease."""
    queried = ipc.call("get_shared_shader_replacements", {
        "expected_capture_id": lease["captureId"],
        "expected_capture_session_id": lease["captureSessionId"],
        "workspace_id": lease["workspaceId"], "replacement_id": lease["replacementId"],
        "lease_metadata_only": True,
    }, timeout=30.0)
    rows = queried.get("replacements") if isinstance(queried, Mapping) else None
    if (not isinstance(rows, list) or len(rows) > 256 or
            queried.get("schema") != "renderdoc-ultra-shared-shader-replacement-list/v1" or
            queried.get("schemaVersion") != 1 or
            type(queried.get("count")) is not int or queried["count"] != len(rows) or
            queried.get("captureId") != lease["captureId"] or
            queried.get("captureSessionId") != lease["captureSessionId"] or
            queried.get("leaseMetadataOnly") is not True or
            queried.get("queryWorkspaceId") != lease["workspaceId"] or
            queried.get("queryReplacementId") != lease["replacementId"] or
            queried.get("originalShadersPreserved") is not True or
            queried.get("replayMutation") is not False or
            type(queried.get("mutationEpoch")) is not int or queried["mutationEpoch"] < 0 or
            any(not isinstance(row, Mapping) for row in rows)):
        raise RuntimeError("Native Shader lease inventory is invalid")
    matches = [row for row in rows if row.get("replacementId") == lease["replacementId"]]
    if len(matches) > 1:
        raise RuntimeError("Native Shader lease inventory has duplicate replacement identities")
    if not matches:
        return False
    row = matches[0]
    if row.get("postApplyValidationFailed") is True:
        raise RuntimeError("Active Shader replacement failed its post-apply validation; lease reuse is unavailable")
    return bool(
        all(row.get(key) == lease.get(key) for key in (
            "captureId", "captureSessionId", "workspaceId", "revision", "stage", "entryPoint",
            "originalResourceId", "originalRawSha256", "candidateRawSha256", "physicalAbiSha256",
            "api", "encoding", "targetResourceId", "shaderFamilyId", "anchorEventId",
            "abiLeaseRequestId", "abiLeaseReportSha256", "abiLeaseCandidateRawSha256", "abiLeaseRevision")) and
        row.get("resourceScoped") is True and row.get("eventScoped") is False and
        row.get("allOriginalResourceUsesAffected") is True and
        row.get("originalShaderPreserved") is True)


def _forget_stale_shared_live_abi_lease(lease: Mapping[str, Any]) -> None:
    """Retire only the observed cache record, never a concurrently renewed one."""
    with _SHADER_OVERRIDE_GUARD:
        token = lease["replacementId"]
        if _SHARED_SHADER_REPLACEMENT_RECORDS.get(token) == lease:
            _SHARED_SHADER_REPLACEMENT_RECORDS.pop(token, None)


_ACTIVE_ORGANIZATION_STATES = frozenset(
    {
        "drafting",
        "awaiting-proposal-review",
        "correction-required",
        "soft-publish-ready",
    }
)


def _workspace_has_active_organization(workspace_path: str | Path) -> bool:
    """True when an unfinished Host IDE organization session still owns the draft."""

    sessions_dir = Path(str(workspace_path)) / "ai" / "organization-sessions"
    if not sessions_dir.is_dir():
        return False
    try:
        children = list(sessions_dir.iterdir())
    except OSError:
        return False
    for child in children:
        if not child.is_dir():
            continue
        session_path = child / "session.json"
        if not session_path.is_file():
            continue
        try:
            session = json.loads(session_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
            continue
        if isinstance(session, Mapping) and session.get("state") in _ACTIVE_ORGANIZATION_STATES:
            return True
    return False


def _require_organization_source_review(workspace_path: str | Path) -> str:
    """Retain open-draft identity without imposing source-annotation admission.

    Compile/ABI/apply endpoints check their actual current source, candidate and
    capture. AI review notes do not authorize or prohibit those operations.
    """
    from .shader_workspace.project_source import archive_superseded_project_source_gate
    archive_superseded_project_source_gate(workspace_path)
    from .shader_workspace.organization import active_draft_id
    organization_id = active_draft_id(workspace_path)
    if not organization_id:
        return ""
    return organization_id


def _task_event_root(explicit: str | Path | None = None) -> Path | None:
    if explicit is not None and str(explicit):
        return Path(str(explicit))
    value = str(os.environ.get(TASK_EVENT_ROOT_ENV, "") or "").strip()
    return Path(value) if value else None


def _release_idle_organization_sessions(
    workspace_path: str | Path,
    *,
    reason: str = "ai-task-idle",
) -> list[dict[str, Any]]:
    """Release no organization data during task occupancy cleanup.

    An organization draft is durable source work, not a live replay resource.
    The old implementation rewrote the sealed ``session.json`` without updating
    its checkpoint, so the next request rejected the Host's own edit as an
    authority/identity change. Live-edit and replacement occupancy are released
    elsewhere; a later explicit organization request may adopt or replace this
    draft after matching the captured original Shader bytes.
    """

    _ = (workspace_path, reason)
    return []


def _pending_shader_deliveries(
    task_id: str, event_root: Path | None
) -> list[dict[str, Any]]:
    if event_root is None or not task_id:
        return []
    _report, state = read_task_report_sidecars(event_root, task_id)
    pending = state.get("pendingShaderWork") if isinstance(state, Mapping) else None
    if not isinstance(pending, Mapping):
        return []
    rows: list[dict[str, Any]] = []
    for workspace, progress in pending.items():
        if not isinstance(progress, Mapping):
            continue
        delivery = progress.get("delivery")
        delivery = delivery if isinstance(delivery, Mapping) else {}
        rows.append(
            {
                "workspacePath": str(workspace),
                "organizationId": str(progress.get("organizationId") or ""),
                "state": str(progress.get("state") or ""),
                "liveEditStarted": delivery.get("liveEditStarted") is True,
                "liveEditId": str(delivery.get("liveEditId") or ""),
                "replayApplied": delivery.get("replayApplied") is True,
                "replacementId": str(delivery.get("replacementId") or ""),
            }
        )
    return rows


def _find_task_ids_for_workspace(
    event_root: Path | None,
    *,
    workspace_id: str = "",
    workspace_path: str = "",
    live_edit_id: str = "",
) -> list[str]:
    if event_root is None or not event_root.is_dir():
        return []
    matched: list[str] = []
    workspace_key = str(workspace_path or "").replace("\\", "/").lower()
    try:
        paths = list(event_root.glob("*.report-state.json"))
    except OSError:
        return []
    for path in paths[:256]:
        task_id = path.name[: -len(".report-state.json")]
        if not task_id:
            continue
        _report, state = read_task_report_sidecars(event_root, task_id)
        pending = state.get("pendingShaderWork") if isinstance(state, Mapping) else None
        if not isinstance(pending, Mapping):
            continue
        for workspace, progress in pending.items():
            if not isinstance(progress, Mapping):
                continue
            delivery = progress.get("delivery")
            delivery = delivery if isinstance(delivery, Mapping) else {}
            path_key = str(workspace).replace("\\", "/").lower()
            if workspace_path and path_key == workspace_key:
                matched.append(task_id)
                break
            if live_edit_id and str(delivery.get("liveEditId") or "") == live_edit_id:
                matched.append(task_id)
                break
            if workspace_id:
                try:
                    manifest = json.loads(
                        (Path(str(workspace)) / "manifest.json").read_text(
                            encoding="utf-8"
                        )
                    )
                except (
                    OSError,
                    UnicodeDecodeError,
                    json.JSONDecodeError,
                    TypeError,
                ):
                    manifest = {}
                if (
                    isinstance(manifest, Mapping)
                    and str(manifest.get("workspaceId") or "") == workspace_id
                ):
                    matched.append(task_id)
                    break
    return matched


def _inspect_shared_shader_occupancy(
    *,
    ipc: Any,
    capture_id: str,
    capture_session_id: str,
    original_resource_id: int = 0,
    workspace_id: str = "",
) -> dict[str, Any]:
    """Describe who currently owns a shared Shader ResourceId and why."""

    queried = ipc.call(
        "get_shared_shader_replacements",
        {
            "expected_capture_id": capture_id,
            "expected_capture_session_id": capture_session_id,
            "include_all_capture_catalogs": True,
        },
        timeout=60.0,
    )
    replacements = (
        queried.get("replacements") if isinstance(queried, Mapping) else None
    )
    if not isinstance(replacements, list):
        return {
            "occupied": False,
            "reason": "replacement-list-invalid",
            "holders": [],
        }
    holders: list[dict[str, Any]] = []
    event_root = _task_event_root()
    try:
        live = _shader_live_edit_remote("list", {})
    except Exception as error:
        live = {"error": str(error)[:300], "sessions": []}
    sessions = live.get("sessions") if isinstance(live, Mapping) else None
    if not isinstance(sessions, list):
        sessions = []
    for item in replacements:
        if not isinstance(item, Mapping):
            continue
        owner_workspace_id = str(item.get("workspaceId") or "")
        resource_id = int(item.get("originalResourceId") or 0)
        if original_resource_id and resource_id != int(original_resource_id):
            continue
        if workspace_id and owner_workspace_id != workspace_id:
            continue
        remembered = _SHARED_SHADER_REPLACEMENT_RECORDS.get(
            str(item.get("replacementId") or "")
        ) or {}
        owner_workspace_path = str(remembered.get("workspacePath") or "")
        live_sessions: list[dict[str, Any]] = []
        for session in sessions:
            if not isinstance(session, Mapping):
                continue
            path = str(session.get("workspacePath") or "")
            if not path:
                continue
            try:
                manifest = json.loads(
                    (Path(path) / "manifest.json").read_text(encoding="utf-8")
                )
            except (
                OSError,
                UnicodeDecodeError,
                json.JSONDecodeError,
                TypeError,
            ):
                continue
            if str(manifest.get("workspaceId") or "") != owner_workspace_id:
                continue
            owner_workspace_path = owner_workspace_path or path
            live_sessions.append(
                {
                    "liveEditId": session.get("liveEditId"),
                    "state": session.get("state"),
                    "pendingApply": session.get("pendingApply") is not None,
                    "applyInProgress": session.get("applyInProgress") is not None,
                    "workspacePath": path,
                }
            )
        organization_draft_present = bool(
            owner_workspace_path
            and _workspace_has_active_organization(owner_workspace_path)
        )
        holding_tasks = _find_task_ids_for_workspace(
            event_root,
            workspace_id=owner_workspace_id,
            workspace_path=owner_workspace_path,
        )
        terminal_tasks = [
            task
            for task in holding_tasks
            if event_root is not None and _task_event_is_terminal(event_root, task)
        ]
        busy_live = any(
            str(session.get("state") or "") in {"starting", "running"}
            and (
                session.get("pendingApply") is True
                or session.get("applyInProgress") is True
            )
            for session in live_sessions
        )
        idle_live = any(
            str(session.get("state") or "") in {"starting", "running", "stopping"}
            for session in live_sessions
        )
        if busy_live:
            hold_reason = "owner-live-edit-busy"
        elif idle_live:
            hold_reason = "owner-live-edit-idle"
        elif terminal_tasks:
            hold_reason = "owner-task-terminal-but-replacement-held"
        else:
            hold_reason = "owner-shared-replacement"
        holders.append(
            {
                "workspaceId": owner_workspace_id,
                "captureId": str(item.get("captureId") or capture_id),
                "workspacePath": owner_workspace_path,
                "replacementId": str(item.get("replacementId") or ""),
                "originalResourceId": resource_id,
                "stage": item.get("stage"),
                "entryPoint": item.get("entryPoint"),
                "liveEditSessions": live_sessions,
                # Organization drafts never own replay occupancy. Keep their
                # presence as diagnostics without turning it into a lock.
                "organizationActive": False,
                "organizationDraftPresent": organization_draft_present,
                "holdingTaskIds": holding_tasks,
                "terminalHoldingTaskIds": terminal_tasks,
                "reason": hold_reason,
            }
        )
    return {
        "occupied": bool(holders),
        "reason": holders[0]["reason"] if holders else "no-owner",
        "holders": holders,
        "captureId": capture_id,
        "captureSessionId": capture_session_id,
    }


def _notify_shader_occupancy(
    message: str,
    *,
    severity: str = "warning",
    code: str = "shaderOccupancy",
    context: Mapping[str, Any] | None = None,
) -> None:
    emit_console_event(
        "shader",
        severity,
        message,
        phase="占用",
        code=code,
        context=dict(context or {}),
    )


def _current_live_edit_delivery(
    workspace_path: str, live_edit_id: str,
) -> dict[str, Any] | None:
    """Recover a delivery made by the watcher rather than the task's MCP call.

    This is an observation of the existing replacement, never a new apply or
    an acceptance decision. A newer source revision may compile to the same
    already validated bytes; its exact current compile binding is sufficient.
    """

    live = _shader_live_edit_remote("poll", {"live_edit_id": live_edit_id})
    if (not isinstance(live, Mapping)
            or live.get("liveEditId") != live_edit_id
            or live.get("state") != "running"
            or live.get("sessionState") != "current"
            or Path(str(live.get("workspacePath") or "")).resolve()
            != Path(workspace_path).resolve()):
        return None
    applied = live.get("lastApply")
    active = live.get("activeReplacement")
    if (not isinstance(applied, Mapping) or applied.get("applied") is not True
            or not isinstance(active, Mapping)):
        return None
    replacement = applied.get("replacement")
    validation = applied.get("validation")
    if (not isinstance(replacement, Mapping)
            or not isinstance(validation, Mapping)
            or validation.get("replayAbiValidated") is not True
            or not _is_lower_hex_value(replacement.get("replacementId"), 32)
            or active.get("replacementId") != replacement.get("replacementId")):
        return None
    status = _shader_workspace_service().status(workspace_path)
    latest = status.get("latestCompiled") or {}
    expected = _normalise_expected_shader_candidate(
        status.get("revision"), latest.get("rawSha256", "")
    )
    try:
        source_sha = _require_shader_candidate_binding(status, expected)
    except RuntimeError:
        return None
    if (expected is None
            or Path(str(status.get("workspacePath") or "")).resolve()
            != Path(workspace_path).resolve()
            or live.get("latestHandledRevision") != expected["revision"]
            or live.get("latestHandledCandidateRawSha256") != expected["candidateRawSha256"]
            or replacement.get("candidateRawSha256") != expected["candidateRawSha256"]
            or active.get("candidateRawSha256") != expected["candidateRawSha256"]):
        return None
    context = _active_live_context(allow_missing_capture_id=True)
    capture = context["capture"]
    binding = live.get("captureBinding")
    from .ipc_client import _CALL_BINDING
    direct = _CALL_BINDING.get()
    instance_id = direct[0] if direct is not None else ipc.instance_id
    session_id = capture["captureSessionId"]
    if (not isinstance(binding, Mapping) or not instance_id
            or binding.get("instanceId") != instance_id
            or binding.get("captureSessionId") != session_id
            or (_effective_capture_scope_session_id() and _effective_capture_scope_session_id() != session_id)
            or _capture_path_key(binding.get("capturePath", "")) != _capture_path_key(capture["path"])
            or _capture_path_key(status.get("capture", {}).get("capturePath", ""))
            != _capture_path_key(capture["path"])):
        return None
    capture_id = status.get("capture", {}).get("captureId")
    queried = ipc.call("get_shared_shader_replacements", {
        "expected_capture_id": capture_id,
        "expected_capture_session_id": session_id,
    }, timeout=60.0)
    rows = queried.get("replacements") if isinstance(queried, Mapping) else None
    if (not isinstance(rows, list) or queried.get("captureId") != capture_id
            or queried.get("captureSessionId") != session_id):
        return None
    shader = status.get("shader") or {}
    original_id = _coerce_transport_resource_id(shader.get("resourceId"), "original_resource_id", False)
    matched = next((row for row in rows if isinstance(row, Mapping)
                   and row.get("replacementId") == replacement["replacementId"]
                   and row.get("workspaceId") == status.get("workspaceId")
                   and row.get("candidateRawSha256") == expected["candidateRawSha256"]
                   and row.get("originalRawSha256") == shader.get("rawSha256")
                   and row.get("stage") == status.get("stage")
                   and row.get("entryPoint") == status.get("entryPoint")
                   and _coerce_transport_resource_id(row.get("originalResourceId"), "original_resource_id", False)
                   == original_id), None)
    if matched is None:
        return None
    root = Path(workspace_path).resolve()
    source_path = Path(str(status.get("source", {}).get("path", "")))
    candidate_path = Path(str(latest.get("candidateBlobPath", "")))
    if (source_path.is_symlink() or candidate_path.is_symlink()
            or not is_within(root, source_path.resolve())
            or not is_within(root, candidate_path.resolve())
            or _bounded_file_sha256(source_path, 64 * 1024 * 1024, "delivered Shader source") != source_sha
            or _bounded_file_sha256(candidate_path, 512 * 1024 * 1024, "delivered Shader candidate")
            != expected["candidateRawSha256"]):
        return None
    return {
        "workspacePath": workspace_path, "liveEditId": live_edit_id,
        "replacementId": replacement["replacementId"],
        "revision": expected["revision"], "sourceSha256": source_sha,
        "candidateRawSha256": expected["candidateRawSha256"],
        "captureSessionId": session_id, "evidenceSource": "live-edit-and-bridge",
    }


def _release_task_shader_occupancy(
    *,
    task_id: str,
    event_root: Path | None = None,
    rollback_replacement: bool = False,
    reason: str = "ai-task-idle",
) -> dict[str, Any]:
    """Release abandoned task work without revoking a delivered live editor.

    A successful shared-resource apply followed by live-edit is a durable
    user-facing delivery. Ending the Agent task must not silently call ``stop``:
    that operation revokes the persistent authorization, which also removes
    the Shader from the workspace panel's current-session projection. Failed
    or cancelled tasks still stop their exact session before rollback.
    """

    root = _task_event_root(event_root)
    deliveries = _pending_shader_deliveries(task_id, root)
    stopped: list[str] = []
    retained: list[str] = []
    reconciled: list[dict[str, Any]] = []
    released_orgs: list[dict[str, Any]] = []
    rolled_back: list[str] = []
    errors: list[str] = []
    for item in deliveries:
        workspace_path = str(item.get("workspacePath") or "")
        live_edit_id = str(item.get("liveEditId") or "")
        if item.get("liveEditStarted") and live_edit_id:
            if not item.get("replayApplied") and not rollback_replacement and workspace_path:
                try:
                    delivery = _current_live_edit_delivery(workspace_path, live_edit_id)
                except Exception as error:
                    # An unavailable readback must not revoke a possibly
                    # delivered editor. Leave it for a later bounded sweep.
                    errors.append("inspect-delivery:%s:%s" % (live_edit_id, str(error)[:180]))
                    continue
                if delivery is not None:
                    item.update(replayApplied=True, replacementId=delivery["replacementId"])
                    reconciled.append(delivery)
            if item.get("replayApplied") and not rollback_replacement:
                retained.append(live_edit_id)
            else:
                try:
                    stopped_result = _shader_live_edit_remote(
                        "stop", {"live_edit_id": live_edit_id}
                    )
                    if (
                        isinstance(stopped_result, Mapping)
                        and str(stopped_result.get("state") or "") == "stopped"
                    ):
                        stopped.append(live_edit_id)
                    else:
                        stopped.append(live_edit_id)
                except Exception as error:
                    errors.append(
                        "stop-live-edit:%s:%s" % (live_edit_id, str(error)[:180])
                    )
        if workspace_path:
            released_orgs.extend(
                _release_idle_organization_sessions(
                    workspace_path, reason=reason
                )
            )
        replacement_id = str(item.get("replacementId") or "")
        if (
            rollback_replacement
            and item.get("replayApplied")
            and replacement_id
            and workspace_path
        ):
            try:
                status = _shader_workspace_service().status(workspace_path)
                capture_id = str(status["capture"]["captureId"])
                ipc.call(
                    "rollback_shader_candidate_shared_resource",
                    {
                        "replacement_id": replacement_id,
                        "expected_capture_id": capture_id,
                        "workspace_id": status["workspaceId"],
                    },
                    timeout=120.0,
                )
                rolled_back.append(replacement_id)
                with _SHADER_OVERRIDE_GUARD:
                    _SHARED_SHADER_REPLACEMENT_RECORDS.pop(replacement_id, None)
            except Exception as error:
                errors.append(
                    "rollback:%s:%s" % (replacement_id, str(error)[:180])
                )
    if root is not None and (stopped or released_orgs or rolled_back or reconciled):
        try:
            with _task_state_lock(root, task_id):
                _report, state = read_task_report_sidecars(root, task_id)
                if isinstance(state, dict):
                    pending = state.get("pendingShaderWork")
                    if isinstance(pending, dict):
                        updated_pending = {}
                        for workspace, progress in pending.items():
                            if not isinstance(progress, Mapping):
                                continue
                            next_progress = dict(progress)
                            delivery = dict(next_progress.get("delivery") or {})
                            live_id = str(delivery.get("liveEditId") or "")
                            replacement = str(delivery.get("replacementId") or "")
                            observed = next((row for row in reconciled
                                             if row["liveEditId"] == live_id
                                             and row["workspacePath"] == str(workspace)), None)
                            if observed is not None:
                                delivery.update(replayApplied=True, replacementId=observed["replacementId"])
                            if live_id and live_id in stopped:
                                delivery["liveEditStarted"] = False
                                delivery.pop("liveEditId", None)
                            if replacement and replacement in rolled_back:
                                delivery["replayApplied"] = False
                                delivery.pop("replacementId", None)
                            next_progress["delivery"] = delivery
                            updated_pending[str(workspace)] = next_progress
                        state = dict(state)
                        state["pendingShaderWork"] = updated_pending
                        state["updatedUnixNs"] = time.time_ns()
                        if state.get("schema") != REPORT_STATE_SCHEMA:
                            state["schema"] = REPORT_STATE_SCHEMA
                        state["taskId"] = task_id
                        _atomic_write_json(
                            task_report_state_path(root, task_id), state
                        )
        except Exception as error:
            errors.append("state-update:%s" % str(error)[:180])
    result = {
        "schema": "replaylab-task-shader-occupancy-release/v1",
        "taskId": task_id,
        "reason": reason,
        "stoppedLiveEditIds": stopped,
        "retainedLiveEditIds": retained,
        "reconciledDeliveries": reconciled,
        "releasedOrganizations": released_orgs,
        "rolledBackReplacementIds": rolled_back,
        "errors": errors,
        "released": not errors,
    }
    if stopped or released_orgs or rolled_back:
        _notify_shader_occupancy(
            "AI 任务已空闲，已释放 Shader 占用（live-edit=%d, organization=%d, rollback=%d）"
            % (len(stopped), len(released_orgs), len(rolled_back)),
            severity="info",
            code="shaderOccupancyReleased",
            context={"operation": "release_task_shader_occupancy", "workspaceId": ""},
        )
    return result


def _release_terminal_task_shader_occupancy_sweep(
    *,
    reason: str = "terminal-task-sweep",
) -> list[dict[str, Any]]:
    """Proactively free live-edit/org holds left by finished AI chats."""

    event_root = _task_event_root()
    if event_root is None or not event_root.is_dir():
        return []
    released: list[dict[str, Any]] = []
    try:
        paths = list(event_root.glob("*.report-state.json"))
    except OSError:
        return []
    for path in paths[:256]:
        task_id = path.name[: -len(".report-state.json")]
        if not task_id or not _task_event_is_terminal(event_root, task_id):
            continue
        deliveries = _pending_shader_deliveries(task_id, event_root)
        if not deliveries:
            continue
        if not any(
            item.get("liveEditStarted")
            or item.get("workspacePath")
            for item in deliveries
        ):
            continue
        terminal = _last_task_event(event_root, task_id)
        kind = str((terminal or {}).get("kind") or "")
        data = (terminal or {}).get("data") if isinstance(terminal, Mapping) else {}
        terminal_status = str(
            (data or {}).get("terminalStatus") or kind or ""
        )
        if terminal_status == "needs-user-input":
            continue
        result = _release_task_shader_occupancy(
            task_id=task_id,
            event_root=event_root,
            # A terminal conversation is not authority to undo a replacement
            # that the Bridge has already applied. Only an explicit rollback
            # request may remove that physical delivery.
            rollback_replacement=False,
            reason=reason,
        )
        if (
            result.get("stoppedLiveEditIds")
            or result.get("releasedOrganizations")
            or result.get("rolledBackReplacementIds")
        ):
            released.append(result)
    return released


def _takeover_idle_foreign_shared_shader_owner(
    *,
    ipc: Any,
    capture_id: str,
    capture_session_id: str,
    original_resource_id: int,
    claimant_workspace_id: str,
) -> dict[str, Any]:
    """Quiesce an idle foreign owner and prepare an exact Bridge handoff.

    Project restore and earlier chats keep exclusive shared-replacement ownership.
    A completed organization draft is saved work, not a replay lock. Takeover
    stops an idle live editor while preserving its files and active replacement;
    pending or in-flight applies still exclude another workspace. The Bridge
    replaces that exact owner only after the new candidate passes validation.
    """

    _release_terminal_task_shader_occupancy_sweep(reason="pre-takeover-terminal-sweep")

    queried = ipc.call(
        "get_shared_shader_replacements",
        {
            "expected_capture_id": capture_id,
            "expected_capture_session_id": capture_session_id,
            "include_all_capture_catalogs": True,
        },
        timeout=60.0,
    )
    if not isinstance(queried, Mapping) or not isinstance(
        queried.get("replacements"), list
    ):
        return {"released": False, "reason": "replacement-list-invalid"}
    foreign: Mapping[str, Any] | None = None
    for item in queried["replacements"]:
        if not isinstance(item, Mapping):
            continue
        if int(item.get("originalResourceId") or 0) != int(original_resource_id):
            continue
        owner = str(item.get("workspaceId") or "")
        if owner and owner != claimant_workspace_id:
            foreign = item
            break
    if foreign is None:
        # The terminal-task sweep or another completed rollback may have
        # removed the conflict since apply failed. Retry only once; the Bridge
        # still checks current ownership at the actual mutation boundary.
        return {"released": False, "retryApply": True, "reason": "no-foreign-owner"}

    owner_workspace_id = str(foreign.get("workspaceId") or "")
    owner_capture_id = str(foreign.get("captureId") or capture_id)
    replacement_id = str(foreign.get("replacementId") or "")
    owner_workspace_path = ""
    stopped_live_edits: list[str] = []
    try:
        live = _shader_live_edit_remote("list", {})
    except Exception as error:
        return {"released": False, "reason": "owner-live-edit-state-unavailable",
                "ownerWorkspaceId": owner_workspace_id,
                "ownerCaptureId": owner_capture_id, "error": str(error)[:300]}
    sessions = live.get("sessions") if isinstance(live, Mapping) else None
    if not isinstance(sessions, list):
        return {"released": False, "reason": "owner-live-edit-state-unavailable",
                "ownerWorkspaceId": owner_workspace_id,
                "ownerCaptureId": owner_capture_id}
    for session in sessions:
        if not isinstance(session, Mapping):
            continue
        path = str(session.get("workspacePath") or "")
        if not path:
            continue
        state = str(session.get("state") or "")
        try:
            manifest = json.loads(
                (Path(path) / "manifest.json").read_text(encoding="utf-8")
            )
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
            # A missing manifest must not disguise an in-memory writer as an
            # idle owner. Its already applied record can identify it without
            # touching the saved source; otherwise refuse an uncertain handoff.
            active = session.get("activeReplacement")
            manifest = {"workspaceId": active.get("workspaceId")} if isinstance(active, Mapping) else {}
            if not manifest.get("workspaceId"):
                if state in {"starting", "running", "stopping"}:
                    return {"released": False, "reason": "owner-live-edit-state-unavailable",
                            "ownerWorkspaceId": owner_workspace_id,
                            "ownerCaptureId": owner_capture_id}
                continue
        if str(manifest.get("workspaceId") or "") != owner_workspace_id:
            continue
        owner_workspace_path = path
        if state in {"starting", "running", "stopping"} and (
            session.get("pendingApply") is not None
            or session.get("applyInProgress") is not None
        ):
            _notify_shader_occupancy(
                "Shader 仍被占用：工作区 %s 的 live-edit 正在应用中（liveEditId=%s）。请等待其完成，或关闭占用它的 AI/面板会话。"
                % (owner_workspace_path, session.get("liveEditId")),
                severity="warning",
                code="shaderOccupancyLiveEditBusy",
                context={
                    "operation": "takeover_idle_foreign_shared_shader_owner",
                    "workspaceId": owner_workspace_id,
                },
            )
            return {
                "released": False,
                "reason": "owner-live-edit-busy",
                "ownerWorkspaceId": owner_workspace_id,
                "ownerWorkspacePath": owner_workspace_path,
                "liveEditId": session.get("liveEditId"),
            }
        if state in {"starting", "running", "stopping"}:
            live_edit_id = str(session.get("liveEditId") or "")
            if live_edit_id:
                try:
                    _shader_live_edit_remote("stop", {"live_edit_id": live_edit_id})
                    stopped_live_edits.append(live_edit_id)
                except Exception as error:
                    return {
                        "released": False,
                        "reason": "owner-live-edit-stop-failed",
                        "ownerWorkspaceId": owner_workspace_id,
                        "ownerWorkspacePath": owner_workspace_path,
                        "error": str(error)[:300],
                    }

    if not owner_workspace_path:
        # Restore ownership may still be present without an easy path; derive from
        # remembered Host records when available.
        remembered = _SHARED_SHADER_REPLACEMENT_RECORDS.get(replacement_id) or {}
        owner_workspace_path = str(remembered.get("workspacePath") or "")

    if not replacement_id:
        return {
            "released": False,
            "reason": "foreign-replacement-id-missing",
            "ownerWorkspaceId": owner_workspace_id,
            "ownerWorkspacePath": owner_workspace_path,
        }
    return {
        "released": False,
        "retryApply": True,
        "reason": "idle-foreign-owner-handoff-prepared",
        "ownerWorkspaceId": owner_workspace_id,
        "ownerCaptureId": owner_capture_id,
        "ownerWorkspacePath": owner_workspace_path,
        "replacementId": replacement_id,
        "stoppedLiveEditIds": stopped_live_edits,
        "expectedOwner": {
            "replacementId": replacement_id,
            "workspaceId": owner_workspace_id,
            "captureId": owner_capture_id,
            "captureSessionId": capture_session_id,
            "candidateRawSha256": str(foreign.get("candidateRawSha256") or ""),
            "revision": foreign.get("revision"),
        },
    }


def _remember_shared_shader_replacement(
    applied: dict[str, Any],
    *,
    status: dict[str, Any],
    abi_lease: dict[str, Any],
) -> None:
    """Publish one validated replacement plus its initial live ABI lease."""

    record = {
        "replacementId": applied["replacementId"],
        "captureId": applied["captureId"],
        "captureSessionId": applied["captureSessionId"],
        "workspaceId": applied["workspaceId"],
        "workspacePath": status["workspacePath"],
        "revision": applied["revision"],
        "stage": applied["stage"],
        "entryPoint": applied["entryPoint"],
        "api": applied["api"],
        "encoding": applied["encoding"],
        "originalResourceId": applied["originalResourceId"],
        "originalRawSha256": applied["originalRawSha256"],
        "candidateRawSha256": applied["candidateRawSha256"],
        "anchorEventId": applied["anchorEventId"],
        "abiLeaseRequestId": abi_lease["abiLeaseRequestId"],
        "abiLeaseReportSha256": abi_lease["abiLeaseReportSha256"],
        "abiLeaseCandidateRawSha256": abi_lease[
            "abiLeaseCandidateRawSha256"
        ],
        "abiLeaseRevision": abi_lease["abiLeaseRevision"],
        "physicalAbiSha256": applied["physicalAbiSha256"],
        "shaderFamilyId": applied["shaderFamilyId"],
        "targetResourceId": applied["targetResourceId"],
    }
    with _SHADER_OVERRIDE_GUARD:
        superseded = applied.get("supersededReplacementId")
        if isinstance(superseded, str):
            _SHARED_SHADER_REPLACEMENT_RECORDS.pop(superseded, None)
        for token, previous in list(_SHARED_SHADER_REPLACEMENT_RECORDS.items()):
            if (
                token != applied["replacementId"]
                and previous.get("originalResourceId")
                == applied["originalResourceId"]
            ):
                _SHARED_SHADER_REPLACEMENT_RECORDS.pop(token, None)
        _SHARED_SHADER_REPLACEMENT_RECORDS[applied["replacementId"]] = record

    # The successful Bridge response already carries the exact signed byte
    # pair. Preserve it beside the workspace without another project lookup,
    # compilation or reflection call. A derived-cache failure cannot revoke
    # the replacement that has just been checked and applied.
    try:
        from .project_restore import _persist_workspace_shader_pair_validation

        applied["workspacePairCacheWritten"] = _persist_workspace_shader_pair_validation(
            status, applied, abi_lease)
    except Exception:
        applied["workspacePairCacheWritten"] = False


def _apply_shader_workspace_shared_resource_with_live_abi_lease(
    workspace_path: str,
    *,
    expected_revision: int,
    expected_candidate_raw_sha256: str,
    operation_id: str = "",
) -> dict[str, Any] | None:
    """Apply one later live-edit save with a single adjacent physical ABI gate.

    ``None`` means that no current initial lease exists and the caller must use
    the ordinary full validation path. A verified pre-mutation stale-lease
    rejection may also return None. Unknown or ambiguous failures are never
    silently retried through another route.
    """

    operation_token = _strict_lower_hex(
        operation_id or uuid.uuid4().hex, 32, "operation_id"
    )
    expected = _normalise_expected_shader_candidate(
        expected_revision, expected_candidate_raw_sha256
    )
    if expected is None:
        raise RuntimeError("live ABI lease requires an exact candidate binding")
    lease = _shared_live_abi_lease(workspace_path)
    if lease is None:
        return None
    # The optimized lease route is only for a later save. A concurrent watcher
    # may revisit the revision that established the lease; sending that pair to
    # the Bridge violates its strict preceding-revision contract. Let the
    # ordinary path observe the already-applied exact pair or validate it.
    lease_revision = lease.get("abiLeaseRevision")
    if type(lease_revision) is not int or lease_revision >= expected["revision"]:
        return None

    service = _shader_workspace_service()
    status = service.status(workspace_path)
    validated_source_sha256 = _require_shader_candidate_binding(status, expected)
    rebound = _ensure_workspace_capture_catalog_identity(
        workspace_path, status=status
    )
    capture_session_id = str(rebound.get("captureSessionId", "") or "")
    if len(capture_session_id) != 32 or any(
        character not in "0123456789abcdef"
        for character in capture_session_id
    ):
        raise RuntimeError("live capture rebinding omitted its session identity")
    _sync_shader_override_capture(capture_session_id)

    # A capture change clears process-local replacement/lease ownership.  Fall
    # back to the ordinary path before any mutation rather than trusting the
    # stale copy captured above.
    current_lease = _shared_live_abi_lease(workspace_path)
    if (
        current_lease is None
        or current_lease.get("replacementId") != lease.get("replacementId")
        or current_lease.get("captureSessionId") != capture_session_id
        or current_lease.get("workspaceId") != status.get("workspaceId")
        or current_lease.get("captureId")
        != status.get("capture", {}).get("captureId")
    ):
        return None
    lease = current_lease
    if not _shared_live_abi_lease_is_current(lease):
        _forget_stale_shared_live_abi_lease(lease)
        return None

    request = service.candidate_reflection_request(workspace_path)
    if any(
        (
            request.get("binding", {}).get("revision") != expected["revision"],
            request.get("binding", {}).get("candidateRawSha256")
            != expected["candidateRawSha256"],
            request.get("binding", {}).get("workspaceId")
            != lease["workspaceId"],
            request.get("binding", {}).get("captureId")
            != lease["captureId"],
            lease["physicalAbiSha256"] not in _workspace_physical_abi_hashes(
                status, request.get("binding", {}).get("baselineAbiSha256")),
        )
    ):
        raise RuntimeError("live ABI lease no longer matches the workspace binding")

    anchor = _expected_shared_shader_anchor(
        status, request, lease["anchorEventId"]
    )
    if lease["physicalAbiSha256"] not in _workspace_physical_abi_hashes(status, anchor["physicalAbiSha256"]):
        raise RuntimeError("live ABI lease physical interface changed")
    anchor["physicalAbiSha256"] = lease["physicalAbiSha256"]
    # A verified same-RDC restore may have rebound a capture-local ResourceId.
    # This record was created by this live Bridge, unlike the persisted ID in
    # the workspace catalog; subsequent saves must target that current owner.
    if lease.get("originalRawSha256") != anchor["originalRawSha256"]:
        raise RuntimeError("live ABI lease original Shader changed")
    anchor["originalResourceId"] = lease["originalResourceId"]

    status_now = service.status(workspace_path)
    source_sha256_now = _require_shader_candidate_binding(status_now, expected)
    request_now = service.candidate_reflection_request(workspace_path)
    if (
        source_sha256_now != validated_source_sha256
        or request_now != request
    ):
        raise RuntimeError("Shader workspace changed before leased live apply")

    apply_params = dict(request_now["params"])
    apply_params.update(
        {
            "expected_capture_id": request["binding"]["captureId"],
            "event_id": anchor["eventId"],
            "expected_original_resource_id": anchor["originalResourceId"],
            "expected_original_sha256": anchor["originalRawSha256"],
            "workspace_id": status_now["workspaceId"],
            "revision": status_now["revision"],
            # requestId stays bound to the current bytes.  The report hash is
            # explicitly an authorization lease from the first fully validated
            # replacement, not a claim that the old report describes new code.
            "abi_request_id": request["requestId"],
            "abi_report_sha256": lease["abiLeaseReportSha256"],
            "abi_validation_mode": "inline-physical-with-initial-lease",
            "abi_lease_request_id": lease["abiLeaseRequestId"],
            "abi_lease_candidate_sha256": lease[
                "abiLeaseCandidateRawSha256"
            ],
            "abi_lease_revision": lease["abiLeaseRevision"],
            "expected_physical_abi_sha256": lease["physicalAbiSha256"],
            "operation_id": operation_token,
            "expected_source_sha256": validated_source_sha256,
            "expected_profile": request["binding"].get("targetProfile") or (status_now.get("targetProfile") or {}).get("profile"),
        }
    )
    # A later-save native gate proves a NEW byte pair. Carry its exact source
    # and catalog provenance so the successful Bridge result can preserve a
    # signed reuse receipt; legacy catalogs still apply without this cache.
    if _is_lower_hex_value(status_now.get("capture", {}).get("catalogSha256"), 64):
        try:
            apply_params["workspace_catalog_binding"] = _verified_restore_catalog_binding(status_now)
        except Exception:
            # The native lease/anchor admission above has already succeeded.
            # Optional future-cache provenance cannot veto this actual apply.
            pass
    raw_applied: Any = None
    applied: dict[str, Any] | None = None
    try:
        raw_applied = ipc.call(
            "apply_shader_candidate_shared_resource", apply_params, timeout=300.0
        )
        applied = _validated_shared_shader_apply_response(
            raw_applied,
            status=status_now,
            request=request_now,
            anchor=anchor,
            report_sha256=lease["abiLeaseReportSha256"],
        )
        if applied.get("operationId") != operation_token:
            raise RuntimeError(
                "RenderDoc leased Shader operation token mismatch")
        inline_expected = {
            "abiValidationMode": "inline-physical-with-initial-lease",
            "preliminaryReflectionSkipped": True,
            "freshPhysicalAbiValidationPerformed": True,
            "abiLeaseRequestId": lease["abiLeaseRequestId"],
            "abiLeaseReportSha256": lease["abiLeaseReportSha256"],
            "abiLeaseCandidateRawSha256": lease[
                "abiLeaseCandidateRawSha256"
            ],
            "abiLeaseRevision": lease["abiLeaseRevision"],
        }
        for key, value in inline_expected.items():
            if applied.get(key) != value:
                raise RuntimeError(
                    "RenderDoc leased Shader response mismatch at %s" % key
                )
        status_after_apply = service.status(workspace_path)
        source_sha256_after_apply = _require_shader_candidate_binding(
            status_after_apply, expected
        )
        request_after_apply = service.candidate_reflection_request(workspace_path)
        if (
            source_sha256_after_apply != validated_source_sha256
            or request_after_apply != request
        ):
            raise RuntimeError(
                "Shader workspace changed during leased shared-resource apply; "
                "the new replacement was rolled back"
            )
    except Exception as error:
        # These two exact Bridge admission errors occur before target creation
        # or replay mutation. A rollback/renewal by another process between the
        # inventory read and apply invalidates only this optimization, not the
        # user's saved candidate. Confirm that fact before full revalidation.
        if (raw_applied is None and isinstance(error, IPCBridgeResponseError) and
                error.code == -32000 and error.message in (
                    "An inline ABI lease requires an active fully validated replacement",
                    "The inline ABI lease does not match the active replacement") and
                not _shared_live_abi_lease_is_current(lease)):
            _forget_stale_shared_live_abi_lease(lease)
            return None
        if (
            isinstance(applied, dict)
            and applied.get("operationCreatedReplacement") is True
            and applied.get("operationId") == operation_token
            and applied.get("idempotent") is False
            and applied.get("metadataOnly") is False
            and applied.get("captureId") == request["binding"]["captureId"]
            and applied.get("workspaceId") == status_now["workspaceId"]
            and applied.get("originalResourceId") == anchor["originalResourceId"]
        ):
            possible_id = str(applied.get("replacementId", "") or "")
            if len(possible_id) == 32 and all(
                character in "0123456789abcdef" for character in possible_id
            ):
                try:
                    ipc.call(
                        "rollback_shader_candidate_shared_resource",
                        {
                            "replacement_id": possible_id,
                            "expected_capture_id": request["binding"]["captureId"],
                            "workspace_id": status_now["workspaceId"],
                        },
                        timeout=60.0,
                    )
                except Exception:
                    pass
        raise

    _remember_shared_shader_replacement(
        applied, status=status_now, abi_lease=lease
    )
    return {
        "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
        "operation": "apply-shared-resource",
        "operationId": operation_token,
        "cbufferSemanticDelivery": _shader_cbuffer_delivery_from_status(status_now),
        "binding": request["binding"],
        "validation": {
            "compatible": True,
            "requiresReplayAbiValidation": False,
            "replayAbiValidated": True,
            "validationScope": "inline-live-physical-interface",
            "preliminaryReplayReflectionSkipped": True,
            "freshPhysicalValidationPerformed": True,
            "freshLiveCaptureValidationPerformed": True,
            "abiLeaseRequestId": lease["abiLeaseRequestId"],
            "abiLeaseReportSha256": lease["abiLeaseReportSha256"],
            "abiLeaseCandidateRawSha256": lease[
                "abiLeaseCandidateRawSha256"
            ],
            "abiLeaseRevision": lease["abiLeaseRevision"],
        },
        "replacement": applied,
        "scope": "captured-resource",
        "applied": True,
        "rollback": {
            "tool": "rollback_shader_workspace_shared_resource",
            "workspacePath": status_now["workspacePath"],
            "replacementId": applied["replacementId"],
        },
    }


def _require_workspace_live_edit_quiescent(workspace_path: str, *, action: str,
                                          expected_candidate: Mapping[str, Any] | None = None) -> None:
    """Reject an active writer, not a saved preference to resume editing.

    The owner service attempts automatic resume before returning ordinary list
    requests. During project restore it deliberately defers resume until the
    replacements exist. Its retained authorizations therefore cannot be treated
    as active writers: doing so prevents restore from ever reaching editor
    startup. Keep those preferences intact and check actual session state.
    The exact in-process apply worker may enter its own transaction; external
    calls and every other active owner remain excluded.
    """

    from .ipc_client import _CALL_BINDING
    from .shader_live_edit import capture_bindings_match, current_live_apply_owner
    owner = (current_live_apply_owner(workspace_path, expected_candidate, _CALL_BINDING.get())
             if action == "applying" else None)
    if owner is not None:
        from .internal_tool_service import require_local_shader_apply_owner
        require_local_shader_apply_owner(workspace_path, expected_candidate, _CALL_BINDING.get())
        return
    owner_seen = False
    live_edits = _shader_live_edit_remote("list", {})
    if not isinstance(live_edits, Mapping):
        raise RuntimeError("Shader live-edit status is unavailable for safe %s" % action)
    sessions = live_edits.get("sessions")
    authorizations = live_edits.get("authorizations")
    if not isinstance(sessions, list) or not isinstance(authorizations, list):
        raise RuntimeError("Shader live-edit status is invalid for safe %s" % action)
    workspace_key = _capture_path_key(workspace_path)
    for entry in sessions:
        if not isinstance(entry, Mapping) or not isinstance(entry.get("workspacePath"), str):
            raise RuntimeError("Shader live-edit session status is invalid")
        if (
            _capture_path_key(entry["workspacePath"]) == workspace_key
            and entry.get("state") not in {"stopped", "failed"}
        ):
            if (owner is not None and entry.get("liveEditId") == owner["liveEditId"]
                    and entry.get("watchId") == owner["watchId"]
                    and capture_bindings_match(entry.get("captureBinding"), owner["captureBinding"])):
                if owner_seen:
                    raise RuntimeError("Shader live-edit apply owner is ambiguous")
                owner_seen = True
                continue
            raise RuntimeError(
                "stop the exact Shader live-edit session before %s its shared replacement"
                % action
            )
    for entry in authorizations:
        if not isinstance(entry, Mapping) or not isinstance(entry.get("workspacePath"), str):
            raise RuntimeError("Shader live-edit authorization status is invalid")
    if owner is not None and (
            not owner_seen or current_live_apply_owner(
                workspace_path, expected_candidate, _CALL_BINDING.get()) != owner):
        raise RuntimeError("Shader live-edit apply owner changed before its shared replacement")


class _SharedShaderPostApplyValidationError(RuntimeError):
    """An exact installed candidate is retained after a failed Native check."""


def _observe_current_shared_shader_candidate(
    workspace_path: str, expected: dict[str, Any] | None,
    operation_id: str, expected_anchor_event_id: int | None,
) -> dict[str, Any] | None:
    """Observe an exact existing effect before admitting another replay writer.

    This readback creates no ABI authority, replacement, lease or publication.
    The Bridge's current-session owner metadata proves the already applied
    native pair; canonical current source/candidate bytes must still match.
    Physical revision/request/operation provenance is retained unchanged.
    """
    try:
        if expected_anchor_event_id is not None and (
                isinstance(expected_anchor_event_id, bool)
                or not isinstance(expected_anchor_event_id, int) or expected_anchor_event_id < 1):
            return None
        service = _shader_workspace_service()
        status = service.status(workspace_path)
        latest = status.get("latestCompiled") or {}
        current = _normalise_expected_shader_candidate(status.get("revision"), latest.get("rawSha256", ""))
        if current is None or expected is not None and expected != current:
            return None
        source_sha = _require_shader_candidate_binding(status, current)
        root = Path(str(status.get("workspacePath") or "")).resolve()
        if root != Path(workspace_path).expanduser().resolve():
            return None
        capture, shader, baseline = status.get("capture") or {}, status.get("shader") or {}, status.get("baseline") or {}
        capture_id = _strict_lower_hex(capture.get("captureId"), 64, "workspace captureId")
        workspace_id = _strict_lower_hex(status.get("workspaceId"), 32, "workspaceId")
        original_raw = _strict_lower_hex(baseline.get("rawSha256"), 64, "original Shader SHA-256")
        physical_abi = _strict_lower_hex(baseline.get("abiSha256"), 64, "original physical ABI SHA-256")
        physical_abi_hashes = _workspace_physical_abi_hashes(status, physical_abi)
        original_id = _coerce_transport_resource_id(shader.get("resourceId"), "original_resource_id", False)
        api = _active_api_key(capture.get("api"))
        encoding = str(latest.get("kind") or "").lower()
        if shader.get("rawSha256") != original_raw or not any(
                api == _active_api_key(checked_api) and encoding in tuple(kind.lower() for kind in kinds)
                for checked_api, kinds in _CHECKED_SHADER_SHARED_APPLY_COMBINATIONS):
            return None

        def files_match() -> bool:
            source = Path(str(status.get("source", {}).get("path") or ""))
            candidate = Path(str(latest.get("candidateBlobPath") or ""))
            return bool(source.is_absolute() and candidate.is_absolute()
                and not source.is_symlink() and not candidate.is_symlink()
                and is_within(root, source.resolve()) and is_within(root, candidate.resolve())
                and _bounded_file_sha256(source, 64 * 1024 * 1024, "current Shader source") == source_sha
                and _bounded_file_sha256(candidate, 512 * 1024 * 1024, "current Shader candidate") == current["candidateRawSha256"])

        if not files_match():
            return None
        context = _active_live_context(allow_missing_capture_id=True)
        live_capture = context["capture"]
        session = _strict_lower_hex(live_capture.get("captureSessionId"), 32, "captureSessionId")
        from .ipc_client import _CALL_BINDING
        bound = _CALL_BINDING.get()
        if ((_effective_capture_scope_session_id() and _effective_capture_scope_session_id() != session)
                or bound is not None and bound[1] != session
                or _capture_path_key(live_capture.get("path", "")) != _capture_path_key(capture.get("capturePath", ""))
                or _active_api_key(live_capture.get("api")) != api):
            return None
        queried = ipc.call("get_shared_shader_replacements", {
            "expected_capture_id": capture_id, "expected_capture_session_id": session,
        }, timeout=30.0)
        rows = queried.get("replacements") if isinstance(queried, Mapping) else None
        if (not isinstance(rows, list) or len(rows) > 256
                or queried.get("schema") != "renderdoc-ultra-shared-shader-replacement-list/v1"
                or queried.get("schemaVersion") != 1 or queried.get("count") != len(rows)
                or queried.get("captureId") != capture_id or queried.get("captureSessionId") != session
                or queried.get("originalShadersPreserved") is not True or queried.get("replayMutation") is not False):
            return None
        matches = [row for row in rows if isinstance(row, Mapping)
            and row.get("workspaceId") == workspace_id
            and _is_lower_hex_value(row.get("replacementId"), 32)
            and _is_lower_hex_value(row.get("operationId"), 32)
            and isinstance(row.get("revision"), int) and not isinstance(row.get("revision"), bool)
            and 0 < row["revision"] <= current["revision"]
            and row.get("candidateRawSha256") == current["candidateRawSha256"]
            and row.get("originalRawSha256") == original_raw
            and _coerce_transport_resource_id(row.get("originalResourceId"), "original_resource_id", False) == original_id
            and row.get("stage") == status.get("stage") and row.get("entryPoint", "") == status.get("entryPoint", "")
            and row.get("api") == api and row.get("encoding") == encoding
            and row.get("physicalAbiSha256") in physical_abi_hashes
            and row.get("resourceScoped") is True and row.get("eventScoped") is False
            and row.get("allOriginalResourceUsesAffected") is True and row.get("originalShaderPreserved") is True
            and isinstance(row.get("anchorEventId"), int) and not isinstance(row.get("anchorEventId"), bool)
            and row["anchorEventId"] > 0]
        if len(matches) != 1:
            return None
        if matches[0].get("postApplyValidationFailed") is True:
            raise _SharedShaderPostApplyValidationError(
                "The current Shader replacement failed post-apply validation; "
                "it cannot be reported as an applied candidate")
        if matches[0].get("postApplyValidationFailed") is not False:
            return None
        requested_binding = None
        if (expected_anchor_event_id is not None
                and matches[0]["anchorEventId"] != expected_anchor_event_id):
            # A shared-resource replacement affects every use of the original.
            # Its representative apply EID is provenance, not another draw's
            # identity. Resolve the requested draw's actual original binding
            # before observing the existing effect; no new ABI/apply is needed.
            requested_binding = _active_bound_shader(
                context, expected_anchor_event_id, status["stage"])
            if (not isinstance(requested_binding, Mapping)
                    or requested_binding.get("stage") != status["stage"]
                    or requested_binding.get("entryPoint", "") != status.get("entryPoint", "")
                    or requested_binding.get("rawSha256") != original_raw
                    or _coerce_transport_resource_id(requested_binding.get("resourceId"),
                        "requested original_resource_id", False) != original_id):
                return None
        after = service.status(workspace_path)
        if (_require_shader_candidate_binding(after, current) != source_sha
                or any(after.get(key) != status.get(key) for key in (
                    "workspaceId", "workspacePath", "capture", "shader", "baseline", "stage", "entryPoint", "targetProfile", "revision", "latestCompiled"))
                or not files_match()):
            return None
        final_context = _active_live_context(allow_missing_capture_id=True)
        if _active_capture_transport_identity(final_context) != _active_capture_transport_identity(context):
            return None
        replacement = dict(matches[0])
        # The inventory intentionally omits the original ABI report/request.
        # Do not invent a current report from the workspace or relabel its
        # physical operation as this readback's operation.
        validation = {"compatible": True, "replayAbiValidated": True,
            "reusedValidation": True, "freshPhysicalValidationPerformed": False,
            "validationScope": "already-applied-live-resource",
            "physicalCandidateRevision": replacement["revision"],
            "baselineAbiSha256": physical_abi, "captureSessionId": session}
        for field, output_field in (("abiRequestId", "requestId"), ("abiReportSha256", "abiReportSha256")):
            if _is_lower_hex_value(replacement.get(field), 64):
                validation[output_field] = replacement[field]
        result = {
            "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
            "operation": "apply-shared-resource", "operationId": operation_id,
            "cbufferSemanticDelivery": _shader_cbuffer_delivery_from_status(after),
            "binding": {"workspaceId": workspace_id, "captureId": capture_id,
                "revision": current["revision"], "sourceSha256": source_sha,
                "candidateRawSha256": current["candidateRawSha256"],
                "stage": status["stage"], "entryPoint": status.get("entryPoint", ""), "api": api, "encoding": encoding},
            "validation": validation,
            "replacement": replacement, "scope": "captured-resource", "applied": True,
            "appliedByThisCall": False, "replayMutation": False, "idempotent": True,
            "evidenceSource": "current-workspace-and-bridge",
            "rollback": {"tool": "rollback_shader_workspace_shared_resource",
                "workspacePath": str(root), "replacementId": replacement["replacementId"]},
        }
        if expected_anchor_event_id is not None:
            result["requestedAnchorEventId"] = expected_anchor_event_id
        if requested_binding is not None:
            result["requestedBinding"] = {"eventId": expected_anchor_event_id,
                "stage": requested_binding["stage"], "entryPoint": requested_binding.get("entryPoint", ""),
                "originalResourceId": original_id, "originalRawSha256": original_raw,
                "source": "current-capture-binding"}
        return result
    except _SharedShaderPostApplyValidationError:
        # A known failed effect is not an absent cache entry. Do not hide it
        # behind either an idempotent success or an automatic new apply.
        raise
    except Exception:
        # Optional observation cannot replace normal admission/owner guards.
        return None


@mcp.tool()
def apply_shader_workspace_shared_resource(
    workspace_path: str,
    expected_revision: int | None = None,
    expected_candidate_raw_sha256: str = "",
    operation_id: str = "",
    expected_anchor_event_id: int | None = None,
) -> str:
    """Apply a candidate to every checked use of one captured Shader ResourceId.

    This sharing-preserving mode is the default for editor save/apply flows.
    The Host checks current workspace, capture, candidate and live-event
    identity, reusing an exact successful ABI reflection from this capture
    session when available. The Bridge then builds one target and calls RenderDoc's
    resource-scoped replacement. D3D12, Vulkan, and OpenGL require checked
    transactions which rebuild every supported affected PSO/program before
    committing derived mappings; D3D12 also reuses the captured root signature.
    Distinct captured
    ResourceIds are never merged, even when their bytecode is identical. The
    original captured Shader is retained for rollback and is never freed. The
    optional expected revision/raw SHA-256 pair is used by save auto-apply to
    reject a newer candidate published between watcher polling and mutation.
    An exact current candidate already applied by this workspace returns an
    idempotent readback without a second ABI/apply transaction. A requested
    EID may differ from the recorded representative anchor when its actual
    captured original binding is the same; the physical receipt keeps its
    original anchor. An active
    live-edit owner must be stopped before applying different bytes. A saved authorization without an active
    session is retained for editor startup and does not block project restore.
    Project restore also supplies its inventory-frozen representative EID;
    that path validates only this one live PSO/ABI anchor and never scans the
    catalog's complete EID-use table to rediscover an anchor.
    Omit operation_id to create a native ID, or retain a UUID/stable workspace
    mutation label across retries. Alternate UUID spellings normalize to one
    native key; labels map deterministically instead of failing a format gate.
    """
    try:
        from .shader_workspace.mutation_jobs import bridge_operation_id
        operation_token = bridge_operation_id(operation_id)
        expected = _normalise_expected_shader_candidate(
            expected_revision, expected_candidate_raw_sha256
        )
        existing = _observe_current_shared_shader_candidate(
            workspace_path, expected, operation_token, expected_anchor_event_id)
        if existing is not None:
            return _ok(existing)
        service, status, request, validated = _shader_candidate_validation_for_apply(
            workspace_path,
            expected_revision,
            expected_candidate_raw_sha256,
        )
        validated_source_sha256 = _require_shader_candidate_binding(
            status, expected
        )
        if validated.get("replayAbiValidated") is not True:
            return _ok(
                {
                    "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
                    "operation": "apply-shared-resource",
                    "binding": request["binding"],
                    "validation": validated,
                    "applied": False,
                    "reason": "candidate ABI is not exactly compatible",
                }
            )

        if expected_anchor_event_id is None:
            exact_uses = list_exact_shader_family_uses(
                status["capture"]["catalogPath"], status["shader"]["shaderKey"]
            )
            if not exact_uses:
                raise RuntimeError(
                    "The workspace Shader has no exact live anchor event in its catalog"
                )
            anchor_event_id = min(int(value) for value in exact_uses)
            anchor = _shader_family_event_bindings(
                status=status, request=request, event_ids=[anchor_event_id]
            )[0]
        else:
            anchor = _expected_shared_shader_anchor(
                status, request, expected_anchor_event_id
            )

        # Repeat all mutable workspace/audit checks immediately before the one
        # resource-scoped Bridge mutation.
        status_now = service.status(workspace_path)
        source_sha256_now = _require_shader_candidate_binding(
            status_now, expected
        )
        if source_sha256_now != validated_source_sha256:
            raise RuntimeError(
                "Shader source changed after ABI validation; apply again"
            )
        request_now = service.candidate_reflection_request(workspace_path)
        if request_now != request:
            raise RuntimeError(
                "Shader workspace changed after ABI validation; apply again"
            )
        latest = status_now.get("latestCompiled") or {}
        gate = latest.get("abiGate") or {}
        report_sha256 = str(validated.get("abiReportSha256", "") or "")
        if any(
            (
                status_now["workspaceId"] != request["binding"]["workspaceId"],
                status_now["revision"] != request["binding"]["revision"],
                latest.get("rawSha256")
                != request["binding"]["candidateRawSha256"],
                gate.get("status") != "compatible",
                gate.get("requestId") != request["requestId"],
                gate.get("reportSha256") != report_sha256,
            )
        ):
            raise RuntimeError("Shader candidate ABI audit binding changed")

        apply_params = dict(request_now["params"])
        apply_params.update(
            {
                "expected_capture_id": request["binding"]["captureId"],
                "event_id": anchor["eventId"],
                "expected_original_resource_id": anchor[
                    "originalResourceId"
                ],
                "expected_original_sha256": anchor["originalRawSha256"],
                "workspace_id": status_now["workspaceId"],
                "revision": status_now["revision"],
                "abi_request_id": request["requestId"],
                "abi_report_sha256": report_sha256,
                "operation_id": operation_token,
                # Bind the Bridge's durable same-RDC validation receipt to
                # the exact editable source which produced this candidate.
                "expected_source_sha256": validated_source_sha256,
            }
        )
        if _is_lower_hex_value(validated.get("captureSessionId"), 32):
            apply_params["expected_capture_session_id"] = validated["captureSessionId"]
        # Legacy workspaces may still be explicitly applied without the newer
        # immutable catalog digest. They remain on the ordinary validation
        # path and cannot acquire a persistent fast-restore receipt.
        if _is_lower_hex_value(status_now.get("capture", {}).get("catalogSha256"), 64):
            apply_params["workspace_catalog_binding"] = _verified_restore_catalog_binding(status_now)
        try:
            _require_workspace_live_edit_quiescent(
                str(status_now["workspacePath"]), action="applying", expected_candidate=expected
            )
        except Exception:
            # A watcher can finish this exact candidate while the explicit
            # request validates ABI. Re-read its effect once before reporting
            # an active writer; never stop that writer or admit different bytes.
            try:
                already_applied = _observe_current_shared_shader_candidate(
                    workspace_path,
                    _normalise_expected_shader_candidate(
                        request["binding"]["revision"],
                        request["binding"]["candidateRawSha256"],
                    ),
                    operation_token,
                    expected_anchor_event_id,
                )
                if (already_applied is not None
                        and already_applied["binding"]["sourceSha256"] == validated_source_sha256):
                    return _ok(already_applied)
            except Exception:
                pass
            raise
        takeover: dict[str, Any] | None = None
        try:
            raw_applied = ipc.call(
                "apply_shader_candidate_shared_resource", apply_params, timeout=300.0
            )
        except Exception as apply_error:
            message = str(apply_error)
            if "owned by a different workspace" not in message:
                raise
            capture_session_id = str(
                (status_now.get("capture") or {}).get("captureSessionId") or ""
            )
            if not capture_session_id:
                capture_session_id = str(
                    _active_live_context()["capture"].get("captureSessionId") or ""
                )
            takeover = _takeover_idle_foreign_shared_shader_owner(
                ipc=ipc,
                capture_id=str(request["binding"]["captureId"]),
                capture_session_id=capture_session_id,
                original_resource_id=int(anchor["originalResourceId"]),
                claimant_workspace_id=str(status_now["workspaceId"]),
            )
            if (takeover.get("released") is not True and
                    takeover.get("retryApply") is not True):
                occupancy = _inspect_shared_shader_occupancy(
                    ipc=ipc,
                    capture_id=str(request["binding"]["captureId"]),
                    capture_session_id=capture_session_id,
                    original_resource_id=int(anchor["originalResourceId"]),
                )
                holders = occupancy.get("holders") if isinstance(occupancy, Mapping) else None
                holder = holders[0] if isinstance(holders, list) and holders else {}
                owner_label = (
                    takeover.get("ownerWorkspacePath")
                    or takeover.get("ownerWorkspaceId")
                    or holder.get("workspacePath")
                    or holder.get("workspaceId")
                    or "unknown"
                )
                holding_tasks = (
                    takeover.get("holdingTaskIds")
                    or holder.get("holdingTaskIds")
                    or []
                )
                _notify_shader_occupancy(
                    "应用被占用拦截：owner=%s reason=%s tasks=%s。请关闭占用方的 AI 对话或停止其 live-edit。"
                    % (
                        owner_label,
                        takeover.get("reason") or occupancy.get("reason") or "unknown",
                        ",".join(str(item) for item in holding_tasks[:4]) or "none",
                    ),
                    severity="warning",
                    code="shaderOccupancyApplyBlocked",
                    context={
                        "operation": "apply_shader_workspace_shared_resource",
                        "workspaceId": str(status_now.get("workspaceId") or ""),
                    },
                )
                raise RuntimeError(
                    "The captured Shader is owned by a different workspace "
                    "(%s); safe takeover was not completed (%s)%s. "
                    "An active apply must finish before takeover; if owner state "
                    "could not be read, retry the same resource-scoped apply after recovery."
                    % (
                        owner_label,
                        takeover.get("reason") or "unknown",
                        (
                            " (tasks: %s)"
                            % ", ".join(str(item) for item in holding_tasks[:4])
                            if holding_tasks
                            else ""
                        ),
                    )
                ) from apply_error
            if takeover.get("expectedOwner") is not None:
                apply_params["expected_owner"] = takeover["expectedOwner"]
            raw_applied = ipc.call(
                "apply_shader_candidate_shared_resource", apply_params, timeout=300.0
            )
        applied: dict[str, Any] | None = None
        try:
            applied = _validated_shared_shader_apply_response(
                raw_applied,
                status=status_now,
                request=request_now,
                anchor=anchor,
                report_sha256=report_sha256,
            )
            if applied.get("operationId") != operation_token:
                raise RuntimeError(
                    "RenderDoc Shader operation token mismatch")
            # The Bridge mutation may take long enough for another IDE save to
            # land.  Do not publish that replacement as current unless the
            # canonical source and candidate remain the exact ABI-validated
            # pair. A newly-created owner is rolled back below unless a completed
            # handoff has already retired the previous owner's target.
            status_after_apply = service.status(workspace_path)
            source_sha256_after_apply = _require_shader_candidate_binding(
                status_after_apply, expected
            )
            request_after_apply = service.candidate_reflection_request(
                workspace_path
            )
            if (
                source_sha256_after_apply != validated_source_sha256
                or request_after_apply != request
            ):
                raise RuntimeError(
                    "Shader workspace changed during shared-resource apply"
                )
        except Exception as post_apply_error:
            # Only a response that proves it created a new owned replacement
            # may be auto-rolled back. Never remove an idempotent/foreign owner
            # based on malformed evidence.
            if (
                isinstance(applied, dict)
                and applied.get("operationCreatedReplacement") is True
                and applied.get("operationId") == operation_token
                and applied.get("idempotent") is False
                and applied.get("metadataOnly") is False
                and applied.get("captureId") == request["binding"]["captureId"]
                and applied.get("workspaceId") == status_now["workspaceId"]
                and applied.get("originalResourceId")
                == anchor["originalResourceId"]
            ):
                possible_id = str(applied.get("replacementId", "") or "")
                if len(possible_id) == 32 and all(
                    character in "0123456789abcdef"
                    for character in possible_id
                ):
                    prior_owner = (takeover or {}).get("expectedOwner")
                    if (isinstance(prior_owner, Mapping)
                            and applied.get("supersededReplacementId") == prior_owner.get("replacementId")):
                        # The Bridge committed the exact handoff and released
                        # the old target. Rolling back this new owner would now
                        # remove the last validated effect, not restore it.
                        # Remember only the pre-commit validated pair; failure
                        # remains explicit and grants no current-source proof.
                        memory_error = ""
                        try:
                            _remember_shared_shader_replacement(applied, status=status_now, abi_lease={
                                "abiLeaseRequestId": request["requestId"],
                                "abiLeaseReportSha256": report_sha256,
                                "abiLeaseCandidateRawSha256": request["binding"]["candidateRawSha256"],
                                "abiLeaseRevision": request["binding"]["revision"],
                            })
                        except Exception as remember_error:
                            memory_error = str(remember_error)
                        return _ok({
                            "error": "Shader handoff committed, but current source verification failed; "
                                     "the validated replay replacement was retained: %s" % post_apply_error,
                            "type": type(post_apply_error).__name__,
                            "data": {"operationId": operation_token,
                                     "replayReplacementRetained": True,
                                     "currentSourceVerified": False,
                                     "replacement": applied,
                                     "recordingError": memory_error},
                        })
                    try:
                        ipc.call(
                            "rollback_shader_candidate_shared_resource",
                            {
                                "replacement_id": possible_id,
                                "expected_capture_id": request["binding"][
                                    "captureId"
                                ],
                                "workspace_id": status_now["workspaceId"],
                            },
                            timeout=60.0,
                        )
                    except Exception:
                        pass
            raise

        _remember_shared_shader_replacement(
            applied,
            status=status_now,
            abi_lease={
                "abiLeaseRequestId": request["requestId"],
                "abiLeaseReportSha256": report_sha256,
                "abiLeaseCandidateRawSha256": request["binding"][
                    "candidateRawSha256"
                ],
                "abiLeaseRevision": request["binding"]["revision"],
            },
        )
        route_memory = _remember_route_success(
            status_now,
            details={
                "candidateRawSha256": request["binding"]["candidateRawSha256"],
                "revision": request["binding"]["revision"],
            },
        )
        response = {
            "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
            "operation": "apply-shared-resource",
            "operationId": operation_token,
            "cbufferSemanticDelivery": _shader_cbuffer_delivery_from_status(status_after_apply),
            "binding": request["binding"],
            "validation": validated,
            "replacement": applied,
            "scope": "captured-resource",
            "applied": True,
            "routeMemory": route_memory,
            "rollback": {
                "tool": "rollback_shader_workspace_shared_resource",
                "workspacePath": status_now["workspacePath"],
                "replacementId": applied["replacementId"],
            },
        }
        if takeover and (takeover.get("released") is True or
                         takeover.get("expectedOwner") is not None):
            response["idleOwnerTakeover"] = dict(takeover, handoffCompleted=True)
        return _ok(response)
    except Exception as error:
        return _err(error)


def _verified_restore_catalog_binding(status: dict[str, Any]) -> dict[str, Any]:
    scope = _workspace_catalog_rebind_scope(status)
    return {
        "projection": _workspace_catalog_binding_projection(status),
        "scope": {key: scope[key] for key in (
            "identityEvidence", "stableIdentityEvidence", "stableCaptureId")},
    }


def _verified_restore_workspace_identity(status: Mapping[str, Any]) -> dict[str, Any]:
    """Inputs which must stay identical while a verified restore is applying."""
    return {key: copy.deepcopy(status.get(key)) for key in (
        "workspaceId", "workspacePath", "capture", "shader", "baseline",
        "stage", "entryPoint", "targetProfile", "revision", "source", "latestCompiled",
    )}


def _apply_project_shader_pair_restore(
    status: dict[str, Any], prior: Mapping[str, Any], capture_session_id: str,
    operation_id: str, anchor_event_id: int,
) -> dict[str, Any]:
    """Reuse a signed exact byte pair while rebinding current source and target.

    The Bridge authenticates the origin proof and current RDC/original bytes.
    A changed candidate or source/candidate binding cannot inherit this route.
    No previous capture-local target handle or catalog authority is reused.
    """
    from .project_restore import _shader_pair_validation_material, _shader_pair_receipt_matches

    session = _strict_lower_hex(capture_session_id, 32, "capture_session_id")
    token = _strict_lower_hex(operation_id, 32, "operation_id")
    service = _shader_workspace_service()
    expected = _normalise_expected_shader_candidate(status.get("revision"),
                                                   status.get("latestCompiled", {}).get("rawSha256", ""))
    source_sha = _require_shader_candidate_binding(status, expected)
    material = _shader_pair_validation_material(status)
    receipt = prior.get("replacement", {}).get("restoreValidationReceipt")
    if not _shader_pair_receipt_matches(receipt, material, status):
        raise RuntimeError("cached Shader pair differs from the current candidate")
    request = service.candidate_reflection_request(status["workspacePath"])
    gate = status.get("latestCompiled", {}).get("abiGate") or {}
    if gate.get("status") != "compatible" or gate.get("requestId") != request["requestId"]:
        raise RuntimeError("cached Shader pair has no bound successful ABI report")
    report_sha = _strict_lower_hex(gate.get("reportSha256"), 64, "cached ABI report SHA-256")
    candidate_abi = _strict_lower_hex(gate.get("candidateAbiSha256"), 64, "cached candidate ABI SHA-256")
    anchor = _expected_shared_shader_anchor(status, request, anchor_event_id)
    receipt_abi = receipt.get("payload", {}).get("physicalAbiSha256")
    if receipt_abi not in _workspace_physical_abi_hashes(status, anchor["physicalAbiSha256"]):
        raise RuntimeError("cached Shader pair physical interface changed")
    anchor["physicalAbiSha256"] = receipt_abi
    capture_path = str(status.get("capture", {}).get("capturePath", ""))
    params = dict(request["params"])
    params.update({
        "expected_capture_id": request["binding"]["captureId"],
        "expected_capture_path": capture_path,
        "expected_capture_sha256": receipt["payload"]["captureSha256"],
        "expected_capture_session_id": session,
        "event_id": anchor["eventId"],
        "expected_original_resource_id": anchor["originalResourceId"],
        "expected_original_sha256": anchor["originalRawSha256"],
        "workspace_id": status["workspaceId"], "revision": status["revision"],
        "expected_source_sha256": source_sha,
        "abi_request_id": request["requestId"], "abi_report_sha256": report_sha,
        "abi_validation_mode": "verified-shader-pair",
        # Reflection uses target_profile; signed pair admission expects this
        # separate field. Derive it from the current validated native binding,
        # never copy the old proof's profile to make a mismatch disappear.
        "expected_profile": request["binding"].get("targetProfile")
            or (status.get("targetProfile") or {}).get("profile"),
        "use_current_anchor_resource": True,
        "restore_validation_receipt": dict(receipt),
        "expected_physical_abi_sha256": anchor["physicalAbiSha256"],
        "workspace_catalog_binding": _verified_restore_catalog_binding(status),
        "operation_id": token,
    })
    _sync_shader_override_capture(session)
    raw = ipc.call("apply_shader_candidate_shared_resource", params, timeout=300.0)
    applied = _validated_shared_shader_apply_response(
        raw, status=status, request=request, anchor=anchor, report_sha256=report_sha)
    returned_receipt = applied.get("restoreValidationReceipt")
    # GLSL proof seals source, so a newly built driver target is reflected
    # inline even on a cache hit. Native bytecode and already-owned targets
    # reuse the authenticated physical pair without repeating that work.
    fresh_physical = (request["binding"].get("encoding") == "glsl"
                      and applied.get("targetBuiltOnce") is True)
    if (applied.get("operationId") != token
            or applied.get("captureSessionId") != session
            or applied.get("abiValidationMode") != "verified-shader-pair"
            or applied.get("freshPhysicalAbiValidationPerformed") is not fresh_physical
            or not _shader_pair_receipt_matches(returned_receipt, material, status)):
        raise RuntimeError("RenderDoc returned invalid cached Shader pair evidence")
    current = service.status(status["workspacePath"])
    if (_verified_restore_workspace_identity(current) != _verified_restore_workspace_identity(status)
            or _require_shader_candidate_binding(current, expected) != source_sha):
        raise RuntimeError("Shader workspace changed during cached Shader pair restore")
    _remember_shared_shader_replacement(applied, status=status, abi_lease={
        "abiLeaseRequestId": request["requestId"], "abiLeaseReportSha256": report_sha,
        "abiLeaseCandidateRawSha256": expected["candidateRawSha256"],
        "abiLeaseRevision": expected["revision"],
    })
    return {
        "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
        "operation": "apply-shared-resource", "operationId": token,
        "binding": request["binding"],
        "validation": {
            "workspacePath": status["workspacePath"], "revision": status["revision"],
            "requestId": request["requestId"], "compatible": True,
            "baselineAbiSha256": anchor["physicalAbiSha256"],
            "candidateAbiSha256": candidate_abi,
            "differences": [], "differencesTruncated": False,
            "requiresReplayAbiValidation": False, "replayAbiValidated": True,
            "abiReportSha256": report_sha,
            "abiReportPath": str(Path(status["workspacePath"]) / gate["reportPath"]),
            "validationScope": "verified-shader-pair", "reusedValidation": True,
            "freshPhysicalValidationPerformed": fresh_physical,
            "captureSessionId": session, "applied": False,
        },
        "replacement": applied, "scope": "captured-resource", "applied": True,
        "rollback": {"tool": "rollback_shader_workspace_shared_resource",
                     "workspacePath": status["workspacePath"],
                     "replacementId": applied["replacementId"]},
    }


def _apply_verified_project_restore(
    snapshot: Mapping[str, Any],
    workspace_statuses: Sequence[dict[str, Any]],
    capture_session_id: str,
    operation_id: str,
) -> dict[str, Any]:
    """Restore unchanged, previously applied candidates to the exact same RDC.

    This is an internal project-restore operation, never an AI-selected bypass.
    Its caller checks the project knowledge and workspace content hashes. The
    Bridge independently authenticates its last successful validation receipt,
    checks the RDC bytes and current original Shader, and creates a new target.
    Persisted GPU handles or capture-session authority are never reused.
    """
    from .project_restore import _VERIFIED_RDC_RESTORE_SCHEMA, _VERIFIED_RDC_RESTORE_VERSION

    session_id = _strict_lower_hex(capture_session_id, 32, "capture_session_id")
    operation_token = _strict_lower_hex(operation_id, 32, "operation_id")
    capture_sha256 = _strict_lower_hex(snapshot.get("captureSha256"), 64, "captureSha256")
    records = snapshot.get("shaders")
    if (snapshot.get("schema") != _VERIFIED_RDC_RESTORE_SCHEMA
            or snapshot.get("schemaVersion") != _VERIFIED_RDC_RESTORE_VERSION
            or not isinstance(records, list) or not records
            or len(records) != len(workspace_statuses)):
        raise RuntimeError("Verified RDC restore has an incomplete workspace set")
    service = _shader_workspace_service()
    _sync_shader_override_capture(session_id)
    prepared = []
    seen = set()
    mapping_capable = getattr(ipc, "supports_verified_restore_mapping", False) is True
    for position, (record, status) in enumerate(zip(records, workspace_statuses)):
        if not isinstance(record, Mapping) or not isinstance(status, dict):
            raise RuntimeError("Verified RDC restore contains an invalid Shader")
        workspace_path = str(status.get("workspacePath") or "")
        expected = _normalise_expected_shader_candidate(
            record.get("candidateRevision"), record.get("candidateRawSha256", ""))
        source_sha256 = _require_shader_candidate_binding(status, expected)
        if (not expected or source_sha256 != record.get("sourceSha256")
                or _capture_path_key(status.get("capture", {}).get("capturePath", ""))
                != _capture_path_key(snapshot.get("capturePath", ""))
                or status.get("workspaceId") != record.get("managedWorkspace", {}).get("workspaceId")):
            raise RuntimeError("Verified RDC restore changed its source or capture binding")
        request = service.candidate_reflection_request(workspace_path)
        binding = request["binding"]
        gate = (status.get("latestCompiled") or {}).get("abiGate") or {}
        validation = record.get("validation")
        previous = record.get("replacement")
        receipt = previous.get("restoreValidationReceipt") if isinstance(previous, Mapping) else None
        if (not isinstance(validation, Mapping) or not isinstance(receipt, Mapping)
                or gate.get("status") != "compatible"
                or gate.get("requestId") != request["requestId"]
                or validation.get("requestId") != request["requestId"]
                or gate.get("reportSha256") != validation.get("abiReportSha256")
                or binding.get("workspaceId") != status.get("workspaceId")
                or binding.get("revision") != expected["revision"]
                or binding.get("candidateRawSha256") != expected["candidateRawSha256"]):
            raise RuntimeError("Verified RDC restore lost its exact successful ABI report")
        anchor = _expected_shared_shader_anchor(status, request, previous.get("anchorEventId"))
        if previous.get("physicalAbiSha256") not in _workspace_physical_abi_hashes(
                status, anchor["physicalAbiSha256"]):
            raise RuntimeError("Verified RDC restore physical interface changed")
        anchor["physicalAbiSha256"] = previous["physicalAbiSha256"]
        for key, value in {
            "workspaceId": status["workspaceId"], "revision": expected["revision"],
            "candidateRawSha256": expected["candidateRawSha256"],
            "originalRawSha256": anchor["originalRawSha256"],
            "physicalAbiSha256": anchor["physicalAbiSha256"],
            "stage": binding["stage"], "entryPoint": binding["entryPoint"],
            "api": binding["api"], "encoding": binding["encoding"],
        }.items():
            if previous.get(key) != value:
                raise RuntimeError("Verified RDC restore receipt differs at %s" % key)
        if anchor["originalResourceId"] in seen:
            raise RuntimeError("Verified RDC restore contains a duplicate physical Shader")
        seen.add(anchor["originalResourceId"])
        params = dict(request["params"])
        token = hashlib.sha256((operation_token + ":" + str(position)).encode("ascii")).hexdigest()[:32]
        params.update({
            "expected_capture_id": binding["captureId"],
            "expected_capture_path": str(snapshot["capturePath"]),
            "expected_capture_sha256": (receipt["payload"]["captureSha256"]
                if snapshot.get("captureReplaySha256") is not None else capture_sha256),
            "expected_capture_session_id": session_id,
            "event_id": anchor["eventId"],
            "expected_original_resource_id": anchor["originalResourceId"],
            "expected_original_sha256": anchor["originalRawSha256"],
            "workspace_id": status["workspaceId"], "revision": binding["revision"],
            "expected_source_sha256": source_sha256,
            "abi_request_id": request["requestId"],
            "abi_report_sha256": gate["reportSha256"],
            "abi_validation_mode": "verified-rdc-restore",
            "restore_validation_receipt": dict(receipt),
            "expected_physical_abi_sha256": anchor["physicalAbiSha256"],
            "workspace_catalog_binding": _verified_restore_catalog_binding(status),
            "operation_id": token,
        })
        if mapping_capable:
            params["verify_replacement_mapping"] = True
        prepared.append((status, request, anchor, dict(validation), params))

    applied_items = []
    attempted = []
    live_owners = set()
    successful_prepared = []
    item_errors = []
    batch_timings = []
    try:
        batched = {}
        if getattr(ipc, "supports_shader_restore_batches", False):
            from .project_restore import _RESTORE_THREAD_STATE
            checkpoint = getattr(_RESTORE_THREAD_STATE, "control_checkpoint", None)
            # Keep bounded cancellation/foreground yield points. Real savings
            # come from coalescing replay, not making a long GPU transaction.
            batch_size = 12
            for offset in range(0, len(prepared), batch_size):
                if callable(checkpoint):
                    checkpoint("before verified Shader restore batch")
                chunk = prepared[offset:offset + batch_size]
                attempted.extend((row[0], row[4]["operation_id"]) for row in chunk)
                batch_started = time.perf_counter()
                response = ipc.call("apply_shader_candidate_shared_resource_batch",
                    {"items": [row[4] for row in chunk]}, timeout=300.0)
                batch_timings.append({"items": len(chunk),
                    "elapsedMs": round((time.perf_counter() - batch_started) * 1000, 3)})
                rows = response.get("items") if isinstance(response, Mapping) else None
                if (response.get("captureSessionId") != session_id or not isinstance(rows, list)
                        or len(rows) != len(chunk)):
                    raise RuntimeError("Verified RDC restore returned an invalid batch")
                for row, item in zip(chunk, rows):
                    batched[row[4]["operation_id"]] = item
        for status, request, anchor, validation, params in prepared:
            # Track dispatch, not just successful responses: a timed-out call
            # may have committed its target before its response was lost.
            if batched:
                item = batched[params["operation_id"]]
                if item.get("ok") is not True:
                    from types import SimpleNamespace
                    from .project_restore import _recover_uncertain_workspace_apply
                    _recover_uncertain_workspace_apply(SimpleNamespace(ipc=ipc), status,
                        params["operation_id"], session_id)
                    item_errors.append({"workspaceId": status["workspaceId"],
                        "error": str(item.get("error", "Shader batch item failed"))[:2048]})
                    continue
                raw = item.get("result")
            else:
                attempted.append((status, params["operation_id"]))
                raw = ipc.call("apply_shader_candidate_shared_resource", params, timeout=300.0)
            if (isinstance(raw, dict) and type(raw.get("originalResourceId")) is int
                    and raw["originalResourceId"] > 0
                    and raw.get("originalRawSha256") == anchor["originalRawSha256"]
                    and raw.get("restoreValidationReceipt") == params["restore_validation_receipt"]):
                anchor = {**anchor, "originalResourceId": raw["originalResourceId"]}
            applied = _validated_shared_shader_apply_response(
                raw, status=status, request=request, anchor=anchor,
                report_sha256=params["abi_report_sha256"])
            fresh_physical = (request["binding"].get("encoding") == "glsl"
                              and applied.get("targetBuiltOnce") is True)
            expected_evidence = {
                "operationId": params["operation_id"], "captureSessionId": session_id,
                "abiValidationMode": "verified-rdc-restore",
                "freshPhysicalAbiValidationPerformed": fresh_physical,
                "restoreValidationReceipt": params["restore_validation_receipt"],
            }
            mismatches = [key for key, expected_value in expected_evidence.items()
                          if applied.get(key) != expected_value or
                          (key == "freshPhysicalAbiValidationPerformed"
                           and applied.get(key) is not fresh_physical)]
            if mismatches:
                # Never dump the signed receipt (which can carry bounded DXIL
                # evidence); field names and scalar values identify the broken
                # response contract without hiding it behind a generic miss.
                diagnostic = ", ".join(
                    (key + " missing") if key not in applied else
                    (key + " differs") if key == "restoreValidationReceipt" else
                    (key + "=" + repr(applied[key])[:160]) for key in mismatches)
                raise RuntimeError("RenderDoc returned invalid verified restore evidence: " + diagnostic)
            if applied["originalResourceId"] in live_owners:
                raise RuntimeError("Verified RDC restore rebound two workspaces to the same live Shader")
            live_owners.add(applied["originalResourceId"])
            validation.update({
                "captureSessionId": session_id, "validationScope": "verified-rdc-restore",
                "reusedValidation": True, "freshLiveCaptureValidationPerformed": True,
                "freshPhysicalValidationPerformed": fresh_physical,
            })
            applied_items.append({
                "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
                "operation": "apply-shared-resource", "operationId": params["operation_id"],
                "binding": request["binding"], "validation": validation,
                "replacement": applied, "scope": "captured-resource", "applied": True,
                "rollback": {"tool": "rollback_shader_workspace_shared_resource",
                             "workspacePath": status["workspacePath"],
                             "replacementId": applied["replacementId"]},
            })
            successful_prepared.append((status, request, anchor, validation, params))
        for status, unused_request, unused_anchor, unused_validation, unused_params in successful_prepared:
            current = service.status(status["workspacePath"])
            if _verified_restore_workspace_identity(current) != _verified_restore_workspace_identity(status):
                raise RuntimeError("Shader workspace changed during verified RDC restore")
        for item, prepared_item in zip(applied_items, successful_prepared):
            status, request, unused_anchor, unused_validation, params = prepared_item
            _remember_shared_shader_replacement(item["replacement"], status=status, abi_lease={
                "abiLeaseRequestId": request["requestId"],
                "abiLeaseReportSha256": params["abi_report_sha256"],
                "abiLeaseCandidateRawSha256": request["binding"]["candidateRawSha256"],
                "abiLeaseRevision": request["binding"]["revision"],
            })
        return {"applied": not item_errors, "items": applied_items, "itemErrors": item_errors,
                "batchTimings": batch_timings}
    except Exception as apply_error:
        from types import SimpleNamespace
        from .project_restore import _recover_uncertain_workspace_apply, RestoreRollbackFailed

        failures = []
        for status, attempted_operation in reversed(attempted):
            try:
                recovered = _recover_uncertain_workspace_apply(
                    SimpleNamespace(ipc=ipc), status, attempted_operation, session_id)
                with _SHADER_OVERRIDE_GUARD:
                    token = recovered.get("replacementId")
                    local = _SHARED_SHADER_REPLACEMENT_RECORDS.get(token)
                    if (local and local.get("workspaceId") == status["workspaceId"]
                            and local.get("captureSessionId") == session_id):
                        _SHARED_SHADER_REPLACEMENT_RECORDS.pop(token, None)
            except Exception as error:
                failures.append(str(error))
        if failures:
            # A recovery failure must not hide the reason the apply was
            # rejected. Only include known, bounded diagnostics here: bridge
            # errors can contain arbitrary payloads, including signed receipts.
            cause = type(apply_error).__name__
            detail = str(apply_error)
            if detail.startswith((
                "RenderDoc shared Shader response mismatch at ",
                "RenderDoc capture changed during shared Shader apply",
                "Verified RDC restore ",
                "Shader workspace changed during verified RDC restore",
            )):
                cause += ": " + detail[:180]
            raise RestoreRollbackFailed(
                "Verified RDC restore rollback needs recovery after "
                + cause + ": " + "; ".join(failures)
            ) from apply_error
        raise


@mcp.tool()
def register_active_project_shader_replacement(
    workspace_path: str,
    expected_revision: int,
    expected_candidate_raw_sha256: str,
    replacement_id: str,
    embed_capture_index: bool = False,
) -> str:
    """Explicitly persist one already-applied shared Shader replacement.

    This project-effect endpoint does not apply or replace a Shader. It binds
    the caller-supplied revision, candidate SHA-256, and replacement token to
    the exact live shared-resource replacement, commits the reviewed workspace
    knowledge and the derived RDC/EID association. ``embed_capture_index``
    explicitly requests writing that index into the RDC; the default leaves
    capture bytes unchanged.
    """

    try:
        if type(embed_capture_index) is not bool:
            raise ValueError("embed_capture_index must be a boolean")
        from .project_restore import sync_active_shader_workspace_after_apply

        return _ok(
            sync_active_shader_workspace_after_apply(
                workspace_path,
                expected_revision=expected_revision,
                expected_candidate_raw_sha256=expected_candidate_raw_sha256,
                replacement_id=replacement_id,
                embed_capture_index=embed_capture_index,
            )
        )
    except Exception as error:
        return _err(error)


def _valid_shader_rollback_physical_result(
    result: Any,
    *,
    status: Mapping[str, Any],
    local: Mapping[str, Any] | None,
    resource_scoped: bool,
) -> bool:
    """Validate a Bridge rollback tombstone against its physical executable."""

    if not isinstance(result, dict):
        return False
    try:
        stage = normalize_stage(result.get("stage"))
    except (TypeError, ValueError):
        return False
    entry_point = result.get("entryPoint")
    api = str(result.get("api", "") or "").strip().casefold()
    encoding = str(result.get("encoding", "") or "").strip().casefold()
    already_restored = result.get("alreadyRestored")
    idempotent = result.get("idempotentRollback")
    manual = (resource_scoped and result.get("abiValidationMode") == "manual-fast" and
              result.get("manualEdit") is True and result.get("replayAbiValidated") is False and
              result.get("validationScope") == "manual-edit-unvalidated")
    manual_hint = (result.get("abiValidationMode") == "manual-fast" or
                   result.get("manualEdit") is True or
                   result.get("validationScope") == "manual-edit-unvalidated")
    if manual_hint and (not manual or result.get("restoreValidationReceipt")):
        return False
    if not (
        stage
        and isinstance(entry_point, str)
        and 0 < len(entry_point) <= 512
        and (
            (api == "d3d11" and encoding == "dxbc")
            or (api == "d3d12" and encoding in {"dxbc", "dxil"})
            or (api == "vulkan" and encoding == "spirv")
            or (api == "opengl" and encoding in {"opengl-spirv", "glsl"})
        )
        and type(result.get("originalResourceId")) is int
        and result["originalResourceId"] > 0
        and type(result.get("targetResourceId")) is int
        and result["targetResourceId"] > 0
        and all(
            (manual and name == "physicalAbiSha256" and result.get(name) == "") or
            (isinstance(result.get(name), str)
             and len(result[name]) == 64
             and all(character in "0123456789abcdef" for character in result[name]))
            for name in (
                "originalRawSha256",
                "candidateRawSha256",
                "physicalAbiSha256",
                "shaderFamilyId",
            )
        )
        and result.get("resourceScoped") is resource_scoped
        and result.get("eventScoped") is (not resource_scoped)
        and type(already_restored) is bool
        and type(idempotent) is bool
        and already_restored is idempotent
        and result.get("cleared") is True
        and result.get("originalShaderPreserved") is True
        and type(result.get("targetFreed")) is bool
    ):
        return False

    shader = status.get("shader")
    baseline = status.get("baseline")
    if isinstance(shader, Mapping):
        status_stage = shader.get("stage", status.get("stage"))
        try:
            if status_stage and normalize_stage(status_stage) != stage:
                return False
        except (TypeError, ValueError):
            return False
        if shader.get("entryPoint") not in (None, "", entry_point):
            return False
        if shader.get("resourceId") not in (None, result["originalResourceId"]):
            return False
    expected_original_raw = (
        baseline.get("rawSha256") if isinstance(baseline, Mapping) else None
    )
    if expected_original_raw not in (None, "", result["originalRawSha256"]):
        return False

    if isinstance(local, Mapping):
        observed = {
            "stage": stage,
            "entryPoint": entry_point,
            "api": api,
            "encoding": encoding,
            "originalResourceId": result["originalResourceId"],
            "originalRawSha256": result["originalRawSha256"],
            "candidateRawSha256": result["candidateRawSha256"],
            "physicalAbiSha256": result["physicalAbiSha256"],
            "shaderFamilyId": result["shaderFamilyId"],
            "targetResourceId": result["targetResourceId"],
        }
        if any(
            local.get(name) not in (None, "") and local.get(name) != value
            for name, value in observed.items()
        ):
            return False
    return True


@mcp.tool()
def rollback_shader_workspace_shared_resource(
    workspace_path: str, replacement_id: str
) -> str:
    """Restore the captured Shader for all uses and free its generated target."""
    try:
        # A task report may be absent, stale, or belong to an earlier Agent
        # conversation. The exact replacement token and the live editor state
        # are physical authority for undo, not that task's bookkeeping.
        status = _shader_workspace_service().status(workspace_path)
        capture_id = str(status["capture"]["captureId"])
        live = ipc.call("get_capture_status", {}, timeout=30.0)
        if not isinstance(live, dict) or live.get("loaded") is not True:
            _sync_shader_override_capture("")
            raise RuntimeError("No capture is loaded in RenderDoc")
        live_capture_path = str(live.get("capturePath", "") or "")
        live_session_id = str(live.get("captureSessionId", "") or "")
        _sync_shader_override_capture(live_session_id)
        if (
            not live_capture_path
            or _capture_path_key(live_capture_path)
            != _capture_path_key(str(status["capture"]["capturePath"]))
            or capture_id
            not in list(live.get("knownCatalogCaptureIds", []) or [])
        ):
            raise RuntimeError(
                "The active RenderDoc capture does not match this workspace"
            )
        token = str(replacement_id or "").strip().lower()
        if len(token) != 32 or any(
            character not in "0123456789abcdef" for character in token
        ):
            raise ValueError(
                "replacement_id must be a 32-character lowercase hex ID"
            )
        with _SHADER_OVERRIDE_GUARD:
            local = _SHARED_SHADER_REPLACEMENT_RECORDS.get(token)
        if local is not None and any(
            (
                local.get("captureId") != capture_id,
                local.get("workspaceId") != status["workspaceId"],
                local.get("captureSessionId") != live_session_id,
            )
        ):
            raise RuntimeError(
                "replacement_id is not bound to this shader workspace"
            )
        _require_workspace_live_edit_quiescent(
            str(status["workspacePath"]), action="rolling back"
        )
        result = ipc.call(
            "rollback_shader_candidate_shared_resource",
            {
                "replacement_id": token,
                "expected_capture_id": capture_id,
                "workspace_id": status["workspaceId"],
            },
            timeout=60.0,
        )
        if not isinstance(result, dict) or any(
            (
                result.get("schema")
                != "renderdoc-ultra-shared-shader-replacement/v1",
                result.get("schemaVersion") != 1,
                result.get("replacementId") != token,
                result.get("captureId") != capture_id,
                result.get("captureSessionId") != live_session_id,
                result.get("workspaceId") != status["workspaceId"],
                not _valid_shader_rollback_physical_result(
                    result,
                    status=status,
                    local=local,
                    resource_scoped=True,
                ),
            )
        ):
            raise RuntimeError(
                "RenderDoc returned an invalid shared Shader rollback result"
            )
        with _SHADER_OVERRIDE_GUARD:
            _SHARED_SHADER_REPLACEMENT_RECORDS.pop(token, None)
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-shared-resource-apply-mcp/v1",
                "operation": "rollback-shared-resource",
                "workspaceId": status["workspaceId"],
                "captureId": capture_id,
                "replacement": result,
                "applied": False,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def rollback_shader_workspace_override(
    workspace_path: str, override_id: str
) -> str:
    """Clear one event-scoped override and free its RenderDoc target shader."""
    try:
        status = _shader_workspace_service().status(workspace_path)
        capture_id = str(status["capture"]["captureId"])
        live = ipc.call("get_capture_status", {}, timeout=30.0)
        if not isinstance(live, dict) or live.get("loaded") is not True:
            _sync_shader_override_capture("")
            raise RuntimeError("No capture is loaded in RenderDoc")
        live_capture_path = str(live.get("capturePath", "") or "")
        live_session_id = str(live.get("captureSessionId", "") or "")
        workspace_capture_path = str(status["capture"]["capturePath"])
        _sync_shader_override_capture(live_session_id)
        if (
            not live_capture_path
            or _capture_path_key(live_capture_path)
            != _capture_path_key(workspace_capture_path)
            or capture_id not in list(live.get("knownCatalogCaptureIds", []) or [])
        ):
            raise RuntimeError(
                "The active RenderDoc capture does not match this workspace"
            )

        token = str(override_id or "").strip().lower()
        if len(token) != 32 or any(
            character not in "0123456789abcdef" for character in token
        ):
            raise ValueError("override_id must be a 32-character lowercase hex ID")
        with _SHADER_OVERRIDE_GUARD:
            local = _SHADER_OVERRIDE_RECORDS.get(token)
        if local is not None and any(
            (
                local.get("captureId") != capture_id,
                local.get("workspaceId") != status["workspaceId"],
                local.get("captureSessionId") != live_session_id,
            )
        ):
            raise RuntimeError("override_id is not bound to this shader workspace")
        try:
            result = ipc.call(
                "rollback_shader_candidate_override",
                {
                    "override_id": token,
                    "expected_capture_id": capture_id,
                },
                timeout=60.0,
            )
        except Exception:
            # Bridge rollback is transactional: on an RPC error it restores the
            # prior override when possible. Keep the local token so a caller can
            # inspect/retry instead of orphaning a still-live family reference.
            raise
        if not isinstance(result, dict) or any(
            (
                result.get("schema")
                != "renderdoc-ultra-event-shader-override/v1",
                result.get("schemaVersion") != 1,
                result.get("overrideId") != token,
                result.get("captureId") != capture_id,
                result.get("captureSessionId") != live_session_id,
                not _valid_shader_rollback_physical_result(
                    result,
                    status=status,
                    local=local,
                    resource_scoped=False,
                ),
            )
        ):
            raise RuntimeError("RenderDoc returned an invalid shader rollback result")
        with _SHADER_OVERRIDE_GUARD:
            _SHADER_OVERRIDE_RECORDS.pop(token, None)
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-apply-mcp/v1",
                "operation": "rollback",
                "workspaceId": status["workspaceId"],
                "captureId": capture_id,
                "override": result,
                "applied": False,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def rollback_shader_workspace_override_family(
    workspace_path: str, override_ids: list[str]
) -> str:
    """Atomically roll back event overrides and release the last family target.

    A target remains alive while any event in the family still references it.
    The captured/original Shader ResourceId is never freed.
    """
    try:
        status = _shader_workspace_service().status(workspace_path)
        capture_id = str(status["capture"]["captureId"])
        live = ipc.call("get_capture_status", {}, timeout=30.0)
        if not isinstance(live, dict) or live.get("loaded") is not True:
            _sync_shader_override_capture("")
            raise RuntimeError("No capture is loaded in RenderDoc")
        live_capture_path = str(live.get("capturePath", "") or "")
        live_session_id = str(live.get("captureSessionId", "") or "")
        _sync_shader_override_capture(live_session_id)
        if (
            not live_capture_path
            or _capture_path_key(live_capture_path)
            != _capture_path_key(str(status["capture"]["capturePath"]))
            or capture_id not in list(live.get("knownCatalogCaptureIds", []) or [])
        ):
            raise RuntimeError(
                "The active RenderDoc capture does not match this workspace"
            )
        if not isinstance(override_ids, list) or not override_ids:
            raise ValueError("override_ids must be a non-empty array")
        if len(override_ids) > 256:
            raise ValueError("override_ids exceeds the 256 override limit")
        tokens = []
        for value in override_ids:
            token = str(value or "").strip().lower()
            if len(token) != 32 or any(
                character not in "0123456789abcdef" for character in token
            ):
                raise ValueError(
                    "override_ids must contain 32-character lowercase hex IDs"
                )
            if token in tokens:
                raise ValueError("override_ids must not contain duplicates")
            tokens.append(token)
        with _SHADER_OVERRIDE_GUARD:
            local_by_token = {
                token: copy.deepcopy(_SHADER_OVERRIDE_RECORDS.get(token))
                for token in tokens
            }
            for token in tokens:
                local = local_by_token[token]
                if local is not None and any(
                    (
                        local.get("captureId") != capture_id,
                        local.get("workspaceId") != status["workspaceId"],
                        local.get("captureSessionId") != live_session_id,
                    )
                ):
                    raise RuntimeError(
                        "override_id is not bound to this shader workspace"
                    )

        result = ipc.call(
            "rollback_shader_candidate_overrides",
            {
                "override_ids": tokens,
                "expected_capture_id": capture_id,
            },
            timeout=60.0,
        )
        if not isinstance(result, dict) or any(
            (
                result.get("schema")
                != "renderdoc-ultra-event-shader-rollback-batch/v1",
                result.get("schemaVersion") != 1,
                result.get("captureId") != capture_id,
                result.get("captureSessionId") != live_session_id,
                result.get("transactional") is not True,
                result.get("originalShadersPreserved") is not True,
                type(result.get("alreadyRestored")) is not bool,
                type(result.get("idempotentRollback")) is not bool,
                result.get("alreadyRestored")
                is not result.get("idempotentRollback"),
            )
        ):
            raise RuntimeError("RenderDoc returned an invalid family rollback result")
        overrides = result.get("overrides")
        if not isinstance(overrides, list) or len(overrides) != len(tokens):
            raise RuntimeError("RenderDoc returned an incomplete family rollback")
        returned = set()
        for item in overrides:
            if not isinstance(item, dict) or any(
                (
                    item.get("schema")
                    != "renderdoc-ultra-event-shader-override/v1",
                    item.get("schemaVersion") != 1,
                    item.get("captureId") != capture_id,
                    item.get("captureSessionId") != live_session_id,
                    item.get("overrideId") not in tokens,
                    not _valid_shader_rollback_physical_result(
                        item,
                        status=status,
                        local=local_by_token.get(item.get("overrideId")),
                        resource_scoped=False,
                    ),
                )
            ):
                raise RuntimeError("RenderDoc returned an invalid family rollback item")
            returned.add(item["overrideId"])
        if returned != set(tokens):
            raise RuntimeError("RenderDoc family rollback tokens do not match")
        with _SHADER_OVERRIDE_GUARD:
            for token in tokens:
                _SHADER_OVERRIDE_RECORDS.pop(token, None)
        return _ok(
            {
                "schema": "renderdoc-ultra-shader-family-apply-mcp/v1",
                "operation": "rollback-family",
                "workspaceId": status["workspaceId"],
                "captureId": capture_id,
                "family": result,
                "applied": False,
            }
        )
    except Exception as error:
        return _err(error)


@mcp.tool()
def prepare_material_session(
    event_id: int,
    constant_block_index: int,
    stage: str = "fragment",
    expected_capture_id: str = "",
) -> str:
    """Create an immutable, event-scoped local D3D11/D3D12 CBuffer session.

    The selected constant block is resolved from live shader reflection. The
    full valid binding window is copied. This preserves D3D11.1 ring-buffer
    offsets and uses a reflection-bounded window for D3D12 root CBVs instead
    of copying the remainder of an upload ring. D3D12 descriptor-table and
    root CBVs are supported; root constants are excluded. Only reflected
    32-bit float/signed-int/unsigned-int scalar and vec2/vec3/vec4 leaves (and
    arrays with explicit stride) become editable.

    Args:
        event_id: Exact draw/dispatch event to replay.
        constant_block_index: Index in the selected shader reflection.
        stage: D3D11/D3D12 shader stage; ``pixel`` is accepted as ``fragment``.
            D3D12 task/amplification and mesh stages are accepted as ``task``
            and ``mesh``.
        expected_capture_id: Optional exported catalog SHA-256. If omitted,
            the active catalog identity is used only when unambiguous.
    """

    try:
        return _ok(
            _material_session_manager().prepare(
                event_id,
                stage,
                constant_block_index,
                expected_capture_id,
            )
        )
    except Exception as error:
        return _err(error)


