def _shader_live_edit_remote(operation: str, parameters: dict[str, Any]) -> dict[str, Any]:
    from .ipc_client import _CALL_BINDING
    from .shader_live_edit_client import request

    context = _active_live_context(allow_missing_capture_id=True)
    capture = context["capture"]
    direct = _CALL_BINDING.get()
    instance = direct[0] if direct is not None else ipc.instance_id
    if not instance:
        raise RuntimeError("Shader live-edit requires an exact qrenderdoc instance")
    binding = {"instanceId": instance, "captureSessionId": capture["captureSessionId"],
               "capturePath": capture["path"]}
    from .shader_restore_admission import local_dispatcher
    dispatch = local_dispatcher()
    # Only the Internal owner's restore worker has this private callable.
    # Keep the same closed payload parser and capture checks as HTTP starts.
    if dispatch is not None:
        from .internal_tool_service import SHADER_LIVE_EDIT_OPERATION_SCHEMA
        request_id = uuid.uuid4().hex
        code, value = dispatch(json.dumps({"schema": SHADER_LIVE_EDIT_OPERATION_SCHEMA,
            "requestId": request_id, "operation": operation, "parameters": parameters,
            "binding": binding}, ensure_ascii=True, allow_nan=False).encode("utf-8"))
        if code != 200:
            error = RuntimeError("Bread internal Shader operation failed: %s" % value.get("error", code))
            if isinstance(value.get("startTiming"), dict):
                error.shader_start_timing = value["startTiming"]
            raise error
        if (value.get("requestId") != request_id or value.get("binding") != binding
                or not isinstance(value.get("result"), dict)):
            raise RuntimeError("Bread internal Shader response identity changed")
        return value["result"]
    return request(operation, parameters, binding)


@mcp.tool()
def start_shader_workspace_live_edit(
    workspace_path: str, debounce_ms: int = 100
) -> str:
    """Authorise fast compilation and shared-resource apply on later editor saves.

    Starting this persistent session is the explicit auto-apply authorisation.
    Existing compiled source and validated replacements are retained. Saves
    reuse source/include/compiler caches. Manual saves do not repeat the AI
    organization ABI/reflection/equivalence checks, and their results explicitly
    carry manual-edit-unvalidated provenance. Compilation and driver creation
    failures retain the last working replacement. Each apply binds the exact
    revision/hash to the current capture and all uses of its captured Shader
    ResourceId; rollback remains available. AI organization and explicit strict
    validation tools retain their full checks.
    """

    try:
        _require_organization_source_review(workspace_path)
        result = _shader_live_edit_remote("start", {"workspace_path": workspace_path, "debounce_ms": debounce_ms})
        return _shader_live_edit_response("start", result)
    except Exception as error:
        return _err(error)


