@mcp.tool()
@non_reporting_task_tool
def release_task_shader_occupancy(
    rollback_incomplete_replacement: bool = False,
) -> str:
    """Release this AI task's abandoned Shader work.

    Call when the chat is no longer actively editing files. A live-edit session
    delivered with a successful replay apply stays authorized for the user's
    editor after the chat ends. Undelivered monitors are stopped.
    ``rollback_incomplete_replacement`` is reserved for an explicit request to
    undo this task's applied replacement. Task failure/cancellation alone never
    selects it; use ``rollback_shader_workspace_shared_resource`` for a known
    replacement token.
    """

    try:
        if type(rollback_incomplete_replacement) is not bool:
            raise ValueError("rollback_incomplete_replacement must be a boolean")
        store = current_task_report_store()
        task_id = str(store.task_id or os.environ.get(TASK_ID_ENV, "") or "")
        if not task_id:
            raise RuntimeError("release_task_shader_occupancy requires the current AI task")
        result = _release_task_shader_occupancy(
            task_id=task_id,
            event_root=store.event_root,
            rollback_replacement=rollback_incomplete_replacement,
            reason="ai-task-idle",
        )
        return _ok(result)
    except Exception as error:
        return _err(error)


@mcp.tool()
def inspect_shader_resource_occupancy(
    original_resource_id: int = 0,
    workspace_id: str = "",
) -> str:
    """Inspect who owns a shared Shader ResourceId and why it is occupied."""

    try:
        live = ipc.call("get_capture_status", {}, timeout=30.0)
        if not isinstance(live, dict) or live.get("loaded") is not True:
            raise RuntimeError("No capture is loaded in RenderDoc")
        capture_id = ""
        try:
            context = _active_live_context()
            capture_id = str((context.get("capture") or {}).get("captureId") or "")
        except Exception:
            capture_id = ""
        if not capture_id:
            known = list(live.get("knownCatalogCaptureIds", []) or [])
            capture_id = str(known[0] if known else "")
        capture_session_id = str(live.get("captureSessionId", "") or "")
        if not capture_id or not capture_session_id:
            raise RuntimeError("active capture identity is unavailable")
        resource = int(original_resource_id or 0)
        expected_workspace = str(workspace_id or "").strip().lower()
        if expected_workspace:
            _strict_lower_hex(expected_workspace, 32, "workspace_id")
        result = _inspect_shared_shader_occupancy(
            ipc=ipc,
            capture_id=capture_id,
            capture_session_id=capture_session_id,
            original_resource_id=resource,
            workspace_id=expected_workspace,
        )
        result["schema"] = "replaylab-shader-resource-occupancy/v1"
        return _ok(result)
    except Exception as error:
        return _err(error)


