def _active_asset_catalog_context(
    *, require_catalog: bool, create_dictionary: bool = False
) -> tuple[
    ActiveReplayProjectService,
    dict[str, Any],
    Path,
    Path,
]:
    """Resolve the path-free active-project asset catalog boundary."""

    service = _active_project_service()
    status = service.status()
    if status.get("scopeConfigured") is not True:
        raise RuntimeError(
            "active project game/build scope must be configured before asset indexing"
        )
    if status.get("assetRootConfigured") is not True:
        raise RuntimeError("active project has no unpacked asset root configured")
    if status.get("assetRootAvailable") is not True:
        raise RuntimeError("configured active-project asset root is unavailable")
    project_root = Path(str(status.get("projectRoot", "") or "")).resolve()
    asset_root = Path(str(status.get("assetRoot", "") or "")).resolve()
    if project_root.is_symlink() or not project_root.is_dir():
        raise RuntimeError("active project root is redirected or unavailable")
    if asset_root.is_symlink() or not asset_root.is_dir():
        raise RuntimeError("active project asset root is redirected or unavailable")
    if create_dictionary:
        assets_directory = service.shared_dictionary_directory("assets")
    else:
        paths = status.get("paths")
        if not isinstance(paths, Mapping) or not paths.get("sharedDictionaries"):
            raise RuntimeError("active project omitted its shared dictionary root")
        shared_root = Path(str(paths["sharedDictionaries"])).resolve()
        assets_directory = (shared_root / "assets").resolve()
        if (
            shared_root.is_symlink()
            or not shared_root.is_dir()
            or assets_directory.is_symlink()
            or not assets_directory.is_dir()
            or not is_within(project_root, shared_root)
            or not is_within(shared_root, assets_directory)
        ):
            raise RuntimeError("active project asset dictionary is unavailable")
    database_path = (assets_directory / ACTIVE_ASSET_CATALOG_FILENAME).resolve()
    if not is_within(project_root, database_path) or not is_within(
        assets_directory, database_path
    ):
        raise RuntimeError("active project asset catalog path escaped its dictionary")
    if require_catalog and (
        database_path.is_symlink() or not database_path.is_file()
    ):
        raise RuntimeError("active project asset catalog has not been prepared")
    return service, status, asset_root, database_path


def _reconcile_stale_asset_catalog(
    status: Mapping[str, Any],
    asset_root: Path,
    database_path: Path,
    *,
    depth: str = "headers",
) -> dict[str, Any] | None:
    """Retire a catalog bound to another root/build and start a fresh index.

    Host never aborts the Agent for a stale catalog: the tree is the source of
    truth, so a mismatched or corrupt SQLite file is replaced and re-searched.
    Returns a reconciliation receipt when rebuild was started, else ``None``.
    """

    expected_root = Path(asset_root).resolve()
    expected_build = str(status.get("scope", {}).get("buildId", "") or "")
    previous_root = ""
    previous_build = ""
    reason = ""
    if database_path.is_symlink() or not database_path.is_file():
        reason = "absent"
    else:
        try:
            current = AssetCatalogService(database_path).status()
        except Exception as exc:  # noqa: BLE001 — any unreadable catalog is rebuilt
            reason = "corrupt:%s" % type(exc).__name__
        else:
            previous_root = str(current.get("rootPath", "") or "")
            previous_build = str(current.get("buildId", "") or "")
            try:
                recorded_root = Path(previous_root).resolve()
            except OSError:
                recorded_root = Path()
                reason = "unreadable-root"
            if not reason and recorded_root != expected_root:
                reason = "stale-root"
            elif not reason and previous_build != expected_build:
                reason = "stale-build"
    if not reason:
        return None
    # ensure_index_job → scan → _open_writable recreates a DB whose root/build
    # no longer matches the active project.
    job = _asset_index_job(
        database_path, expected_root, expected_build, depth=str(depth or "headers")
    )
    return {
        "schema": "replaylab-asset-catalog-reconcile/v1",
        "schemaVersion": 1,
        "reconciled": True,
        "reason": reason,
        "expectedRoot": str(expected_root),
        "expectedBuildId": expected_build,
        "previousRoot": previous_root,
        "previousBuildId": previous_build,
        "job": job,
        "ready": False,
        "complete": False,
    }


@mcp.tool()
def get_unpacked_asset_index_capabilities() -> str:
    """Report fixed generic/UEX-aware asset index and relationship capabilities."""

    try:
        return _ok(AssetCatalogService.capabilities())
    except Exception as error:
        return _err(error)


@mcp.tool()
def get_active_unpacked_asset_index_status() -> str:
    """Read the current project-owned unpacked-asset catalog status without scanning."""

    try:
        unused_service, status, asset_root, database_path = (
            _active_asset_catalog_context(require_catalog=False, create_dictionary=True)
        )
        reconcile = _reconcile_stale_asset_catalog(status, asset_root, database_path)
        if reconcile is not None:
            reconcile["project"] = {
                "workspaceId": status["workspaceId"],
                "projectRoot": status["projectRoot"],
            }
            reconcile["backgroundJob"] = reconcile.get("job")
            reconcile["indexState"] = "indexing"
            reconcile["assetRootConfigured"] = True
            reconcile["directAssetReadsAvailable"] = asset_root.is_dir()
            reconcile["partialCatalogAvailable"] = False
            reconcile["applied"] = True
            return _ok(reconcile)
        if database_path.is_symlink() or not database_path.is_file():
            raise RuntimeError("active project asset catalog has not been prepared")
        result = AssetCatalogService(database_path).status()
        result["project"] = {
            "workspaceId": status["workspaceId"],
            "projectRoot": status["projectRoot"],
        }
        result["backgroundJob"] = _asset_index_status(database_path)
        # One truth about the index. `ready` used to say "a catalog exists" while the
        # gate said "still indexing", and an Agent reading both just polled in circles.
        gate = _asset_index_state()
        result["indexState"] = gate["state"]
        result["complete"] = gate["state"] == "ready"
        result["assetRootConfigured"] = True
        result["directAssetReadsAvailable"] = asset_root.is_dir()
        result["partialCatalogAvailable"] = bool(result.get("assetCount"))
        if gate["state"] != "ready":
            result["ready"] = False
            if gate.get("progress"):
                result["progress"] = gate["progress"]
            if gate.get("error"):
                result["indexError"] = gate["error"]
        result["applied"] = False
        return _ok(result)
    except Exception as error:
        # Catalog errors do not establish whether a project has an asset root.
        # Re-read the actual active configuration; never infer availability
        # from the wording of a stale-index, permission or database exception.
        configured: bool | None = None
        direct_reads = False
        configuration_error = ""
        try:
            active = _active_project_service().status()
            root_text = str(active.get("assetRoot", "") or "").strip()
            configured = active.get("assetRootConfigured") is True and bool(root_text)
            if configured:
                root_path = Path(root_text)
                direct_reads = bool(active.get("assetRootAvailable") is True
                                    and root_path.is_dir() and not root_path.is_symlink()
                                    and not getattr(root_path, "is_junction", lambda: False)())
        except Exception as status_error:
            configuration_error = str(status_error)
        return _ok(
            {
                "schema": "renderdoc-ultra-unpacked-asset-index-status/v1",
                "schemaVersion": 1,
                "ready": False,
                "reason": str(error),
                "assetRootConfigured": configured,
                "directAssetReadsAvailable": direct_reads,
                "configurationError": configuration_error,
                "applied": False,
            }
        )


@mcp.tool()
def index_active_unpacked_assets(
    scan_mode: str = "incremental",
    max_files: int = ACTIVE_ASSET_DEFAULT_MAX_FILES,
    max_file_size_mb: int = ACTIVE_ASSET_DEFAULT_MAX_FILE_SIZE_MB,
    depth: str = "headers",
    wait_seconds: float = 0.0,
) -> str:
    """Start (or join) the background scan of the active project's asset tree.

    This returns as soon as the scan is running -- it never waits for it. The scan
    lives in the process qrenderdoc keeps alive, so it survives this task, and it
    checkpoints as it goes, so everything already walked is queryable immediately.
    The background scan does not block subsequent tool calls.

    ``retrieve_shader_asset_candidates``,
    ``profile_unpacked_asset_directories`` and ``search_unpacked_assets`` index what
    they need on first use, and the folder-scoped ``hydrate_unpacked_asset_scope``
    parses selected folders without scanning the whole tree.

    When ``wait_seconds`` is positive, the call waits up to that many seconds and
    returns the completed scan result if available; otherwise it returns a job receipt.

    ``depth``: ``names`` walks paths only (a minute on a large tree), ``headers``
    (default) also parses the small descriptive files -- package headers, materials,
    shaders, metadata -- and defers bulk data, ``full`` parses everything admitted by
    the size bounds. ``scan_mode``, ``max_files`` and ``max_file_size_mb`` are
    accepted for older callers and ignored; the background scan owns its own bounds.
    """

    del scan_mode, max_files, max_file_size_mb  # the background scan owns its own bounds
    try:
        service, status, asset_root, database_path = _active_asset_catalog_context(
            require_catalog=False,
            create_dictionary=True,
        )
        del service
        workspace_id = str(status.get("workspaceId", "") or "")
        project_root = Path(str(status.get("projectRoot", "") or "")).resolve()
        build_id = str(status.get("scope", {}).get("buildId", "") or "")
        # A tree of a few hundred thousand files takes minutes to walk. Running that
        # here would hold this process for the whole scan, and every other tool call
        # -- including the ones the AI needs to keep working while it indexes --
        # would time out behind it. The scan therefore belongs to the background job
        # that outlives this task (preferably in ReplayLabInternal), and this tool
        # starts or joins it and returns what it is doing.
        job = _asset_index_job(database_path, asset_root, build_id, depth=str(depth or "headers"))
        waited = max(0.0, min(float(wait_seconds or 0.0), 600.0))
        if waited > 0:
            # An explicit, opt-in wait: the caller said how long it is willing to
            # block. The default is still zero -- nothing waits unless it asks.
            from .asset_index_jobs import wait_for_index_job

            joined = wait_for_index_job(database_path, waited) or job
            job = dict(joined)
            finished = job.get("result") if isinstance(job.get("result"), Mapping) else None
            if job.get("status") == "failed" and job.get("error"):
                raise RuntimeError(str(job["error"]))
            if finished is not None:
                result = dict(finished)
                result["job"] = {key: value for key, value in job.items() if key != "result"}
                result["project"] = {"workspaceId": workspace_id, "projectRoot": str(project_root)}
                result["applied"] = True
                return _ok(result)
        return _ok({
            "schema": "renderdoc-ultra-unpacked-asset-index/v2",
            "schemaVersion": 2,
            "operation": "index-unpacked-assets",
            "started": True,
            "job": job,
            "project": {"workspaceId": workspace_id, "projectRoot": str(project_root)},
            "assetRoot": str(asset_root),
            "applied": True,
        })
    except AssetCatalogScanLimitError as error:
        return _ok(
            {
                "schema": "renderdoc-ultra-unpacked-asset-index-error/v1",
                "schemaVersion": 1,
                "operation": "index-unpacked-assets",
                "error": str(error),
                "type": type(error).__name__,
                "applied": False,
                "catalogReplaced": False,
                "coverage": {
                    "complete": False,
                    "truncated": True,
                    "walkedFiles": error.observed_files,
                    "maximumFiles": error.maximum_files,
                },
                "policy": dict(_ACTIVE_PROJECT_MCP_POLICY),
            }
        )
    except Exception as error:
        return _active_project_error("index-unpacked-assets", error)


@mcp.tool()
def query_active_unpacked_assets(
    text: str = "",
    kinds: list[str] | None = None,
    sha256: str = "",
    asset_ids: list[str] | None = None,
    limit: int = 20,
    include_relationships: bool = True,
) -> str:
    """Query only the active project's prepared catalog using typed filters."""

    try:
        service, status, asset_root, database_path = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=True
        )
        workspace_id = str(status.get("workspaceId", "") or "")
        project_root = Path(str(status.get("projectRoot", "") or "")).resolve()
        with service.pin_active_project(workspace_id, project_root):
            reconcile = _reconcile_stale_asset_catalog(
                status, asset_root, database_path
            )
            if reconcile is not None:
                reconcile["project"] = {
                    "workspaceId": workspace_id,
                    "projectRoot": str(project_root),
                }
                reconcile["assets"] = []
                reconcile["applied"] = True
                return _ok(reconcile)
            result = AssetCatalogService(database_path).query(
                text=text,
                kinds=kinds or (),
                sha256=sha256,
                asset_ids=asset_ids or (),
                limit=limit,
                include_relationships=include_relationships,
            )
            if Path(str(result.get("rootPath", "") or "")).resolve() != asset_root:
                reconcile = _reconcile_stale_asset_catalog(
                    status, asset_root, database_path
                )
                if reconcile is not None:
                    reconcile["project"] = {
                        "workspaceId": workspace_id,
                        "projectRoot": str(project_root),
                    }
                    reconcile["assets"] = []
                    reconcile["applied"] = True
                    return _ok(reconcile)
                raise RuntimeError("asset catalog belongs to another configured root")
            _require_same_active_project(status)
        result["project"] = {
            "workspaceId": workspace_id,
            "projectRoot": str(project_root),
        }
        result["applied"] = False
        return _ok(result)
    except Exception as error:
        return _active_project_error("query-unpacked-assets", error)


SHADER_ASSET_RESOLUTIONS_FILENAME = "shader-asset-resolutions-v1.sqlite3"


def _shader_asset_memory(raw_sha256: str, stage: str, entry_point: str) -> dict[str, Any] | None:
    """Remembered asset resolutions + material-family keys for one shader.

    Returns None when the active project has no indexed asset root; never
    raises, because memory is optional evidence for decompile/rename paths.
    """

    try:
        service, status, asset_root, database_path = _active_asset_catalog_context(require_catalog=True)
    except Exception:
        return None
    try:
        game_key = _shader_asset_game_key(status, asset_root)
        store = shader_asset_retrieval.ShaderAssetResolutionStore(
            database_path.parent / SHADER_ASSET_RESOLUTIONS_FILENAME)
        catalog = AssetCatalogService(database_path)
        exact = store.lookup(game_key, str(raw_sha256).lower(), "", normalize_stage(stage), str(entry_point or ""))
        resolutions: list[dict[str, Any]] = []
        for raw_resolution in exact.get("resolutions") or []:
            if not isinstance(raw_resolution, Mapping) or not _resolution_row_is_host_sealed(
                raw_resolution
            ):
                continue
            evidence = raw_resolution.get("evidence")
            evidence = evidence if isinstance(evidence, Mapping) else {}
            binding = evidence.get("assetBinding")
            if not isinstance(binding, Mapping):
                continue
            current, unused_reason = _asset_evidence_binding_is_current(binding)
            if current:
                resolutions.append(dict(raw_resolution))
        families: list[str] = []
        family_authorities: dict[str, dict[str, str]] = {}
        for resolution in resolutions:
            evidence = resolution.get("evidence")
            evidence = evidence if isinstance(evidence, Mapping) else {}
            binding = evidence.get("assetBinding")
            binding = binding if isinstance(binding, Mapping) else {}
            authority = {
                "assetVersionSha256": str(
                    binding.get("assetVersionSha256") or ""
                ).lower(),
                "assetResolutionHmacSha256": str(
                    evidence.get("hostResolutionHmacSha256") or ""
                ).lower(),
            }
            path = str(resolution.get("assetRelativePath") or "")
            if path and path not in families:
                families.append(path)
            if path:
                family_authorities.setdefault(path, dict(authority))
            try:
                found = catalog.query(text=PurePosixPath(path).name, limit=20, include_relationships=True)
            except Exception:
                found = {"assets": []}
            for asset in found.get("assets", []):
                if str(asset.get("relativePath")) != path:
                    continue
                for relation in asset.get("relationships") or []:
                    if relation.get("relation") == "parent-material" and relation.get("targetPath"):
                        parent = str(relation["targetPath"])
                        if parent not in families:
                            families.append(parent)
                        family_authorities.setdefault(parent, dict(authority))
        return {"store": store, "gameKey": game_key, "catalog": catalog, "resolutions": resolutions,
                "familyKeys": families, "familyAuthorities": family_authorities,
                "databasePath": database_path}
    except Exception:
        return None


def _shader_asset_game_key(status: Mapping[str, Any], asset_root: Path) -> str:
    scope = status.get("scope") if isinstance(status.get("scope"), Mapping) else {}
    game = str((scope or {}).get("gameId", "") or "").strip()
    build = str((scope or {}).get("buildId", "") or "").strip()
    if game or build:
        return "%s@%s" % (game or "game", build or "build")
    return "root:" + hashlib.sha256(os.path.normcase(str(asset_root)).encode("utf-8")).hexdigest()[:16]


def _shader_asset_capture_features(event_id: int, stage: str, *, pass_hint: str, mesh_hint: str,
                                   extra_tokens: Sequence[str]) -> tuple[dict[str, Any], dict[str, Any]]:
    """Collect capture-side retrieval features for one event/stage shader."""

    context = _active_live_context(allow_missing_capture_id=True)
    selection = _active_capture_catalog_selection(int(event_id), stage)
    if selection is None:
        raise RuntimeError(
            "no active Shader catalog covers this event/stage; call "
            "get_active_shader_workspace_path(event_id, stage) first"
        )
    unused_exported, unused_path, selected, unused_binding = selection
    identity = {
        "captureId": selected.capture_id,
        "captureSessionId": context["capture"]["captureSessionId"],
        "eventId": int(event_id),
        "stage": selected.key.stage,
        "entryPoint": selected.key.entry_point,
        "shaderResourceId": selected.key.resource_id,
        "rawSha256": selected.key.raw_sha256,
    }
    textures = ipc.call("get_bound_textures", {"event_id": int(event_id), "stage": selected.key.stage}, timeout=60.0)
    if not isinstance(textures, list):
        textures = []
    bound_names = []
    resource_names = []
    texture_ids: list[int] = []
    for entry in textures[:256]:
        if not isinstance(entry, Mapping):
            continue
        tex_name = str(entry.get("texName", "") or "")
        if tex_name:
            bound_names.append(tex_name)
        reflection_name = str(entry.get("name", "") or "")
        if reflection_name:
            resource_names.append(reflection_name)
        try:
            rid = int(entry.get("resourceId") or 0)
        except (TypeError, ValueError):
            rid = 0
        if rid > 0 and rid not in texture_ids and len(texture_ids) < 16:
            texture_ids.append(rid)
    # Content fingerprints: RenderDoc converts a small mip of each bound texture
    # to PNG (any GPU format), the Host hashes it. Names are not needed.
    fingerprints: list[dict[str, Any]] = []
    fingerprint_status: dict[str, Any] = {"status": "skipped", "reason": "no bound textures"}
    if texture_ids:
        try:
            import base64 as _base64

            from .symbols.imaging import decode_png, fingerprint as image_fingerprint

            snapshots = ipc.call("get_texture_fingerprints", {"event_id": int(event_id), "resource_ids": texture_ids}, timeout=120.0)
            fingerprint_status = {"status": "ok", "requested": len(texture_ids), "available": 0}
            for snapshot in (snapshots.get("textures") if isinstance(snapshots, Mapping) else []) or []:
                if not isinstance(snapshot, Mapping):
                    continue
                item: dict[str, Any] = {"resourceId": snapshot.get("resourceId"), "name": snapshot.get("name"),
                                        "width": snapshot.get("width"), "height": snapshot.get("height"),
                                        "format": snapshot.get("format"), "available": False}
                if not snapshot.get("available"):
                    item["reason"] = snapshot.get("reason") or "no snapshot"
                    fingerprints.append(item)
                    continue
                try:
                    rgba, width, height = decode_png(_base64.b64decode(str(snapshot.get("pngBase64") or "")))
                    computed = image_fingerprint(rgba, width, height)
                    item.update({"available": True, "thumbnail": computed["thumbnail"], "dhash": computed["dhash"],
                                 "meanColor": computed["meanColor"], "flat": computed["flat"],
                                 "snapshot": {"mip": snapshot.get("mip"), "width": width, "height": height}})
                    fingerprint_status["available"] += 1
                except Exception as error:
                    item["reason"] = "snapshot undecodable: %s" % str(error)[:160]
                fingerprints.append(item)
        except Exception as error:
            fingerprint_status = {"status": "error", "reason": str(error)[:300]}
    # Raw constant-buffer lanes: distinctive floats become value evidence
    # (a complex number shared with an asset's parameter data is near-identity).
    lanes: list[dict[str, Any]] = []
    cbuffer_status: dict[str, Any] = {"status": "unavailable"}
    try:
        from .symbols.engines.unreal_package import is_distinctive_value

        values = ipc.call("get_constant_buffer_values", {"event_id": int(event_id), "stage": selected.key.stage}, timeout=60.0)
        if isinstance(values, Mapping):
            blocks = values.get("constantBuffers") or []
            cbuffer_status = {
                "status": str(values.get("status") or "unknown"),
                "blocks": [{"bind": block.get("bind"), "space": block.get("space"), "byteSize": block.get("byteSize"),
                            "status": block.get("status"), "reason": block.get("reason")} for block in blocks[:32]],
            }
            for block in blocks:
                for index, value in enumerate(block.get("floats") or []):
                    if isinstance(value, (int, float)) and not isinstance(value, bool) and is_distinctive_value(float(value)):
                        lanes.append({"bind": block.get("bind"), "space": block.get("space"), "lane": index, "value": float(value)})
                        if len(lanes) >= 1024:
                            break
                if len(lanes) >= 1024:
                    break
    except Exception as error:
        cbuffer_status = {"status": "error", "reason": str(error)[:300]}
    # Draw geometry: counts/layout survive even when every name is stripped.
    geometry: dict[str, Any] = {"available": False}
    try:
        geometry_result = ipc.call("get_draw_geometry", {"event_id": int(event_id)}, timeout=60.0)
        if isinstance(geometry_result, Mapping):
            geometry = {key: geometry_result.get(key) for key in (
                "available", "indexCount", "vertexCount", "instanceCount", "topology", "vertexInputs",
                "vertexBuffers", "indexBuffer", "meshHint")}
    except Exception as error:
        geometry = {"available": False, "reason": str(error)[:200]}
    if not mesh_hint and geometry.get("meshHint") in ("skeletal", "static", "instanced"):
        mesh_hint = str(geometry["meshHint"])
    # Code logic hints from the workspace source when one already exists.
    code_hints: dict[str, Any] = {}
    try:
        workspace_status = None
        project = _active_project_service()
        project_status = project.status()
        binding_now = _active_capture_catalog_binding()
        if binding_now is not None:
            catalog_sha = str(binding_now[2].get("catalogSha256") or "")
            workspace_dir = project.shader_workspace_path(
                capture_id=selected.capture_id, catalog_sha256=catalog_sha,
                route_binding_sha256=_active_shader_route_binding_sha256(), stage=selected.key.stage,
                shader_resource_id=selected.key.resource_id, raw_sha256=selected.key.raw_sha256, create=False)
            if workspace_dir and Path(str(workspace_dir)).is_dir():
                workspace_status = _shader_workspace_service().status(str(workspace_dir))
        source_path = (workspace_status or {}).get("source", {}).get("path") if workspace_status else None
        if source_path and Path(str(source_path)).is_file():
            text = Path(str(source_path)).read_text("utf-8", errors="replace")[:2 * 1024 * 1024]
            code_hints = {
                "usesDiscard": bool(re.search(r"\bdiscard\b|\bclip\s*\(", text)),
                "textureSampleCount": len(re.findall(r"\.(?:Sample|SampleLevel|SampleGrad|SampleBias|SampleCmp|Load|Gather\w*)\s*\(", text)),
                "usesDerivatives": bool(re.search(r"\bdd[xy](?:_fine|_coarse)?\s*\(", text)),
                "outputTargetCount": len(set(re.findall(r"SV_Target(\d*)", text))),
                "sourceLines": text.count("\n") + 1,
            }
    except Exception as error:
        code_hints = {"unavailable": str(error)[:160]}
    abi = getattr(selected, "abi", None)
    block_sizes: list[int] = []
    sampler_count = uav_count = 0
    if abi is not None:
        try:
            block_sizes = [int(block.byte_size) for block in abi.constant_blocks]
            sampler_count = len(abi.samplers)
            uav_count = len(abi.read_write_resources)
        except Exception:
            block_sizes = []
    features = {
        "stage": selected.key.stage,
        "entryPoint": selected.key.entry_point,
        "boundTextureNames": bound_names,
        "resourceNames": resource_names,
        "textureSlotCount": len(textures),
        "constantBlockSizes": block_sizes,
        "passHint": str(pass_hint or "")[:64],
        "meshHint": str(mesh_hint or "")[:64],
        "extraTokens": [str(item)[:64] for item in extra_tokens][:32],
        "constantBufferLanes": lanes,
        "constantBufferValueStatus": cbuffer_status,
        "boundTextureFingerprints": fingerprints,
        "textureFingerprintStatus": fingerprint_status,
        "drawGeometry": geometry,
        "codeHints": code_hints,
    }
    features["structuralKey"] = shader_asset_retrieval.structural_key(
        selected.key.stage, block_sizes, len(textures), sampler_count, uav_count, selected.key.entry_point
    )
    _require_same_active_capture(context, allow_missing_capture_id=True)
    return identity, features


# The first names walk is the one wait worth taking: without it there is
# nothing to search. It is a plain directory walk, not a parse.
ASSET_INDEX_FOREGROUND_BUDGET_SECONDS = 90.0
# A checkpointed catalog is already usable: wait only briefly for more.
ASSET_INDEX_PARTIAL_FOREGROUND_BUDGET_SECONDS = 5.0
# How many name hits one shader may pull into the deep index per request.
TARGETED_ASSET_HYDRATION_LIMIT = 48


def _targeted_asset_hydration(catalog: Any, asset_root: Path, features: Mapping[str, Any],
                              scope_prefixes: Sequence[str] = ()) -> dict[str, Any]:
    """Parse only the files this request points at; nothing else in the tree.

    Two pointers are trusted: the folders the reader chose after profiling the
    tree (``scope_prefixes`` -- their descriptive files are parsed, bulk data
    is not) and the reader's own words (``extra_tokens``, plus the shader's
    resource names). Texture names from the capture are deliberately not
    used: a shipped game rarely carries asset names on GPU resources. The
    parsed rows stay in the index, so the next question about the same
    folder costs nothing.
    """

    started = time.monotonic()
    extra = [str(item) for item in (features.get("extraTokens") or []) if isinstance(item, str)][:32]
    resources = [str(item) for item in (features.get("resourceNames") or []) if isinstance(item, str)
                 and not re.fullmatch(r"(?:t|s|u|b|cb)\d+|Material_Texture2D_\d+|.*_\d+", item)][:32]
    tokens = extra + resources
    receipt: dict[str, Any] = {"tokens": tokens[:64], "scopePrefixes": [str(item) for item in scope_prefixes],
                               "examined": 0, "hydrated": [], "seconds": 0.0}
    if scope_prefixes:
        try:
            scoped = catalog.hydrate_scope(asset_root, list(scope_prefixes)[:64],
                                           max_files=TARGETED_ASSET_HYDRATION_LIMIT * 4)
            receipt["scope"] = {key: scoped.get(key) for key in ("candidates", "materialExports", "truncated")}
            receipt["hydrated"].extend(scoped.get("hydrated") or [])
            receipt["missing"] = list(scoped.get("missing") or [])
        except Exception as error:
            receipt["scopeError"] = str(error)[:300]
    if not tokens:
        receipt["reason"] = ("no words from the user; ranking rests on folders, constant-buffer values, "
                             "texture pixels and structure")
        receipt["seconds"] = round(time.monotonic() - started, 1)
        return receipt
    try:
        search = catalog.search_tokens(tokens, kinds=(), class_names=[], limit=TARGETED_ASSET_HYDRATION_LIMIT)
    except Exception as error:
        receipt["reason"] = "name search failed: %s" % str(error)[:200]
        receipt["seconds"] = round(time.monotonic() - started, 1)
        return receipt
    wanted: list[str] = []
    folded_scope = [str(prefix).replace("\\", "/").strip("/").casefold() + "/" for prefix in scope_prefixes if str(prefix).strip("/")]
    for item in search.get("candidates", []):
        relative = str(item.get("relativePath") or "")
        if not relative:
            continue
        receipt["examined"] += 1
        suffix = PurePosixPath(relative).suffix.casefold()
        if suffix in {".ubulk", ".uptnl", ".ushaderbytecode", ".upipelinecache"}:
            continue
        if folded_scope and not any(relative.casefold().startswith(prefix) for prefix in folded_scope):
            continue
        if item.get("parseStatus") not in (None, "deferred"):
            continue
        wanted.append(relative)
        if suffix in {".uasset", ".umap"}:
            sibling = PurePosixPath(relative).with_suffix(".uexp").as_posix()
            if sibling not in wanted:
                wanted.append(sibling)
        if len(wanted) >= TARGETED_ASSET_HYDRATION_LIMIT * 2:
            break
    wanted = [path for path in wanted if path not in receipt["hydrated"]]
    if wanted:
        try:
            hydrated = catalog.hydrate(asset_root, wanted)
            receipt["hydrated"].extend(hydrated.get("hydrated") or [])
            receipt.setdefault("missing", []).extend(hydrated.get("missing") or [])
        except Exception as error:
            receipt["error"] = str(error)[:300]
    receipt["seconds"] = round(time.monotonic() - started, 1)
    return receipt


class _AssetCatalogNotReady(RuntimeError):
    """Raised while the on-demand index is still being built."""

    def __init__(self, receipt: Mapping[str, Any]):
        super().__init__("asset catalog is being indexed")
        self.receipt = dict(receipt)


def _asset_index_job(database_path: Path, asset_root: Path, build_id: str, depth: str = "headers") -> dict[str, Any]:
    """Start (or join) the background scan, preferring qrenderdoc's persistent service.

    ``ReplayLabInternal`` outlives this task-scoped process, so the scan keeps
    running after the task ends and later tasks simply join it.  When that
    service is unreachable (source runs, tests, old runtime) the scan runs in
    this process; its checkpoints still make the next attempt resume.
    """

    from . import asset_index_client
    from .asset_index_jobs import ensure_index_job

    if asset_index_client.is_current_process_owner():
        unused_service, status, current_root, current_database = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=True)
        current_build = str(status.get("scope", {}).get("buildId", "") or "")
        if (_capture_path_key(str(current_database)) != _capture_path_key(str(database_path))
                or _capture_path_key(str(current_root)) != _capture_path_key(str(asset_root))
                or current_build != build_id):
            raise RuntimeError("active project asset-index scope changed before the local request")
        return ensure_index_job(current_database, current_root, current_build,
                                depth=depth, owner="ReplayLabInternal")

    try:
        result = asset_index_client.request("ensure", depth=depth)
        job = dict(result.get("job") or {})
        job.setdefault("owner", "ReplayLabInternal")
        return job
    except asset_index_client.InternalAssetIndexUnavailable as exc:
        fallback_reason = str(exc)
    job = ensure_index_job(database_path, asset_root, build_id, depth=depth, owner="task-process")
    job["fallbackReason"] = fallback_reason
    return job


def _asset_index_status(database_path: Path) -> dict[str, Any] | None:
    from . import asset_index_client
    from .asset_index_jobs import index_job_status

    if asset_index_client.is_current_process_owner():
        unused_service, unused_status, unused_root, current_database = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=False)
        if _capture_path_key(str(current_database)) != _capture_path_key(str(database_path)):
            raise RuntimeError("active project asset-index scope changed before the local status request")
        return index_job_status(current_database)

    try:
        result = asset_index_client.request("status")
        job = result.get("job")
        return dict(job) if isinstance(job, Mapping) else None
    except asset_index_client.InternalAssetIndexUnavailable:
        return index_job_status(database_path)
    except Exception:
        return index_job_status(database_path)


_ASSET_ACTIVATION_REFRESH_LOCK = threading.RLock()
_ASSET_ACTIVATION_REFRESHED: set[tuple[str, str, str]] = set()


def _ensure_asset_activation_content_refresh(
    *, force_activation: bool = False, depth: str = "headers"
) -> dict[str, Any] | None:
    """Start one bounded background catalog refresh per Host activation.

    Asset-root configuration requests a names-only generation so selecting a
    broad unpacked tree never implicitly hashes/parses the whole game.  Deeper
    header/content generations remain available through the explicit index
    route and normal on-demand hydration.
    """

    selected_depth = str(depth or "").strip().casefold()
    if selected_depth not in {"names", "headers", "full"}:
        raise ValueError("asset activation refresh depth is invalid")

    unused_service, status, asset_root, database_path = (
        _active_asset_catalog_context(
            require_catalog=False,
            create_dictionary=True,
        )
    )
    catalog_revision = "unprepared"
    if database_path.is_file() and not database_path.is_symlink():
        try:
            catalog_status = AssetCatalogService(database_path).status()
            catalog_revision = str(
                catalog_status.get("catalogSha256") or "unidentified"
            )
        except Exception as error:
            # The synchronous prepare_root performed by _asset_index_job will
            # either retire this incompatible database safely or raise the
            # concrete lock/corruption error to the MCP caller. Do not hide it.
            catalog_revision = "unreadable:%s" % type(error).__name__
    key = (
        _capture_path_key(str(database_path)),
        _capture_path_key(str(asset_root)),
        catalog_revision,
    )
    job = _asset_index_status(database_path)
    with _ASSET_ACTIVATION_REFRESH_LOCK:
        # A completed process-local job can predate this project/RDC
        # activation by hours. An activation epoch must start a fresh
        # owner scan instead of trusting that cached result.
        if force_activation:
            _ASSET_ACTIVATION_REFRESHED.discard(key)
        elif isinstance(job, Mapping) and job.get("status") == "failed":
            _ASSET_ACTIVATION_REFRESHED.discard(key)
        if key in _ASSET_ACTIVATION_REFRESHED:
            return dict(job) if isinstance(job, Mapping) else None
        _ASSET_ACTIVATION_REFRESHED.add(key)
    try:
        return _asset_index_job(
            database_path,
            asset_root,
            str(status.get("scope", {}).get("buildId", "") or ""),
            depth=selected_depth,
        )
    except Exception:
        with _ASSET_ACTIVATION_REFRESH_LOCK:
            _ASSET_ACTIVATION_REFRESHED.discard(key)
        raise


def _ensure_shader_asset_catalog() -> tuple[Any, dict[str, Any], Path, Path, dict[str, Any]]:
    """Make sure the asset root has a *name* index; never a whole-tree parse.

    First use walks the tree once (names only: path tokens, no hashing or
    parsing -- about a minute for a few hundred thousand files). That is
    enough to search by the words the draw gives us; the few files that look
    relevant are then parsed on demand (``_targeted_asset_hydration``), so the
    index grows around what was actually asked, not around the whole game.
    A checkpointed catalog of any depth is returned as usable evidence with
    ``partial: true`` while its scan continues in the background.
    """

    service, status, asset_root, database_path = _active_asset_catalog_context(
        require_catalog=False, create_dictionary=True)
    receipt: dict[str, Any] = {"action": "reused", "depth": None, "seconds": 0.0}
    needs_scan = database_path.is_symlink() or not database_path.is_file()
    partial = False
    if not needs_scan:
        try:
            current = AssetCatalogService(database_path).status()
            if current.get("tokenIndex") not in {"fts5", "plain"} or current.get("engine") in (None, ""):
                needs_scan = True
                receipt["reason"] = "catalog predates retrieval tokens/engine parsing"
            elif current.get("complete") is False:
                partial = True
                receipt["reason"] = "catalog is a checkpoint of an unfinished scan"
                receipt["checkpoint"] = dict(current.get("progress") or {})
                receipt["assetCount"] = current.get("assetCount")
        except Exception as error:
            needs_scan = True
            receipt["reason"] = "catalog unreadable: %s" % str(error)[:200]
    if needs_scan or partial:
        build_id = str(status.get("scope", {}).get("buildId", "") or "")
        # A missing catalog gets the names walk; an unfinished one is joined as
        # it is (whatever depth was asked for) and used while it runs.
        job = (_asset_index_job(database_path, asset_root, build_id, depth="names")
               if needs_scan else _asset_index_status(database_path) or {"status": "done"})
        budget = ASSET_INDEX_FOREGROUND_BUDGET_SECONDS if needs_scan else ASSET_INDEX_PARTIAL_FOREGROUND_BUDGET_SECONDS
        started = time.monotonic()
        deadline = started + budget
        while job.get("status") == "running" and time.monotonic() < deadline:
            time.sleep(1.0)
            job = _asset_index_status(database_path) or job
        elapsed = round(float(job.get("elapsedSeconds") or (time.monotonic() - started)), 1)
        if job.get("status") == "running":
            indexing = {
                "action": "indexing-in-background", "status": "running",
                "depth": str(job.get("depth") or ("names" if needs_scan else "headers")),
                "owner": job.get("owner"), "elapsedSeconds": elapsed,
                "progress": dict(job.get("progress") or {}), "retryAfterSeconds": 30,
            }
            if job.get("fallbackReason"):
                indexing["fallbackReason"] = job["fallbackReason"]
            if not partial:
                raise _AssetCatalogNotReady(indexing)
            receipt.update({"action": "partial-catalog-while-indexing", "partial": True, "indexing": indexing})
            return service, status, asset_root, database_path, receipt
        if job.get("status") == "failed":
            if partial:
                receipt.update({"action": "partial-catalog-after-failed-scan", "partial": True,
                                "indexing": {"status": "failed", "error": job.get("error")}})
                return service, status, asset_root, database_path, receipt
            raise RuntimeError("on-demand asset indexing failed: %s" % job.get("error"))
        result = job.get("result") or {}
        receipt.update({
            "action": "indexed-on-demand", "depth": str(job.get("depth") or "names"), "seconds": elapsed,
            "owner": job.get("owner"),
            "assetCount": result.get("assetCount"), "deferredCount": result.get("deferredCount"),
            "engine": (result.get("engine") or {}).get("engine"),
        })
    return service, status, asset_root, database_path, receipt


# One call never holds the Host longer than this; the Agent calls again to keep waiting.
ASSET_INDEX_WAIT_SLICE_SECONDS = 60.0
ASSET_RESOLUTION_WORKSPACE_FILENAME = "asset-resolution.json"

# These seals distinguish results emitted by this Host process from JSON/SQLite
# that an Agent can write into the project.  Persisted rows from an earlier Host
# remain useful retrieval hints, but must be re-read before they authorize
# semantic names in a new process.
_ASSET_PROVENANCE_HMAC_KEY = secrets.token_bytes(32)
_ASSET_PROVENANCE_LEDGER_LOCK = threading.RLock()
_ASSET_CONTENT_RECEIPT_TASKS: dict[str, tuple[str, str]] = {}
_ASSET_NO_MATCH_READER_TASKS: dict[tuple[str, str], set[str]] = {}


def _asset_provenance_task_id() -> str:
    try:
        store = current_task_report_store()
        if getattr(store, "enabled", False):
            return str(getattr(store, "task_id", "") or "")[:256]
    except Exception:
        pass
    return ""


def _asset_provenance_hmac(label: str, value: Mapping[str, Any]) -> str:
    material = json.dumps(
        {"label": label, "value": dict(value)},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hmac.new(
        _ASSET_PROVENANCE_HMAC_KEY, material, hashlib.sha256
    ).hexdigest()


def _seal_member_rule_proof(rule: Mapping[str, Any]) -> str:
    """Sign one family/ABI/offset semantic rule in the Host process."""

    unsigned = dict(rule)
    unsigned.pop("hostProofHmacSha256", None)
    return _asset_provenance_hmac("shader-member-rule/v2", unsigned)


def _member_rule_proof_is_current(
    rule: Mapping[str, Any], family_authorities: Mapping[str, Mapping[str, Any]]
) -> bool:
    unsigned = dict(rule)
    supplied = str(unsigned.pop("hostProofHmacSha256", "") or "").lower()
    family = str(unsigned.get("familyKey") or "")
    authority = family_authorities.get(family)
    if not isinstance(authority, Mapping):
        return False
    return bool(
        re.fullmatch(r"[0-9a-f]{64}", supplied)
        and hmac.compare_digest(
            supplied, _asset_provenance_hmac("shader-member-rule/v2", unsigned)
        )
        and str(unsigned.get("assetVersionSha256") or "").lower()
        == str(authority.get("assetVersionSha256") or "").lower()
        and str(unsigned.get("assetResolutionHmacSha256") or "").lower()
        == str(authority.get("assetResolutionHmacSha256") or "").lower()
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(authority.get("assetResolutionHmacSha256") or "").lower(),
        )
    )


def _asset_content_provenance_material(proof: Mapping[str, Any]) -> dict[str, Any]:
    binding = proof.get("assetBinding")
    binding = binding if isinstance(binding, Mapping) else {}
    stable_binding = _asset_catalog_authority_binding(binding)
    for field in ("assetContentSha256", "assetEvidenceSha256"):
        stable_binding[field] = str(binding.get(field) or "").lower()
    stable_binding["evidenceAssets"] = [
        {
            "assetId": str(item.get("assetId") or ""),
            "relativePath": str(item.get("relativePath") or ""),
            "contentSha256": str(item.get("contentSha256") or "").lower(),
        }
        for item in (binding.get("evidenceAssets") or [])
        if isinstance(item, Mapping)
    ]
    return {
        "taskId": str(proof.get("taskId") or "")[:256],
        "assetId": str(proof.get("assetId") or ""),
        "relativePath": str(proof.get("relativePath") or ""),
        "tool": str(proof.get("tool") or ""),
        "receiptSha256": str(proof.get("receiptSha256") or "").lower(),
        "assetBinding": stable_binding,
    }


def _seal_asset_content_proof(proof: Mapping[str, Any]) -> dict[str, Any]:
    sealed = dict(proof)
    sealed["taskId"] = _asset_provenance_task_id()
    sealed["hostReaderProofHmacSha256"] = _asset_provenance_hmac(
        "asset-content-reader/v1", _asset_content_provenance_material(sealed)
    )
    with _ASSET_PROVENANCE_LEDGER_LOCK:
        binding = sealed.get("assetBinding")
        binding = binding if isinstance(binding, Mapping) else {}
        _ASSET_CONTENT_RECEIPT_TASKS[
            sealed["hostReaderProofHmacSha256"]
        ] = (
            sealed["taskId"], str(binding.get("assetVersionSha256") or "")
        )
        if len(_ASSET_CONTENT_RECEIPT_TASKS) > 4096:
            for key in list(_ASSET_CONTENT_RECEIPT_TASKS)[:1024]:
                _ASSET_CONTENT_RECEIPT_TASKS.pop(key, None)
    return sealed


def _asset_content_proof_is_host_sealed(proof: Mapping[str, Any]) -> bool:
    unsigned = dict(proof)
    supplied = str(unsigned.pop("hostReaderProofHmacSha256", "") or "").lower()
    valid = bool(
        re.fullmatch(r"[0-9a-f]{64}", supplied)
        and hmac.compare_digest(
            supplied,
            _asset_provenance_hmac(
                "asset-content-reader/v1",
                _asset_content_provenance_material(unsigned),
            ),
        )
    )
    if not valid:
        return False
    with _ASSET_PROVENANCE_LEDGER_LOCK:
        recorded = _ASSET_CONTENT_RECEIPT_TASKS.get(supplied)
    binding = proof.get("assetBinding")
    binding = binding if isinstance(binding, Mapping) else {}
    proof_task = str(proof.get("taskId") or "")
    return proof_task == _asset_provenance_task_id() and recorded == (
        proof_task,
        str(binding.get("assetVersionSha256") or ""),
    )


def _seal_asset_reader_attempt(
    attempt: Mapping[str, Any], asset_binding: Mapping[str, Any]
) -> dict[str, Any]:
    sealed = dict(attempt)
    task_id = _asset_provenance_task_id()
    stable = _asset_catalog_authority_binding(asset_binding)
    material = {"taskId": task_id, "attempt": sealed, "assetBinding": stable}
    receipt = _asset_provenance_hmac("asset-reader-attempt/v1", material)
    sealed["taskId"] = task_id
    sealed["hostReaderAttemptHmacSha256"] = receipt
    version = str(stable.get("assetVersionSha256") or "")
    reader_id = str(sealed.get("readerId") or "")[:96]
    coverage = sealed.get("coverage")
    coverage = coverage if isinstance(coverage, Mapping) else {}
    qualifies = bool(
        sealed.get("supported") is True
        and sealed.get("started") is True
        and (
            (
                sealed.get("outcome") == "no-match"
                and coverage.get("completeCatalog") is True
                and coverage.get("narrowed") is False
            )
            or (
                sealed.get("outcome") == "unsupported-target"
                and str(sealed.get("targetAssetId") or "")
            )
        )
    )
    if qualifies and version and reader_id:
        with _ASSET_PROVENANCE_LEDGER_LOCK:
            key = (task_id, version)
            _ASSET_NO_MATCH_READER_TASKS.setdefault(key, set()).add(reader_id)
            if len(_ASSET_NO_MATCH_READER_TASKS) > 1024:
                for old in list(_ASSET_NO_MATCH_READER_TASKS)[:256]:
                    _ASSET_NO_MATCH_READER_TASKS.pop(old, None)
    return sealed


def _require_host_no_match_grounding(asset_binding: Mapping[str, Any]) -> None:
    task_id = _asset_provenance_task_id()
    version = str(asset_binding.get("assetVersionSha256") or "")
    with _ASSET_PROVENANCE_LEDGER_LOCK:
        readers = set(_ASSET_NO_MATCH_READER_TASKS.get((task_id, version), set()))
    # Reading one arbitrary file proves only that file exists.  It says nothing
    # about whether this Shader has a supported material match elsewhere in the
    # root.  A final negative therefore requires two independent Host-owned
    # reader outcomes that each covered the complete, non-narrowed catalog (or
    # the equivalent exact unsupported-target closure recorded by the Host).
    if len(readers) < 2:
        raise RuntimeError(
            "final no-supported-match requires this Host task's two distinct "
            "complete non-narrowed reader outcomes; an unrelated asset read is not coverage"
        )


def _resolution_provenance_material(
    row: Mapping[str, Any], evidence: Mapping[str, Any]
) -> dict[str, Any]:
    unsigned_evidence = dict(evidence)
    unsigned_evidence.pop("hostResolutionHmacSha256", None)
    return {
        "gameKey": str(row.get("gameKey") or ""),
        "shaderRawSha256": str(row.get("shaderRawSha256") or "").lower(),
        "structuralKey": str(row.get("structuralKey") or ""),
        "stage": str(row.get("stage") or ""),
        "entryPoint": str(row.get("entryPoint") or ""),
        "assetRelativePath": str(row.get("assetRelativePath") or ""),
        "assetContentSha256": str(row.get("assetContentSha256") or "").lower(),
        "assetClass": str(row.get("assetClass") or ""),
        "catalogSha256": str(row.get("catalogSha256") or "").lower(),
        "negative": row.get("negative") is True,
        "confidence": float(row.get("confidence") or 0.0),
        "decidedBy": str(row.get("decidedBy") or ""),
        "rationale": str(row.get("rationale") or ""),
        "evidence": unsigned_evidence,
    }


def _seal_resolution_evidence(
    row: Mapping[str, Any], evidence: Mapping[str, Any]
) -> dict[str, Any]:
    sealed = dict(evidence)
    material = _resolution_provenance_material(row, sealed)
    sealed["hostResolutionHmacSha256"] = _asset_provenance_hmac(
        "shader-asset-resolution/v1", material
    )
    return sealed


def _resolution_row_is_host_sealed(row: Mapping[str, Any]) -> bool:
    evidence = row.get("evidence")
    if not isinstance(evidence, Mapping):
        return False
    supplied = str(evidence.get("hostResolutionHmacSha256") or "").lower()
    material = _resolution_provenance_material(row, evidence)
    return bool(
        re.fullmatch(r"[0-9a-f]{64}", supplied)
        and hmac.compare_digest(
            supplied,
            _asset_provenance_hmac("shader-asset-resolution/v1", material),
        )
    )


def _asset_catalog_version_binding(
    catalog: AssetCatalogService, asset_root: str | Path
) -> dict[str, Any]:
    root = Path(asset_root).resolve()
    try:
        unused_service, project_status, expected_root, database_path = (
            _active_asset_catalog_context(require_catalog=False, create_dictionary=True)
        )
        del unused_service
        if expected_root == root and Path(catalog.database_path).resolve() == database_path:
            reconcile = _reconcile_stale_asset_catalog(
                project_status, expected_root, database_path
            )
            if reconcile is not None:
                raise _AssetCatalogNotReady(reconcile)
    except _AssetCatalogNotReady:
        raise
    except Exception:
        pass
    status = catalog.status()
    recorded_root = Path(str(status.get("rootPath") or "")).resolve()
    if root != recorded_root:
        raise RuntimeError(
            "active asset catalog belongs to another configured root; "
            "call get_active_unpacked_asset_index_status to rebuild it"
        )
    catalog_sha = str(status.get("catalogSha256") or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{64}", catalog_sha) is None:
        raise RuntimeError("active asset catalog omitted its content revision")
    refresh_job = _asset_index_status(Path(catalog.database_path))
    if isinstance(refresh_job, Mapping) and refresh_job.get("status") == "running":
        raise RuntimeError(
            "asset content generation refresh is still running; its prior Merkle "
            "generation cannot authorize a new resolution"
        )
    try:
        manifest = catalog.content_manifest_status(root)
    except Exception:
        # Compatibility for catalogs made before content generations existed.
        # This full refresh is paid once. Normal index jobs publish the same
        # generation in their background owner before callers reach this path.
        manifest = catalog.refresh_content_manifest(root)
    version = {
        "assetRoot": str(root),
        "catalogSha256": catalog_sha,
        **manifest,
    }
    # A successful owner refresh always advances its diagnostic scan
    # generation/document receipt.  Those volatile fields cannot make a
    # previously verified project stale when every path and content byte is
    # unchanged.  The Merkle content root commits path + size + SHA-256 for
    # every file, while catalogSha256 commits the parsed catalog revision.
    authority = {
        "assetRoot": version["assetRoot"],
        "catalogSha256": version["catalogSha256"],
        "assetRootManifestSha256": version["assetRootManifestSha256"],
        "assetRootFileCount": version["assetRootFileCount"],
        "assetRootByteSize": version["assetRootByteSize"],
    }
    version["assetVersionSha256"] = _canonical_json_sha256(
        authority, "asset catalog version binding"
    )
    return version


def _asset_catalog_authority_binding(binding: Mapping[str, Any]) -> dict[str, Any]:
    """Return only stable fields that authorize one asset-root revision."""

    return {
        "assetRoot": str(binding.get("assetRoot") or ""),
        "catalogSha256": str(binding.get("catalogSha256") or "").lower(),
        "assetRootManifestSha256": str(
            binding.get("assetRootManifestSha256") or ""
        ).lower(),
        "assetRootFileCount": int(binding.get("assetRootFileCount") or 0),
        "assetRootByteSize": int(binding.get("assetRootByteSize") or 0),
        "assetVersionSha256": str(
            binding.get("assetVersionSha256") or ""
        ).lower(),
    }


def _asset_resolution_evidence_binding(
    catalog: AssetCatalogService,
    asset_root: str | Path,
    selected_asset: Mapping[str, Any],
    *,
    version_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Freeze selected material plus content-bearing parent/texture/export assets."""

    binding = (
        dict(version_binding)
        if isinstance(version_binding, Mapping)
        else _asset_catalog_version_binding(catalog, asset_root)
    )
    catalog_sha = binding["catalogSha256"]
    selected_id = str(selected_asset.get("assetId") or "").strip()
    if not selected_id:
        raise RuntimeError("selected asset omitted its catalog identity")
    queued = [selected_id]
    seen: set[str] = set()
    assets: dict[str, Mapping[str, Any]] = {}
    while queued:
        asset_id = queued.pop(0)
        if asset_id in seen:
            continue
        if len(seen) >= 64:
            raise RuntimeError(
                "selected asset dependency set exceeds the fixed evidence bound"
            )
        seen.add(asset_id)
        found = catalog.query(
            asset_ids=[asset_id], limit=1, include_relationships=True
        ).get("assets", [])
        if not found:
            raise RuntimeError("selected asset dependency disappeared from the catalog")
        asset = found[0]
        assets[asset_id] = asset
        if asset.get("relationshipsTruncated") is True:
            raise RuntimeError(
                "selected asset dependency relations exceed the fixed evidence bound"
            )
        for relation in asset.get("relationships") or []:
            if not isinstance(relation, Mapping):
                continue
            target_id = str(relation.get("targetAssetId") or "").strip()
            if target_id and target_id not in seen and target_id not in queued:
                queued.append(target_id)

    # Cooked material exports can be a sibling rather than an explicit edge.
    selected_relative = PurePosixPath(str(selected_asset.get("relativePath") or ""))
    if selected_relative.suffix.lower() in {".uasset", ".umap"}:
        sibling = selected_relative.with_suffix(".uexp").as_posix()
        found = catalog.query(
            relative_paths=[sibling], limit=1, include_relationships=False
        ).get("assets", [])
        if found:
            sibling_id = str(found[0].get("assetId") or "")
            if sibling_id and sibling_id not in assets:
                assets[sibling_id] = found[0]

    evidence_assets: list[dict[str, str]] = []
    selected_content = ""
    for asset_id, asset in sorted(
        assets.items(), key=lambda item: str(item[1].get("relativePath") or "")
    ):
        content_sha = str(asset.get("contentSha256") or "").strip().lower()
        if not content_sha:
            # Names-only/deferred rows were not content-bearing evidence and do
            # not authorize names. The catalog revision still binds their index row.
            continue
        resolved = catalog.resolve(
            asset_root,
            asset_id=asset_id,
            expected_catalog_sha256=catalog_sha,
        )
        entry = {
            "assetId": asset_id,
            "relativePath": str(resolved["relativePath"]),
            "contentSha256": str(resolved["contentSha256"]),
        }
        evidence_assets.append(entry)
        if asset_id == selected_id:
            selected_content = entry["contentSha256"]
    if not selected_content:
        raise RuntimeError(
            "selected asset was not content-hashed and cannot authorize Shader naming"
        )
    aggregate = {
        "assetRoot": binding["assetRoot"],
        "catalogSha256": catalog_sha,
        "evidenceAssets": evidence_assets,
    }
    return {
        **binding,
        "assetContentSha256": selected_content,
        "evidenceAssets": evidence_assets,
        "assetEvidenceSha256": _canonical_json_sha256(
            aggregate, "asset resolution evidence binding"
        ),
    }


def _asset_no_match_evidence_binding(
    catalog: AssetCatalogService, asset_root: str | Path
) -> dict[str, Any]:
    binding = _asset_catalog_version_binding(catalog, asset_root)
    aggregate = {
        **_asset_catalog_authority_binding(binding),
        "outcome": "no-supported-match",
        "evidenceAssets": [],
    }
    return {
        **binding,
        "evidenceAssets": [],
        "assetEvidenceSha256": _canonical_json_sha256(
            aggregate, "asset no-match evidence binding"
        ),
    }


def _asset_authorization_blocked(
    *,
    code: str,
    reason: str,
    relative_path: str = "",
    detail: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Report the exact proof failure without prescribing the Agent's next step."""

    payload: dict[str, Any] = {
        "schema": "replaylab-asset-authorization-status/v1",
        "schemaVersion": 1,
        "authorized": False,
        "code": str(code)[:96],
        "reason": str(reason)[:800],
        "relativePath": str(relative_path or ""),
    }
    if isinstance(detail, Mapping) and detail:
        payload["detail"] = dict(list(detail.items())[:32])
    return payload


def _asset_content_proof_attempt(
    relative_path: str,
    tool: str,
    *,
    receipt: Mapping[str, Any] | None = None,
    version_binding: Mapping[str, Any] | None = None,
    hydrate_if_deferred: bool = True,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Try to seal one content-reader proof; never silently return empty.

    Describe can parse a file directly from disk even when the names-only
    catalog never indexed that path, or left it ``deferred`` without
    ``contentSha256``. Authorization needs a content hash, so this path will
    create/hash the exact file (and a cooked Unreal ``.uexp`` sibling when
    present) before sealing. Failures return a blocked status the Agent can
    act on immediately instead of retrying describe/submit forever.
    """

    wanted = PurePosixPath(str(relative_path or "").replace("\\", "/")).as_posix().lstrip("/")
    if not wanted:
        blocked = _asset_authorization_blocked(
            code="relative-path-missing",
            reason="relative_path is empty; content proof cannot be sealed",
        )
        return None, blocked
    try:
        unused_service, unused_status, asset_root, database_path = (
            _active_asset_catalog_context(require_catalog=True)
        )
    except Exception as error:
        blocked = _asset_authorization_blocked(
            code="catalog-unavailable",
            reason="active asset catalog is unavailable: %s" % str(error)[:400],
            relative_path=wanted,
        )
        return None, blocked

    catalog = AssetCatalogService(database_path)
    hydrate_receipt: dict[str, Any] | None = None
    root_path = Path(asset_root)

    def _exact_rows() -> list[dict[str, Any]]:
        found = catalog.query(
            relative_paths=[wanted], limit=2, include_relationships=True
        ).get("assets", [])
        return [
            item for item in found
            if isinstance(item, Mapping)
            and str(item.get("relativePath") or "") == wanted
        ]

    def _disk_file(relative: str) -> Path | None:
        cursor = root_path
        for part in PurePosixPath(relative).parts:
            cursor = cursor / part
            if cursor.is_symlink():
                return None
        if not cursor.is_file() or cursor.is_symlink():
            return None
        try:
            resolved = cursor.resolve(strict=True)
        except OSError:
            return None
        if not is_within(root_path.resolve(), resolved):
            return None
        return resolved

    def _hydrate_paths(paths: list[str]) -> dict[str, Any]:
        unique: list[str] = []
        for path in paths:
            text = PurePosixPath(str(path or "").replace("\\", "/")).as_posix().lstrip("/")
            if text and text not in unique:
                unique.append(text)
        return catalog.hydrate(asset_root, unique[:32])

    exact = _exact_rows()
    if len(exact) > 1:
        blocked = _asset_authorization_blocked(
            code="catalog-path-not-unique",
            reason="relative_path matched more than one catalog row",
            relative_path=wanted,
            detail={"matchCount": len(exact)},
        )
        return None, blocked

    selected: Mapping[str, Any] | None = exact[0] if exact else None
    content_sha = (
        str(selected.get("contentSha256") or "").strip().lower() if selected else ""
    )
    hash_status = str(selected.get("hashStatus") or "") if selected else ""
    disk = _disk_file(wanted)
    needs_hydrate = False
    if selected is None:
        if disk is None:
            blocked = _asset_authorization_blocked(
                code="catalog-path-missing",
                reason=(
                    "relative_path is absent from the active catalog and not a readable "
                    "file under the asset root"
                ),
                relative_path=wanted,
                detail={"matchCount": 0},
            )
            return None, blocked
        # Describe already proved the file exists; create/hash the catalog row now.
        needs_hydrate = bool(hydrate_if_deferred)
    elif (not content_sha or hash_status in {"deferred", "skipped-size"}) and hydrate_if_deferred:
        needs_hydrate = True

    if needs_hydrate:
        hydrate_paths = [wanted]
        if PurePosixPath(wanted).suffix.lower() in {".uasset", ".umap"}:
            sibling = PurePosixPath(wanted).with_suffix(".uexp").as_posix()
            if _disk_file(sibling) is not None:
                sibling_rows = catalog.query(
                    relative_paths=[sibling], limit=1, include_relationships=False
                ).get("assets", [])
                sibling_sha = (
                    str(sibling_rows[0].get("contentSha256") or "").strip()
                    if sibling_rows else ""
                )
                if not sibling_sha:
                    hydrate_paths.append(sibling)
        try:
            hydrate_receipt = _hydrate_paths(hydrate_paths)
            exact = _exact_rows()
            if len(exact) != 1:
                blocked = _asset_authorization_blocked(
                    code="hydrate-lost-catalog-row",
                    reason=(
                        "on-demand hydrate finished but the catalog still has no unique row "
                        "for this relative_path"
                    ),
                    relative_path=wanted,
                    detail={
                        "hydrate": hydrate_receipt,
                        "matchCount": len(exact),
                        "diskPresent": disk is not None,
                    },
                )
                return None, blocked
            selected = exact[0]
            content_sha = str(selected.get("contentSha256") or "").strip().lower()
            hash_status = str(selected.get("hashStatus") or "")
        except Exception as error:
            blocked = _asset_authorization_blocked(
                code="hydrate-failed",
                reason="on-demand content hash failed: %s" % str(error)[:400],
                relative_path=wanted,
                detail={"hydratePaths": hydrate_paths},
            )
            return None, blocked

    if selected is None or not content_sha:
        blocked = _asset_authorization_blocked(
            code="content-hash-missing",
            reason=(
                "selected asset still has no contentSha256 after hydrate "
                "(hashStatus=%s); naming authorization cannot be sealed"
                % (hash_status or "unknown")
            ),
            relative_path=wanted,
            detail={
                "assetId": str((selected or {}).get("assetId") or ""),
                "hashStatus": hash_status,
                "size": (selected or {}).get("size"),
                "hydrate": hydrate_receipt,
            },
        )
        return None, blocked

    # Parent/texture edges used for naming evidence often remain deferred after a
    # names-only scan. Hash a bounded set of them before sealing the binding.
    if hydrate_if_deferred:
        deferred_deps: list[str] = []
        for relation in selected.get("relationships") or []:
            if not isinstance(relation, Mapping):
                continue
            target_id = str(relation.get("targetAssetId") or "").strip()
            if not target_id:
                continue
            found = catalog.query(
                asset_ids=[target_id], limit=1, include_relationships=False
            ).get("assets", [])
            if not found:
                continue
            dep = found[0]
            if str(dep.get("contentSha256") or "").strip():
                continue
            dep_path = str(dep.get("relativePath") or "")
            if dep_path and _disk_file(dep_path) is not None:
                deferred_deps.append(dep_path)
            if len(deferred_deps) >= 16:
                break
        if PurePosixPath(wanted).suffix.lower() in {".uasset", ".umap"}:
            sibling = PurePosixPath(wanted).with_suffix(".uexp").as_posix()
            if sibling not in deferred_deps and _disk_file(sibling) is not None:
                sibling_rows = catalog.query(
                    relative_paths=[sibling], limit=1, include_relationships=False
                ).get("assets", [])
                if sibling_rows and not str(sibling_rows[0].get("contentSha256") or "").strip():
                    deferred_deps.append(sibling)
        if deferred_deps:
            try:
                dep_receipt = _hydrate_paths(deferred_deps)
                if isinstance(hydrate_receipt, Mapping):
                    merged = dict(hydrate_receipt)
                    merged["dependencyHydrated"] = dep_receipt.get("hydrated") or []
                    hydrate_receipt = merged
                else:
                    hydrate_receipt = dep_receipt
                exact = _exact_rows()
                if len(exact) == 1:
                    selected = exact[0]
                    content_sha = str(selected.get("contentSha256") or "").strip().lower()
            except Exception as error:
                blocked = _asset_authorization_blocked(
                    code="dependency-hydrate-failed",
                    reason=(
                        "selected material hashed, but parent/texture dependency hashing "
                        "failed: %s" % str(error)[:400]
                    ),
                    relative_path=wanted,
                    detail={"dependencyPaths": deferred_deps[:16]},
                )
                return None, blocked

    try:
        binding = _asset_resolution_evidence_binding(
            catalog,
            asset_root,
            selected,
            version_binding=version_binding,
        )
    except Exception as error:
        blocked = _asset_authorization_blocked(
            code="evidence-binding-failed",
            reason=str(error)[:400],
            relative_path=wanted,
            detail={
                "assetId": str(selected.get("assetId") or ""),
                "hydrate": hydrate_receipt,
            },
        )
        return None, blocked

    proof_payload = {
        "assetId": str(selected["assetId"]),
        "relativePath": wanted,
        "tool": str(tool),
        "assetBinding": binding,
        "readerReceipt": dict(receipt or {}),
    }
    proof = _seal_asset_content_proof({
        "assetId": proof_payload["assetId"],
        "relativePath": wanted,
        "tool": str(tool),
        "receiptSha256": _canonical_json_sha256(
            proof_payload, "asset content-reader receipt"
        ),
        "assetBinding": binding,
    })
    status = {
        "schema": "replaylab-asset-authorization-status/v1",
        "schemaVersion": 1,
        "authorized": True,
        "code": "content-proof-sealed",
        "reason": "Host sealed a content-reader proof for this exact catalog path",
        "relativePath": wanted,
        "hydrate": hydrate_receipt,
    }
    return proof, status


def _asset_content_proof_for_path(
    relative_path: str,
    tool: str,
    *,
    receipt: Mapping[str, Any] | None = None,
    version_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Issue one Host proof for content actually read from an indexed asset.

    Prefer ``_asset_content_proof_attempt`` when the caller must surface a
    blocked authorization status. This wrapper keeps older call sites working.
    """

    proof, unused_status = _asset_content_proof_attempt(
        relative_path,
        tool,
        receipt=receipt,
        version_binding=version_binding,
        hydrate_if_deferred=True,
    )
    return proof


def _asset_evidence_binding_is_current(binding: Mapping[str, Any]) -> tuple[bool, str]:
    """Freshness is content-hash only: matched resource bytes must still exist.

    Paths, catalog revision, asset-root string form, and assetId are not
    authorization criteria. If any remembered content hash is missing or the
    on-disk bytes changed, the binding is stale and the Agent must rematch.
    """

    try:
        unused_service, unused_status, root, database_path = (
            _active_asset_catalog_context(require_catalog=True)
        )
        catalog = AssetCatalogService(database_path)
        current_catalog_sha = str(catalog.status().get("catalogSha256") or "").lower()
        if not re.fullmatch(r"[0-9a-f]{64}", current_catalog_sha or ""):
            return False, "active asset catalog has no content revision; rematch"
        evidence_assets = binding.get("evidenceAssets")
        if not isinstance(evidence_assets, list):
            return False, (
                "asset evidence dependency list is missing; rematch unpacked assets"
            )
        if not evidence_assets:
            # A final no-match is a conclusion about the complete configured
            # root, not about zero files. Bind it to the owner's stable content
            # Merkle so additions, removals and byte changes force retrieval to
            # run again. Diagnostic scan generations/timestamps are excluded by
            # _asset_catalog_authority_binding and therefore do not cause noise.
            if Path(str(binding.get("assetRoot") or "")).resolve() != root:
                return False, (
                    "asset root changed after a no-supported-match receipt; rematch"
                )
            expected_authority = _asset_catalog_authority_binding(binding)
            supplied_version = expected_authority.get("assetVersionSha256", "")
            expected_material = {
                key: expected_authority[key]
                for key in (
                    "assetRoot",
                    "catalogSha256",
                    "assetRootManifestSha256",
                    "assetRootFileCount",
                    "assetRootByteSize",
                )
            }
            if (
                re.fullmatch(r"[0-9a-f]{64}", supplied_version or "") is None
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    expected_authority.get("catalogSha256", "") or "",
                )
                is None
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    expected_authority.get("assetRootManifestSha256", "") or "",
                )
                is None
                or supplied_version
                != _canonical_json_sha256(
                    expected_material, "asset catalog version binding"
                )
            ):
                return False, (
                    "no-supported-match receipt omitted its exact asset-root "
                    "content revision; rematch"
                )
            current_authority = _asset_catalog_authority_binding(
                _asset_catalog_version_binding(catalog, root)
            )
            if current_authority != expected_authority:
                return False, (
                    "asset-root content revision changed after the no-supported-match "
                    "receipt; rematch unpacked assets"
                )
            return True, ""
        for item in evidence_assets:
            if not isinstance(item, Mapping):
                return False, "asset evidence dependency is invalid; rematch"
            digest = str(item.get("contentSha256") or "").strip().lower()
            if not re.fullmatch(r"[0-9a-f]{64}", digest or ""):
                return False, (
                    "asset evidence omitted contentSha256; rematch unpacked assets"
                )
            found = catalog.query(
                sha256=digest, limit=2, include_relationships=False
            ).get("assets", [])
            if not found:
                return False, (
                    "remembered asset contentSha256 %s is absent from the catalog; "
                    "rematch unpacked assets" % digest[:12]
                )
            # Prefer exact digest match; path may have moved inside the root.
            matched = [
                row for row in found
                if str(row.get("contentSha256") or "").lower() == digest
            ]
            if not matched:
                return False, (
                    "remembered asset contentSha256 %s no longer matches catalog "
                    "bytes; rematch unpacked assets" % digest[:12]
                )
            row = matched[0]
            try:
                delivered = catalog.resolve(
                    root,
                    asset_id=str(row.get("assetId") or ""),
                    expected_catalog_sha256=current_catalog_sha,
                )
            except Exception as error:
                return False, (
                    "remembered asset content could not be rehashed (%s); "
                    "rematch unpacked assets" % str(error)[:200]
                )
            if str(delivered.get("contentSha256") or "").lower() != digest:
                return False, (
                    "resource file content changed for remembered hash %s; "
                    "rematch unpacked assets" % digest[:12]
                )
        return True, ""
    except Exception as error:
        return False, (
            "asset evidence could not be verified (%s); rematch unpacked assets"
            % str(error)[:300]
        )


def _asset_index_state() -> dict[str, Any]:
    """One answer for 'can asset matching run now?', without scanning inline.

    States: ``ready`` (complete catalog), ``indexing`` (a scan is running or a
    checkpoint exists), ``failed``, ``unconfigured`` (no asset root configured).
    """

    try:
        unused_service, status, asset_root, database_path = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=False)
    except Exception as error:
        text = str(error)
        configured = "no unpacked asset root" not in text.lower()
        return {
            "state": "failed" if configured else "unconfigured",
            "reason": text[:400],
            "assetRootConfigured": configured,
        }
    build_id = str(status.get("scope", {}).get("buildId", "") or "")
    catalog_status: dict[str, Any] = {}
    complete = False
    if database_path.is_file() and not database_path.is_symlink():
        try:
            catalog_status = AssetCatalogService(database_path).status()
            complete = catalog_status.get("complete") is not False
        except Exception:
            catalog_status = {}
    job = _asset_index_status(database_path) or {}
    job_status = str(job.get("status") or "")
    running = job_status == "running"
    if complete and not running:
        return {
            "state": "ready",
            "assetCount": catalog_status.get("assetCount"),
            "engine": catalog_status.get("engine"),
            "databasePath": str(database_path),
            "assetRoot": str(asset_root),
            "catalogSha256": catalog_status.get("catalogSha256"),
        }
    if job_status == "failed" and not catalog_status:
        return {"state": "failed", "error": str(job.get("error") or "")[:400]}
    if not running:
        # A checkpoint with no scan behind it never finishes on its own: the previous
        # attempt died (publish conflict, crash, restart). Report that fact so
        # callers can distinguish a stalled scan from one that is still running.
        return {
            "state": "stalled",
            "jobStatus": job_status or "none",
            "error": str(job.get("error") or "")[:400],
            "progress": dict(job.get("progress") or {}),
            "partialAssetCount": catalog_status.get("assetCount"),
            "buildId": build_id,
        }
    return {
        "state": "indexing",
        "running": True,
        "owner": job.get("owner"),
        "progress": dict(job.get("progress") or {}),
        "elapsedSeconds": job.get("elapsedSeconds"),
        "partialAssetCount": catalog_status.get("assetCount"),
        "buildId": build_id,
    }


# Search primitives work on the configured asset root directly: no catalog, no scan,
# no waiting. Each call is bounded in time and results so the Host stays responsive,
# and returns a cursor so the Agent decides whether to keep looking.
UNPACKED_SEARCH_MAX_SECONDS = 8.0
UNPACKED_SEARCH_MAX_RESULTS = 200
UNPACKED_SEARCH_MAX_CONTENT_BYTES = 512 * 1024
UNPACKED_LIST_MAX_ENTRIES = 500
UNPACKED_RELATIONS_MAX_WALK_FILES = 4000


# A ResourceId is a 64-bit value; the ones RenderDoc hands out are around 1e18,
# which is past 2^53 and therefore has no exact IEEE-754 double. A client that
# parses tool arguments as JSON numbers (Cursor's ACP client does) turns
# 1000000000000000755 into 1000000000000000800 before the Host ever sees it, and
# an exact comparison then rejects the altered identity. Accept decimal strings
# losslessly and keep identity comparisons exact: neighbouring resources can
# share the same IEEE-754 double value.
_MAX_EXACT_DOUBLE_INT = 2 ** 53


def _coerce_resource_id(value: Any, name: str) -> int | None:
    """A ResourceId from a tool argument: int, or a string when precision matters."""

    if value is None:
        return None
    if isinstance(value, bool):
        raise ValueError("%s must be a positive ResourceId" % name)
    if isinstance(value, int):
        parsed = value
    elif isinstance(value, str):
        text = value.strip()
        if not text.isdigit() or len(text) > 24:
            raise ValueError("%s must be a positive ResourceId (digits only)" % name)
        parsed = int(text)
    elif isinstance(value, float):
        if not value.is_integer() or abs(value) >= _MAX_EXACT_DOUBLE_INT:
            raise ValueError("%s must be an exact ResourceId; pass it as a decimal string" % name)
        parsed = int(value)
    else:
        raise ValueError("%s must be a positive ResourceId" % name)
    if parsed <= 0:
        raise ValueError("%s must be a positive ResourceId" % name)
    return parsed


def _resource_id_matches(expected: int | None, actual: int) -> bool:
    """Whether an optional supplied ResourceId exactly identifies this resource."""

    return expected is None or expected == actual


def _resource_id_mismatch(name: str, expected: Any, actual: int) -> str:
    return ("%s does not match the Shader here (it is %s). Pass the id as a *string* "
            "when you repeat it -- a 19-digit ResourceId does not survive a JSON "
            "number, and %r is what arrived." % (name, actual, expected))


def _unpacked_asset_root() -> tuple[Path, dict[str, Any]]:
    service = _active_project_service()
    status = service.status()
    if status.get("assetRootConfigured") is not True or status.get("assetRootAvailable") is not True:
        raise RuntimeError("active project has no available unpacked asset root configured")
    root = Path(str(status.get("assetRoot", "") or "")).resolve()
    if not root.is_dir():
        raise RuntimeError("configured unpacked asset root is not a directory")
    return root, status


def _unpacked_relative(root: Path, candidate: Path) -> str:
    try:
        return candidate.resolve().relative_to(root).as_posix()
    except (OSError, ValueError):
        return candidate.name


def _unpacked_within(root: Path, relative_path: str) -> Path:
    text = str(relative_path or "").strip().replace("\\", "/")
    if text.startswith("/") or ":" in text or ".." in text.split("/"):
        raise ValueError("relative_path must stay inside the configured asset root")
    candidate = (root / text).resolve() if text else root
    if candidate != root and root not in candidate.parents:
        raise ValueError("relative_path must stay inside the configured asset root")
    return candidate


# Unpacked does not mean readable: a cooked UE tree is 200k ``.uasset`` files whose
# extension says "engine package" and nothing else. What an asset *is* comes from a
# reader that understands the container — the same parsers the asset catalog uses —
# and, for anything the built-ins do not know, from a reader the user registered.
_ASSET_READER_MAGIC: tuple[tuple[bytes, str, str], ...] = (
    (b"DDS ", "texture", "DDS surface"),
    (b"\x89PNG\r\n\x1a\n", "texture", "PNG image"),
    (b"\xff\xd8\xff", "texture", "JPEG image"),
    (b"v/1\x01", "texture", "OpenEXR image"),
    (b"#?RADIANCE", "texture", "Radiance HDR"),
    (b"Kaydara FBX Binary", "mesh", "FBX"),
    (b"glTF", "mesh", "glTF binary"),
    (b"RIFF", "audio", "RIFF container"),
    (b"OggS", "audio", "Ogg stream"),
    (b"UnityFS", "package", "Unity asset bundle"),
    (b"PK\x03\x04", "archive", "zip container"),
)
_UNREAL_CLASS_KINDS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("texture", ("Texture2D", "TextureCube", "Texture2DArray", "VirtualTexture2D",
                 "TextureRenderTarget2D", "LightMapTexture2D")),
    ("material", ("Material", "MaterialInstanceConstant", "MaterialInstanceDynamic",
                  "MaterialFunction", "MaterialParameterCollection", "PhysicalMaterial")),
    ("mesh", ("StaticMesh", "SkeletalMesh", "SkinnedAsset", "GeometryCollection")),
    ("animation", ("AnimSequence", "AnimMontage", "Skeleton", "BlendSpace", "AnimBlueprint")),
    ("particle", ("NiagaraSystem", "NiagaraEmitter", "ParticleSystem")),
    ("shader", ("MaterialShaderMap", "NiagaraScript")),
    ("level", ("World", "Level")),
    ("blueprint", ("Blueprint", "WidgetBlueprint")),
)


def _unreal_kind_for_class(class_name: str) -> str:
    text = str(class_name or "")
    for kind, classes in _UNREAL_CLASS_KINDS:
        if text in classes:
            return kind
    return "other"


_TOOL_CACHE: dict[str, Any] = {"stamp": None, "tools": ()}
_MATERIAL_PARENT_CHAIN_COMPOSITION = contextvars.ContextVar(
    "replaylab_material_parent_chain_composition", default=0
)


def _registered_tools() -> tuple[dict[str, Any], ...]:
    """Tools the user registered, re-read only when the file actually changes.

    Identifying a directory of assets asks this once per file; re-parsing the
    configuration each time would dominate the walk.
    """

    try:
        from .tool_providers import (
            default_tools_path,
            load_tools,
            migrate_legacy,
            tool_runtime_status,
        )

        def available(items: Sequence[Mapping[str, Any]]) -> tuple[dict[str, Any], ...]:
            # Keep missing optional tools in Settings, but never offer their stale
            # operations to the Agent. Recheck on every read so installing the
            # payload makes it available without rewriting the configuration.
            return tuple(
                dict(item) for item in items if tool_runtime_status(item)[0]
            )

        source = default_tools_path()
        try:
            stamp = (source.stat().st_mtime_ns, source.stat().st_size)
        except OSError:
            stamp = None
        if stamp is None and _TOOL_CACHE["stamp"] is None and not _TOOL_CACHE["tools"]:
            # First look with no file yet: fold any legacy registry in, once.
            migrate_legacy()
            try:
                stamp = (source.stat().st_mtime_ns, source.stat().st_size)
            except OSError:
                stamp = None
        if stamp == _TOOL_CACHE["stamp"] and _TOOL_CACHE["tools"]:
            return available(_TOOL_CACHE["tools"])
        tools, _ = load_tools(source)
        _TOOL_CACHE["stamp"] = stamp
        _TOOL_CACHE["tools"] = tuple(tools)
        return available(_TOOL_CACHE["tools"])
    except Exception:  # noqa: BLE001 - a broken registration never blocks a search
        return ()


def _tool_claims(operation: Mapping[str, Any], relative: str) -> bool:
    """Only ask a tool about files it said it reads."""

    patterns = operation.get("patterns") or ()
    if not patterns:
        return True
    name = PurePosixPath(relative).name
    for pattern in patterns:
        text = str(pattern)
        if fnmatch.fnmatch(relative, text) or fnmatch.fnmatch(name, text):
            return True
    return False


def _uex_host_slots(operation: Mapping[str, Any], file_path: Path | None = None,
                    root: Path | None = None) -> dict[str, str]:
    """Values for the uex slots of a recipe, derived from the active project's unpacked root.

    uex reads an already-unpacked tree directly -- no paks, no AES keys -- so the only
    facts it needs are the directory to mount and an engine version, and both come
    from the project, never from a hand-written profile. ``uex_profiles`` keeps the
    generated profile; this only looks it up. A recipe that mentions none of the
    slots costs nothing here.
    """

    from .tool_runner import host_slots_needed

    needed = host_slots_needed(operation)
    if not needed:
        return {}
    if root is None:
        root, _status = _unpacked_asset_root()
    if set(needed) == {"assetRoot"}:
        return {"assetRoot": str(root)}
    from . import uex_profiles

    profile = uex_profiles.ensure_profile(root)
    slots = {
        "assetRoot": str(root),
        "uexConfig": profile["configPath"],
        "uexProfile": profile["profile"],
    }
    if file_path is not None:
        slots["uexPath"] = uex_profiles.uex_relative_path(profile["mountRoot"], file_path)
    return slots


def _unpacker_profile_summary(asset_root: Path) -> dict[str, Any]:
    """How the bundled uex sees this tree: the generated profile, so uex MCP tools can be
    called with ``profile`` and nobody has to write a profiles.json. Never fails a listing."""

    try:
        from . import uex_profiles

        facts = uex_profiles.ensure_profile(asset_root)
    except Exception as error:  # noqa: BLE001 - informational
        return {"uex": {"available": False, "reason": str(error)[:160]}}
    return {"uex": {
        "available": True,
        "profile": facts["profile"],
        "configPath": facts["configPath"],
        "mountRoot": facts["mountRoot"],
        "mountRootSource": facts["mountRootSource"],
        "gameName": facts["gameName"],
        "engineVersion": facts.get("game", ""),
        "engineVersionFromHeaders": facts.get("detectedVersion", ""),
        "versionPinned": facts["pinned"],
        "note": ("uex mounts the unpacked tree directly: no paks, no AES keys. Its recipes "
                 "(uex_preview_asset, uex_search, uex_export, ...) fill this profile themselves; "
                 "the uex MCP tools take profile=" + facts["profile"] + ". Virtual paths are "
                 "relative to mountRoot, e.g. " + (facts["gameName"] or "<Game>") + "/Content/... "
                 "Each CLI call mounts the tree again (seconds on a large one), so for more than a "
                 "few lookups prefer the uex MCP tools, whose process keeps the mount. The engine "
                 "version was read from a cooked package header; "
                 "set_unpacked_asset_engine_version corrects it if a package will not parse."),
    }}


def _describe_from_uex_exports(exports: list[Any], relative: str) -> dict[str, Any] | None:
    """Turn uex's FModel-style export array into the reader contract's one object.

    ``uex preview`` prints the package's exports (``[{"Type": "MaterialInstanceConstant",
    "Name": ..., "Properties": {...}}, ...]``). The first export names the asset; its
    properties are the material parameters, texture references and mesh facts the
    retriever matches on, so they are kept (bounded) rather than summarised away.
    """

    records = [item for item in exports if isinstance(item, Mapping)]
    if not records:
        return None
    primary = next((item for item in records
                    if str(item.get("Type", "")) not in {"", "Package"}), records[0])
    class_name = str(primary.get("Type", "") or primary.get("Class", "") or "")
    properties = primary.get("Properties")
    text = json.dumps(properties, ensure_ascii=False, default=str) if isinstance(properties, Mapping) else "{}"
    if len(text) > 64 * 1024:
        text = text[:64 * 1024]
        truncated = True
    else:
        truncated = False
    references: list[dict[str, Any]] = []
    seen: set[str] = set()
    for match in re.finditer(r'"(/(?:Game|Engine|Script)/[^"\\]{1,400})"', text):
        value = match.group(1)
        if value in seen:
            continue
        seen.add(value)
        references.append({"relation": "property", "objectPath": value})
        if len(references) >= 64:
            break
    return {
        "relativePath": relative,
        "engine": "unreal",
        "kind": _unreal_kind_for_class(class_name),
        "className": class_name,
        "objectName": str(primary.get("Name", "") or ""),
        "exportClasses": sorted({str(item.get("Type", "")) for item in records if item.get("Type")})[:32],
        # Keep the bounded input document intact for parameter parsing. Only the
        # reference text scan is truncated; agent display compaction happens later.
        "properties": properties if isinstance(properties, Mapping) else {},
        "propertiesTruncated": False,
        "referencesTruncated": truncated or len(references) >= 64,
        "references": references,
        "parseStatus": "parsed",
    }


def _run_cli_reader_operation(tool: Mapping[str, Any], operation: Mapping[str, Any],
                              path: Path, relative: str, root: Path | None = None) -> dict[str, Any] | None:
    """Run a command-line tool's proved invocation: file in, one JSON object out."""

    from .tool_runner import (ToolRunError, background_process_kwargs,
                              validate_headless_argv, validate_operation_proof)

    connection = tool.get("connection") or {}
    program = str(connection.get("command", ""))
    arguments = [str(item) for item in (operation.get("argv") or [])]
    if arguments and arguments[0] == "{program}":
        arguments.pop(0)
    command = [program] + [str(item) for item in connection.get("args") or []] + arguments
    identifier = str(tool.get("id", "tool"))
    slots: dict[str, str] = {"path": str(path), "program": program}
    try:
        slots.update(_uex_host_slots(operation, file_path=path, root=root))
    except Exception as error:  # noqa: BLE001 - no active root is an answer, not a crash
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "failed", "reason": str(error)[:200]}
    if not any("{path}" in item or "{uexPath}" in item for item in command):
        command.append(str(path))
    pattern = re.compile(r"\{(" + "|".join(sorted(slots)) + r")\}")
    command = [pattern.sub(lambda found: slots[found.group(1)], item) for item in command if item]
    try:
        validate_headless_argv(command)
        validate_operation_proof(operation, command[0])
        completed = subprocess.run(
            command, capture_output=True,
            timeout=float(operation.get("timeoutSeconds", 20) or 20), check=False,
            env={**os.environ, **{str(key): str(value) for key, value in
                                 (connection.get("env") or {}).items()}},
            **background_process_kwargs())
    except (OSError, subprocess.SubprocessError, ToolRunError) as error:
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "failed", "reason": str(error)[:200]}
    if completed.returncode != 0:
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "failed",
                "reason": completed.stderr.decode("utf-8", "replace")[-400:]}
    if len(completed.stdout) > 8 * 1024 * 1024:
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "invalid-output", "reason": "reader JSON exceeds the 8 MiB limit"}
    try:
        # Agent response compaction is not an input limit: cutting JSON at that
        # boundary discarded material parameters at the end of valid documents.
        payload = json.loads(completed.stdout.decode("utf-8-sig", "strict"))
    except (ValueError, UnicodeError):
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "invalid-output",
                "reason": "the tool did not print a JSON object"}
    if isinstance(payload, list):
        # uex preview (and FModel-style exporters) print the package's exports as an
        # array; the reader contract wants one object about the file.
        payload = _describe_from_uex_exports(payload, relative)
    if not isinstance(payload, dict):
        return None
    payload.setdefault("relativePath", relative)
    payload["reader"] = identifier
    payload.setdefault("kind", "unknown")
    payload.setdefault("readerStatus", "parsed")
    return payload


def _registered_tools_claiming(relative: str) -> list[str]:
    """Ids of enabled registered tools whose proved reader operation claims this path."""

    try:
        from .tool_providers import asset_reader_operation
    except Exception:  # noqa: BLE001
        return []
    found: list[str] = []
    for tool in _registered_tools():
        try:
            operation = asset_reader_operation(tool)
        except Exception:  # noqa: BLE001 - one bad registration must not hide others
            continue
        if operation is not None and _tool_claims(operation, relative):
            found.append(str(tool.get("id", "tool")))
    return found[:16]


from .asset_reader_routing import ReaderResultCache as _ReaderResultCache

_ASSET_READER_RESULTS = _ReaderResultCache()


async def _invoke_asset_reader(tool: Mapping[str, Any], operation: Mapping[str, Any],
                              root: Path, path: Path, relative: str) -> dict[str, Any]:
    """One bounded read, shared by normal routing and capability verification."""
    identifier = str(tool.get("id", "tool"))
    try:
        context = await asyncio.to_thread(_uex_host_slots, operation, path, root) \
            if operation.get("kind") == "cli" else {}
        key = _ASSET_READER_RESULTS.key(root, path, tool, operation, context=context)
    except Exception as error:  # noqa: BLE001 - profile errors must allow capture-only fallback
        return {"relativePath": relative, "reader": identifier, "kind": "unknown",
                "readerStatus": "failed", "reason": str(error)[:200]}
    cached, pending, owner = _ASSET_READER_RESULTS.acquire(key)
    if cached is not None:
        return dict(cached, reader=identifier, readerResultReused=True)
    if not owner:
        payload = await asyncio.shield(asyncio.wrap_future(pending))
        return dict(payload, reader=identifier, readerResultReused=True)
    payload = {"relativePath": relative, "reader": identifier, "kind": "unknown",
               "readerStatus": "failed", "reason": "reader invocation cancelled"}
    try:
        if operation.get("kind") == "mcp":
            from .mcp_tool_client import shared_client

            raw = await asyncio.wait_for(shared_client().call(
                tool, str(operation.get("name", "")),
                {str(operation.get("pathArgument") or "path"): str(path)}),
                timeout=min(float(operation.get("timeoutSeconds", 60) or 60), 300))
            if isinstance(raw, list):
                raw = _describe_from_uex_exports(raw, relative)
            payload = dict(raw) if isinstance(raw, Mapping) else {
                "readerStatus": "invalid-output", "reason": "reader did not return an asset object"}
        else:
            raw = await asyncio.to_thread(_run_cli_reader_operation, tool, operation, path, relative, root)
            payload = dict(raw) if isinstance(raw, Mapping) else {
                "readerStatus": "invalid-output", "reason": "reader did not return an asset object"}
        payload.setdefault("relativePath", relative)
        payload["reader"] = identifier
        payload.setdefault("kind", "unknown")
        payload.setdefault("readerStatus", "parsed")
    except Exception as error:  # noqa: BLE001 - optional reader failure is evidence
        payload = {"relativePath": relative, "reader": identifier, "kind": "unknown",
                   "readerStatus": "failed", "reason": str(error)[:200]}
    finally:
        _ASSET_READER_RESULTS.finish(key, payload)
    return payload


async def _describe_with_registered_tool(path: Path, relative: str,
                                         header: bytes, *, root: Path | None = None,
                                         engine: str = "", capability: str = "properties",
                                         preferred: str = "") -> dict[str, Any] | None:
    """Use the project's reader, then at most one compatible fallback.

    Every result is checked for the requested evidence; successful process exit
    and a recognized container are not proof of parameter or dependency reads.
    """
    del header
    from .asset_reader_routing import (MAX_READER_ATTEMPTS, capture_fallback,
        normalize_capability, normalize_engine, reader_candidates, result_capabilities,
        selected_reader, selection_for_root)

    capability = normalize_capability(capability)
    if root is None:
        try:
            root, unused_status = _unpacked_asset_root()
        except Exception:  # noqa: BLE001 - also used on individual exported files
            root = path.parent
    selection = selection_for_root(_load_asset_reader_selection(), root)
    if not engine:
        built_in = await asyncio.to_thread(_read_builtin_asset_description, root, path)
        engine = normalize_engine(built_in.get("engine") or selection.get("engine"))
    preferred = preferred or selected_reader(selection, engine, capability)
    tools = await asyncio.to_thread(_registered_tools)
    candidates = reader_candidates(tools, relative, engine=engine, capability=capability,
                                   preferred=preferred)
    attempts = []
    for tool, operation in candidates[:MAX_READER_ATTEMPTS]:
        payload = await _invoke_asset_reader(tool, operation, root, path, relative)
        provided = result_capabilities(payload)
        result_engine = normalize_engine(payload.get("engine"))
        if engine and result_engine and result_engine != engine:
            provided = set()
            payload = dict(payload, readerStatus="invalid-output", reason="reader-engine-mismatch")
        attempts.append({"reader": str(tool.get("id", "")), "operation": operation.get("name", ""),
                         "builtinKind": tool.get("builtinKind", ""),
                         "status": payload.get("readerStatus"), "providedCapabilities": sorted(provided),
                         "reason": str(payload.get("reason", ""))[:200],
                         "reused": bool(payload.get("readerResultReused"))})
        if capability in provided:
            payload["readerRouting"] = {"state": "ready", "capability": capability,
                "engine": result_engine or engine, "selectedReader": preferred, "attempts": attempts,
                "providedCapabilities": sorted(provided)}
            return payload
    reason = "reader-capability-insufficient" if candidates else "no-compatible-reader"
    return {"relativePath": relative, "reader": "none", "kind": "unknown",
            "readerStatus": "unavailable", "reason": reason,
            "readerRouting": {"state": "capture-only", "capability": capability, "engine": engine,
                "selectedReader": preferred, "attempts": attempts,
                "attemptLimit": MAX_READER_ATTEMPTS, "eligibleReaders": len(candidates)},
            **capture_fallback(reason)}


def _utc_now_text() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _asset_reader_operation_of(tool: Mapping[str, Any]) -> dict[str, Any] | None:
    try:
        from .tool_providers import asset_reader_operation

        return asset_reader_operation(tool)
    except Exception:  # noqa: BLE001 - a broken entry never blocks a read
        return None


def _read_builtin_asset_description(root: Path, path: Path, *,
                                    deep: bool = False) -> dict[str, Any]:
    """What Bread's own parsers make of one file, without calling any tool.

    Synchronous on purpose: this touches only local parsing, so it is safe on the
    event loop and usable from the compatibility shim.
    """

    relative = _unpacked_relative(root, path)
    try:
        with path.open("rb") as stream:
            header = stream.read(UNPACKED_SEARCH_MAX_CONTENT_BYTES if deep else 65536)
    except OSError as error:
        return {"relativePath": relative, "kind": "unreadable", "reader": "none",
                "reason": str(error)[:200]}

    suffix = path.suffix.lower()
    if suffix in {".uasset", ".umap", ".uexp"}:
        try:
            from .symbols.engines import parse_engine_asset

            parsed = parse_engine_asset(None, relative, header)
        except Exception as error:  # noqa: BLE001 - a malformed package is data, not a crash
            parsed = None
            parse_error = str(error)[:200]
        else:
            parse_error = ""
        if parsed is not None:
            metadata, references = parsed
            class_name = str(metadata.get("className", "") or metadata.get("primaryClass", "") or "")
            description = {
                "relativePath": relative,
                "reader": "unreal-package",
                "engine": "unreal",
                "kind": _unreal_kind_for_class(class_name),
                "className": class_name,
                "parseStatus": metadata.get("parseStatus", "parsed"),
                "metadata": {key: value for key, value in metadata.items()
                             if key in ("objectPath", "exportClasses", "parseStatus", "reason",
                                        "distinctiveValues", "textureFormat", "width", "height",
                                        "mipCount", "vertexCount", "triangleCount")},
                # targetPath needs the tree's mount table to resolve; the object path is
                # always there and is what a search matches on.
                "references": [
                    {
                        "relation": item.get("relation"),
                        "objectPath": (item.get("evidence") or {}).get("objectPath"),
                        "class": (item.get("evidence") or {}).get("class"),
                        "targetPath": item.get("targetPath") or "",
                    }
                    for item in (references or [])[:64]
                ],
            }
            if not class_name and metadata.get("parseStatus") == "failed":
                description["reason"] = metadata.get("reason", "")
            return description
        if parse_error:
            return {"relativePath": relative, "reader": "unreal-package", "kind": "package",
                    "parseStatus": "failed", "reason": parse_error}

    if suffix in {".assets", ".unity3d", ".bundle", ".sharedassets", ".resource", ""} or \
            header[:8] in (b"UnityFS\x00", b"UnityWeb", b"UnityRaw"):
        try:
            from .symbols.engines import unity_serialized

            unity = unity_serialized.parse(header)
        except Exception:  # noqa: BLE001 - a malformed file is data, not a crash
            unity = None
        if unity is not None:
            unity["relativePath"] = relative
            return unity

    for magic, kind, label in _ASSET_READER_MAGIC:
        if header.startswith(magic) or (magic == b"glTF" and header[:4] == b"glTF"):
            return {"relativePath": relative, "reader": "container-magic", "kind": kind,
                    "container": label}

    text_suffixes = {".ini", ".json", ".xml", ".txt", ".cfg", ".csv", ".yaml", ".yml",
                     ".hlsl", ".usf", ".ush", ".glsl", ".shader"}
    if suffix in text_suffixes:
        kind = "shader" if suffix in {".hlsl", ".usf", ".ush", ".glsl", ".shader"} else "metadata"
        return {"relativePath": relative, "reader": "text", "kind": kind}
    return {"relativePath": relative, "reader": "none", "kind": "unknown"}


async def _read_unpacked_asset_description(root: Path, path: Path, *,
                                           deep: bool = False,
                                           capability: str = "") -> dict[str, Any]:
    """Read the requested evidence, preserving classification on optional failure."""
    from .asset_reader_routing import (normalize_capability, normalize_engine,
        result_capabilities, selected_reader, selection_for_root)

    capability = normalize_capability(capability, deep=deep)

    # Even the shallow built-in readers perform bounded file IO and package
    # parsing.  Keep those operations off the MCP event loop so runtime/status
    # calls can be served while a directory search is identifying candidates.
    described = await asyncio.to_thread(
        _read_builtin_asset_description, root, path, deep=deep
    )
    relative = described.get("relativePath") or _unpacked_relative(root, path)
    selection = selection_for_root(_load_asset_reader_selection(), root)
    engine = normalize_engine(described.get("engine") or selection.get("engine"))
    preferred = selected_reader(selection, engine, capability)
    provided = result_capabilities(described)
    if capability in provided and preferred in {"", described.get("reader")}:
        described["readerRouting"] = {"state": "ready", "capability": capability, "engine": engine,
            "selectedReader": preferred, "attempts": [], "providedCapabilities": sorted(provided)}
        return described
    from_tool = await _describe_with_registered_tool(path, relative, b"", root=root,
        engine=engine, capability=capability, preferred=preferred)
    if from_tool is not None and capability in result_capabilities(from_tool):
        return from_tool
    described = dict(described)
    if from_tool is not None:
        for key in ("readerRouting", "nonblocking", "fallback"):
            if key in from_tool:
                described[key] = from_tool[key]
        # A selected external reader failing must not discard sufficient local
        # evidence, but header-only data still cannot satisfy a deeper request.
        if capability in provided:
            described.pop("fallback", None)
            described.pop("nonblocking", None)
            described["readerRouting"]["state"] = "ready"
            described["readerRouting"]["providedCapabilities"] = sorted(provided)
        else:
            described["readerStatus"] = "capability-unavailable"
            described["reason"] = from_tool.get("reason", "")
            described["note"] = (
                "continue with capture evidence and inferred Shader names; optionally add the tool that reads it "
                "in Settings > AI (Tools) to supply original asset metadata")
    return described


def _read_unpacked_asset_description_sync(root: Path, path: Path, deep: bool,
                                         capability: str = "") -> dict[str, Any]:
    """Blocking wrapper so describe can leave the MCP event loop free to poll."""

    return asyncio.run(_read_unpacked_asset_description(root, path, deep=deep, capability=capability))


def _exact_asset_read_facts(root: Path, path: Path) -> dict[str, Any]:
    """Return facts for exactly one file, without scanning or binding its asset root."""

    return {
        "relativePath": _unpacked_relative(root, path),
        "bytes": int(path.stat().st_size),
        "contentSha256": _file_sha256(path),
    }


def _classify_unpacked_asset(path: Path, header: bytes = b"") -> dict[str, Any]:
    """Compatibility shim: the kind of one asset, read from its container.

    Synchronous, so it sees only the built-in parsers. A registered tool may be a
    subprocess or a network call and belongs on the awaited path.
    """

    del header
    try:
        root, unused_status = _unpacked_asset_root()
    except Exception:  # noqa: BLE001 - classification is also used on loose paths
        root = path.parent
    described = _read_builtin_asset_description(root, path)
    return {
        "kind": described.get("kind", "unknown"),
        "reader": described.get("reader", "none"),
        "className": described.get("className", ""),
        "basis": described.get("container") or described.get("className") or described.get("reader", ""),
    }


ASSET_READER_SELECTION_FILENAME = "asset-reader-selection.json"
ASSET_READER_PROBE_MAX_SAMPLES = 48


def _asset_reader_selection_path() -> Path | None:
    try:
        unused_service, unused_status, unused_root, database_path = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=True)
    except Exception:  # noqa: BLE001 - no project means no remembered selection
        return None
    return database_path.parent / ASSET_READER_SELECTION_FILENAME


def _load_asset_reader_selection() -> dict[str, Any] | None:
    """The reader this project already proved can read its tree."""

    path = _asset_reader_selection_path()
    if path is None:
        return None
    try:
        if not path.is_file() or path.is_symlink():
            return None
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return payload if isinstance(payload, dict) else None


def _store_asset_reader_selection(payload: Mapping[str, Any]) -> str:
    path = _asset_reader_selection_path()
    if path is None:
        return ""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        record = dict(payload)
        record["schema"] = "replaylab-asset-reader-selection/v1"
        record["decidedAt"] = datetime.now(timezone.utc).isoformat(timespec="seconds")
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_text(json.dumps(record, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(temporary, path)
        return str(path)
    except OSError:
        return ""


def _sample_unpacked_assets(root: Path, limit: int) -> list[Path]:
    """A spread of real files from the tree, not just the first directory."""

    samples: list[Path] = []
    deadline = time.monotonic() + 5.0
    for directory, directories, files in os.walk(root):
        directories.sort()
        for name in sorted(files)[:3]:
            candidate = Path(directory) / name
            try:
                if candidate.is_file() and not candidate.is_symlink() and candidate.stat().st_size > 0:
                    samples.append(candidate)
            except OSError:
                continue
            if len(samples) >= limit:
                return samples
        if time.monotonic() >= deadline:
            break
    return samples


@mcp.tool()
def get_bread_configuration() -> str:
    """Read the Bread configuration the Settings > AI panel edits.

    Skills (which are installed, which are enabled, which folders they come from),
    external MCP servers, and registered asset readers — the same files qrenderdoc's
    settings page writes. Read this before changing anything so a change is additive.
    """

    try:
        from .asset_readers import (
            BUILTIN_READERS,
            default_readers_path,
            load_external_readers,
            reader_contract,
        )
        from .replaylab_configuration import read_agent_tools

        tools = read_agent_tools()
        readers = list(load_external_readers())
        # One list to scan. Each entry says what it is for, so choosing what to load is a
        # reading problem rather than a guessing one.
        capabilities: list[dict[str, Any]] = []
        for skill in tools["skills"]:
            capabilities.append({
                "kind": "skill", "id": skill.get("id", ""),
                "title": skill.get("id", ""), "description": skill.get("description", ""),
                "enabled": bool(skill.get("enabled")), "source": "built-in" if skill.get("always")
                else "user", "loadWith": "load_bread_skill",
            })
        for server in tools["mcpServers"]:
            capabilities.append({
                "kind": "mcp-server", "id": server.get("id", ""),
                "title": server.get("title", ""), "description": server.get("note", ""),
                "enabled": bool(server.get("enabled", True)), "source": "user",
                "loadWith": "attached to the task when enabled",
            })
        for reader in BUILTIN_READERS:
            capabilities.append({
                "kind": "asset-reader", "id": reader["id"], "title": reader["title"],
                "description": reader["description"], "enabled": True, "source": "built-in",
                "loadWith": "describe_unpacked_asset",
            })
        for reader in readers:
            capabilities.append({
                "kind": "asset-reader", "id": reader.get("id", ""),
                "title": reader.get("title", ""), "description": reader.get("note", ""),
                "enabled": bool(reader.get("enabled", True)), "source": "user",
                "loadWith": "describe_unpacked_asset",
            })
        return _ok_compact({
            "schema": "replaylab-configuration/v1",
            "schemaVersion": 1,
            "capabilities": capabilities,
            "skills": tools["skills"],
            "skillRoots": tools["skillRoots"],
            "disabledSkills": tools["disabledSkills"],
            "mcpServers": tools["mcpServers"],
            "builtinAssetReaders": [dict(item) for item in BUILTIN_READERS],
            "assetReaders": readers,
            "assetReaderSelection": _load_asset_reader_selection(),
            "files": {
                "agentTools": tools["path"],
                "assetReaders": str(default_readers_path()),
            },
            "readerContract": reader_contract(),
            "applied": False,
        })
    except Exception as error:
        return _err(error)


@mcp.tool()
def update_bread_configuration(
    enable_skills: list[str] | None = None,
    disable_skills: list[str] | None = None,
    add_skill_roots: list[str] | None = None,
    remove_skill_roots: list[str] | None = None,
    upsert_mcp_servers: list[dict[str, Any]] | None = None,
    remove_mcp_servers: list[str] | None = None,
    upsert_asset_readers: list[dict[str, Any]] | None = None,
    remove_asset_readers: list[str] | None = None,
    upsert_tools: list[dict[str, Any]] | None = None,
    remove_tools: list[str] | None = None,
    write_skills: list[dict[str, Any]] | None = None,
    user_confirmation: str = "",
) -> str:
    """Change that configuration on the user's behalf.

    Use it when the user asked for a setup — "here is my extractor, wire it up", "turn
    that Skill off", "add this MCP server", "write me a Skill for this workflow" — and
    quote what they said in ``user_confirmation``. Every change is additive and
    reversible in the same panel; nothing here touches a capture. Report exactly what
    changed.

    ``upsert_tools`` takes ``[{id, title, description, roles, connection}]`` — one entry
    per external tool, whether it speaks MCP over stdio or streamable HTTP or is a plain
    command line. Write the connection only: the ``interface`` is discovered by
    ``discover_tool_interface`` and written back, never composed here.

    ``upsert_mcp_servers`` takes ``[{id, title, transport, command, args, env, url,
    enabled, note}]`` — ``stdio`` needs ``command``; ``http`` needs an ``https://``
    ``url``. An entry that carries only ``{id, enabled}`` toggles an existing server in
    place and keeps its connection. Ids are lower-case (``a-z 0-9 . - _``).

    ``write_skills`` takes ``[{id, content, replace}]`` and writes each ``SKILL.md``
    into the user's own Skill folder, registering that folder and enabling the Skill.
    The installed package is never written to, so an update cannot erase the Skill.
    Overwriting an existing one needs ``replace`` — a Skill the user edited by hand is
    not collateral. Write the whole document: the front matter (``name``, ``title``,
    ``description``) and the procedure the AI is to follow.
    """

    try:
        if not str(user_confirmation or "").strip():
            raise ValueError(
                "user_confirmation must quote the request this change carries out")
        from .replaylab_configuration import apply_configuration_change

        result = apply_configuration_change(
            enable_skills=enable_skills or [],
            disable_skills=disable_skills or [],
            add_skill_roots=add_skill_roots or [],
            remove_skill_roots=remove_skill_roots or [],
            upsert_mcp_servers=upsert_mcp_servers or [],
            remove_mcp_servers=remove_mcp_servers or [],
            upsert_asset_readers=upsert_asset_readers or [],
            remove_asset_readers=remove_asset_readers or [],
            upsert_tools=upsert_tools or [],
            remove_tools=remove_tools or [],
            write_skills=write_skills or [],
        )
        result["schema"] = "replaylab-configuration-change/v1"
        result["userConfirmation"] = str(user_confirmation)[:512]
        result["applied"] = True
        return _ok_compact(result)
    except Exception as error:
        return _err(error)


@mcp.tool()
async def discover_tool_interface(tool_id: str, sample_size: int = 3,
                                  extra_argv: list[str] | None = None) -> str:
    """Ask a registered tool what it can do, prove it, and write the answer down.

    This is what replaces configuring an interface by hand. For an MCP connection the
    answer is ``tools/list`` — typed and self-describing — and the operation that takes
    a file path and answers about one asset is picked from it. For a plain command line
    there is no such answer, so the candidate invocations are *tried* against real
    files from this project until one exits cleanly and prints a JSON object.

    Either way the result is stored on the tool, so the next task starts from the
    answer instead of rediscovering it, and the Settings panel can show what the tool
    is actually able to do. An operation that could not be proved is not written.
    """

    try:
        from .asset_reader_routing import result_capabilities
        from .tool_providers import (
            asset_reader_operation,
            default_tools_path,
            load_tools,
            record_interface,
        )

        identifier = str(tool_id or "").strip().lower()
        tools, _ = load_tools()
        tool = next((item for item in tools if item["id"] == identifier), None)
        if tool is None:
            raise ValueError(f"unknown tool: {identifier or '(empty)'}")

        existing_interface = tool.get("interface") or {}
        if (tool.get("builtinKind")
                and existing_interface.get("source") == "builtin:%s" % tool["builtinKind"]
                and existing_interface.get("operations") and not extra_argv):
            return _ok_compact({
                "schema": "replaylab-tool-interface/v1", "tool": identifier,
                "state": "ready", "connection": tool["connection"].get("kind"),
                "interface": existing_interface, "roles": tool["roles"],
                "assetReader": asset_reader_operation(tool) is not None,
                "attempts": [], "configurationFile": str(default_tools_path())})

        root, _ = _unpacked_asset_root()
        samples = _sample_unpacked_assets(root, max(1, min(int(sample_size), 8)))
        if not samples:
            raise RuntimeError("the configured asset root holds no readable files to test with")

        kind = str(tool["connection"].get("kind", ""))
        interface: dict[str, Any] = {"discoveredAt": _utc_now_text(), "operations": []}
        attempts: list[dict[str, Any]] = []

        if kind.startswith("mcp-"):
            from .mcp_tool_client import shared_client

            listing = await shared_client().list_tools(tool)
            interface["source"] = "mcp/tools-list"
            interface["toolCount"] = len(listing)
            interface["note"] = "; ".join(
                f"{item['name']}({', '.join(item['arguments'][:4])})" for item in listing[:12])
            for candidate in _ranked_asset_reader_candidates(listing):
                argument = candidate["pathArgument"]
                proved = None
                for sample in samples:
                    try:
                        payload = await shared_client().call(tool, candidate["name"],
                                                             {argument: str(sample)})
                    except Exception as error:  # noqa: BLE001 - a refusal is data
                        attempts.append({"operation": candidate["name"],
                                         "outcome": str(error)[:200]})
                        break
                    if isinstance(payload, Mapping) and result_capabilities(payload):
                        proved = {"sample": sample.relative_to(root).as_posix(),
                                  "at": _utc_now_text()}
                        attempts.append({"operation": candidate["name"], "outcome": "answered"})
                        break
                if proved:
                    interface["operations"].append({
                        "role": "asset-reader", "kind": "mcp", "name": candidate["name"],
                        "pathArgument": argument,
                        "patterns": sorted({f"*{sample.suffix.lower()}" for sample in samples
                                            if sample.suffix}),
                        "proved": proved,
                        "observedCapabilities": sorted(result_capabilities(payload)),
                        "engines": [str(payload["engine"])] if payload.get("engine") else [],
                    })
                    break
        else:
            from .asset_readers import candidate_invocations

            interface["source"] = "cli/probe"
            command = str(tool["connection"].get("command", ""))
            resolved = shutil.which(command) or command
            if not Path(resolved).is_file():
                return _ok_compact({
                    "schema": "replaylab-tool-interface/v1", "tool": identifier,
                    "state": "not-found", "command": command})
            help_text = _probe_reader_help(resolved)
            interface["note"] = help_text[:400]
            shapes = [tuple(str(item) for item in extra_argv)] if extra_argv else []
            shapes += [shape for shape in candidate_invocations(resolved, help_text)]
            for shape in shapes[:ASSET_READER_PROBE_MAX_ATTEMPTS]:
                if any("{profile}" in item for item in shape):
                    continue
                # A discovered invocation is declared like every other operation, so
                # the catalog the Agent reads has one shape: a callable name, a
                # sentence, and the one parameter this probe knows how to fill.
                operation = {
                    "role": "asset-reader", "kind": "cli", "argv": list(shape),
                    "timeoutSeconds": ASSET_READER_PROBE_TIMEOUT, "patterns": [],
                    "name": "%s_describe_asset" % re.sub(r"[^a-z0-9]+", "_",
                                                         identifier.lower()).strip("_"),
                    "description": ("Ask %s what one asset is. Discovered by trying "
                                    "invocations against real files in this project."
                                    % (tool.get("title") or identifier)),
                    "inputSchema": {
                        "type": "object",
                        "properties": {"path": {
                            "type": "string",
                            "description": "The asset file to describe."}},
                        "required": ["path"],
                    },
                    "result": {"kind": "stdout-text",
                               "successWhen": {"exitCode": 0, "minFiles": 0}},
                }
                outcome = ""
                for sample in samples:
                    described = await asyncio.to_thread(
                        _run_cli_reader_operation, tool, operation, sample,
                        sample.relative_to(root).as_posix())
                    outcome = str((described or {}).get("readerStatus", "failed"))
                    if outcome == "parsed" and result_capabilities(described):
                        operation["patterns"] = [f"*{sample.suffix.lower()}"] if sample.suffix \
                            else ["*"]
                        operation["proved"] = {"sample": sample.relative_to(root).as_posix(),
                                               "at": _utc_now_text()}
                        operation["observedCapabilities"] = sorted(result_capabilities(described))
                        operation["engines"] = [str(described["engine"])] if described.get("engine") else []
                        break
                    outcome = str((described or {}).get("reason", outcome))[:200]
                attempts.append({"operation": " ".join(shape), "outcome": outcome[:200]})
                if operation.get("proved"):
                    interface["operations"].append(operation)
                    break

        updated = record_interface(identifier, interface)
        result: dict[str, Any] = {
            "schema": "replaylab-tool-interface/v1",
            "tool": identifier,
            "connection": kind,
            "attempts": attempts,
            "interface": (updated or {}).get("interface", interface),
            "roles": (updated or {}).get("roles", tool["roles"]),
            "configurationFile": str(default_tools_path()),
        }
        if asset_reader_operation(updated or tool):
            result["state"] = "ready"
        else:
            result["state"] = "no-operation"
        return _ok_compact(result)
    except Exception as error:
        return _active_project_error("discover-tool-interface", error)


def _ranked_asset_reader_candidates(listing: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Which of a server's tools might answer "what is this one file?".

    Ranked by how much the name and its arguments look like a single-asset read, so the
    likely one is tried first instead of calling everything the server offers.
    """

    ranked: list[tuple[int, dict[str, Any]]] = []
    for item in listing:
        arguments = [str(name) for name in (item.get("arguments") or [])]
        path_argument = next(
            (name for name in arguments
             if name.lower() in {"path", "asset", "asset_path", "assetpath", "file", "filepath",
                                 "file_path", "object_path", "objectpath", "target"}), "")
        if not path_argument:
            continue
        name = str(item.get("name", "")).lower()
        description = str(item.get("description", "")).lower()
        score = 0
        for token, weight in (("preview", 5), ("describe", 5), ("inspect", 4), ("read", 3),
                              ("info", 3), ("asset", 2), ("metadata", 2), ("get", 1)):
            if token in name:
                score += weight
            if token in description:
                score += 1
        for token in ("export", "extract", "scan", "batch", "all", "bulk", "job"):
            if token in name:
                score -= 4
        if len(arguments) <= 3:
            score += 1
        ranked.append((score, {"name": item.get("name", ""), "pathArgument": path_argument,
                               "score": score}))
    ranked.sort(key=lambda entry: entry[0], reverse=True)
    return [entry[1] for entry in ranked[:6] if entry[0] > 0]


@mcp.tool()
async def verify_unpacked_asset_readers(sample_size: int = 12, capability: str = "classify") -> str:
    """Probe bounded candidates for one capability and remember each engine's winner.

    Classification is the backwards-compatible default. Use properties or references
    to verify richer evidence; recognizing a header never proves those capabilities.
    Missing or inadequate readers return a nonblocking capture-only fallback.
    """

    try:
        from .asset_readers import (
            BUILTIN_READERS,
            MCP_PRESETS,
            discover_installed_readers,
            presets_for_engine,
        )
        from .tool_providers import asset_reader_operation, default_tools_path, load_tools
        from .asset_reader_routing import (capture_fallback, normalize_capability,
            normalize_engine, reader_candidates, result_capabilities, selected_reader,
            selection_for_root)

        capability = normalize_capability(capability)
        try:
            root, status = _unpacked_asset_root()
        except RuntimeError:
            return _ok_compact({"schema": "replaylab-asset-reader-verification/v1",
                "state": "no-reader", "capability": capability, "sampled": 0,
                **capture_fallback("asset-root-unavailable")})
        wanted = min(max(int(sample_size), 1), ASSET_READER_PROBE_MAX_SAMPLES)
        samples = await asyncio.to_thread(_sample_unpacked_assets, root, wanted)
        if not samples:
            return _ok_compact({"schema": "replaylab-asset-reader-verification/v1",
                "state": "no-reader", "capability": capability, "sampled": 0,
                **capture_fallback("asset-root-empty")})
        engine = ""
        try:
            from .symbols.engines import detect_engine

            # detect_engine classifies from *relative file paths*; handing it the root
            # Path iterated its characters, raised, and was swallowed -- so the engine
            # was always "" and the presets were never narrowed. The sampled files are
            # already a spread of the tree, so they are the paths to classify.
            relative = [item.relative_to(root).as_posix() for item in samples]
            engine = normalize_engine(getattr(detect_engine(relative), "engine", ""))
        except Exception:  # noqa: BLE001 - engine detection is a hint, not a gate
            engine = ""

        # Discovery is explicit here, never a side effect of Shader organization.
        # Bound it instead of trying every installed program against a game tree.
        tools, _ = load_tools()
        discovered = 0
        for tool in tools:
            if discovered >= 2:
                break
            if not tool.get("enabled", True) or "asset-reader" not in tool.get("roles", []):
                continue
            tool_engines = {normalize_engine(item) for item in tool.get("engines") or []}
            if engine and tool_engines and engine not in tool_engines:
                continue
            if asset_reader_operation(tool) is None:
                await discover_tool_interface(tool["id"], sample_size=3)
                discovered += 1
        tools = await asyncio.to_thread(_registered_tools)
        previous = selection_for_root(_load_asset_reader_selection(), root)

        tally: dict[tuple[str, str], dict[str, Any]] = {}
        attempts: list[dict[str, Any]] = []
        external_attempts = 0
        for sample in samples:
            described = await asyncio.to_thread(_read_builtin_asset_description, root, sample,
                                               deep=capability != "classify")
            sample_engine = normalize_engine(described.get("engine") or engine)
            relative = _unpacked_relative(root, sample)
            reads = [described]
            candidates = reader_candidates(tools, relative, engine=sample_engine, capability=capability,
                preferred=selected_reader(previous, sample_engine, capability))
            # Invoke candidates directly: probing through the dispatcher would let
            # the first successful header parser answer on behalf of every tool.
            for tool, operation in candidates[:2]:
                if external_attempts >= ASSET_READER_PROBE_MAX_ATTEMPTS:
                    break
                reads.append(await _invoke_asset_reader(tool, operation, root, sample, relative))
                external_attempts += 1
            for read in reads:
                provided = result_capabilities(read)
                read_engine = normalize_engine(read.get("engine"))
                if sample_engine and read_engine and read_engine != sample_engine:
                    provided = set()
                reader = str(read.get("reader", "none"))
                attempts.append({"reader": reader, "relativePath": relative,
                    "providedCapabilities": sorted(provided), "satisfied": capability in provided,
                    "reason": str(read.get("reason", ""))[:200]})
                if capability not in provided:
                    continue
                actual_engine = normalize_engine(read.get("engine") or sample_engine)
                entry = tally.setdefault((actual_engine, reader), {"reader": reader, "engine": actual_engine,
                    "parsed": 0, "classes": [], "kindsRead": [], "capability": capability})
                entry["parsed"] += 1
                class_name = str(read.get("className") or read.get("container") or "")
                if class_name and class_name not in entry["classes"]:
                    entry["classes"] = (entry["classes"] + [class_name])[:8]
                kind = str(read.get("kind") or "")
                if kind and kind not in entry["kindsRead"]:
                    entry["kindsRead"] = sorted(set(entry["kindsRead"] + [kind]))[:12]

        ranked = sorted(tally.values(), key=lambda item: (
            -item["parsed"], item["reader"] != selected_reader(previous, item["engine"], capability)))
        result: dict[str, Any] = {
            "schema": "replaylab-asset-reader-verification/v1",
            "schemaVersion": 1,
            "assetRoot": str(root),
            "engine": engine,
            "capability": capability,
            "sampled": len(samples),
            "candidates": ranked,
            "attempts": attempts,
            "externalAttemptLimit": ASSET_READER_PROBE_MAX_ATTEMPTS,
            "externalAttempts": external_attempts,
            "scope": status.get("scope", {}) if isinstance(status, Mapping) else {},
        }
        if ranked and ranked[0]["parsed"]:
            chosen = ranked[0]
            selections = dict(previous.get("selections") or {})
            selected_engines: set[str] = set()
            for entry in ranked:
                group = entry["engine"] or "unknown"
                if group not in selected_engines:
                    selections[group] = dict(selections.get(group) or {})
                    selections[group][capability] = dict(entry)
                    selected_engines.add(group)
            stored = _store_asset_reader_selection({
                "reader": chosen["reader"],
                "engine": engine,
                "capability": capability,
                "selections": selections,
                "parsed": chosen["parsed"],
                "sampled": len(samples),
                "assetRoot": str(root),
                "classes": chosen["classes"],
                "kindsRead": chosen["kindsRead"],
            })
            result["state"] = "ready"
            result["selectedReader"] = chosen["reader"]
            result["kindsRead"] = chosen["kindsRead"]
            result["selectionPath"] = stored
        else:
            result["state"] = "no-reader"
            result.update(capture_fallback("no-reader-for-capability"))
            result["builtInCoverage"] = [dict(item) for item in BUILTIN_READERS]
            result["installed"] = await asyncio.to_thread(discover_installed_readers)
            result["presets"] = [
                {"id": item["id"], "title": item["title"], "engines": item["engines"],
                 "homepage": item["homepage"], "command": item["command"], "note": item["note"]}
                for item in presets_for_engine(engine)
            ]
            result["mcpServerPresets"] = [
                dict(item) for item in MCP_PRESETS if not engine or engine in item["engines"]]
            result["configurationFile"] = str(default_tools_path())
        return _ok_compact(result)
    except Exception as error:
        return _active_project_error("verify-unpacked-asset-readers", error)


@mcp.tool()
def discover_asset_readers() -> str:
    """Find extractors already installed on this machine.

    Registering a tool should cost the user one path, and often not even that. This
    looks in the obvious places — PATH, %LOCALAPPDATA%, Program Files, Downloads — for
    the tools people actually have (uex, AssetStudio, umodel, FModel, QuickBMS) and
    reports what it found, with the connection to register it under. Nothing is
    registered by this call; ``update_bread_configuration(upsert_tools=[…])``
    does that, then ``discover_tool_interface`` works out how to drive it.
    """

    try:
        from .asset_readers import discover_installed_readers
        from .tool_providers import load_tools

        tools, _ = load_tools()
        registered = {str(item.get("connection", {}).get("command", "")).lower()
                      for item in tools}
        candidates = []
        for item in discover_installed_readers():
            entry = dict(item)
            entry["alreadyRegistered"] = item["command"].lower() in registered
            # uex speaks MCP, which needs no interface discovery at all.
            entry["suggestedConnection"] = (
                {"kind": "mcp-stdio", "command": item["command"], "args": ["mcp"]}
                if item["id"] == "uex"
                else {"kind": "cli", "command": item["command"]})
            candidates.append(entry)
        return _ok_compact({
            "schema": "replaylab-asset-reader-discovery/v1",
            "candidates": candidates,
        })
    except Exception as error:
        return _err(error)


@mcp.tool()
def list_bread_tools() -> str:
    """Every external tool Bread can call, and what was discovered about it.

    One list, whatever the connection: an MCP server over stdio or streamable HTTP, or
    a plain command line. ``roles`` says what each may be used for — ``asset-reader``
    is called by the Host itself while reading unpacked assets, ``general`` means its
    tools are offered to you during a task. ``interface.operations`` is what was proved
    to work; an empty one means ``discover_tool_interface`` has not run yet.
    """

    try:
        from .asset_readers import BUILTIN_READERS, MCP_PRESETS, PRESETS
        from .tool_providers import default_tools_path, load_tools

        tools, diagnostics = load_tools()
        return _ok_compact({
            "schema": "replaylab-tools-view/v1",
            "schemaVersion": 1,
            "tools": tools,
            "diagnostics": diagnostics,
            "builtInReaders": [dict(item) for item in BUILTIN_READERS],
            "projectReaderSelection": _load_asset_reader_selection(),
            "presets": {
                "mcp": [dict(item) for item in MCP_PRESETS],
                "commandLine": [dict(item) for item in PRESETS],
            },
            "configurationFile": str(default_tools_path()),
            "registration": {
                "connection": "mcp-stdio (command), mcp-http (url), or cli (command)",
                "roles": "asset-reader and/or general",
                "interface": ("discovered by discover_tool_interface and written back here; "
                              "never write one by hand"),
            },
            "applied": False,
        })
    except Exception as error:
        return _err(error)


@mcp.tool()
async def test_tool_connection(tool_id: str) -> str:
    """Start one registered tool and report whether it actually answers.

    A configured tool is not a working tool. For MCP this initialises the session and
    counts the operations it offers; for a command line it checks the program exists
    and runs its help. Nothing is written.
    """

    try:
        from .tool_providers import load_tools

        identifier = str(tool_id or "").strip().lower()
        tools, _ = load_tools()
        tool = next((item for item in tools if item["id"] == identifier), None)
        if tool is None:
            raise ValueError(f"unknown tool: {identifier or '(empty)'}")
        kind = str(tool["connection"].get("kind", ""))
        started = time.monotonic()
        if kind.startswith("mcp-"):
            from .mcp_tool_client import shared_client

            try:
                listing = await shared_client().list_tools(tool)
            except Exception as error:  # noqa: BLE001 - a failure to start is the answer
                return _ok_compact({"schema": "replaylab-tool-test/v1", "tool": identifier,
                                    "ok": False, "operations": 0,
                                    "seconds": round(time.monotonic() - started, 2),
                                    "error": str(error)[:400]})
            return _ok_compact({
                "schema": "replaylab-tool-test/v1", "tool": identifier, "ok": True,
                "operations": len(listing),
                "operationNames": [item["name"] for item in listing[:32]],
                "seconds": round(time.monotonic() - started, 2), "error": ""})
        command = str(tool["connection"].get("command", ""))
        resolved = shutil.which(command) or command
        if not Path(resolved).is_file():
            return _ok_compact({"schema": "replaylab-tool-test/v1", "tool": identifier,
                                "ok": False, "operations": 0, "seconds": 0.0,
                                "error": f"no such executable: {command}"})
        help_text = await asyncio.to_thread(_probe_reader_help, resolved)
        return _ok_compact({
            "schema": "replaylab-tool-test/v1", "tool": identifier, "ok": bool(help_text),
            "operations": 0, "seconds": round(time.monotonic() - started, 2),
            "helpText": help_text[:2000],
            "error": "" if help_text else "the program produced no output"})
    except Exception as error:
        return _err(error)


ASSET_READER_PROBE_TIMEOUT = 25.0
ASSET_READER_PROBE_MAX_ATTEMPTS = 24


def _probe_reader_help(command: str) -> str:
    """Whatever the tool says about itself, bounded."""

    from .asset_readers import help_flags
    from .tool_runner import background_process_kwargs, validate_headless_argv

    for flags in help_flags(command):
        try:
            validate_headless_argv([command, *flags])
            completed = subprocess.run([command, *flags], capture_output=True, timeout=15.0,
                                       check=False, **background_process_kwargs())
        except (OSError, subprocess.SubprocessError):
            continue
        text = (completed.stdout + b"\n" + completed.stderr).decode("utf-8", "replace")
        if text.strip():
            return text[:20000]
    return ""


@mcp.tool()
async def describe_unpacked_asset(relative_path: str, deep: bool = False, capability: str = "") -> str:
    """Read one unpacked asset through a reader that understands its container.

    A cooked engine tree has no informative extensions: everything is a package.
    This dispatches to the built-in reader for the engine (Unreal package headers:
    class, exports, referenced object paths, texture header, distinctive values),
    to a container-magic reader for standalone files, or to a reader the user
    registered for a format the built-ins do not know. ``kind`` is what the reader
    determined, never a guess from the file name. ``capability`` may be classify,
    properties or references. If omitted, deep=True requests properties; a shallow
    read requests classification. Missing richer evidence permits capture-only work.
    """

    try:
        slot = LongToolSlot(
            "describe_unpacked_asset",
            {"relative_path": relative_path, "deep": bool(deep), "capability": capability},
        )
        if slot.busy is not None:
            return _ok(slot.busy)
        try:
            root, unused_status = _unpacked_asset_root()
            path = _unpacked_within(root, relative_path)
            if not path.is_file() or path.is_symlink():
                raise ValueError("relative_path is not a regular file inside the asset root")
            try:
                file_size = int(path.stat().st_size)
            except OSError:
                file_size = 0
            slot.update(
                "reading-package",
                detail="parsing %s" % _unpacked_relative(root, path),
                fileSizeBytes=file_size,
                deep=bool(deep),
                unit="bytes",
                summary=(
                    "reading package (%s bytes, deep=%s); parser has no finer sub-steps"
                    % (file_size, bool(deep))
                ),
            )
            description = await asyncio.to_thread(
                _read_unpacked_asset_description_sync, root, path, bool(deep), capability
            )
            description["schema"] = "replaylab-unpacked-asset-description/v1"
            description["schemaVersion"] = 1
            description["toolStatus"] = "ok"
            description["registeredTools"] = [
                {"id": item.get("id"), "connection": item.get("connection", {}).get("kind", ""),
                 "patterns": list((_asset_reader_operation_of(item) or {}).get("patterns") or [])}
                for item in _registered_tools()
            ]
            description.update(_exact_asset_read_facts(root, path))
            description["applied"] = False
            runtime = slot.close(ok=True)
            return _ok_compact(attach_runtime(description, runtime or {}))
        except Exception:
            slot.close(ok=False)
            raise
    except Exception as error:
        return _active_project_error("describe-unpacked-asset", error)


@mcp.tool()
async def find_unpacked_asset_relations(relative_path: str, direction: str = "both", limit: int = 40) -> str:
    """Walk the relationships around one unpacked asset.

    ``references`` reads the asset's own embedded names and finds the files they point
    at (its textures, its parent material, its meshes). ``referenced-by`` searches the
    tree for files that name this asset (the material instances that use it, the meshes
    that bind it). Following one confirmed match into its neighbours is usually how the
    original material's parameter block — the one whose layout matches the captured
    constant buffer — is found.
    """

    try:
        slot = LongToolSlot(
            "find_unpacked_asset_relations",
            {"relative_path": relative_path, "direction": direction, "limit": limit},
        )
        if slot.busy is not None:
            return _ok(slot.busy)

        def _run_sync() -> dict[str, Any]:
            root, unused_status = _unpacked_asset_root()
            path = _unpacked_within(root, relative_path)
            if not path.is_file():
                raise ValueError("relative_path is not a file inside the asset root")
            wanted = min(max(int(limit), 1), 200)
            if direction not in ("references", "referenced-by", "both"):
                raise ValueError("direction must be references, referenced-by or both")
            with path.open("rb") as stream:
                header = stream.read(UNPACKED_SEARCH_MAX_CONTENT_BYTES)
            slot.update(
                "classifying-seed",
                detail="shallow classify seed asset",
                wanted=wanted,
                maxWalkFiles=UNPACKED_RELATIONS_MAX_WALK_FILES,
            )
            # Shallow classify the seed asset. Deep + whole-tree walks under a
            # 300k-file root were hanging the Host while qrenderdoc held tens of GB.
            classification = _read_unpacked_asset_description_sync(
                root, path, False
            )
            result: dict[str, Any] = {
                "schema": "replaylab-unpacked-asset-relations/v1",
                "schemaVersion": 1,
                "relativePath": _unpacked_relative(root, path),
                "classification": classification,
                "applied": False,
                "walkBounded": True,
            }
            # Prefer catalog edges when present so we do not build an in-memory
            # stem index over the whole unpacked tree.
            catalog_refs: list[dict[str, Any]] = []
            try:
                unused_service, unused_status, unused_root, database_path = (
                    _active_asset_catalog_context(require_catalog=True)
                )
                del unused_service, unused_status, unused_root
                if database_path.is_file():
                    relative = _unpacked_relative(root, path)
                    catalog = AssetCatalogService(database_path)
                    rows = catalog.query(
                        relative_paths=[relative], limit=1, include_relationships=True
                    ).get("assets") or []
                    if rows:
                        for relation in rows[0].get("relationships") or []:
                            if not isinstance(relation, Mapping):
                                continue
                            target = str(
                                relation.get("targetPath")
                                or relation.get("targetRelativePath")
                                or ""
                            ).strip()
                            if target:
                                catalog_refs.append({
                                    "relativePath": target,
                                    "relation": relation.get("relation"),
                                    "name": Path(target).stem,
                                    "source": "catalog",
                                })
            except Exception:
                catalog_refs = []
            names: list[str] = []
            if direction in ("references", "both"):
                for match in re.findall(rb"[\x20-\x7e]{4,96}", header):
                    text = match.decode("ascii", "ignore")
                    for token in re.findall(r"[A-Za-z_][A-Za-z0-9_]{3,63}", text):
                        if token not in names and not token.isdigit():
                            names.append(token)
                names = [name for name in names if name.lower() != path.stem.lower()][:400]
                references: list[dict[str, Any]] = list(catalog_refs[:wanted])
                if len(references) < wanted:
                    # Bound the fallback walk to the seed's parent tree, not the
                    # entire game dump. Parent-folder miss is content-based: only
                    # after files under that folder fail match.
                    search_root = path.parent
                    index: dict[str, str] = {}
                    deadline = time.monotonic() + UNPACKED_SEARCH_MAX_SECONDS
                    walked = 0
                    for directory, directories, files in os.walk(search_root):
                        directories.sort()
                        if time.monotonic() >= deadline:
                            break
                        for name in files:
                            walked += 1
                            if walked > UNPACKED_RELATIONS_MAX_WALK_FILES:
                                break
                            if walked % 256 == 0:
                                slot.update(
                                    "walking-parent-folder",
                                    walkedFiles=walked,
                                    maxWalkFiles=UNPACKED_RELATIONS_MAX_WALK_FILES,
                                    wanted=wanted,
                                    unit="files",
                                )
                            index.setdefault(
                                Path(name).stem.lower(),
                                _unpacked_relative(root, Path(directory) / name),
                            )
                        if walked > UNPACKED_RELATIONS_MAX_WALK_FILES:
                            break
                    result["walkedFiles"] = walked
                    for token in names:
                        hit = index.get(token.lower())
                        if hit and all(item["relativePath"] != hit for item in references):
                            references.append({
                                "relativePath": hit, "name": token, "source": "local-walk"
                            })
                        if len(references) >= wanted:
                            break
                result["references"] = references
                result["referenceNames"] = names[:64]
            if direction in ("referenced-by", "both"):
                needle = path.stem.encode("ascii", "ignore")
                wide = path.stem.encode("utf-16-le", "ignore")
                found: list[dict[str, Any]] = []
                scanned = 0
                deadline = time.monotonic() + UNPACKED_SEARCH_MAX_SECONDS
                # Only scan the immediate parent tree; never the whole asset root.
                for directory, directories, files in os.walk(path.parent):
                    directories.sort()
                    if time.monotonic() >= deadline or len(found) >= wanted:
                        break
                    for name in sorted(files):
                        candidate = Path(directory) / name
                        if candidate == path:
                            continue
                        scanned += 1
                        if scanned > UNPACKED_RELATIONS_MAX_WALK_FILES:
                            break
                        if scanned % 256 == 0:
                            slot.update(
                                "scanning-referenced-by",
                                scannedFiles=scanned,
                                maxWalkFiles=UNPACKED_RELATIONS_MAX_WALK_FILES,
                                wanted=wanted,
                                unit="files",
                            )
                        if scanned % 256 == 0 and time.monotonic() >= deadline:
                            break
                        try:
                            if candidate.stat().st_size > UNPACKED_SEARCH_MAX_CONTENT_BYTES:
                                continue
                            with candidate.open("rb") as stream:
                                blob = stream.read(UNPACKED_SEARCH_MAX_CONTENT_BYTES)
                        except OSError:
                            continue
                        if needle in blob or (wide and wide in blob):
                            found.append({
                                "relativePath": _unpacked_relative(root, candidate),
                                "classification": _read_unpacked_asset_description_sync(
                                    root, candidate, False
                                ),
                            })
                            if len(found) >= wanted:
                                break
                    if scanned > UNPACKED_RELATIONS_MAX_WALK_FILES:
                        break
                result["referencedBy"] = found
                result["scannedFiles"] = scanned
            result.update(_exact_asset_read_facts(root, path))
            return result

        try:
            # The two bounded walks and their package reads are deliberately one
            # worker operation.  Yielding here keeps status/heartbeat tools
            # responsive for the full scan rather than only between files.
            payload = await asyncio.to_thread(_run_sync)
            if isinstance(payload, dict):
                payload.setdefault("toolStatus", "ok")
                runtime = slot.close(ok=True)
                return _ok_compact(attach_runtime(payload, runtime or {}))
            runtime = slot.close(ok=True)
            return _ok_compact(payload)
        except Exception:
            slot.close(ok=False)
            raise
    except Exception as error:
        return _active_project_error("find-unpacked-asset-relations", error)


def _search_unpacked_assets_sync(
    name_contains: str = "",
    name_glob: str = "",
    text_contains: str = "",
    under: str = "",
    extensions: list[str] | None = None,
    kinds: list[str] | None = None,
    identify: bool = True,
    limit: int = 50,
    cursor: str = "",
    timeout_seconds: int = 8,
) -> str:
    """Search the project's unpacked assets directly, with no catalog and no waiting.

    This is the primary way to find an asset: you decide what to look for from what
    the capture and the shader told you, and refine across calls. ``name_contains`` /
    ``name_glob`` match the path; ``text_contains`` additionally scans the first
    512 KiB of small files for a literal string (engine packages carry referenced
    names and class names as plain text); ``under`` limits the walk to a subtree;
    ``extensions`` filters by suffix. ``kinds`` filters by what the asset actually is
    — ``texture``, ``material``, ``mesh``, ``shader``, ``animation``, ``level`` … —
    determined by reading each candidate's container (an engine package declares its
    class; the extension never decides). Pass ``identify=false`` to skip that read
    when you only want paths. The walk is bounded by ``timeout_seconds`` and
    ``limit`` and returns ``cursor`` to continue where it stopped, so a 200k-file tree
    never blocks anything. The asset index, when one exists, is only an accelerator —
    this call never needs it.
    """

    try:
        root, status = _unpacked_asset_root()
        budget = min(max(float(timeout_seconds), 1.0), UNPACKED_SEARCH_MAX_SECONDS)
        wanted = min(max(int(limit), 1), UNPACKED_SEARCH_MAX_RESULTS)
        needle = str(name_contains or "").strip().lower()
        pattern = str(name_glob or "").strip()
        content = str(text_contains or "")
        if len(content) > 512:
            raise ValueError("text_contains must be a short literal string")
        suffixes = {("." + str(item).lstrip(".")).lower() for item in (extensions or []) if str(item).strip()}
        kinds = {str(item).strip().lower() for item in (kinds or []) if str(item).strip()}
        identify = bool(identify) or bool(kinds)
        start_at = str(cursor or "")
        base = _unpacked_within(root, under)
        deadline = time.monotonic() + budget
        matches: list[dict[str, Any]] = []
        scanned = 0
        resume = ""
        skipping = bool(start_at)
        content_bytes = content.encode("utf-8", "ignore") if content else b""
        for directory, directories, names in os.walk(base):
            directories.sort()
            names.sort()
            for name in names:
                path = Path(directory) / name
                relative = _unpacked_relative(root, path)
                if skipping:
                    if relative == start_at:
                        skipping = False
                    continue
                scanned += 1
                if scanned % 256 == 0 and time.monotonic() >= deadline:
                    resume = relative
                    break
                if suffixes and path.suffix.lower() not in suffixes:
                    continue
                lowered = relative.lower()
                if needle and needle not in lowered:
                    continue
                if pattern and not fnmatch.fnmatch(relative, pattern) and not fnmatch.fnmatch(name, pattern):
                    continue
                why = []
                if needle:
                    why.append("name contains %r" % name_contains)
                if pattern:
                    why.append("path matches %r" % pattern)
                if content_bytes:
                    try:
                        size = path.stat().st_size
                        if size > UNPACKED_SEARCH_MAX_CONTENT_BYTES:
                            continue
                        with path.open("rb") as stream:
                            blob = stream.read(UNPACKED_SEARCH_MAX_CONTENT_BYTES)
                    except OSError:
                        continue
                    if content_bytes not in blob and content_bytes.decode(
                            "utf-8", "ignore").encode("utf-16-le") not in blob:
                        continue
                    why.append("content contains %r" % content[:64])
                try:
                    size = path.stat().st_size
                except OSError:
                    size = 0
                entry: dict[str, Any] = {
                    "relativePath": relative,
                    "name": name,
                    "bytes": int(size),
                    "why": "; ".join(why) or "under the searched subtree",
                }
                if identify:
                    described = _read_unpacked_asset_description_sync(root, path, False)
                    entry["kind"] = described.get("kind", "unknown")
                    entry["reader"] = described.get("reader", "none")
                    if described.get("className"):
                        entry["className"] = described["className"]
                    if kinds and entry["kind"] not in kinds:
                        continue
                matches.append(entry)
                if len(matches) >= wanted:
                    resume = relative
                    break
            if resume or (time.monotonic() >= deadline):
                if not resume:
                    resume = _unpacked_relative(root, Path(directory))
                break
        return _ok_compact({
            "schema": "replaylab-unpacked-asset-search/v1",
            "schemaVersion": 1,
            "assetRoot": str(root),
            "scannedFiles": scanned,
            "matches": matches,
            "truncated": bool(resume) and len(matches) >= wanted,
            "cursor": resume,
            "searchCoverage": {
                "fullyWalked": not bool(resume),
                "rootRelative": _unpacked_relative(root, base),
            },
            "applied": False,
        })
    except Exception as error:
        return _active_project_error("search-unpacked-assets", error)


@mcp.tool()
async def search_unpacked_assets(
    name_contains: str = "",
    name_glob: str = "",
    text_contains: str = "",
    under: str = "",
    extensions: list[str] | None = None,
    kinds: list[str] | None = None,
    identify: bool = True,
    limit: int = 50,
    cursor: str = "",
    timeout_seconds: int = 8,
) -> str:
    """Search the project's unpacked assets directly, with no catalog and no waiting.

    ``name_contains`` / ``name_glob`` match paths, ``text_contains`` scans the
    bounded prefix of small files, and ``under``/``extensions`` narrow the walk.
    ``kinds`` identifies candidates by reading their containers; pass
    ``identify=false`` for path-only search. The walk is bounded by time/result
    limits and returns a cursor. Filesystem walking, content reads and package
    identification run on a worker so ``get_host_runtime_status`` remains
    responsive throughout the call.
    """

    slot = LongToolSlot(
        "search_unpacked_assets",
        {
            "under": under,
            "identify": bool(identify),
            "limit": limit,
            "cursor": cursor,
        },
    )
    if slot.busy is not None:
        return _ok(slot.busy)
    try:
        payload_text = await asyncio.to_thread(
            _search_unpacked_assets_sync,
            name_contains,
            name_glob,
            text_contains,
            under,
            extensions,
            kinds,
            identify,
            limit,
            cursor,
            timeout_seconds,
        )
        try:
            payload = json.loads(payload_text)
        except (TypeError, ValueError):
            payload = None
        ok = isinstance(payload, Mapping) and not payload.get("error")
        runtime = slot.close(ok=bool(ok))
        if isinstance(payload, dict):
            return _ok_compact(attach_runtime(payload, runtime or {}))
        return str(payload_text)
    except Exception:
        slot.close(ok=False)
        raise


@mcp.tool()
def profile_unpacked_asset_directories(depth: int = 3, prefix: str = "", kinds: list[str] | None = None,
                                       limit: int = 120) -> str:
    """Map the unpacked asset tree: which folders hold materials, textures, meshes, shaders.

    Built from the names index (a first use walks the tree once, no parsing),
    so it answers in seconds even for hundreds of thousands of files. Read it
    the way an artist reads a project: ``Content/Characters/<Name>/Materials``
    is where a character's materials live, ``.../Textures`` its textures. Then
    pass the promising folders as ``scope_prefixes`` to
    ``retrieve_shader_asset_candidates`` (or ``hydrate_unpacked_asset_scope``)
    -- only those folders are parsed. ``kinds`` narrows the count to e.g.
    ["package", "material", "texture", "mesh", "shader"]; ``prefix`` zooms in.
    """

    try:
        service, status, asset_root, database_path, indexing = _ensure_shader_asset_catalog()
        catalog = AssetCatalogService(database_path)
        profile = catalog.directory_profile(depth=int(depth), prefix=str(prefix or ""),
                                            kinds=list(kinds or []), limit=int(limit))
        profile["indexing"] = indexing
        profile["unpacker"] = _unpacker_profile_summary(asset_root)
        profile["applied"] = False
        return _ok(profile)
    except _AssetCatalogNotReady as pending:
        return _ok({"schema": "renderdoc-ultra-unpacked-asset-directory-profile/v1", "schemaVersion": 1,
                    "ready": False, "indexing": pending.receipt,
                    "reason": "the names index of the asset root is still being built (first use)",
                    "applied": False})
    except Exception as error:
        return _active_project_error("profile-unpacked-asset-directories", error)


def _hydrate_unpacked_asset_scope_sync(
    prefixes: list[str], kinds: list[str] | None = None, max_files: int = 200
) -> str:
    """Parse the descriptive files under a few folders into the asset index.

    Package headers (class, referenced textures, parent material), the cooked
    exports of the materials among them (parameter values, shader types),
    material/JSON descriptors and texture headers/fingerprints -- for the
    given folders only; bulk data is never read. ``retrieve_shader_asset_candidates``
    with ``scope_prefixes`` does this for you; call it directly to prepare a
    folder once (results stay in the index) or to read a folder with
    ``query_active_unpacked_assets`` afterwards.
    """

    try:
        wanted = [str(item) for item in (prefixes or []) if isinstance(item, str) and item.strip()][:64]
        if not wanted:
            raise ValueError("prefixes must name at least one folder of the asset root")
        service, status, asset_root, database_path, indexing = _ensure_shader_asset_catalog()
        catalog = AssetCatalogService(database_path)
        started = time.monotonic()
        receipt = catalog.hydrate_scope(asset_root, wanted, kinds=list(kinds or []), max_files=int(max_files))
        receipt["seconds"] = round(time.monotonic() - started, 1)
        receipt["indexing"] = indexing
        receipt["applied"] = False
        return _ok(receipt)
    except _AssetCatalogNotReady as pending:
        return _ok({"schema": "renderdoc-ultra-unpacked-asset-hydrate-scope/v1", "schemaVersion": 1,
                    "ready": False, "indexing": pending.receipt,
                    "reason": "the names index of the asset root is still being built (first use)",
                    "applied": False})
    except Exception as error:
        return _active_project_error("hydrate-unpacked-asset-scope", error)


@mcp.tool()
async def hydrate_unpacked_asset_scope(
    prefixes: list[str], kinds: list[str] | None = None, max_files: int = 200
) -> str:
    """Parse a bounded folder scope into the asset index on a worker thread.

    Package/material descriptors and texture headers are read only below the
    requested prefixes. Progress remains visible through Host runtime status,
    which stays responsive while the filesystem/parser work is running.
    """

    slot = LongToolSlot(
        "hydrate_unpacked_asset_scope",
        {"prefixes": list(prefixes or [])[:64], "max_files": max_files},
    )
    if slot.busy is not None:
        return _ok(slot.busy)
    try:
        payload_text = await asyncio.to_thread(
            _hydrate_unpacked_asset_scope_sync,
            prefixes,
            kinds,
            max_files,
        )
        try:
            payload = json.loads(payload_text)
        except (TypeError, ValueError):
            payload = None
        ok = isinstance(payload, Mapping) and not payload.get("error")
        runtime = slot.close(ok=bool(ok))
        if isinstance(payload, dict):
            return _ok_compact(attach_runtime(payload, runtime or {}))
        return str(payload_text)
    except Exception:
        slot.close(ok=False)
        raise


@mcp.tool()
def set_unpacked_asset_engine_version(version: str = "", redetect: bool = False) -> str:
    """Say which engine version this unpacked tree was cooked with (or re-read it).

    You do not normally need this. The directory to read comes from the project's
    configured unpacked path, and the engine version is read out of a cooked
    package header -- a ``.uasset`` states its own object versions, so one file
    decides it. Call this when that reading disagreed with itself, when a uex
    operation says a package cannot be parsed, or when the user tells you the
    version: pass a CUE4Parse ``EGame`` name (``GAME_UE5_4``, ``GAME_SilverPalace``),
    a number (``5.4``) or ``latest``, and it is used from then on with no further
    probing. ``redetect=True`` re-reads the headers and reports what they say
    without changing anything.

    A version is a reading of the files, not a secret: an unpacked tree needs no
    AES key and no profile from anyone.
    """

    try:
        from . import uex_profiles

        root, unused_status = _unpacked_asset_root()
        facts = uex_profiles.ensure_profile(root)
        wanted = str(version or "").strip()
        detection = (uex_profiles.detect_engine_version(Path(facts["mountRoot"]))
                     if (redetect or not wanted) else {})
        applied: dict[str, Any] = {}
        if wanted:
            applied = uex_profiles.set_version(facts["profile"], wanted)
        return _ok({
            "schema": "renderdoc-ultra-unpacked-asset-engine-version/v1", "schemaVersion": 1,
            "profile": facts["profile"],
            "configPath": facts["configPath"],
            "mountRoot": facts["mountRoot"],
            "mountRootSource": facts["mountRootSource"],
            "assetRoot": facts["assetRoot"],
            "version": applied.get("game") or facts.get("game", ""),
            "pinned": bool(applied.get("pinned") or facts.get("pinned")),
            "readFromHeaders": detection,
            "applied": bool(wanted),
        })
    except Exception as error:
        return _active_project_error("set-unpacked-asset-engine-version", error)


@mcp.tool()
def list_unpacked_asset_directory(relative_path: str = "", limit: int = 200) -> str:
    """List one directory of the unpacked asset root: names, sizes, subdirectories.

    Use it to understand how the tree is organised before searching it, exactly as a
    person would. Needs no catalog.
    """

    try:
        root, unused_status = _unpacked_asset_root()
        base = _unpacked_within(root, relative_path)
        if not base.is_dir():
            raise ValueError("relative_path is not a directory inside the asset root")
        wanted = min(max(int(limit), 1), UNPACKED_LIST_MAX_ENTRIES)
        directories: list[str] = []
        files: list[dict[str, Any]] = []
        truncated = False
        with os.scandir(base) as entries:
            for entry in sorted(entries, key=lambda item: item.name):
                if len(directories) + len(files) >= wanted:
                    truncated = True
                    break
                if entry.is_dir(follow_symlinks=False):
                    directories.append(entry.name)
                elif entry.is_file(follow_symlinks=False):
                    try:
                        size = entry.stat().st_size
                    except OSError:
                        size = 0
                    files.append({"name": entry.name, "bytes": int(size)})
        return _ok_compact({
            "schema": "replaylab-unpacked-asset-listing/v1",
            "schemaVersion": 1,
            "assetRoot": str(root),
            "relativePath": _unpacked_relative(root, base) if base != root else "",
            "directories": directories,
            "files": files,
            "truncated": truncated,
            "applied": False,
        })
    except Exception as error:
        return _active_project_error("list-unpacked-asset-directory", error)


@mcp.tool()
async def read_unpacked_asset(relative_path: str, max_bytes: int = 65536, offset: int = 0) -> str:
    """Read one unpacked asset's bytes as text and as a printable-strings extract.

    Engine packages keep referenced texture names, class names and parameter names as
    plain strings in their header, which is usually all that is needed to confirm a
    match. Bounded and read-only; needs no catalog.
    """

    try:
        root, unused_status = _unpacked_asset_root()
        path = _unpacked_within(root, relative_path)
        if not path.is_file() or path.is_symlink():
            raise ValueError("relative_path is not a regular file inside the asset root")
        wanted = min(max(int(max_bytes), 256), UNPACKED_SEARCH_MAX_CONTENT_BYTES)
        start = max(int(offset), 0)
        size = path.stat().st_size
        with path.open("rb") as stream:
            stream.seek(start)
            blob = stream.read(wanted)
        strings = sorted({
            match.decode("ascii", "ignore")
            for match in re.findall(rb"[\x20-\x7e]{6,96}", blob)
        })
        wide = sorted({
            match.decode("utf-16-le", "ignore")
            for match in re.findall(rb"(?:[\x20-\x7e]\x00){6,96}", blob)
        })
        payload = {
            "schema": "replaylab-unpacked-asset-read/v1",
            "schemaVersion": 1,
            "relativePath": _unpacked_relative(root, path),
            "classification": await _read_unpacked_asset_description(root, path),
            "bytes": int(size),
            "offset": start,
            "returnedBytes": len(blob),
            "strings": strings[:400],
            "wideStrings": wide[:400],
            "moreBytes": start + len(blob) < size,
            "applied": False,
        }
        payload["contentSha256"] = await asyncio.to_thread(_file_sha256, path)
        return _ok_compact(payload)
    except Exception as error:
        return _active_project_error("read-unpacked-asset", error)


@mcp.tool()
async def wait_for_unpacked_asset_index(timeout_seconds: int = 20) -> str:
    """Wait (in slices) until the project's unpacked-asset index is complete.

    Asset matching is only trustworthy against a finished catalog: a partial one
    can miss the very asset a shader comes from. This joins or starts the scan and
    waits for up to ``timeout_seconds`` (1-60 per call) without blocking any other
    Host tool, then reports. ``indexing`` means it is still building and you should
    call again — a large tree takes several minutes and the scan continues between
    calls. ``stalled`` means the previous scan died before publishing; call
    ``index_active_unpacked_assets`` instead of waiting again.
    """

    try:
        budget = float(timeout_seconds)
        if not 1.0 <= budget <= ASSET_INDEX_WAIT_SLICE_SECONDS:
            raise ValueError(
                "timeout_seconds must be between 1 and %d; call again to keep waiting"
                % int(ASSET_INDEX_WAIT_SLICE_SECONDS))
        state = _asset_index_state()
        if state["state"] in {"absent", "ready", "failed", "stalled"}:
            state["schema"] = "replaylab-unpacked-asset-index-wait/v1"
            state["applied"] = False
            return _ok(state)
        unused_service, status, asset_root, database_path = _active_asset_catalog_context(
            require_catalog=False, create_dictionary=True)
        build_id = str(status.get("scope", {}).get("buildId", "") or "")
        _asset_index_job(database_path, asset_root, build_id)
        started = time.monotonic()
        deadline = started + budget
        while time.monotonic() < deadline:
            # asyncio.sleep, never time.sleep: a synchronous sleep here holds the whole
            # MCP server, and every other tool call (even ping) times out behind it.
            await asyncio.sleep(0.5)
            state = _asset_index_state()
            if state["state"] != "indexing":
                break
        state["schema"] = "replaylab-unpacked-asset-index-wait/v1"
        state["waitedSeconds"] = round(time.monotonic() - started, 1)
        state["applied"] = False
        return _ok(state)
    except Exception as error:
        return _active_project_error("wait-for-unpacked-asset-index", error)


def _workspace_asset_resolution_path(workspace_path: str | Path) -> Path:
    return Path(str(workspace_path)) / "ai" / ASSET_RESOLUTION_WORKSPACE_FILENAME


def _read_workspace_asset_resolution(workspace_path: str | Path) -> dict[str, Any] | None:
    path = _workspace_asset_resolution_path(workspace_path)
    try:
        if not path.is_file() or path.is_symlink():
            return None
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return payload if isinstance(payload, dict) else None


def _write_workspace_asset_resolution(workspace_path: str | Path, payload: Mapping[str, Any]) -> str:
    """Mirror asset retrieval/decisions into the workspace for the next conversation.

    The authoritative memory stays in the project's resolution store; this file
    is the fast local read: a resumed or brand-new task sees what was already
    matched without repeating retrieval.
    """

    path = _workspace_asset_resolution_path(workspace_path)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        existing = _read_workspace_asset_resolution(workspace_path) or {}
        merged = dict(existing)
        new_raw = str(payload.get("shaderRawSha256") or "").strip().lower()
        new_stage = normalize_stage(payload.get("stage"))
        if new_raw and new_stage:
            old_raw = str(existing.get("shaderRawSha256") or "").strip().lower()
            old_stage = normalize_stage(existing.get("stage"))
            try:
                old_event = int(existing.get("eventId") or 0)
            except (TypeError, ValueError):
                old_event = 0
            try:
                new_event = int(payload.get("eventId") or 0)
            except (TypeError, ValueError):
                new_event = 0
            same_identity = (
                old_raw == new_raw
                and old_stage == new_stage
                and (not new_event or old_event == new_event)
            )
            new_asset_binding = payload.get("assetBinding")
            old_asset_binding = existing.get("assetBinding")
            if isinstance(new_asset_binding, Mapping) and isinstance(old_asset_binding, Mapping):
                same_identity = same_identity and (
                    Path(str(new_asset_binding.get("assetRoot") or "")).resolve()
                    == Path(str(old_asset_binding.get("assetRoot") or "")).resolve()
                    and str(new_asset_binding.get("catalogSha256") or "").lower()
                    == str(old_asset_binding.get("catalogSha256") or "").lower()
                )
            if not same_identity:
                # Recovery/rebind may reuse a directory for a new capture
                # identity. Preserve the former decision only as a hint; it
                # cannot authorize names for the new Shader.
                prior = {
                    key: existing.get(key)
                    for key in (
                        "shaderRawSha256", "stage", "eventId",
                        "resolvedAssets", "rejected", "noSupportedMatch", "decidedAt",
                        "assetBinding", "materialSemanticContext",
                    )
                    if key in existing
                }
                if prior:
                    merged["previousResolutionHint"] = prior
                for key in (
                    "resolvedAssets", "rejected", "noSupportedMatch",
                    "decidedAt", "confidence", "assetBinding", "materialSemanticContext",
                ):
                    merged.pop(key, None)
        merged.update(dict(payload))
        merged["schema"] = "replaylab-shader-asset-resolution-record/v1"
        merged["updatedAt"] = datetime.now(timezone.utc).isoformat(timespec="seconds")
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_text(json.dumps(merged, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(temporary, path)
        return str(path)
    except OSError:
        return ""


def _shader_asset_authorization_identity(
    workspace_path: str | Path,
    event_id: int | None = None,
    stage: str = "",
    raw_sha256: str = "",
) -> dict[str, Any]:
    """Return only Host-owned, current resolution-store authority for this Shader."""

    empty: dict[str, Any] = {
        "schema": "replaylab-shader-asset-authorization/v1",
        "schemaVersion": 1,
        "current": False,
        "resolvedAssets": [],
        "noSupportedMatch": None,
    }
    try:
        remembered = _read_workspace_asset_resolution(workspace_path) or {}
        requested_event = int(event_id or remembered.get("eventId") or 0)
        if requested_event <= 0:
            return {**empty, "reason": "a positive selected EID is required"}
        requested_stage = normalize_stage(stage or remembered.get("stage"))
        identity, features = _shader_asset_capture_features(
            requested_event,
            requested_stage,
            pass_hint="",
            mesh_hint="",
            extra_tokens=[],
        )
        expected_raw = str(raw_sha256 or identity.get("rawSha256") or "").lower()
        if expected_raw != str(identity.get("rawSha256") or "").lower():
            return {**empty, "reason": "workspace/capture Shader bytes changed"}
        unused_service, status, asset_root, database_path = (
            _active_asset_catalog_context(require_catalog=True)
        )
        store = shader_asset_retrieval.ShaderAssetResolutionStore(
            database_path.parent / SHADER_ASSET_RESOLUTIONS_FILENAME
        )
        memory = store.lookup(
            _shader_asset_game_key(status, asset_root),
            identity["rawSha256"],
            features["structuralKey"],
            identity["stage"],
            identity["entryPoint"],
        )

        def same_identity(value: Any) -> bool:
            # Asset naming is about shader bytes + draw/stage, not the live UI
            # session. RenderDoc reassigns ResourceIds and mint a new
            # captureSessionId on every reopen; requiring either would force a
            # full asset re-scan after every restart even when the sealed
            # material/content evidence is unchanged.
            value = value if isinstance(value, Mapping) else {}
            return bool(
                int(value.get("eventId") or 0) == requested_event
                and normalize_stage(value.get("stage")) == normalize_stage(identity["stage"])
                and str(value.get("entryPoint") or "") == str(identity.get("entryPoint") or "")
                and str(value.get("rawSha256") or "").lower()
                == str(identity.get("rawSha256") or "").lower()
                and (
                    not identity.get("captureId")
                    or not value.get("captureId")
                    or str(value.get("captureId") or "").lower()
                    == str(identity.get("captureId") or "").lower()
                )
            )

        accepted: list[dict[str, Any]] = []
        final_negative: dict[str, Any] | None = None
        stale_reasons: list[str] = []
        rows = [*(memory.get("resolutions") or []), *(memory.get("rejected") or [])]
        for row in rows:
            if not isinstance(row, Mapping):
                continue
            if not _resolution_row_is_host_sealed(row):
                stale_reasons.append(
                    "asset resolution has no current Host provenance receipt"
                )
                continue
            evidence = row.get("evidence")
            evidence = evidence if isinstance(evidence, Mapping) else {}
            if not same_identity(evidence.get("shaderIdentity")):
                continue
            binding = evidence.get("assetBinding")
            if not isinstance(binding, Mapping):
                continue
            current, reason_text = _asset_evidence_binding_is_current(binding)
            if not current:
                stale_reasons.append(reason_text)
                continue
            if (
                str(row.get("catalogSha256") or "").lower()
                != str(binding.get("catalogSha256") or "").lower()
            ):
                continue
            if row.get("negative") is True:
                if (
                    row.get("assetRelativePath") == "__NO_SUPPORTED_MATCH__"
                    and evidence.get("finalNoSupportedMatch") is True
                    and isinstance(evidence.get("grounding"), Mapping)
                ):
                    final_negative = {
                        "resolutionId": row.get("resolutionId"),
                        "finalNoSupportedMatch": True,
                        "confidence": row.get("confidence"),
                        "rationale": row.get("rationale"),
                    }
                continue
            reader_proof = evidence.get("readerProof")
            if not isinstance(reader_proof, Mapping) or not reader_proof:
                continue
            if (
                str(row.get("assetContentSha256") or "").lower()
                != str(binding.get("assetContentSha256") or "").lower()
            ):
                continue
            accepted.append({
                "resolutionId": row.get("resolutionId"),
                "assetRelativePath": row.get("assetRelativePath"),
                "assetContentSha256": row.get("assetContentSha256"),
                "assetClass": row.get("assetClass"),
                "confidence": row.get("confidence"),
                "rationale": row.get("rationale"),
                "assetBinding": binding,
                "readerProof": reader_proof,
            })
        current = bool(accepted or final_negative)
        authority = {
            **empty,
            "current": current,
            "identity": identity,
            "resolvedAssets": accepted,
            "noSupportedMatch": final_negative,
            "staleReasons": list(dict.fromkeys(item for item in stale_reasons if item))[:8],
            "workspaceMirrorAuthority": False,
        }
        authority["authorizationSha256"] = _canonical_json_sha256(
            {key: value for key, value in authority.items() if key != "authorizationSha256"},
            "Shader asset authorization",
        )
        return authority
    except Exception as error:
        return {**empty, "reason": str(error)[:400]}


def _shader_asset_debug(features: Mapping[str, Any], retrieval: Mapping[str, Any]) -> dict[str, Any]:
    """Per-channel availability and limitation facts."""

    channels: dict[str, Any] = {}
    limitations: list[str] = []
    names = [item for item in features.get("boundTextureNames") or [] if item]
    channels["names"] = {"boundTextureNames": len(names), "note": "reference only; stripped in most shipped captures"}
    if not names:
        limitations.append("no texture debug names were present in this capture")
    fp_status = features.get("textureFingerprintStatus") or {}
    fingerprints = features.get("boundTextureFingerprints") or []
    channels["texturePixels"] = {"status": fp_status.get("status"), "snapshots": sum(1 for f in fingerprints if f.get("available")),
                                 "failed": [{"texture": f.get("name") or f.get("resourceId"), "reason": f.get("reason")}
                                            for f in fingerprints if not f.get("available")][:8]}
    identity = (retrieval.get("signals") or {}).get("textureIdentity") or []
    unmatched = [item for item in identity if not item.get("matches")]
    if fingerprints and unmatched and len(unmatched) == len(identity):
        limitations.append("no bound texture matched an indexed fingerprint; textures may be in unindexed bulk files, generated at runtime, or use an unsupported format")
    cb = features.get("constantBufferValueStatus") or {}
    lanes = features.get("constantBufferLanes") or []
    channels["cbufferValues"] = {"status": cb.get("status"), "distinctiveLanes": len(lanes),
                                 "blocks": cb.get("blocks")}
    if not lanes:
        limitations.append("no distinctive constant-buffer values were readable; value matching was inactive for this draw")
    geometry = features.get("drawGeometry") or {}
    channels["geometry"] = {"available": geometry.get("available"), "meshHint": geometry.get("meshHint"),
                            "indexCount": geometry.get("indexCount"), "vertexInputs": len(geometry.get("vertexInputs") or [])}
    channels["codeHints"] = features.get("codeHints") or {}
    candidates = retrieval.get("candidates") or []
    if not candidates:
        limitations.append("no candidate was produced by any Host evidence channel")
    elif retrieval.get("decisionHint", "").startswith("ambiguous"):
        limitations.append("candidate ranking is ambiguous")
    if isinstance(features.get("codeHints"), Mapping) and features["codeHints"].get("unavailable"):
        limitations.append("code hints were unavailable because no workspace source existed")
    return {"channels": channels, "limitations": limitations}


@mcp.tool()
def retrieve_shader_asset_candidates(
    event_id: int,
    stage: str = "fragment",
    top_k: int = 8,
    pass_hint: str = "",
    mesh_hint: str = "",
    extra_tokens: list[str] | None = None,
    force_search: bool = False,
    workspace_path: str = "",
    require_complete_index: bool = False,
    scope_prefixes: list[str] | None = None,
) -> str:
    """Find the unpacked asset (material / material instance / shader source) behind a captured shader.

    Folder-scoped, content-matched, and tolerant. ``scope_prefixes`` limits
    on-demand parsing to selected folders rather than the whole tree.
    Candidates are ranked by what can be compared -- the
    draw's constant-buffer values against material parameter values, the bound
    textures' pixels against asset textures, the shader map / vertex factory /
    blend mode against the code, the mesh kind -- plus the reader's own words
    (``extra_tokens``: what the user said, what the draw shows). Texture debug
    names from the capture are *not* used for ranking; shipped games do not
    carry asset names. A disagreeing check lowers a score, it never drops a
    candidate. Each candidate returns a compact document and its checks so
    evidence behind each score is returned. A remembered decision
    for this shader (or a same-shape suggestion) is returned first;
    ``force_search`` re-runs retrieval anyway. Resolution submission accepts
    ``links_json`` for texture / cbuffer / mesh correspondences.
    Nothing here mutates replay state.
    """

    try:
        # Matching against a half-built catalog is how a shader gets named after the
        # wrong material. Report the gate instead, so the Agent waits and retries.
        if require_complete_index:
            gate = _asset_index_state()
            if gate["state"] in {"indexing", "stalled"}:
                return _ok({
                    "schema": "replaylab-shader-asset-candidates/v1", "schemaVersion": 1, "ready": False,
                    "assetGate": gate,
                    "reason": ("the unpacked-asset catalog is still being built"
                               if gate["state"] == "indexing"
                               else "the last unpacked-asset scan stopped before it completed"),
                    "state": "catalog-incomplete",
                    "blockingConditions": ["complete-index-required"],
                    "availableCapabilities": [
                        "search_unpacked_assets",
                        "list_unpacked_asset_directory",
                        "read_unpacked_asset",
                        "retrieve_shader_asset_candidates",
                    ],
                    "applied": False,
                })
        try:
            service, status, asset_root, database_path, indexing = _ensure_shader_asset_catalog()
        except _AssetCatalogNotReady as pending:
            return _ok({
                "schema": "replaylab-shader-asset-candidates/v1", "schemaVersion": 1, "ready": False,
                "indexing": pending.receipt,
                "reason": "the unpacked-asset catalog is still being built on first use",
                "state": "catalog-indexing",
                "availableCapabilities": [
                    "get_host_runtime_status",
                    "retrieve_shader_asset_candidates",
                ],
                "applied": False,
            })
        except Exception as error:
            # No configured/available asset root is a normal state, not a
            # failure: report it so the Agent continues without asset evidence.
            return _ok({
                "schema": "replaylab-shader-asset-candidates/v1", "schemaVersion": 1, "ready": False,
                "reason": str(error)[:300],
                "state": "asset-root-unavailable",
                "blockingConditions": ["active-project-asset-root-unavailable"],
                "availableCapabilities": ["configure_active_project_asset_root"],
                "applied": False,
            })
        identity, features = _shader_asset_capture_features(
            int(event_id), stage, pass_hint=pass_hint, mesh_hint=mesh_hint, extra_tokens=extra_tokens or [])
        catalog = AssetCatalogService(database_path)
        game_key = _shader_asset_game_key(status, asset_root)
        store = shader_asset_retrieval.ShaderAssetResolutionStore(
            database_path.parent / SHADER_ASSET_RESOLUTIONS_FILENAME)
        memory = store.lookup(game_key, identity["rawSha256"], features["structuralKey"],
                              identity["stage"], identity["entryPoint"])
        result: dict[str, Any] = {
            "schema": "replaylab-shader-asset-candidates/v1",
            "schemaVersion": 1,
            "gameKey": game_key,
            "identity": identity,
            "features": features,
            "memory": memory,
            "indexing": indexing,
            "retrieval": None,
        }
        if indexing.get("partial"):
            result["partialCatalog"] = {
                "note": ("candidates come from a checkpoint of an unfinished scan (%s assets so far); "
                         "usable now, retry later for full coverage" % indexing.get("assetCount")),
                "indexing": indexing.get("indexing"),
            }
        # ``scope`` is also used below to decide whether an empty result covered
        # the complete catalog. Keep it defined on the remembered-resolution
        # path: the remembered asset may have disappeared after a catalog rebuild.
        scope = [
            str(item)
            for item in (scope_prefixes or [])
            if isinstance(item, str) and item.strip()
        ][:64]
        if memory.get("resolved") and not force_search:
            resolution = memory["resolution"]
            try:
                found = catalog.query(text=PurePosixPath(str(resolution["assetRelativePath"])).name,
                                      limit=20, include_relationships=False)
                asset = next((item for item in found.get("assets", [])
                              if str(item.get("relativePath")) == resolution["assetRelativePath"]), None)
            except Exception:
                asset = None
            result["resolvedDocument"] = (
                shader_asset_retrieval._material_document(catalog, asset) if asset else None)
            result["resolvedAssetStillPresent"] = asset is not None
            result["state"] = "remembered-resolution"
            result["availableCapabilities"] = [
                "submit_shader_asset_resolution",
                "retrieve_shader_asset_candidates",
            ]
        else:
            # Targeted first: read the files the chosen folders and the reader's
            # words point at, then rank by content agreement.
            result["targeted"] = _targeted_asset_hydration(catalog, asset_root, features, scope)
            if result["targeted"].get("hydrated"):
                catalog = AssetCatalogService(database_path)
            retrieval = shader_asset_retrieval.retrieve(catalog, features, top_k=top_k, scope_prefixes=scope)
            # Hydrate candidates whose cooked export data was deferred so the
            # document carries shader types/defines before the decision.
            pending = [
                PurePosixPath(str(item["relativePath"])).with_suffix(".uexp").as_posix()
                for item in retrieval.get("candidates", [])
                if str(item.get("relativePath", "")).endswith((".uasset", ".umap"))
                and item.get("document", {}).get("exportParseStatus") == "deferred"
            ]
            # A few pixel matches already provide a useful exact index scope.
            # Decode only unread documents reached by those relationships or
            # adjacent indexed paths; never wait for every bound texture.
            expansion = (retrieval.get("signals") or {}).get("anchorExpansion") or {}
            for candidate in list(expansion.get("candidates") or []) + list(expansion.get("pathCandidates") or []):
                relative = str(candidate.get("relativePath") or "")
                if not relative or candidate.get("parseStatus") != "deferred":
                    continue
                if scope and not shader_asset_retrieval._in_scope(relative, [
                        str(prefix).replace("\\", "/").strip("/").casefold() + "/" for prefix in scope]):
                    continue
                pending.append(relative)
                if relative.endswith((".uasset", ".umap")):
                    pending.append(PurePosixPath(relative).with_suffix(".uexp").as_posix())
            pending = list(dict.fromkeys(pending))[:16]
            if pending:
                try:
                    started = time.monotonic()
                    catalog.hydrate(asset_root, pending[:16])
                    catalog = AssetCatalogService(database_path)
                    retrieval = shader_asset_retrieval.retrieve(catalog, features, top_k=top_k, scope_prefixes=scope)
                    indexing["hydrated"] = {"paths": pending[:16], "seconds": round(time.monotonic() - started, 1)}
                except Exception as error:
                    indexing["hydrated"] = {"error": str(error)[:200]}
            # Structure memory: shaders with the same cbuffer sizes / texture
            # counts that were already resolved point at their material family.
            suggestions = memory.get("sameShapeSuggestions") or []
            if suggestions:
                by_path = {str(item.get("assetRelativePath")): item for item in suggestions}
                for candidate in retrieval.get("candidates", []):
                    hit = by_path.get(str(candidate.get("relativePath")))
                    if hit is not None:
                        candidate["facets"]["structure"] = {
                            "sameShapeAsShader": hit.get("shaderRawSha256"), "confidence": hit.get("confidence"),
                            "note": "a shader with identical cbuffer sizes/texture counts was resolved to this asset before"}
                        candidate["adjustedScore"] = round(float(candidate.get("adjustedScore") or 0) + 4.0, 4)
                        candidate["confidence"] = round(min(0.95, max(float(candidate.get("confidence") or 0), 0.5 + 0.4 * float(hit.get("confidence") or 0))), 3)
                        candidate["why"] += "; same structural shape as a previously resolved shader of this family"
                retrieval["candidates"].sort(key=lambda item: -float(item.get("adjustedScore") or 0))
                retrieval["structureSuggestions"] = [
                    {"assetRelativePath": item.get("assetRelativePath"), "confidence": item.get("confidence"),
                     "fromShader": item.get("shaderRawSha256"), "decidedBy": item.get("decidedBy")} for item in suggestions[:5]]
            retrieval["debug"] = _shader_asset_debug(features, retrieval)
            result["retrieval"] = retrieval
            result["state"] = (
                "candidates-ready"
                if retrieval.get("candidates")
                else "no-candidates"
            )
            result["availableCapabilities"] = [
                "submit_shader_asset_resolution",
                "retrieve_shader_asset_candidates",
            ]
        workspace = str(workspace_path or "").strip()
        if workspace and Path(workspace).is_dir():
            leaders = [
                {
                    "assetRelativePath": item.get("relativePath"),
                    "confidence": item.get("confidence"),
                    "why": str(item.get("why", ""))[:400],
                }
                for item in ((result.get("retrieval") or {}).get("candidates") or [])[:8]
            ]
            written = _write_workspace_asset_resolution(
                workspace,
                {
                    "candidates": leaders,
                    "identityLinks": _identity_links(result.get("retrieval") or {}),
                    "shaderRawSha256": identity["rawSha256"],
                    "stage": identity["stage"],
                    "eventId": int(event_id),
                    "indexComplete": _asset_index_state().get("state") == "ready",
                },
            )
            if written:
                result["workspaceRecordPath"] = written
        result["applied"] = False
        candidates_present = bool(
            (result.get("retrieval") or {}).get("candidates")
            if isinstance(result.get("retrieval"), Mapping)
            else False
        )
        texture_identity_links = [
            dict(link) for link in _identity_links(result.get("retrieval") or {})
            if isinstance(link, Mapping)
        ]
        if texture_identity_links:
            result["textureIdentityLinks"] = texture_identity_links[:32]
        resolved_present = bool(
            result.get("resolvedDocument") and result.get("resolvedAssetStillPresent") is True
        )
        if not resolved_present and not candidates_present:
            complete_catalog = bool(
                not scope
                and not indexing.get("partial")
                and catalog.status().get("complete") is True
            )
            if complete_catalog:
                result["searchCoverage"] = {
                    "supported": True,
                    "started": True,
                    "outcome": "no-match",
                    "readerId": "shader-asset-catalog-retrieval",
                    "coverage": {
                        "completeCatalog": True,
                        "narrowed": False,
                    },
                }
        return _ok(result)
    except Exception as error:
        return _active_project_error("retrieve-shader-asset-candidates", error)


def _named_event_ids(value: Any, *, name: str, limit: int = 16) -> list[int]:
    """Read a list of event ids from a JSON array or a comma-separated string."""

    if value in (None, "", [], ()):
        return []
    items: Any = value
    if isinstance(value, str):
        text = value.strip()
        items = json.loads(text) if text.startswith("[") else text.replace(";", ",").split(",")
    if not isinstance(items, (list, tuple)):
        raise ValueError("%s must be a list of event ids" % name)
    out: list[int] = []
    for item in items:
        if isinstance(item, str) and not item.strip():
            continue
        number = int(item)
        if number <= 0:
            raise ValueError("%s contains %r, which is not an event id" % (name, item))
        if number not in out:
            out.append(number)
    return out[:limit]


def _blocks_for_event(ipc: Any, event_id: int, stage_name: str) -> list[Mapping[str, Any]]:
    values = ipc.call("get_constant_buffer_values",
                      {"event_id": int(event_id), "stage": stage_name}, timeout=60.0)
    if not isinstance(values, Mapping):
        raise RuntimeError("constant-buffer values returned an invalid response")
    if values.get("error") or not isinstance(values.get("constantBuffers"), list):
        raise RuntimeError(str(values.get("error") or "constant-buffer values are unavailable"))
    return [item for item in (values.get("constantBuffers") or []) if isinstance(item, Mapping)]


def _block_label(block: Mapping[str, Any]) -> str:
    return "b%s:s%s" % (block.get("bind"), block.get("space"))


async def _variance_by_block(ipc: Any, event_ids: Sequence[int],
                             stage_name: str) -> dict[str, Any]:
    """The same constant buffer read from several draws, one entry per block."""

    from . import shader_anchors

    samples: dict[str, list[dict[str, Any]]] = {}
    for event_id in event_ids:
        for block in await asyncio.to_thread(_blocks_for_event, ipc, event_id, stage_name):
            samples.setdefault(_block_label(block), []).append(
                {"eventId": int(event_id), "floats": list(block.get("floats") or [])})
    return {label: shader_anchors.lane_variance(rows) for label, rows in samples.items()}


@mcp.tool()
async def profile_constant_buffer_variance(event_ids: str, stage: str = "fragment") -> str:
    """Report how constant-buffer lanes vary across several captured draws.

    A block bound to many draws holds different kinds of thing side by side, and
    they give themselves away by how they behave. Read the same block from a
    handful of events and the lanes separate: the ones that change every draw, and
    the ones that do not.

    Semantic classification depends on the caller-selected cohort. For example:

    * draws of the **same material** (the same object, or several objects sharing
      it): a lane that changes is per-object data -- a transform, an instance
      value, time -- and cannot be a material parameter.
    * draws of **different materials** through the same shader: a lane that does
      *not* change is a frame or view constant and cannot be one either.

    The Host reports observed values and differences; it does not decide which
    cohort relationship applies. This operation does not require unpacked assets.
    """

    try:
        wanted = _named_event_ids(event_ids, name="event_ids")
        if len(wanted) < 2:
            raise ValueError("give at least two event ids: nothing can be said to vary from one draw")
        stage_name = normalize_stage(stage)
        by_block = await _variance_by_block(ipc, wanted, stage_name)
        if not by_block:
            raise ValueError("none of those events bind a constant buffer at this stage")
        return _ok_compact({
            "schema": "replaylab-constant-buffer-variance/v1",
            "schemaVersion": 1,
            "stage": stage_name,
            "eventIds": wanted,
            "blocks": by_block,
            "facts": {
                "semanticClassificationProvided": False,
                "classificationDependsOnCallerSelectedCohort": True,
            },
            "availableCapabilities": ["propose_shader_names_from_asset"],
            "applied": False,
        })
    except Exception as error:
        return _shader_err(error, "constant-buffer-variance")


_CBUFFER_BLOCK = re.compile(
    r"cbuffer\s+(?P<name>[A-Za-z_]\w*)\s*:\s*register\s*\(\s*b(?P<bind>\d+)"
    r"(?:\s*,\s*space(?P<space>\d+))?\s*\)\s*\{(?P<body>[^}]*)\}", re.S)
_CBUFFER_MEMBER = re.compile(
    r"(?P<type>[A-Za-z_]\w*)\s+(?P<name>[A-Za-z_]\w*)\s*:\s*packoffset\s*\("
    r"\s*c(?P<register>\d+)(?:\.(?P<component>[xyzw]))?\s*\)\s*;")
_RESOURCE_SLOT = re.compile(
    r"(?P<type>[A-Za-z_]\w*(?:\s*<[^>;]*>)?)\s+(?P<name>[A-Za-z_]\w*)\s*:\s*register\s*\("
    r"\s*t(?P<slot>\d+)(?:\s*,\s*space(?P<space>\d+))?\s*\)\s*;")


def _workspace_declarations(workspace_path: str) -> dict[str, Any]:
    """What the organized HLSL actually declares: cbuffer lanes and texture slots.

    This is the missing half of a proposal. A name is only applicable where there
    is an identifier to rename, and a cooked shader declares **only the lanes it
    reads** -- a 132-lane block routinely shows three members. So the Host reports
    which proposals land on a declared member (rename those now) and which land on
    a lane this shader never touches (nothing to rename; the name is still true,
    it just has nowhere to go in this source).
    """

    try:
        status = _shader_workspace_service().status(workspace_path)
        source_path = Path(str(((status.get("source") or {}).get("path")) or ""))
        if not source_path.is_file():
            return {"available": False, "reason": "the workspace has no editable HLSL yet"}
        if (status.get("source") or {}).get("format") == "glsl":
            return {"available": False, "sourceFormat": "glsl",
                    "reason": "GLSL linked uniform/interface names are preserved; publish captured-layout "
                              "CBuffer aliases and use material names in comments/local symbols. "
                              "A material parameter list does not prove std140/std430 member offsets."}
        text = source_path.read_text(encoding="utf-8", errors="replace")
    except Exception as error:  # noqa: BLE001 - a missing workspace is not a failure here
        return {"available": False, "reason": str(error)[:200]}
    from .shader_workspace.quality import declared_binding_inventory

    inventory = declared_binding_inventory(text)
    lanes: dict[tuple[int, int, int], str] = {}
    for item in inventory:
        if item.get("kind") != "member":
            continue
        bind, offset = item.get("bind"), item.get("byteOffset")
        if (not isinstance(bind, int) or isinstance(bind, bool) or bind < 0
                or not isinstance(offset, int) or isinstance(offset, bool) or offset < 0
                or offset % 4):
            continue
        lanes[(int(item.get("space") or 0), bind, offset // 4)] = str(item["renameSelector"])
    slots = {
        (int(item.get("space") or 0), int(item["bind"])): str(item["renameSelector"])
        for item in inventory
        if item.get("kind") == "texture"
        and isinstance(item.get("bind"), int) and not isinstance(item.get("bind"), bool)
        and item.get("bind", -1) >= 0
    }
    return {"available": True, "cbufferLanes": lanes, "textureSlots": slots,
            "declaredLaneCount": len(lanes), "declaredSlotCount": len(slots),
            "declaredBindings": inventory}


def _identity_links(retrieval: Mapping[str, Any]) -> list[dict[str, Any]]:
    """Bound textures whose pixels were matched to an asset, kept for the naming step.

    A texture identified by its own image is the anchor that survives translation
    best -- repacking, recompression and an engine upgrade all leave the picture
    recognisable while every float in the frame drifts. Remembering which resource
    that was means the next step can place the material's texture array without
    asking the Agent to re-derive what retrieval already proved.
    """

    signals = retrieval.get("signals") if isinstance(retrieval, Mapping) else None
    per_texture = (signals or {}).get("textureIdentity") if isinstance(signals, Mapping) else None
    out: list[dict[str, Any]] = []
    for entry in per_texture or ():
        if not isinstance(entry, Mapping):
            continue
        resource_id = entry.get("resourceId")
        best = None
        for match in entry.get("matches") or ():
            if isinstance(match, Mapping) and match.get("verdict") == "same-image":
                if best is None or float(99 if match.get("distance") is None else match["distance"]) < \
                        float(99 if best.get("distance") is None else best["distance"]):
                    best = match
        if best is None or resource_id in (None, ""):
            continue
        out.append({
            "resourceId": resource_id,
            "asset": str(best.get("ownerPath") or best.get("relativePath") or ""),
            "distance": best.get("distance"),
            "why": "the bound image and the asset's are the same picture (hash distance %s)"
                   % best.get("distance"),
        })
    return out[:32]


def _material_semantic_delivery(
    material: Mapping[str, Any], workspace_path: str, event_id: int, stage: str,
    asset_path: str, recorded: Mapping[str, Any], selected: Mapping[str, Any] | None,
    members: Mapping[str, Any], slots: Mapping[str, Any], notes: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Keep unmatched parameters useful without another capture/reader request."""
    from .shader_asset_semantics import build_material_semantic_context, semantic_context_summary

    identity = dict(recorded.get("identity") or {})
    identity.update(eventId=event_id, stage=stage)
    project_id = ""
    binding = dict((selected or {}).get("assetBinding") or {})
    binding["assetRelativePath"] = asset_path or str((selected or {}).get("assetRelativePath") or "")
    local_project = None
    diagnostics = []
    try:
        service, project_root, manifest = _local_shader_asset_project()
        if workspace_path and not is_within(project_root, Path(workspace_path).resolve()):
            raise ValueError("material semantic workspace is outside the active project")
        local_project = (service, project_root, manifest)
        project_id = str(manifest.get("workspaceId") or "")
        binding.setdefault("assetRoot", str(manifest.get("assetRoot") or ""))
    except Exception as error:
        diagnostics.append("local project: " + str(error)[:200])
    if local_project and workspace_path and Path(workspace_path).is_dir() and not identity.get("rawSha256"):
        try:
            local = _shader_organization_semantic_context(workspace_path, event_id)
            identity.update({key: local.get(key) for key in ("captureId", "rawSha256", "entryPoint")})
            identity["shaderResourceId"] = (local.get("shader") or {}).get("resourceId")
        except Exception as error:
            diagnostics.append("local Shader identity: " + str(error)[:200])
    context = build_material_semantic_context(
        material, identity=identity, project_id=project_id, asset_binding=binding,
        member_candidates=members.get("proposals") or [],
        texture_candidates=slots.get("proposals") or [], agent_notes=notes,
        parameter_localization=members.get("parameterLocalization"))
    result = {"materialSemanticContext": context}
    path = ""
    if local_project and workspace_path and Path(workspace_path).is_dir():
        path = _write_workspace_asset_resolution(workspace_path, {"materialSemanticContext": context})
        if path:
            result["materialSemanticContextPath"] = path
    result["materialSemanticContextSummary"] = semantic_context_summary(context, path)
    # Enrich an existing positive association in place. Do not manufacture an
    # asset match merely because the Agent supplied a parameter document.
    if local_project and selected and identity.get("rawSha256"):
        try:
            service, project_root, manifest = local_project
            database = (Path(service._paths(project_root)["sharedDictionaries"]) / "assets"
                        / SHADER_ASSET_RESOLUTIONS_FILENAME)
            if database.is_file():
                store = shader_asset_retrieval.ShaderAssetResolutionStore(database)
                game_key = _shader_asset_game_key(manifest, Path(str(manifest.get("assetRoot") or "")))
                memory = store.lookup(game_key, identity["rawSha256"], "", stage,
                                      str(identity.get("entryPoint") or ""))
                for row in memory.get("resolutions") or []:
                    if row.get("resolutionId") != selected.get("resolutionId"):
                        continue
                    evidence = dict(row.get("evidence") or {})
                    evidence["materialSemanticContext"] = context
                    evidence = _seal_resolution_evidence(row, evidence)
                    store.record(
                        game_key=game_key, shader_raw_sha256=row["shaderRawSha256"],
                        structural=row["structuralKey"], stage=row["stage"], entry_point=row["entryPoint"],
                        asset_relative_path=row["assetRelativePath"], asset_content_sha256=row["assetContentSha256"],
                        asset_class=row["assetClass"], catalog_sha256=row["catalogSha256"],
                        negative=False, confidence=row["confidence"], decided_by=row["decidedBy"],
                        rationale=row["rationale"], evidence=evidence)
                    break
        except Exception as error:
            diagnostics.append("shared material context: " + str(error)[:200])
    if diagnostics:
        result["materialSemanticContextDiagnostics"] = diagnostics
    return result


@mcp.tool()
async def propose_shader_names_from_asset(
    event_id: int, stage: str = "fragment", workspace_path: str = "",
    asset_path: str = "", material_json: str = "", fill_gaps: bool = True,
    provisional_suffix: str = "_u", anchors_json: str = "",
    same_material_event_ids: str = "", other_material_event_ids: str = "",
    packings: str = "", relations: str = "", parameter_source: str = "",
    reader_operation: str = "", reader_arguments: dict | None = None,
    semantic_notes_json: str = "",
    reuse_material_context: bool = False,
) -> str:
    """Propose semantic names using capture offsets and parsed material evidence.

    Read the selected material and its parent/reference chain with a proved reader
    first. Pass its document as material_json or use asset_path/reader_operation.
    Unreal, Unity and explicit {scalars, vectors, textures} documents are supported;
    parameter_source selects a reader when more than one shape is present.

    With reuse_material_context=True, reuse the already-read exact-Shader material
    dictionary in workspace ai/asset-resolution.json and compare current CBuffer
    values once, without rereading assets. No prior offset is reused. The returned
    parameterLocalization accounts for EVERY numeric parameter, including common
    defaults, split vector components, ambiguous locations and unmatched values.
    Corroborate candidate positions using Shader consumers or compiled fields;
    use supported original names first, then infer remaining roles. A dictionary
    read alone is not a completed per-parameter offset investigation.

    Captured reflection and shader accesses determine physical bindings and byte
    offsets. Distinctive scalars and nontrivial vectors can support value
    candidates. Vector value equality does not prove parameter output width:
    a float2 followed by two unrelated scalars can equal a serialized float4.
    Repeated/default values cannot establish identity alone. Texture names require
    individual content/binding evidence; material array order is not a GPU layout.

    anchors_json may supply observations with their reasons. An Agent-confirmed
    texture content match may be published when its anchor includes
    contentMatch=true, asset, evidenceKind, resourceId, bindPoint and space and
    those fields identify exactly one parameter and exactly one current live
    binding. Ordered-window alignments and layout hypotheses remain provisional;
    they do not become physical proof simply because the model supplied them. Use
    fill_gaps=False for independently matched names only. Automatic renames and
    alias rows omit autoApplyEligible=false candidates. Resolve withheldRenames
    through parameter-to-output metadata before publishing those names; a
    provisional suffix does not substitute for evidence about component ownership.

    packings limits candidate layouts (d3d-cbuffer,std140,std430,metal,tight).
    These are hypotheses to compare with actual offsets, not engine-wide rules.
    relations selects exact,float16,near,srgb-to-linear,linear-to-srgb,one-minus.
    float16 tests value quantization; it does not decode packed 16-bit storage.
    Color conversions require evidence about the actual channel/color space.
    Packed fields require captured type/bit-layout evidence and explicit decoding.

    same_material_event_ids/other_material_event_ids supply variance observations,
    which narrow hypotheses but do not prove per-frame or per-object ownership.
    Non-finite or implausible float interpretations are excluded from this float
    matcher without claiming that their raw bits necessarily represent integers.
    An ambiguous position remains a candidate; its material name/value is retained
    in materialSemanticContext for Agent reasoning about functions and calculations.
    semantic_notes_json optionally records a bounded array of Agent hypotheses
    (parameter, sourceSymbol, suggestedName, role, reason, evidence). These remain
    semantic hints, not verified physical aliases, including after reuse.

    rename_shader_workspace_symbols changes source identifiers in the resumable
    organization proposal. publish_cbuffer_aliases publishes display rows, including
    rows not declared by the source; inspect actual written/skipped receipts.
    submit_shader_asset_resolution records the material and per-binding texture
    links for reuse. Neither a proposal nor a stored decision means it was applied.
    """

    try:
        from . import material_naming

        semantic_notes = []
        if semantic_notes_json:
            if len(semantic_notes_json.encode("utf-8")) > 32768:
                raise ValueError("semantic_notes_json exceeds 32 KiB")
            semantic_notes = json.loads(semantic_notes_json)
            if not isinstance(semantic_notes, list) or any(not isinstance(item, dict) for item in semantic_notes):
                raise ValueError("semantic_notes_json must be an array of objects")

        if type(event_id) is not int or isinstance(event_id, bool) or event_id <= 0:
            raise ValueError("event_id must be a positive integer")
        stage_name = normalize_stage(stage)

        remembered = _read_workspace_asset_resolution(workspace_path) or {} if workspace_path else {}
        recorded_evidence = (
            _shader_asset_authorization_identity(workspace_path, event_id, stage_name)
            if workspace_path and not reuse_material_context else {}
        )

        def resolved_path(value: Any) -> str:
            if isinstance(value, str):
                return value.strip()
            if isinstance(value, Mapping):
                for key in ("assetRelativePath", "assetPath", "relativePath"):
                    path = value.get(key)
                    if isinstance(path, str) and path.strip():
                        return path.strip()
            return ""

        hinted = remembered.get("resolvedAssets") or []
        hinted = [(resolved_path(item), item) for item in hinted
                  if resolved_path(item)] if isinstance(hinted, list) else []
        current_recorded = (
            recorded_evidence.get("resolvedAssets")
            if isinstance(recorded_evidence, Mapping)
            and recorded_evidence.get("current") is True else []
        )
        current_recorded = [
            (resolved_path(item), item) for item in (current_recorded or [])
            if isinstance(item, Mapping) and resolved_path(item)
        ]
        resolved = current_recorded or hinted
        selected_resolution: Mapping[str, Any] | None = None
        wanted = str(asset_path or "").strip()
        explicit_matches = [item for path, item in current_recorded if path == wanted] if wanted else []
        if len(explicit_matches) == 1 and isinstance(explicit_matches[0], Mapping):
            selected_resolution = explicit_matches[0]

        document: Any = None
        cached_material = None
        source = ""
        receipt: Mapping[str, Any] | None = None
        text = str(material_json or "").strip()
        if reuse_material_context:
            if text or wanted or reader_operation or reader_arguments:
                raise ValueError("reuse_material_context uses the retained dictionary only; omit explicit asset/reader inputs")
            from .material_parameter_localization import material_from_semantic_context
            from .shader_asset_semantics import assess_material_semantic_context
            previous = remembered.get("materialSemanticContext")
            unused_service, project_root, project = _local_shader_asset_project()
            if not workspace_path or not is_within(project_root, Path(workspace_path).resolve()):
                raise ValueError("Retained material context must belong to the active project workspace")
            current_identity = dict(recorded_evidence.get("identity") or {})
            local_identity = _shader_organization_semantic_context(workspace_path, event_id)
            current_identity.update(local_identity)
            selected_capture = _active_capture_catalog_selection(event_id, stage_name)
            if selected_capture is None:
                raise ValueError("No current catalog covers this EID/stage; resolve the active Shader workspace once")
            unused_catalog, unused_path, selected_shader, unused_binding = selected_capture
            if selected_shader.key.raw_sha256 != current_identity.get("rawSha256"):
                raise ValueError("Retained material dictionary does not belong to the current EID Shader")
            live_context = await asyncio.to_thread(_active_live_context, allow_missing_capture_id=True)
            current_identity.update(captureId=selected_shader.capture_id,
                captureSessionId=live_context["capture"]["captureSessionId"],
                captureApi=live_context["capture"].get("api", ""),
                shaderResourceId=selected_shader.key.resource_id)
            current_identity.update(eventId=event_id, stage=stage_name)
            recorded_evidence = {"identity": current_identity, "current": False, "resolvedAssets": []}
            assessed = assess_material_semantic_context(previous or {}, identity=current_identity,
                project_id=str(project.get("workspaceId") or ""), asset_root=str(project.get("assetRoot") or ""))
            if assessed["reuse"]["scope"] == "stale":
                raise ValueError("Retained material context is stale: " + ", ".join(assessed["reuse"]["reasons"]))
            cached_material = material_from_semantic_context(assessed)
            wanted = str((previous.get("binding") or {}).get("assetRelativePath") or "")
            exact = [item for path, item in current_recorded if path == wanted]
            selected_resolution = exact[0] if len(exact) == 1 else {
                "assetBinding": dict(previous.get("binding") or {})}
            source = "retained-material-dictionary"
        elif text:
            document = json.loads(text)
            source = "material_json"
            if not wanted and len(current_recorded) == 1:
                selected_resolution = current_recorded[0][1]
        else:
            if not wanted and len(resolved) > 1:
                return _ok({
                    "schema": material_naming.SCHEMA, "schemaVersion": 1,
                    "ready": False, "reason": "multiple-resolved-assets",
                    "assetCandidates": [{"assetPath": path} for path, unused in resolved],
                    "applied": False,
                })
            if not wanted and len(resolved) == 1:
                wanted, unused_selected = resolved[0]
                exact = [item for path, item in current_recorded if path == wanted]
                selected_resolution = exact[0] if len(exact) == 1 else None
            if not wanted:
                raise ValueError(
                    "no material to read: pass asset_path (the virtual path of the resolved "
                    "material), or material_json, or a workspace_path whose resolution names one")
            receipt = await _read_material_asset(
                wanted, reader_operation=reader_operation, reader_arguments=reader_arguments)
            if not receipt.get("succeeded"):
                return _ok({
                    "schema": material_naming.SCHEMA, "schemaVersion": 1,
                    "ready": False, "asset": wanted, "receipt": receipt,
                    "applied": False,
                })
            document = receipt["document"]
            source = str(receipt.get("source") or "asset-reader")

        material = cached_material or material_naming.parse_material_parameters(
            document, source=str(parameter_source or "").strip())
        blocks = await asyncio.to_thread(_blocks_for_event, ipc, event_id, stage_name)
        suffix = str(provisional_suffix or "")[:16]
        supplied_anchors: Any = ()
        anchor_text = str(anchors_json or "").strip()
        if anchor_text:
            supplied_anchors = json.loads(anchor_text)
        same_ids = _named_event_ids(same_material_event_ids, name="same_material_event_ids")
        other_ids = _named_event_ids(other_material_event_ids, name="other_material_event_ids")
        from . import shader_anchors

        wanted_packings = [item.strip() for item in str(packings or "").replace(";", ",").split(",")
                           if item.strip()]
        wanted_relations = [item.strip() for item in str(relations or "").replace(";", ",").split(",")
                            if item.strip()]
        same_by_block = await _variance_by_block(ipc, same_ids, stage_name) \
            if len(same_ids) >= 2 else {}
        other_by_block = await _variance_by_block(ipc, other_ids, stage_name) \
            if len(other_ids) >= 2 else {}
        narrowing_by_block: dict[str, Any] = {}
        candidate_lanes_by_block: dict[str, Any] = {}
        for block in blocks:
            label = _block_label(block)
            floats = list(block.get("floats") or [])
            # A lane offset only has meaning within this register/space. A
            # per-object lane in b0 cannot exclude the same offset in b4.
            bits = shader_anchors.implausible_float_lanes(
                floats, list(block.get("uints") or []))
            block_narrowing = shader_anchors.material_lane_candidates(
                same_by_block.get(label), other_by_block.get(label),
                lane_count=len(floats), implausible=bits)
            narrowing_by_block[label] = block_narrowing
            candidate_lanes_by_block[label] = (
                block_narrowing["lanes"] if block_narrowing.get("applied") else None)
        # Keep the single-block projection for existing readers; multiple blocks
        # carry only their own filters, never a misleading shared lane list.
        narrowing = (dict(next(iter(narrowing_by_block.values())))
                     if len(narrowing_by_block) == 1 else
                     {"applied": any(item.get("applied") for item in narrowing_by_block.values())})
        narrowing["blocks"] = narrowing_by_block
        members = material_naming.propose_member_names(
            material, blocks, fill_gaps=bool(fill_gaps), provisional_suffix=suffix,
            anchors=supplied_anchors, candidate_lanes_by_block=candidate_lanes_by_block,
            packings=wanted_packings or None, relations=wanted_relations or None)
        # A captured value can narrow candidate offsets, but neither a caller
        # document nor an asset reader's default value proves which compiled
        # parameter owns that byte. Keep those useful matches inspectable while
        # withholding all CBuffer write payloads from this value matcher.
        value_matched = [
            dict(item) for item in members["proposals"]
            if item.get("autoApplyEligible") is True
        ]
        other_candidates = [
            dict(item) for item in members["proposals"]
            if item.get("autoApplyEligible") is not True
        ]
        for item in members["proposals"]:
            item["valueMatchEligible"] = item.get("autoApplyEligible") is True
            item["autoApplyEligible"] = False
            if item["valueMatchEligible"]:
                item["withheldReason"] = (
                    "A captured value match and material parameter name do not "
                    "prove this parameter owns the compiled CBuffer offset. "
                    "Inspect independent parameter-to-output or source evidence "
                    "before choosing a semantic alias."
                )
        members["autoApplyCount"] = 0
        members["withheldCount"] = len(members["proposals"])
        textures = await asyncio.to_thread(
            ipc.call, "get_bound_textures",
            {"event_id": int(event_id), "stage": stage_name}, timeout=60.0)
        if not isinstance(textures, list):
            raise RuntimeError(str(textures.get("error") or "bound textures are unavailable")
                               if isinstance(textures, Mapping) else
                               "bound textures returned an invalid response")
        links: list[Mapping[str, Any]] = []
        slot_list = textures
        # A stored reader link is one optional source of content-match evidence;
        # it is not workflow authority. Explicit Agent content-match anchors are
        # handled alongside these links below, and both paths are checked against
        # the current live resourceId/bind/space tuple before publication.
        reader_proof = (
            selected_resolution.get("readerProof")
            if isinstance(selected_resolution, Mapping) else None
        )
        proof_links: list[Any] = []
        if isinstance(reader_proof, Mapping):
            for field in (
                "textureIdentityLinks", "textureReferenceLinks", "resolvedTextureLinks"
            ):
                value = reader_proof.get(field)
                if isinstance(value, list):
                    proof_links.extend(value)
            nested_proof = reader_proof.get("assetContentProof")
            if isinstance(nested_proof, Mapping):
                for field in ("textureIdentityLinks", "textureReferenceLinks"):
                    value = nested_proof.get(field)
                    if isinstance(value, list):
                        proof_links.extend(value)
        # A fresh reader can supply reference-chain evidence after a material
        # decision was recorded. Its sealed content proof must name the exact
        # selected asset version before those links are considered; the links
        # themselves still have to match a current live resource/bind/space.
        selected_binding = (
            selected_resolution.get("assetBinding")
            if isinstance(selected_resolution, Mapping) else None
        )
        reader_proofs = (
            receipt.get("assetContentProofs")
            if isinstance(receipt, Mapping) else None
        )
        reader_matches_selected = bool(
            isinstance(selected_binding, Mapping)
            and isinstance(reader_proofs, list)
            and any(
                isinstance(proof, Mapping)
                and _asset_content_proof_is_host_sealed(proof)
                and proof.get("assetBinding") == selected_binding
                and str(proof.get("relativePath") or "") == wanted
                for proof in reader_proofs
            )
        )
        if reader_matches_selected and isinstance(receipt, Mapping):
            for field in ("textureIdentityLinks", "textureReferenceLinks", "resolvedTextureLinks"):
                value = receipt.get(field)
                if isinstance(value, list):
                    proof_links.extend(value)
        for item in proof_links:
            if not isinstance(item, Mapping):
                continue
            kind = str(
                item.get("hostEvidenceKind") or item.get("evidenceKind")
                or item.get("kind") or item.get("verdict") or ""
            ).strip().lower()
            if kind not in {"same-image", "pixel-same-image", "resolved-reference-chain"}:
                continue
            resource_id = item.get("resourceId")
            asset = str(
                item.get("asset") or item.get("assetPath")
                or item.get("ownerPath") or item.get("relativePath") or ""
            ).strip()
            if resource_id in (None, "") or not asset:
                continue
            positions = [
                index for index, bound in enumerate(slot_list)
                if isinstance(bound, Mapping)
                and str(bound.get("resourceId")) == str(resource_id)
            ]
            if "bindPoint" in item or "bind" in item or "space" in item:
                expected_bind = item.get("bindPoint", item.get("bind"))
                expected_space = int(item.get("space") or 0)
                positions = [
                    index for index in positions
                    if slot_list[index].get("bindPoint", slot_list[index].get("bind"))
                    == expected_bind
                    and int(slot_list[index].get("space") or 0) == expected_space
                ]
            if len(positions) != 1:
                continue
            slot = positions[0]
            bound = slot_list[slot]
            links.append({
                "slot": slot,
                "asset": asset,
                "resourceId": resource_id,
                "bindPoint": bound.get("bindPoint", bound.get("bind")),
                "space": int(bound.get("space") or 0),
                "hostVerified": True,
                "hostEvidenceKind": kind,
                "why": str(item.get("why") or item.get("evidence") or kind)[:400],
            })
        path_resolution = None
        texture_parameters = material.get("textures") or []
        if links and any(not any(material_naming._same_asset(parameter.get("objectPath"), link.get("asset"))
                                 for parameter in texture_parameters) for link in links if link.get("asset")):
            try:
                from . import uex_profiles

                unused_service, unused_status, asset_root, catalog_path = _active_asset_catalog_context(
                    require_catalog=True)
                profiles = uex_profiles._load(uex_profiles.profiles_path()).get("profiles") or {}
                reader_roots = [item["paksDir"] for item in profiles.values()
                                if isinstance(item, Mapping) and item.get("paksDir") and item.get("assetRoot")
                                and Path(str(item["assetRoot"])).resolve() == asset_root]
                references = [str(item["objectPath"]) for item in texture_parameters if item.get("objectPath")]
                references.extend(str(item["asset"]) for item in links if item.get("asset"))
                path_resolution = AssetCatalogService(catalog_path).resolve_unreal_texture_paths(
                    asset_root, references, reader_mount_roots=reader_roots)
                mapped = path_resolution.get("resolved") or {}
                material = {**material, "textures": [
                    {**item, "objectPath": mapped.get(item.get("objectPath"), item.get("objectPath"))}
                    for item in texture_parameters]}
                links = [{**item, "asset": mapped.get(item.get("asset"), item.get("asset"))} for item in links]
            except Exception as error:
                path_resolution = {"available": False, "reason": str(error), "resolved": {}}
        slots = material_naming.propose_texture_names(
            material, slot_list, links, provisional_suffix=suffix, anchors=supplied_anchors)
        if path_resolution is not None:
            slots["pathResolution"] = path_resolution
        declarations = _workspace_declarations(workspace_path) if workspace_path else \
            {"available": False, "reason": "no workspace_path given, so there is no source to rename in"}
        renames: dict[str, str] = {}
        withheld_renames: list[dict[str, Any]] = []
        resource_alias_rows: list[dict[str, Any]] = []
        withheld_resource_alias_rows: list[dict[str, Any]] = []
        unreadable: list[dict[str, Any]] = []
        if declarations.get("available"):
            by_lane = declarations["cbufferLanes"]
            for item in members["proposals"]:
                key = (int(item.get("space") or 0), int(item.get("bind") or 0), int(item["lane"]))
                symbol = by_lane.get(key)
                if symbol:
                    item["workspaceSymbol"] = symbol
                    item["memberLocationEvidence"] = "source-packoffset"
                    if item.get("autoApplyEligible"):
                        renames[symbol] = item["markedIdentifier"]
                    else:
                        withheld_renames.append({
                            "workspaceSymbol": symbol, "candidate": item["markedIdentifier"],
                            "bind": item.get("bind"), "space": item.get("space"),
                            "byteOffset": item["byteOffset"], "reason": item["withheldReason"],
                        })
                else:
                    unreadable.append({"lane": item["lane"], "parameter": item["parameter"]})
            by_slot = declarations["textureSlots"]
            for item in slots["proposals"]:
                bind = item.get("bindPoint")
                symbol = (by_slot.get((int(item.get("space") or 0), bind))
                          if isinstance(bind, int) else None)
                if symbol:
                    item["workspaceSymbol"] = symbol
                    if item.get("autoApplyEligible") is True:
                        renames[symbol] = item["markedIdentifier"]
                    else:
                        withheld_renames.append({
                            "workspaceSymbol": symbol,
                            "candidate": item["markedIdentifier"],
                            "bind": bind,
                            "space": item.get("space"),
                            "resourceId": item.get("resourceId"),
                            "reason": item.get("withheldReason") or (
                                "texture name lacks an exact current binding/content match"
                            ),
                        })
        for item in slots["proposals"]:
            bind = item.get("bindPoint")
            space = item.get("space") or 0
            resource_id = item.get("resourceId")
            candidate = {
                "selector": str(item.get("workspaceSymbol") or (
                    "texture-resource:s%s:t%s:r%s" % (space, bind, resource_id)
                )),
                "resourceId": resource_id,
                "bindNumber": bind,
                "registerSpace": space,
                "alias": item.get("markedIdentifier"),
                "assetPath": item.get("asset"),
                "hostEvidenceKind": item.get("hostEvidenceKind"),
            }
            if (
                item.get("autoApplyEligible") is True
                and type(resource_id) is int and resource_id > 0
                and type(bind) is int and bind >= 0
                and type(space) is int and space >= 0
            ):
                resource_alias_rows.append(candidate)
            else:
                withheld_resource_alias_rows.append({
                    **candidate,
                    "reason": item.get("withheldReason") or (
                        "texture resource name lacks an exact live binding/content proof"
                    ),
                })
        rows: list[dict[str, Any]] = []
        # Retain candidate row groupings for inspection, never as the
        # directly publishable cbufferAliasRows payload. alias_rows filters
        # autoApplyEligible=False, so these copies express presentation only.
        withheld_alias_rows = (
            material_naming.alias_rows(value_matched)
            + material_naming.alias_rows([
                {**item, "autoApplyEligible": True} for item in other_candidates
            ])
        )
        supported = bool(members["autoApplyCount"] or slots.get("autoApplyCount"))
        layout_required = bool(members["withheldCount"] or slots.get("withheldCount"))
        layout_capabilities = [
            "list_asset_tool_operations",
            "run_asset_tool_operation",
        ]
        layout_facts: dict[str, Any] = {
            "parameterSource": material.get("parameterSource", ""),
            "assetHint": wanted or resolved_path(selected_resolution),
        }
        if material.get("parameterSource") == "unreal":
            layout_capabilities.extend([
                "uex_material_shader_maps",
                "decode_material_shader_outputs",
            ])
            layout_facts["compiledLayoutEvidenceKind"] = (
                "Unreal material shader-map and preshader output metadata"
            )
            layout_facts["defaultValueOffsetIsGpuOffset"] = False
        layout_uncertainties = ([{
            "code": "parameter-output-binding-unverified",
            "message": (
                "Matched values do not establish which material parameter owns "
                "the captured CBuffer byte offset. Independent source or "
                "compiled-output evidence may clarify the semantic ownership."
            ),
        }] if layout_required else [])
        supported = bool(renames or rows or resource_alias_rows)
        payload = {
            "schema": material_naming.SCHEMA, "schemaVersion": 1,
            "ready": supported,
            "readinessScope": "automatic-proposal-payload-only",
            "matchStatus": ("supported-proposals" if supported else
                            "ambiguous-parameter-layout" if layout_required else "no-automatic-proposal"),
            "cbufferAliasRows": rows,
            "withheldCBufferAliasRows": withheld_alias_rows,
            "resourceAliasRows": resource_alias_rows,
            "withheldResourceAliasRows": withheld_resource_alias_rows,
            "resourceNaming": {
                "state": "ready" if (resource_alias_rows or rows) else "unavailable",
                "stateScope": "automatic-proposal-payload-only",
                "facts": {
                    "currentRdcTextureNames": len(resource_alias_rows),
                    "currentRdcCBufferRows": len(rows),
                    "withheldTextureNames": len(withheld_resource_alias_rows),
                    "withheldCBufferRows": len(withheld_alias_rows),
                    "userAliasesArePreserved": True,
                    "managedAliasesMayBeReplaced": True,
                },
                "availableCapabilities": [
                    *(["publish_shader_resource_names"]
                      if resource_alias_rows else []),
                    *(["publish_cbuffer_aliases"] if rows else []),
                ],
            },
            "aliasSummary": {
                "rows": len(rows),
                "rowsThisShaderDoesNotRead": sum(1 for item in rows
                                                 if not item["readByThisShader"]),
                "note": ("A source rename reaches only declared lanes. A panel alias is keyed "
                         "by layout and byte offset and may be visible in other shaders that bind "
                         "the same block. Panel rows are 16 bytes and may contain unrelated scalars."),
            },
            "material": {"name": material["objectName"], "class": material["className"],
                         "source": source, "parameterCounts": members["parameterCounts"],
                         "parameterStorage": material.get("parameterStorage", ""),
                         "defaultValuesOnly": material.get("defaultValuesOnly", False),
                         "gpuLayoutKnown": material.get("gpuLayoutKnown", False),
                          "layoutEvidence": {
                              "method": "capture-value-correspondence",
                              "compiledLayoutRead": False,
                              "samePlatformMaterialRecompiled": False,
                              "semanticWidthsVerified": False,
                              "memberLocationEvidence": ("source-packoffset" if declarations.get("available") else "capture-float-lane"),
                              "withheldCandidates": members["withheldCount"],
                              "facts": layout_facts,
                              "uncertainties": layout_uncertainties,
                              "availableCapabilities": list(dict.fromkeys(
                                  layout_capabilities
                              )),
                          },
                         "warnings": ([{"reason": "Material defaults do not describe GPU layout; "
                                                  "array indices are not CBuffer offsets."}]
                                      if material.get("defaultValuesOnly") else [])
                                      + ([{"reason": "Matched values and source packoffsets do not prove "
                                                    "parameter ownership or component width. Candidates are "
                                                    "withheld from automatic renames and alias rows."}] if layout_required else [])
                                     + list(material.get("parameterReadWarnings") or [])[:8],
                         "parameterSource": material.get("parameterSource", ""),
                         "parameterSourceDecided": material.get("parameterSourceDecided", ""),
                         "parameterSourceCandidates":
                             material.get("parameterSourceCandidates", [])},
            "renames": renames,
            "semanticNameAuthority": "agent",
            "hostWorkflowAuthorizationRequired": False,
            "withheldRenames": withheld_renames,
            "renameSummary": {
                "applicable": len(renames),
                "withheld": len(withheld_renames),
                "declaredLanes": declarations.get("declaredLaneCount"),
                "declaredSlots": declarations.get("declaredSlotCount"),
                "lanesThisShaderDoesNotRead": len(unreadable),
                "examples": unreadable[:6],
                "reason": declarations.get("reason", ""),
                "note": ("'renames' contains automatic proposals with current symbol bindings. "
                         "Withheld proposals have an unresolved semantic correspondence; source "
                         "packoffset proves byte location only. Proposals without workspaceSymbol "
                         "do not identify a source declaration."),
            },
            "constantBufferMembers": members,
            "laneNarrowing": narrowing,
            "packingRules": {name: rule["description"]
                             for name, rule in shader_anchors.PACKING_RULES.items()},
            "valueRelations": shader_anchors.TRANSFORM_NOTES,
            "textureSlots": slots,
            "availableCapabilities": [
                *([{"tool": "publish_shader_resource_names",
                    "uses": ["resourceAliasRows", "eventId", "stage"]}]
                  if resource_alias_rows else []),
                *([{"tool": "publish_cbuffer_aliases",
                    "uses": ["cbufferAliasRows"]}]
                  if rows else []),
                *([{"tool": "rename_shader_workspace_symbols",
                    "uses": ["renames"]}]
                  if renames else []),
            ],
            "applied": False,
        }
        payload.update(_material_semantic_delivery(
            material, workspace_path, event_id, stage_name, wanted, recorded_evidence,
            selected_resolution, members, slots, semantic_notes))
        return _ok(payload)
    except Exception as error:
        return _shader_err(error, "propose-names-from-asset")


def _bounded_cbuffer_alias(parts: Sequence[str], *, maximum: int = 64) -> str:
    """Join semantic row labels without producing an invalid panel alias."""

    clean = []
    for value in parts:
        text = " ".join(str(value or "").split()).strip(" |\x00")
        if text and text not in clean:
            clean.append(text)
    if not clean:
        return ""
    joined = " | ".join(clean)
    if len(joined) <= maximum:
        return joined
    kept: list[str] = []
    for index, text in enumerate(clean):
        remaining = len(clean) - index - 1
        suffix = " | +%d" % remaining if remaining else ""
        candidate = " | ".join([*kept, text])
        if len(candidate) + len(suffix) <= maximum:
            kept.append(text)
            continue
        break
    if kept:
        remaining = len(clean) - len(kept)
        return " | ".join(kept) + (" | +%d" % remaining if remaining else "")
    return clean[0][: max(1, maximum - 3)].rstrip() + "..."


def _material_output_alias_rows(
    outputs: Sequence[Mapping[str, Any]], *, bind: int, space: int
) -> list[dict[str, Any]]:
    """Project decoded UE output components into physical 16-byte panel rows."""

    rows: dict[int, dict[str, Any]] = {}
    component_names = "xyzw"
    for output in outputs:
        if not isinstance(output, Mapping):
            continue
        offset, size = output.get("byteOffset"), output.get("byteSize")
        if (
            type(offset) is not int
            or type(size) is not int
            or offset < 0
            or size <= 0
            or size > 16
        ):
            continue
        row_offset = (offset // 16) * 16
        if offset + size > row_offset + 16:
            # One display row cannot truthfully name an output crossing a row.
            continue
        row = rows.setdefault(
            row_offset,
            {"labels": [], "vectors": {}, "order": [], "ranges": []},
        )
        row["ranges"].append(
            {"byteOffset": offset, "byteSize": size, "outputType": output.get("outputType")}
        )
        for component in output.get("components") or []:
            if not isinstance(component, Mapping):
                continue
            parameter = component.get("parameterInfo")
            if not isinstance(parameter, Mapping):
                continue
            name = " ".join(str(parameter.get("Name") or "").split()).strip()
            if not name:
                continue
            association = str(parameter.get("Association") or "")
            index = parameter.get("Index")
            key = (name, association, index)
            component_index = component.get("parameterComponent")
            if (
                str(component.get("parameterType") or "").lower() == "vector"
                and type(component_index) is int
                and 0 <= component_index < 4
            ):
                record = row["vectors"].setdefault(key, set())
                record.add(component_index)
                order_key = ("vector", key)
            else:
                if name not in row["labels"]:
                    row["labels"].append(name)
                order_key = ("scalar", name)
            if order_key not in row["order"]:
                row["order"].append(order_key)
    result: list[dict[str, Any]] = []
    for row_offset in sorted(rows):
        row = rows[row_offset]
        labels: list[str] = []
        for kind, value in row["order"]:
            if kind == "scalar":
                label = str(value)
            else:
                name, unused_association, unused_index = value
                indexes = row["vectors"].get(value, set())
                suffix = "".join(component_names[index] for index in sorted(indexes))
                label = "%s.%s" % (name, suffix) if suffix else name
            if label and label not in labels:
                labels.append(label)
        alias = _bounded_cbuffer_alias(labels)
        if not alias:
            continue
        result.append(
            {
                "bind": bind,
                "space": space,
                "byteOffset": row_offset,
                "alias": alias,
                "decodedRanges": row["ranges"],
            }
        )
    return result


def _compiled_layout_receipt(
    *,
    shader_platform: str,
    metadata_sha256: str,
    evidence_files: Sequence[Mapping[str, Any]],
    outputs: Sequence[Mapping[str, Any]],
    alias_rows: Sequence[Mapping[str, Any]],
    event_id: int,
    stage: str,
    bind: int,
    space: int,
    capture_evidence: Mapping[str, Any] | None,
    shader_raw_sha256: str = "",
    layout_sha256: str = "",
    capture_api: str = "",
    capture_platform_compatible: bool | None = None,
) -> dict[str, Any]:
    """Create a content/offset receipt, never a workflow authorization token."""

    receipt: dict[str, Any] = {
        "schema": "bread-compiled-cbuffer-layout/v1",
        "schemaVersion": 1,
        "shaderPlatform": str(shader_platform or ""),
        "metadataSha256": str(metadata_sha256 or "").lower(),
        "evidenceFiles": [dict(item) for item in evidence_files],
        "eventId": int(event_id or 0),
        "stage": str(stage or ""),
        "bind": bind,
        "space": space,
        "shaderRawSha256": str(shader_raw_sha256 or "").lower(),
        "layoutSha256": str(layout_sha256 or "").lower(),
        "captureApi": str(capture_api or ""),
        "capturePlatformCompatible": capture_platform_compatible,
        "captureEvidence": dict(capture_evidence or {}),
        "outputRanges": [
            {
                "byteOffset": item.get("byteOffset"),
                "byteSize": item.get("byteSize"),
                "outputType": item.get("outputType"),
            }
            for item in outputs
            if isinstance(item, Mapping)
        ],
        "suggestedRows": [
            {
                "bind": item.get("bind"),
                "space": item.get("space"),
                "byteOffset": item.get("byteOffset"),
                "alias": item.get("alias"),
            }
            for item in alias_rows
            if isinstance(item, Mapping)
        ],
        "authority": "evidence-only",
    }
    receipt["receiptSha256"] = _canonical_json_sha256(
        receipt, "compiled CBuffer layout receipt"
    )
    return receipt


def _capture_platform_matches_material_platform(api: str, shader_platform: str) -> bool | None:
    api_key = "".join(character for character in str(api or "").lower() if character.isalnum())
    # RenderDoc normally serializes this enum as ``GraphicsAPI.D3D12`` rather
    # than the shorter UI spelling.  Keep the enum qualifier out of the API
    # family lookup; it is presentation, not part of the platform identity.
    if api_key.startswith("graphicsapi"):
        api_key = api_key[len("graphicsapi"):]
    platform = str(shader_platform or "").upper()
    families = {
        "d3d11": ("PCD3D", "D3D", "DXBC"),
        "direct3d11": ("PCD3D", "D3D", "DXBC"),
        "d3d12": ("PCD3D", "D3D", "DXIL"),
        "direct3d12": ("PCD3D", "D3D", "DXIL"),
        "vulkan": ("VULKAN", "SF_VULKAN"),
        "opengl": ("OPENGL", "GLSL", "SF_GL"),
        "opengles": ("OPENGL", "GLSL", "SF_GL"),
        "metal": ("METAL", "SF_METAL"),
    }
    expected = families.get(api_key)
    if expected is None:
        return None
    return any(token in platform for token in expected)


@mcp.tool()
async def decode_material_shader_outputs(
    metadata_path: str, metadata_sha256: str, shader_platform: str,
    material_chain_json: str = "", event_id: int = 0, stage: str = "fragment",
    bind: int = 0, space: int = 0, start_output: int = 0, max_outputs: int = 64,
    workspace_path: str = "",
) -> str:
    """Decode one explicitly selected cooked material ShaderMap receipt, read-only.

    Use list_asset_tool_operations/run_asset_tool_operation to select the proved
    uex_material_shader_maps reader, then pass its complete stdoutPath and
    stdoutFileSha256 here. Choose shader_platform from that receipt. The optional
    material_chain_json is a JSON array of {path,sha256,assetPath} preview receipts,
    leaf instance first, ending at the parent of the ShaderMap material. Every
    parent reference must agree; material parameter array order is never layout.

    Supports only UE5 legacy float Parameter/ComponentSwizzle/AppendVector output
    fields. Unknown versions/programs produce diagnostics and no guessed names;
    this is not a Unity decoder. With event_id>0, compare the selected bind/space
    against fresh captured float32 lanes. Return only outputs common to every
    value-consistent variant, paged by start_output/max_outputs (at most 128).
    Inspect byteOffset, byteSize and each component's parameterInfo before using
    bounded workspace declarations to propose renames. When workspace_path and
    event_id are supplied the result also contains publishable ``cbufferAliasRows``
    and a content-bound ``compiledLayoutReceipt``. The receipt is physical evidence,
    not a conversation/task/asset authorization. No shader archive identity,
    recompilation, alias publication or shader modification is implied.
    """
    from .material_shader_outputs import decode_outputs

    try:
        for label, value, maximum in (("event_id", event_id, 2**32 - 1),
                                      ("bind", bind, 65535), ("space", space, 65535),
                                      ("start_output", start_output, 512)):
            if type(value) is not int or not 0 <= value <= maximum:
                raise ValueError("%s is outside its supported range" % label)
        if type(max_outputs) is not int or not 1 <= max_outputs <= 128:
            raise ValueError("max_outputs must be between 1 and 128")
        if not isinstance(material_chain_json, str) or len(material_chain_json) > 65536:
            raise ValueError("material_chain_json exceeds 64 KiB")
        chain = json.loads(material_chain_json) if material_chain_json.strip() else []
        if not isinstance(chain, list) or len(chain) > 8 or not all(isinstance(e, dict) for e in chain):
            raise ValueError("material_chain_json must contain at most 8 exact receipt objects")
        roots = _evidence_roots()
        total_bytes = 0
        receipts = []

        def read_document(path_text: Any, digest: Any) -> Any:
            nonlocal total_bytes
            expected_hash = _strict_lower_hex(digest, 64, "evidence SHA256")
            if not isinstance(path_text, str) or not path_text or len(path_text) > 32768:
                raise ValueError("evidence path is required")
            target = Path(path_text)
            if not target.is_absolute() or ".." in target.parts:
                raise ValueError("evidence path must be absolute without parent traversal")
            for root in roots:
                try:
                    relative = target.relative_to(root)
                except ValueError:
                    continue
                size = target.stat().st_size
                if size > 8 * 1024 * 1024 or total_bytes + size > 16 * 1024 * 1024:
                    raise ValueError("material evidence exceeds 8 MiB/file or 16 MiB/chain")
                raw, reason, unused = read_recovery_regular_file(root, relative, size)
                if raw is None or len(raw) != size or hashlib.sha256(raw).hexdigest() != expected_hash:
                    raise ValueError("material evidence changed or could not be verified: %s" % reason)
                total_bytes += size
                receipts.append({"path": str(target), "sha256": expected_hash, "byteSize": size})
                return json.loads(raw.decode("utf-8-sig"))
            raise ValueError("material evidence is outside the Host's evidence directories")

        document = await asyncio.to_thread(read_document, metadata_path, metadata_sha256)
        overrides = []
        for entry in chain:
            overrides.append({"assetPath": entry.get("assetPath"),
                              "document": await asyncio.to_thread(read_document, entry.get("path"), entry.get("sha256"))})
        capture_values, capture_evidence = None, None
        stage_name = normalize_stage(stage) if event_id else str(stage or "")
        shader_raw_sha256 = ""
        layout_sha256 = ""
        capture_api = ""
        platform_compatible: bool | None = None
        if event_id:
            before = await asyncio.to_thread(_active_live_context, allow_missing_capture_id=True)
            identity = _active_capture_transport_identity(before)
            capture_api = str((before.get("capture") or {}).get("api") or "")
            platform_compatible = _capture_platform_matches_material_platform(
                capture_api, shader_platform
            )
            blocks = await asyncio.to_thread(_blocks_for_event, ipc, event_id, stage_name)
            selected = [b for b in blocks if b.get("bind") == bind and b.get("space", 0) == space]
            if len(selected) != 1 or not isinstance(selected[0].get("floats"), list) or not selected[0]["floats"]:
                raise ValueError("the exact capture bind/space has no readable float lanes")
            capture_values = selected[0]["floats"]
            if len(capture_values) > 16384:
                raise ValueError("capture block exceeds the supported 64 KiB numeric region")
            after = await asyncio.to_thread(_active_live_context, allow_missing_capture_id=True)
            if _active_capture_transport_identity(after) != identity:
                raise ValueError("capture session changed during the material output comparison")
            capture_evidence = {"capture": before["capture"], "eventId": event_id,
                                "stage": stage_name, "bind": bind, "space": space,
                                "floatLaneCount": len(capture_values)}
            if str(workspace_path or "").strip():
                workspace_status = await asyncio.to_thread(
                    _alias_publication_workspace_status,
                    str(workspace_path),
                )
                bound_shader = await asyncio.to_thread(
                    _active_bound_shader, before, event_id, stage_name
                )
                alias_identity = await asyncio.to_thread(
                    _shader_organization_cbuffer_alias_identity,
                    str(workspace_path),
                    status=workspace_status,
                    status_loader=_alias_publication_workspace_status,
                )
                if (
                    alias_identity.get("stage") != stage_name
                    or alias_identity.get("rawSha256") != bound_shader.get("rawSha256")
                ):
                    raise ValueError(
                        "workspace and selected EID do not identify the same original Shader"
                    )
                alias_blocks = [
                    item
                    for item in (alias_identity.get("blocks") or [])
                    if isinstance(item, Mapping)
                    and item.get("bind") == bind
                    and int(item.get("space") or 0) == space
                ]
                if len(alias_blocks) != 1:
                    raise ValueError(
                        "the workspace Shader has no unique reflected block at this bind/space"
                    )
                alias_block = alias_blocks[0]
                members = [
                    {"name": member.get("name"), "offset": member.get("offset")}
                    for member in (alias_block.get("members") or [])
                    if isinstance(member, Mapping)
                ]
                from .shader_workspace import aliases as cbuffer_aliases

                layout_sha256 = cbuffer_aliases.layout_sha256(
                    str(alias_block.get("block") or ""), members
                )
                shader_raw_sha256 = str(alias_identity.get("rawSha256") or "")
                capture_evidence.update(
                    {
                        "shaderRawSha256": shader_raw_sha256,
                        "layoutSha256": layout_sha256,
                        "workspacePhysicalBindingVerified": True,
                    }
                )
        result = await asyncio.to_thread(decode_outputs, document, overrides,
                                         shader_platform=shader_platform, capture_values=capture_values)
        all_outputs = [
            dict(item) for item in (result.get("outputs") or [])
            if isinstance(item, Mapping)
        ]
        alias_rows = _material_output_alias_rows(all_outputs, bind=bind, space=space)
        result["outputs"] = all_outputs[start_output:start_output + max_outputs]
        result["page"] = {"startOutput": start_output, "returnedOutputs": len(result["outputs"]),
                          "nextStartOutput": start_output + len(result["outputs"]) if start_output + len(result["outputs"]) < result["outputCount"] else None}
        result["evidenceFiles"] = receipts
        result["captureComparisonAvailable"] = capture_values is not None
        result["captureEvidence"] = capture_evidence
        result["capturePlatformCompatible"] = platform_compatible
        result["cbufferAliasRows"] = alias_rows
        result["compiledLayoutReceipt"] = _compiled_layout_receipt(
            shader_platform=shader_platform,
            metadata_sha256=_strict_lower_hex(
                metadata_sha256, 64, "metadata SHA256"
            ),
            evidence_files=receipts,
            outputs=all_outputs,
            alias_rows=alias_rows,
            event_id=event_id,
            stage=stage_name,
            bind=bind,
            space=space,
            capture_evidence=capture_evidence,
            shader_raw_sha256=shader_raw_sha256,
            layout_sha256=layout_sha256,
            capture_api=capture_api,
            capture_platform_compatible=platform_compatible,
        )
        result["readyForAliasPublication"] = bool(
            event_id
            and str(workspace_path or "").strip()
            and alias_rows
            and shader_raw_sha256
            and layout_sha256
            and platform_compatible is True
        )
        return _ok(result)
    except Exception as error:
        return _shader_err(error, "decode-material-shader-outputs")


async def _read_material_asset(
    asset: str, *, reader_operation: str = "", reader_arguments: dict | None = None,
) -> dict[str, Any]:
    """Read one material without treating every engine's asset as an Unreal package.

    Explicit operations belong to the Agent: their declared schemas decide the
    arguments. Automatic reads require a local JSON document, a proved file
    reader, or actual Unreal package-header evidence. Header classification alone
    never counts as having read material parameters.
    """
    from .material_naming import MaterialNamingError, parse_material_parameters
    from .asset_reader_routing import capture_fallback

    def material_document(document: Any) -> bool:
        try:
            parsed = parse_material_parameters(document)
        except MaterialNamingError:
            return False
        return any(parsed.get(key) for key in ("scalars", "vectors", "textures"))

    def operation_document(receipt: Any) -> Any:
        if not isinstance(receipt, dict) or receipt.get("succeeded") is not True:
            return None
        maximum_bytes = 8 * 1024 * 1024
        stdout_path = receipt.get("stdoutPath")
        if stdout_path is not None:
            if receipt.get("stdoutFileTruncated") is not False:
                raise ValueError("material reader stdout file is truncated or lacks completeness evidence")
            size = receipt.get("stdoutByteSize")
            file_size = receipt.get("stdoutFileByteSize")
            if (type(size) is not int or type(file_size) is not int or
                    size < 0 or size > maximum_bytes or file_size != size):
                raise ValueError("material reader stdout full/file sizes differ or exceed the 8 MiB limit")
            digest = _strict_lower_hex(receipt.get("stdoutSha256"), 64, "material reader stdoutSha256")
            if receipt.get("stdoutFileSha256") != digest:
                raise ValueError("material reader stdout full/file SHA256 evidence differs")
            output_directory = receipt.get("outputDirectory")
            if (not isinstance(stdout_path, str) or not stdout_path or
                    not isinstance(output_directory, str) or not output_directory or
                    len(stdout_path) > 32768 or len(output_directory) > 32768):
                raise ValueError("material reader stdout file needs an exact outputDirectory and path")
            root, target = Path(output_directory), Path(stdout_path)
            if (not root.is_absolute() or not target.is_absolute() or
                    ".." in root.parts or ".." in target.parts):
                raise ValueError("material reader stdout file path escapes its outputDirectory")
            try:
                relative = target.relative_to(root)
            except ValueError as error:
                raise ValueError("material reader stdout file path escapes its outputDirectory") from error
            # Reuse the root-handle reader: no symlink/reparse traversal, bounded
            # read and before/after fstat on the same descriptor, on both platforms.
            raw, read_error, unused_consumed = read_recovery_regular_file(root, relative, size)
            if raw is None or len(raw) != size:
                raise ValueError("material reader stdout file could not be verified: %s" % (read_error or "size changed"))
            if hashlib.sha256(raw).hexdigest() != digest:
                raise ValueError("material reader stdout file SHA256 does not match its receipt")
            try:
                return json.loads(raw.decode("utf-8-sig"))
            except (UnicodeError, ValueError) as error:
                raise ValueError("material reader stdout file is not complete UTF-8 JSON: %s" % error) from error
        document = receipt.get("description")
        if material_document(document):
            return document
        if receipt.get("stdoutTruncated") or receipt.get("stdoutFileTruncated"):
            raise ValueError("material reader stdout is truncated and no complete stdout file is available")
        stdout = receipt.get("stdout") or ""
        if not isinstance(stdout, str):
            raise ValueError("material reader stdout must be UTF-8 JSON text")
        raw = stdout.encode("utf-8")
        if len(raw) > maximum_bytes:
            raise ValueError("material reader stdout exceeds the 8 MiB limit")
        if (("stdoutByteSize" in receipt and receipt["stdoutByteSize"] != len(raw)) or
                ("stdoutSha256" in receipt and receipt["stdoutSha256"] != hashlib.sha256(raw).hexdigest())):
            raise ValueError("material reader inline stdout size/SHA256 does not match its receipt")
        if not stdout.strip():
            return None
        try:
            return json.loads(stdout)
        except ValueError as error:
            raise ValueError("material reader stdout is not complete JSON; the inline preview may be compacted") from error

    catalog = _declared_asset_operations()
    attempts: list[dict[str, Any]] = []
    if reader_operation:
        arguments = dict(reader_arguments or {})
        operation = next((item for item in catalog if item.get("name") == reader_operation), None)
        # The caller already selected an exact asset. Supply that path to the
        # reader's declared path argument instead of failing an empty selection.
        properties = ((operation or {}).get("inputSchema") or {}).get("properties") or {}
        path_arguments = [key for key in ("asset", "assetPath", "asset_path", "path", "file_path")
                          if key in properties]
        if len(path_arguments) == 1 and path_arguments[0] not in arguments:
            arguments[path_arguments[0]] = asset
        receipt = json.loads(await run_asset_tool_operation(
            name=reader_operation, arguments=arguments))
        document = operation_document(receipt)
        if not material_document(document) and isinstance(document, Mapping):
            from .material_parent_chain import _embedded_material_preview
            embedded = _embedded_material_preview(document, asset)
            if material_document(embedded):
                document = embedded
        if material_document(document):
            return {"succeeded": True, "source": reader_operation,
                    "document": document, "receipt": receipt}
        # Exporters may produce several materials. Do not take the first JSON
        # file and attach another object's names to this draw.
        return {"succeeded": False, "reason": "operation-needs-material-selection",
                "receipt": receipt, "operations": catalog,
                "limitations": ["Select the exact exported material and pass material_json."]}

    try:
        root, unused = _unpacked_asset_root()
    except RuntimeError:
        return {"succeeded": False, "reason": "asset-root-unavailable", "operations": catalog,
                **capture_fallback("asset-root-unavailable")}
    # Virtual engine object paths must be interpreted by the selected reader.
    if str(asset).startswith("/"):
        return {"succeeded": False, "reason": "virtual-path-needs-reader",
                "operations": catalog, "asset": asset, **capture_fallback("virtual-path-needs-reader")}
    path = _unpacked_within(root, asset)
    if path.is_file():
        relative = _unpacked_relative(root, path)
        if path.suffix.lower() == ".json":
            if path.stat().st_size > 8 * 1024 * 1024:
                raise ValueError("material JSON exceeds the bounded reader limit; select a smaller material export")
            document = json.loads(path.read_text(encoding="utf-8-sig"))
            if material_document(document):
                read = {
                    "succeeded": True,
                    "source": "project-material-json",
                    "document": document,
                    "sourceFiles": [relative],
                    "sourceFile": _exact_asset_read_facts(root, path),
                }
                return read
        rich = await _describe_with_registered_tool(path, relative, b"")
        if rich is not None:
            if rich.get("readerStatus") == "parsed" and material_document(rich):
                read = {
                    "succeeded": True,
                    "source": str(rich.get("reader") or "asset-reader"),
                    "document": rich,
                    "sourceFiles": [relative],
                    "sourceFile": _exact_asset_read_facts(root, path),
                }
                return read
            attempts.append(rich)
        # The capability router already tried the project's selected reader and
        # bounded fallback. Do not invoke UEX again merely because the header is
        # Unreal: that duplicates a failed read and bypasses project selection.
    return {"succeeded": False, "reason": "material-reader-selection-required",
            "attempts": attempts, "operations": catalog,
            **capture_fallback("material-properties-unavailable"),
            "limitations": ["A container header is not material parameter evidence.",
                            "Virtual object paths require an explicitly selected reader operation."]}


def _run_uex_preview(asset: str) -> dict[str, Any]:
    """Run the registered uex preview recipe on one virtual asset path."""

    from . import tool_runner

    operation = next((item for item in _declared_asset_operations()
                      if item.get("name") == "uex_preview_asset"), None)
    if operation is None:
        raise RuntimeError(
            "uex is not registered here, so the material cannot be read for you; run the "
            "preview yourself and pass material_json")
    program = str(operation.get("program", "") or "")
    if not program:
        raise RuntimeError("the uex recipe has no registered program")
    return tool_runner.run_operation(
        operation, {"asset": str(asset)}, program=program,
        output_root=_asset_tool_output_root(), timeout_seconds=180.0,
        host_slots=_uex_host_slots(operation))


def _resource_alias_manifest_rows(
    rows: Sequence[Mapping[str, Any]], binding: Mapping[str, Any]
) -> list[dict[str, Any]]:
    """Project AI-selected rows into the bridge's capture-bound schema.

    The Host proves the physical Shader/resource binding below, not the Agent's
    semantic interpretation of the unpacked texture match.  Keeping those two
    claims separate prevents a task-report/session token from becoming workflow
    authority while preserving the bridge's strict live-target validation.
    """

    return [
        {
            "verified": True,
            "metadata": {
                "programVerified": True,
                "resourceBindingVerified": True,
                "eventId": binding.get("eventId"),
                "semanticEvidenceOwner": "ai",
                # Optional explanatory provenance, never publication authority.
                "semanticEvidenceKind": row.get("hostEvidenceKind") or None,
                "assetPath": row.get("assetPath") or None,
            },
            "provenance": "ai-content-match",
            "captureId": binding.get("captureId"),
            "shaderResourceId": binding.get("shaderResourceId"),
            "resourceId": row.get("resourceId"),
            "stage": binding.get("stage"),
            "entryPoint": binding.get("entryPoint"),
            "rawSha256": binding.get("shaderRawSha256"),
            "bindingKind": "textureResource",
            "bindNumber": row.get("bindNumber"),
            "registerSpace": row.get("registerSpace"),
            "alias": row.get("alias"),
        }
        for row in rows
    ]


def _current_resource_alias_publication_binding(
    workspace_root: Path,
    rows: Sequence[Mapping[str, Any]],
    *,
    event_id: int,
    stage: str,
    status: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Validate only the current physical target for texture-name publication."""

    if type(event_id) is not int or event_id <= 0:
        raise ValueError("event_id must be a positive current RenderDoc EID")
    stage_name = normalize_stage(stage)
    if not stage_name:
        raise ValueError("stage must identify the current Shader stage")
    normalized_rows = ShaderOrganizationManager._canonical_resource_alias_rows(rows)
    status = (
        status
        if status is not None
        else _alias_publication_workspace_status(str(workspace_root))
    )
    original_workspace_binding = _workspace_catalog_binding_projection(status)
    status_stage = normalize_stage(status.get("stage"))
    if status_stage != stage_name:
        raise RuntimeError(
            "requested resource names target a different Shader stage than the workspace"
        )
    # Make the workspace's exact bounded catalog known to this live Bridge
    # before constructing the alias manifest.  A freshly opened capture can
    # initially expose only an identity/full-frame symbol snapshot; the
    # workspace rebind proves the same Shader by API, stable catalog evidence and exact
    # bytes.  The alias transaction itself must still use the Bridge's *active*
    # symbol-catalog captureId, which can legitimately differ from the saved
    # one-event workspace catalog's id.
    _ensure_workspace_capture_catalog_identity(
        str(workspace_root),
        status=status,
        status_loader=_alias_publication_workspace_status,
        require_active_catalog=True,
    )
    context = _active_live_context(require_event_state=False)
    current_shader = _active_bound_shader(context, event_id, stage_name)
    workspace_shader = (
        status.get("shader") if isinstance(status.get("shader"), Mapping) else {}
    )
    workspace_raw = _strict_lower_hex(
        workspace_shader.get("rawSha256"), 64, "workspace.shader.rawSha256"
    )
    if (
        current_shader.get("rawSha256") != workspace_raw
        or current_shader.get("stage") != stage_name
        or str(current_shader.get("entryPoint") or "")
        != str(status.get("entryPoint") or "")
    ):
        raise RuntimeError(
            "current EID/stage Shader bytes do not match this workspace target"
        )
    bound = ipc.call(
        "get_bound_textures",
        {"event_id": event_id, "stage": stage_name},
        timeout=60.0,
    )
    if not isinstance(bound, list):
        raise RuntimeError(
            str(bound.get("error") or "bound textures are unavailable")
            if isinstance(bound, Mapping)
            else "bound textures returned an invalid response"
        )

    def physical_target(item: Mapping[str, Any]) -> tuple[int, int, int] | None:
        values = (
            item.get("resourceId"),
            item.get("bindPoint", item.get("bind")),
            item.get("space", 0),
        )
        if any(isinstance(value, bool) for value in values):
            return None
        try:
            resource_id, bind, space_value = (int(value) for value in values)
        except (TypeError, ValueError, OverflowError):
            return None
        if resource_id <= 0 or bind < 0 or space_value < 0:
            return None
        return resource_id, bind, space_value

    live_targets = [
        target
        for item in bound
        if isinstance(item, Mapping)
        for target in [physical_target(item)]
        if target is not None
    ]
    for row in normalized_rows:
        target = (
            int(row["resourceId"]),
            int(row["bindNumber"]),
            int(row["registerSpace"]),
        )
        if live_targets.count(target) != 1:
            raise RuntimeError(
                "resource alias row does not identify one current bound texture "
                "for EID %d stage %s (resourceId=%d, bind=%d, space=%d)"
                % (event_id, stage_name, *target)
            )
    if _workspace_catalog_binding_projection(
        _alias_publication_workspace_status(str(workspace_root))
    ) != original_workspace_binding:
        raise RuntimeError(
            "Shader workspace physical identity changed during resource-name preflight"
        )
    _require_same_active_capture(context)
    capture = context.get("capture") if isinstance(context.get("capture"), Mapping) else {}
    binding: dict[str, Any] = {
        "workspaceId": _strict_lower_hex(
            status.get("workspaceId"), 32, "workspaceId"
        ),
        "captureId": _strict_lower_hex(
            capture.get("captureId"), 64, "capture.captureId"
        ),
        "captureSessionId": _strict_lower_hex(
            capture.get("captureSessionId"), 32, "capture.captureSessionId"
        ),
        "eventId": event_id,
        "stage": stage_name,
        "entryPoint": str(current_shader.get("entryPoint") or ""),
        "shaderResourceId": int(current_shader["resourceId"]),
        "shaderRawSha256": workspace_raw,
        "rows": normalized_rows,
    }
    binding["bindingId"] = _canonical_json_sha256(
        binding, "current resource-name publication binding"
    )[:32]
    return normalized_rows, binding


def _resource_alias_transaction_status(
    capture_id: str, capture_session_id: str
) -> dict[str, Any]:
    status = ipc.call(
        "get_symbol_alias_transaction",
        {
            "expected_capture_id": capture_id,
            "expected_capture_session_id": capture_session_id,
        },
        timeout=30.0,
    )
    if (
        not isinstance(status, Mapping)
        or status.get("schema") != "renderdoc-ultra-alias-transaction-status/v1"
        or status.get("schemaVersion") != 1
        or status.get("captureId") != capture_id
        or status.get("captureSessionId") != capture_session_id
        or status.get("state") not in {
            "absent", "pending", "committed", "rolled-back"
        }
        or not isinstance(status.get("mutationPresent"), bool)
        or not isinstance(status.get("recoveryRequired"), bool)
        or status.get("replayMutation") is not False
    ):
        raise RuntimeError("RenderDoc returned invalid alias transaction status")
    if status.get("mutationPresent"):
        if (
            not _is_lower_hex_value(status.get("transactionId"), 32)
            or not _is_lower_hex_value(status.get("manifestSha256"), 64)
            or not isinstance(status.get("manifestPath"), str)
            or not status.get("manifestPath")
        ):
            raise RuntimeError(
                "active alias transaction lacks its exact manifest path/digest"
            )
    return dict(status)


def _rollback_resource_alias_transaction(
    *, capture_id: str, capture_session_id: str, transaction_id: str
) -> dict[str, Any]:
    receipt = ipc.call(
        "rollback_symbol_aliases",
        {
            "expected_capture_id": capture_id,
            "expected_capture_session_id": capture_session_id,
            "expected_transaction_id": transaction_id,
        },
        timeout=60.0,
    )
    if (
        not isinstance(receipt, Mapping)
        or receipt.get("schema") != "renderdoc-ultra-alias-rollback/v1"
        or receipt.get("schemaVersion") != 1
        or receipt.get("captureId") != capture_id
        or receipt.get("captureSessionId") != capture_session_id
        or receipt.get("transactionId") != transaction_id
        or receipt.get("status") not in {"restored", "already-restored"}
        or receipt.get("restored") is not True
        or receipt.get("verified") is not True
        or receipt.get("recoveryRequired") is not False
        or receipt.get("failures") != []
    ):
        raise RuntimeError("RenderDoc did not prove complete alias rollback")
    return dict(receipt)


def _load_resource_alias_manifest(
    path: Path, digest: str, operation_id: str
) -> dict[str, Any]:
    receipt = ipc.call(
        "load_symbol_aliases",
        {
            "path": str(path),
            "confirmed_only": True,
            "expected_sha256": digest,
            "strict_atomic": True,
            "operation_id": operation_id,
        },
        timeout=60.0,
    )
    counts = receipt.get("counts") if isinstance(receipt, Mapping) else None
    count_fields = (
        "manifestAliases", "deterministicAliases", "liveBoundAliases",
        "activeValidatedAliases", "renamedShaders", "renamedTextures",
        "renamedResources", "keptUser", "skipped", "conflicts",
    )
    valid_counts = isinstance(counts, Mapping) and all(
        type(counts.get(field)) is int and counts[field] >= 0
        for field in count_fields
    )
    transaction_id = str(
        (receipt.get("transactionId") or "")
        if isinstance(receipt, Mapping) else ""
    )
    mutation_present = (
        receipt.get("mutationPresent") if isinstance(receipt, Mapping) else None
    )
    transaction_receipt_valid = bool(
        (
            transaction_id == operation_id
            and isinstance(receipt, Mapping)
            and receipt.get("rollbackAvailable") is True
            and mutation_present in {None, True}
        )
        or (
            transaction_id == ""
            and isinstance(receipt, Mapping)
            and receipt.get("rollbackAvailable") is False
            and mutation_present is False
            and valid_counts
            and counts.get("renamedResources") == 0
            and counts.get("keptUser") == counts.get("manifestAliases")
        )
    )
    if (
        not isinstance(receipt, Mapping)
        or receipt.get("schema") != "renderdoc-ultra-aliases/v1"
        or receipt.get("schemaVersion") != 1
        or receipt.get("strictAtomic") is not True
        or receipt.get("committed") is not True
        or receipt.get("operationId") != operation_id
        or Path(str(receipt.get("path") or "")).resolve() != path.resolve()
        or receipt.get("confirmedOnly") is not True
        or receipt.get("recoveryRequired") is not False
        or not transaction_receipt_valid
        or not valid_counts
        or counts.get("skipped") != 0
        or counts.get("conflicts") != 0
        or counts.get("manifestAliases") != counts.get("deterministicAliases")
        or counts.get("manifestAliases") != counts.get("liveBoundAliases")
        or counts.get("manifestAliases") != counts.get("activeValidatedAliases")
        or receipt.get("skipped") != []
        or receipt.get("conflicts") != []
    ):
        raise RuntimeError(
            "RenderDoc did not prove a complete strict resource-name commit"
        )
    return dict(receipt)


def _resource_alias_publication_receipt(
    *,
    rows: Sequence[Mapping[str, Any]],
    aliases: Sequence[Mapping[str, Any]],
    replaced_targets: set[tuple[Any, ...]],
    bridge_receipt: Mapping[str, Any],
    binding: Mapping[str, Any],
    ledger_path: Path,
) -> dict[str, Any]:
    from .shader_workspace.resource_name_publication import texture_physical_target

    written = {
        (item.get("resourceId"), item.get("displayName"))
        for item in (bridge_receipt.get("written") or [])
        if isinstance(item, Mapping)
    }
    bridge_replaced = {
        (item.get("resourceId"), item.get("displayName"))
        for item in (bridge_receipt.get("replacedManaged") or [])
        if isinstance(item, Mapping)
    }
    kept = {
        (item.get("resourceId"), item.get("requestedDisplayName")): item
        for item in (bridge_receipt.get("keptUser") or [])
        if isinstance(item, Mapping)
    }
    outcomes: list[dict[str, Any]] = []
    for row, alias in zip(rows, aliases):
        key = (row.get("resourceId"), row.get("alias"))
        target = texture_physical_target(alias)
        if key in kept:
            outcome = "keptUser"
            current_name = kept[key].get("displayName")
        elif key in bridge_replaced or (key in written and target in replaced_targets):
            outcome = "replacedManaged"
            current_name = row.get("alias")
        elif key in written:
            outcome = "written"
            current_name = row.get("alias")
        else:
            raise RuntimeError(
                "RenderDoc commit omitted a requested texture resource receipt"
            )
        outcomes.append({
            **dict(row),
            "outcome": outcome,
            "currentDisplayName": current_name,
        })
    counts = {
        "requested": len(rows),
        "written": sum(item["outcome"] == "written" for item in outcomes),
        "replacedManaged": sum(
            item["outcome"] == "replacedManaged" for item in outcomes
        ),
        "keptUser": sum(item["outcome"] == "keptUser" for item in outcomes),
        "rejected": 0,
        "skipped": 0,
    }
    return {
        "schema": "replaylab-shader-resource-name-publication/v1",
        "schemaVersion": 1,
        "applied": bool(counts["written"] or counts["replacedManaged"]),
        "complete": sum(counts[key] for key in (
            "written", "replacedManaged", "keptUser"
        )) == counts["requested"],
        "counts": counts,
        "rows": outcomes,
        "bindingId": binding.get("bindingId"),
        "captureId": binding.get("captureId"),
        "captureSessionId": binding.get("captureSessionId"),
        "eventId": binding.get("eventId"),
        "stage": binding.get("stage"),
        "transactionId": bridge_receipt.get("transactionId"),
        "operationLedgerPath": str(ledger_path),
        "bridgeReceipt": dict(bridge_receipt),
        "acceptance": {
            "allRequestedRowsAccountedFor": True,
            "userAliasesPreserved": counts["keptUser"],
            "bridgeSkipped": 0,
            "bridgeConflicts": 0,
        },
    }


@mcp.tool()
async def publish_shader_resource_names(
    workspace_path: str,
    rows_json: str,
    operation_id: str,
    event_id: int,
    stage: str = "fragment",
    wait_seconds: float = 5.0,
) -> str:
    """Publish AI-selected texture names on one current Shader binding.

    Pass content-matched rows with the exact current ``event_id`` and ``stage``.
    The Host does not authenticate the Agent's semantic interpretation through a
    task report, asset-resolution token, HMAC, session owner, or ``evidenceAssets``.
    It validates the managed workspace, current Shader bytes, and every live
    resourceId/register/space tuple, then merges the project alias manifest under
    the existing strict atomic/CAS/idempotency contract. Existing user custom
    names are returned as ``keptUser``; earlier Bread-managed names may be
    replaced. Reuse the caller-generated ``operation_id`` only for an identical
    timeout recovery.
    """

    try:
        from .shader_workspace.mutation_jobs import (
            normalize_operation_id,
            start_shader_mutation_job,
            wait_for_shader_mutation_job,
        )
        from .shader_workspace.resource_name_publication import (
            LEDGER_SCHEMA,
            ledger_phase as resource_publication_ledger_phase,
            merge_alias_manifest,
            publication_paths,
            read_alias_manifest_exact,
            read_ledger,
            replay_committed_receipt as replay_committed_resource_receipt,
            texture_target,
            write_ledger,
            write_manifest,
        )

        requested = json.loads(str(rows_json or "[]"))
        if not isinstance(requested, list) or not requested:
            raise ValueError("rows_json must be a non-empty resourceAliasRows list")
        resolved_operation_id = normalize_operation_id(operation_id, required=True)
        workspace_status = await asyncio.to_thread(
            _alias_publication_workspace_status, workspace_path
        )
        root = Path(str(workspace_status["workspacePath"])).resolve()
        caller_request = {
            "tool": "publish_shader_resource_names",
            "operationId": resolved_operation_id,
            "workspacePath": str(root),
            "eventId": event_id,
            "stage": normalize_stage(stage),
            "rows": copy.deepcopy(requested),
        }
        caller_request_sha, compatible_caller_request_shas = (
            workspace_bound_request_hashes(caller_request, root)
        )
        durable_replay = replay_committed_resource_receipt(
            workspace_root=root,
            operation_id=resolved_operation_id,
            caller_request_sha256=caller_request_sha,
            compatible_caller_request_sha256=compatible_caller_request_shas,
        )
        if durable_replay is not None:
            return _ok(durable_replay)

        rows, binding = await asyncio.to_thread(
            _current_resource_alias_publication_binding,
            root,
            requested,
            event_id=event_id,
            stage=stage,
            status=workspace_status,
        )
        bridge_operation_id = hashlib.sha256(
            ("resource-name-publication\0" + resolved_operation_id).encode("utf-8")
        ).hexdigest()[:32]
        manifest_path, ledger_path = publication_paths(root, resolved_operation_id)
        aliases = _resource_alias_manifest_rows(rows, binding)
        request = {
            "tool": "publish_shader_resource_names",
            "workspaceId": binding.get("workspaceId"),
            "bindingId": binding.get("bindingId"),
            "rows": rows,
        }
        request_sha = _canonical_json_sha256(request, "resource name publication")
        target_id = "resource-names:%s" % binding.get("workspaceId")

        def _runner() -> dict[str, Any]:
            slot = LongToolSlot(
                "publish_shader_resource_names",
                {
                    "operation_id": resolved_operation_id,
                    "workspace_id": binding.get("workspaceId"),
                },
            )
            if slot.busy is not None:
                raise RuntimeError(
                    "another long tool is active; inspect get_host_runtime_status"
                )
            ok = False
            old_manifest_path = ""
            old_manifest_sha = ""
            old_transaction_id = ""
            old_manifest_verified = False
            bridge_mutation_attempted = False
            ledger: dict[str, Any] | None = None
            try:
                slot.update(
                    "resource-name-preflight",
                    operationId=resolved_operation_id,
                    detail="verify and merge the active alias transaction",
                )
                ledger = read_ledger(ledger_path)
                if ledger is not None and (
                    ledger.get("operationId") != resolved_operation_id
                    or ledger.get("requestSha256") != request_sha
                    or (
                        ledger.get("callerRequestSha256")
                        and ledger.get("callerRequestSha256")
                        not in {
                            caller_request_sha,
                            *compatible_caller_request_shas,
                        }
                    )
                    or (
                        ledger.get("workspaceRoot")
                        and canonical_workspace_identity(
                            str(ledger.get("workspaceRoot") or "")
                        )
                        != canonical_workspace_identity(root)
                    )
                    or ledger.get("captureId") != binding.get("captureId")
                    or ledger.get("captureSessionId")
                    != binding.get("captureSessionId")
                    or ledger.get("bridgeOperationId") != bridge_operation_id
                ):
                    raise RuntimeError(
                        "resource-name operation id is bound to different inputs"
                    )
                phase = (
                    resource_publication_ledger_phase(ledger)
                    if ledger is not None
                    else ""
                )
                status = _resource_alias_transaction_status(
                    str(binding["captureId"]),
                    str(binding["captureSessionId"]),
                )
                if ledger is not None and phase == "recovery-required":
                    active = status.get("mutationPresent") is True
                    transaction_id = str(status.get("transactionId") or "")
                    manifest_sha = str(status.get("manifestSha256") or "")
                    exact_new = active and (
                        transaction_id == str(ledger.get("bridgeOperationId") or "")
                        and manifest_sha == str(ledger.get("manifestSha256") or "")
                    )
                    exact_old = active and (
                        bool(ledger.get("oldTransactionId"))
                        and transaction_id
                        == str(ledger.get("oldTransactionId") or "")
                        and manifest_sha
                        == str(ledger.get("oldManifestSha256") or "")
                    )
                    exact_none = (
                        not active
                        and status.get("state") in {"absent", "rolled-back"}
                        and status.get("recoveryRequired") is False
                    )
                    if not (exact_new or exact_old or exact_none):
                        raise RuntimeError(
                            "resource-name publication recovery is still ambiguous; "
                            "the durable ledger was preserved"
                        )
                replaced_targets: set[tuple[Any, ...]] = set()
                if ledger is None:
                    previous_aliases: list[Mapping[str, Any]] = []
                    if status.get("mutationPresent"):
                        old_transaction_id = str(status.get("transactionId") or "")
                        old_manifest_path = str(status.get("manifestPath") or "")
                        old_manifest_sha = str(status.get("manifestSha256") or "")
                        old_document, unused_raw = read_alias_manifest_exact(
                            old_manifest_path,
                            old_manifest_sha,
                            str(binding["captureId"]),
                        )
                        old_manifest_verified = True
                        previous_aliases = list(old_document["aliases"])
                    merged, replaced_targets = merge_alias_manifest(
                        str(binding["captureId"]), previous_aliases, aliases
                    )
                    manifest_sha = write_manifest(manifest_path, merged)
                    ledger = {
                        "schema": LEDGER_SCHEMA,
                        "schemaVersion": 1,
                        "operationId": resolved_operation_id,
                        "bridgeOperationId": bridge_operation_id,
                        "requestSha256": request_sha,
                        "callerRequestSha256": caller_request_sha,
                        "workspaceRoot": str(root),
                        "bindingId": binding.get("bindingId"),
                        "captureId": binding.get("captureId"),
                        "captureSessionId": binding.get("captureSessionId"),
                        "manifestPath": str(manifest_path),
                        "manifestSha256": manifest_sha,
                        "oldTransactionId": old_transaction_id,
                        "oldManifestPath": old_manifest_path,
                        "oldManifestSha256": old_manifest_sha,
                        "replacedTargets": [list(item) for item in sorted(replaced_targets)],
                        "phase": "prepared",
                        "result": None,
                    }
                    write_ledger(ledger_path, ledger)
                else:
                    manifest_path_from_ledger = Path(str(ledger.get("manifestPath") or ""))
                    if canonical_workspace_identity(
                        manifest_path_from_ledger
                    ) != canonical_workspace_identity(manifest_path):
                        raise RuntimeError("resource-name ledger manifest path changed")
                    manifest_document, unused_raw = read_alias_manifest_exact(
                        str(manifest_path),
                        str(ledger.get("manifestSha256") or ""),
                        str(binding["captureId"]),
                    )
                    # Ensure the durable manifest still contains every requested
                    # exact row before using it for crash recovery.
                    durable_targets = {
                        texture_target(item)
                        for item in manifest_document.get("aliases") or []
                        if isinstance(item, Mapping)
                        and str(item.get("bindingKind") or "").casefold()
                        == "textureresource"
                    }
                    if not all(texture_target(item) in durable_targets for item in aliases):
                        raise RuntimeError("resource-name durable manifest lost a requested row")
                    replaced_targets = {
                        tuple(item) for item in (ledger.get("replacedTargets") or [])
                        if isinstance(item, list)
                    }
                    old_transaction_id = str(ledger.get("oldTransactionId") or "")
                    old_manifest_path = str(ledger.get("oldManifestPath") or "")
                    old_manifest_sha = str(ledger.get("oldManifestSha256") or "")
                    old_fields = (
                        old_transaction_id, old_manifest_path, old_manifest_sha
                    )
                    if any(old_fields):
                        if not all(old_fields):
                            raise RuntimeError(
                                "resource-name ledger has incomplete old-manifest recovery data"
                            )
                        read_alias_manifest_exact(
                            old_manifest_path,
                            old_manifest_sha,
                            str(binding["captureId"]),
                        )
                        old_manifest_verified = True

                manifest_sha = str(ledger["manifestSha256"])
                # A timeout may have hidden the successful load. Asking with the
                # same bridge operation id returns its committed receipt.
                if (
                    status.get("mutationPresent")
                    and status.get("transactionId") == bridge_operation_id
                    and status.get("manifestSha256") == manifest_sha
                ):
                    bridge_mutation_attempted = True
                    bridge_receipt = _load_resource_alias_manifest(
                        manifest_path, manifest_sha, bridge_operation_id
                    )
                else:
                    if status.get("mutationPresent"):
                        if (
                            status.get("transactionId") != old_transaction_id
                            or status.get("manifestSha256") != old_manifest_sha
                        ):
                            raise RuntimeError(
                                "another alias transaction replaced the prepared publication"
                            )
                        slot.update(
                            "resource-name-rollback-old-aliases",
                            operationId=resolved_operation_id,
                        )
                        bridge_mutation_attempted = True
                        rollback = _rollback_resource_alias_transaction(
                            capture_id=str(binding["captureId"]),
                            capture_session_id=str(binding["captureSessionId"]),
                            transaction_id=old_transaction_id,
                        )
                        ledger["oldRollback"] = rollback
                        ledger["phase"] = "old-rolled-back"
                        write_ledger(ledger_path, ledger)
                    slot.update(
                        "resource-name-load-merged-aliases",
                        operationId=resolved_operation_id,
                    )
                    try:
                        bridge_mutation_attempted = True
                        bridge_receipt = _load_resource_alias_manifest(
                            manifest_path, manifest_sha, bridge_operation_id
                        )
                    except Exception:
                        # Resolve the common lost-response case before attempting
                        # any rollback. A committed bridge ledger is authoritative.
                        after = _resource_alias_transaction_status(
                            str(binding["captureId"]),
                            str(binding["captureSessionId"]),
                        )
                        if (
                            after.get("mutationPresent")
                            and after.get("transactionId") == bridge_operation_id
                            and after.get("manifestSha256") == manifest_sha
                        ):
                            bridge_receipt = _load_resource_alias_manifest(
                                manifest_path, manifest_sha, bridge_operation_id
                            )
                        else:
                            raise
                result = _resource_alias_publication_receipt(
                    rows=rows,
                    aliases=aliases,
                    replaced_targets=replaced_targets,
                    bridge_receipt=bridge_receipt,
                    binding=binding,
                    ledger_path=ledger_path,
                )
                ledger["phase"] = "committed"
                ledger["result"] = result
                ledger["callerRequestSha256"] = caller_request_sha
                ledger["workspaceRoot"] = str(root)
                write_ledger(ledger_path, ledger)
                ok = True
                runtime = slot.close(ok=True)
                return attach_runtime(result, runtime or {})
            except Exception as exc:
                # A failed/lost receipt must never leave the new transaction
                # active while the Host reports failure. Roll it back even when
                # there was no prior alias transaction. Restore an old project
                # manifest only when its exact bytes passed preflight.
                if bridge_mutation_attempted:
                    try:
                        current = _resource_alias_transaction_status(
                            str(binding["captureId"]),
                            str(binding["captureSessionId"]),
                        )
                        if (
                            current.get("mutationPresent")
                            and current.get("transactionId") == bridge_operation_id
                        ):
                            _rollback_resource_alias_transaction(
                                capture_id=str(binding["captureId"]),
                                capture_session_id=str(binding["captureSessionId"]),
                                transaction_id=bridge_operation_id,
                            )
                            current = _resource_alias_transaction_status(
                                str(binding["captureId"]),
                                str(binding["captureSessionId"]),
                            )
                        if old_manifest_verified:
                            if not current.get("mutationPresent"):
                                restored = _load_resource_alias_manifest(
                                    Path(old_manifest_path),
                                    old_manifest_sha,
                                    old_transaction_id,
                                )
                                if ledger is not None:
                                    ledger["oldRestoreReceipt"] = restored
                            elif not (
                                current.get("transactionId") == old_transaction_id
                                and current.get("manifestSha256") == old_manifest_sha
                            ):
                                raise RuntimeError(
                                    "an unexpected alias transaction blocks old-manifest recovery"
                                )
                            if ledger is not None:
                                ledger["phase"] = "failed-old-restored"
                                ledger["error"] = str(exc)[:800]
                                write_ledger(ledger_path, ledger)
                        else:
                            if current.get("mutationPresent"):
                                raise RuntimeError(
                                    "an unexpected alias transaction remains after failed publication"
                                )
                            if ledger is not None:
                                ledger["phase"] = "failed-new-rolled-back"
                                ledger["error"] = str(exc)[:800]
                                write_ledger(ledger_path, ledger)
                    except Exception as restore_error:
                        if ledger is not None:
                            ledger["phase"] = "recovery-required"
                            ledger["error"] = str(exc)[:800]
                            ledger["recoveryError"] = str(restore_error)[:800]
                            write_ledger(ledger_path, ledger)
                        raise RuntimeError(
                            "resource-name publication failed and bridge state "
                            "could not be recovered: %s; recovery: %s"
                            % (str(exc), str(restore_error))
                        ) from restore_error
                raise
            finally:
                if not ok:
                    slot.close(ok=False)

        job = start_shader_mutation_job(
            tool="publish_shader_resource_names",
            workspace_path=str(root),
            organization_id=target_id,
            request_sha256=request_sha,
            operation_id=resolved_operation_id,
            runner=_runner,
            retry_failed=True,
        )
        waited = max(0.0, min(float(wait_seconds or 0.0), 5.0))
        if waited and job.get("status") not in {"busy", "done", "failed"}:
            job = await asyncio.to_thread(
                wait_for_shader_mutation_job,
                str(job.get("operationId") or ""),
                waited,
            ) or job
        return _ok(_shader_mutation_tool_result(job))
    except Exception as error:
        return _shader_err(error, "publish-resource-names")


def _validate_compiled_cbuffer_layout_receipt(
    receipt: Mapping[str, Any] | None,
    *,
    identity: Mapping[str, Any],
    rows: Sequence[Mapping[str, Any]],
    block_alias: str = "",
) -> dict[str, Any]:
    """Recheck optional compiled-offset evidence without granting name authority.

    Current capture reflection binds every requested alias to a physical leaf
    before this check. A cooked layout receipt, when supplied, is checked in
    full; its absence says nothing about whether the Agent's chosen *meaning*
    is correct and does not prevent a physically bound display name.
    """

    def neutral_prefix(bind: int, space: int) -> str:
        return (
            "cbuffer_b%d" % bind
            if space == 0
            else "cbuffer_s%d_b%d" % (space, bind)
        )

    semantic_rows = [
        row
        for row in rows
        if str(row.get("alias") or "").strip()
        != "%s_offset_%d" % (
            neutral_prefix(int(row.get("bind") or 0), int(row.get("space") or 0)),
            int(row.get("byteOffset") or 0),
        )
    ]
    semantic_block = False
    if str(block_alias or "").strip():
        first = rows[0]
        semantic_block = str(block_alias).strip() != neutral_prefix(
            int(first.get("bind") or 0), int(first.get("space") or 0)
        )

    if receipt is None:
        return {
            "provided": False,
            "validated": False,
            "authority": "none",
            "neutralOnly": not (semantic_rows or semantic_block),
            "semanticNamesAgentChosen": bool(semantic_rows or semantic_block),
            "note": (
                "current Shader reflection verifies physical targets; semantic "
                "meaning is Agent-chosen and not Host-verified"
            ),
        }
    if not isinstance(receipt, Mapping):
        raise ValueError("compiled_layout_receipt must be the decoder receipt object")
    supplied_sha = _strict_lower_hex(
        receipt.get("receiptSha256"), 64, "compiled layout receipt SHA256"
    )
    unsigned = {
        key: copy.deepcopy(value)
        for key, value in receipt.items()
        if key != "receiptSha256"
    }
    if (
        receipt.get("schema") != "bread-compiled-cbuffer-layout/v1"
        or receipt.get("schemaVersion") != 1
        or _canonical_json_sha256(unsigned, "compiled CBuffer layout receipt")
        != supplied_sha
    ):
        raise ValueError("compiled layout receipt is malformed or changed")
    if receipt.get("authority") != "evidence-only":
        raise ValueError("compiled layout receipt must be evidence-only")
    if receipt.get("capturePlatformCompatible") is not True:
        raise ValueError(
            "semantic CBuffer aliases require a compiled material ShaderMap "
            "proved compatible with the capture API"
        )
    shader_raw = str(receipt.get("shaderRawSha256") or "").lower()
    if shader_raw != str(identity.get("rawSha256") or "").lower():
        raise ValueError("compiled layout receipt targets different original Shader bytes")
    receipt_stage = str(receipt.get("stage") or "")
    if not receipt_stage or normalize_stage(receipt_stage) != normalize_stage(identity.get("stage")):
        raise ValueError("compiled layout receipt targets a different Shader stage")
    receipt_bind, receipt_space = receipt.get("bind"), receipt.get("space")
    if type(receipt_bind) is not int or type(receipt_space) is not int:
        raise ValueError("compiled layout receipt has no exact bind/space")
    ranges = receipt.get("outputRanges")
    if not isinstance(ranges, list) or not ranges:
        raise ValueError("compiled layout receipt contains no decoded output ranges")
    clean_ranges: list[tuple[int, int]] = []
    for item in ranges:
        if not isinstance(item, Mapping):
            raise ValueError("compiled layout receipt output range is invalid")
        offset, size = item.get("byteOffset"), item.get("byteSize")
        if type(offset) is not int or type(size) is not int or offset < 0 or size <= 0:
            raise ValueError("compiled layout receipt output range is invalid")
        clean_ranges.append((offset, offset + size))
    layouts = {str(item.get("layoutSha256") or "") for item in rows}
    receipt_layout = str(receipt.get("layoutSha256") or "").lower()
    if not receipt_layout or layouts != {receipt_layout}:
        raise ValueError("compiled layout receipt differs from current reflected layout")
    for row in rows:
        if row.get("bind") != receipt_bind or int(row.get("space") or 0) != receipt_space:
            raise ValueError("compiled layout receipt does not cover every requested bind/space")
        offset = int(row.get("byteOffset") or 0)
        leaf_window = (offset, offset + 16)
        if not any(start < leaf_window[1] and end > leaf_window[0]
                   for start, end in clean_ranges):
            raise ValueError(
                "requested CBuffer row is outside the decoded compiled output ranges"
            )
    evidence_files = receipt.get("evidenceFiles")
    if not isinstance(evidence_files, list) or not evidence_files:
        raise ValueError("compiled layout receipt contains no material evidence files")
    for item in evidence_files:
        if (
            not isinstance(item, Mapping)
            or not isinstance(item.get("path"), str)
            or type(item.get("byteSize")) is not int
        ):
            raise ValueError("compiled layout receipt evidence file is invalid")
        _strict_lower_hex(item.get("sha256"), 64, "compiled evidence SHA256")
    return {
        "provided": True,
        "validated": True,
        "authority": "evidence-only",
        "receiptSha256": supplied_sha,
        "shaderPlatform": str(receipt.get("shaderPlatform") or ""),
        "metadataSha256": str(receipt.get("metadataSha256") or ""),
        "capturePlatformCompatible": receipt.get("capturePlatformCompatible"),
        "outputRangeCount": len(clean_ranges),
    }


from typing_extensions import NotRequired, TypedDict


class CBufferNamingReference(TypedDict):
    kind: Literal["capture", "shader-source", "unpacked-asset", "user-description", "analysis"]
    locator: str
    sha256: NotRequired[str]


class CBufferNamingEvidence(TypedDict):
    schema: Literal["bread-cbuffer-naming-evidence/v1"]
    summary: str
    references: list[CBufferNamingReference]


def _cbuffer_naming_evidence(value: Mapping[str, Any] | None) -> dict[str, Any] | None:
    """Bound an Agent's optional provenance claim without authorizing its name."""

    if value is None:
        return None
    if not isinstance(value, Mapping):
        raise ValueError('naming_evidence must be {"schema":"bread-cbuffer-naming-evidence/v1", "summary":"specific observed evidence", "references":[{"kind":"shader-source", "locator":"source/shader.hlsl:123"}]}')
    if value.get("schema") != "bread-cbuffer-naming-evidence/v1":
        raise ValueError('naming_evidence.schema must be exactly "bread-cbuffer-naming-evidence/v1"; also supply summary and references:[{kind,locator,sha256?}]. Use actual evidence, not an invented asset match')
    summary = value.get("summary")
    references = value.get("references")
    if not isinstance(summary, str) or not summary.strip() or len(summary) > 2000:
        raise ValueError("naming_evidence requires a bounded summary")
    if not isinstance(references, list) or not 1 <= len(references) <= 16:
        raise ValueError('naming_evidence.references requires 1-16 objects, e.g. {"kind":"shader-source","locator":"source/shader.hlsl:123"}; sha256 is optional')
    clean_references: list[dict[str, str]] = []
    for item in references:
        if not isinstance(item, Mapping):
            raise ValueError('Each naming_evidence reference must be an object with kind and locator, not a string; e.g. {"kind":"shader-source","locator":"source/shader.hlsl:123"}')
        kind, locator, digest = item.get("kind"), item.get("locator"), item.get("sha256")
        if (
            not isinstance(kind, str)
            or kind not in {"capture", "shader-source", "unpacked-asset", "user-description", "analysis"}
            or not isinstance(locator, str) or not locator.strip() or len(locator) > 512
        ):
            raise ValueError("naming_evidence reference kind must be capture/shader-source/unpacked-asset/user-description/analysis; locator must name the actual evidence in 1-512 characters")
        reference = {"kind": kind, "locator": locator.strip()}
        if digest is not None:
            reference["sha256"] = _strict_lower_hex(
                digest, 64, "naming evidence reference SHA256"
            )
        clean_references.append(reference)
    return {
        "schema": "bread-cbuffer-naming-evidence/v1",
        "summary": summary.strip(),
        "references": clean_references,
        "authority": "agent-provenance-only",
    }


def _cbuffer_json_argument(inline: str, file: str, digest: str, label: str) -> tuple[Any, dict | None]:
    if file:
        if str(inline or "[]").strip() != "[]":
            raise ValueError(label + "_json and " + label + "_file are mutually exclusive; leave the inline argument at its default []")
        from .agent_workspace_files import read_agent_json_file
        value, metadata = read_agent_json_file(file, digest)
        return value, {"argument": label, **metadata}
    if digest:
        raise ValueError(label + "_file_sha256 requires " + label + "_file")
    return json.loads(str(inline or "[]")), None


@mcp.tool()
async def publish_cbuffer_aliases(
    workspace_path: str,
    rows_json: str,
    operation_id: str,
    block_alias: str = "",
    compiled_layout_receipt: dict | None = None,
    asset_alias_authorization: dict | None = None,
    wait_seconds: float = 5.0,
    naming_evidence: CBufferNamingEvidence | None = None,
    semantic_fields_json: str = "[]",
    semantic_source_sha256: str = "",
    binding_reviews_json: str = "[]",
    semantic_fields_file: str = "",
    semantic_fields_file_sha256: str = "",
    binding_reviews_file: str = "",
    binding_reviews_file_sha256: str = "",
) -> str:
    """Name rows of a constant buffer for RenderDoc's panel, read or not.

    Use English parameter identifiers by default even in a Chinese UI/chat;
    localize descriptions, not existing source/asset identifiers. Preserve user
    labels and follow an explicitly requested naming language.

    The companion to ``rename_shader_workspace_symbols`` and deliberately wider
    than it. A rename changes an identifier in the organized HLSL, so it only
    exists for a lane this shader declares -- and a cooked shader declares only
    what it reads, often three members of a hundred-lane block. An alias is a
    *display name* keyed by a current reflected byte offset. Named layouts may be
    shared by layout; stripped ``unknown[N]`` layouts are additionally scoped by
    original Shader bytes, stage, bind and space so unrelated shaders cannot inherit
    the names. Nothing about the captured Shader or its reflection changes.

    ``rows_json`` is what ``propose_shader_names_from_asset`` returns under
    ``cbufferAliasRows``: ``[{"bind": 4, "space": 0, "byteOffset": 80,
    "alias": "Roughness | Metallic | AO"}]``. Prefer rows returned by
    ``decode_material_shader_outputs`` after following the exact material parent
    chain and selecting the capture-compatible cooked ShaderMap platform. Pass its
    ``compiledLayoutReceipt`` when that evidence is available. A supplied receipt
    must match the capture platform, Shader bytes, reflected layout and requested
    offsets. Semantic aliases may also be chosen from other explicit evidence;
    pass ``naming_evidence={"schema":"bread-cbuffer-naming-evidence/v1",
    "summary":"Specific observed naming evidence", "references":[{
    "kind":"shader-source", "locator":"source/shader.hlsl:123"}]}`` to
    preserve that provenance. References use kind capture/shader-source/
    unpacked-asset/user-description/analysis, a concrete locator (1-512 chars),
    and optionally the evidence file's lowercase SHA256. Supply 1-16 references
    and a summary up to 2000 characters. Omit this optional object when unused;
    do not invent an asset match. The Host checks the *physical target* from current capture
    reflection, not the Agent's interpretation of a name. Publication
    never depends on a
    task report, conversation/session/Agent identity, asset resolution ownership,
    ``evidenceAssets`` or an HMAC authorization. The legacy
    ``asset_alias_authorization`` argument is accepted but ignored. User names are
    never overwritten (``keptUser``).

    ``semantic_fields_json`` optionally groups/splits physical 32-bit lanes for
    display only, without changing reflection, source declarations or ABI:
    ``[{"bind":5,"space":0,"name":"baseColor","type":"float4",
    "components":[{"offset":832},{"offset":836},{"offset":840},{"offset":844}],
    "status":"inferred","provenance":"shader","evidence":"shader.hlsl:123",
    "description":"Base surface color and opacity"}]``. Types are float/int/uint
    with optional vector width 2-4; offsets may be noncontiguous but cannot
    overlap. Each component must exist with a compatible reflected scalar type.
    Status is confirmed/inferred and provenance is asset/shader/combined. These
    are Agent provenance, not Host certification of the interpretation. Send the
    complete intended field list for each touched block: it replaces that
    Shader scope's previous AI semantic view. Unmapped lanes and user names stay
    visible. Untouched blocks retain their views; row-only publication leaves
    every semantic view unchanged. ``rows_json="[]"`` permits semantic-only
    publication. ``semantic_source_sha256`` may identify the saved Shader source
    used for the post-organization review; when supplied it must match the
    workspace's current saved source. Check semanticFieldsWritten/KeptUser in
    the receipt, not only ``applied``.

    Whole-Shader delivery accounts for every active reflected CBuffer binding,
    not just blocks submitted in this call. For physically present lanes whose
    roles remain unknown after reading their consumers, provide
    ``binding_reviews_json=[{"bind":1,"space":0,"unresolvedOffsets":[16,20],
    "evidence":"Exact unresolved consumers and why their role remains uncertain"}]``.
    An optional ``unusedOffsets`` list requires ``unusedEvidence`` proving non-use
    across the current program's branches and indexing; it must not overlap named
    or unresolved lanes. ``bindingCoverage.complete`` is review coverage, whereas
    ``namingComplete`` stays false while any reviewed role remains unresolved.
    Do not invent names to fill coverage. Existing same-source/current-candidate
    coverage for untouched blocks is retained; changed source invalidates it.
    The returned ``bindingCoverage`` names missing bindings/lanes. Publish all
    supported fields in one batch; a successful CB5 call alone cannot complete
    naming of CB1-CB4. Inspect source alias candidates with the outline's
    ``cbuffer-semantics`` section before constructing the fields.

    For generated arrays or large field lists, write UTF-8 JSON in this run's
    controller-owned Agent working directory and pass ``semantic_fields_file``
    plus ``semantic_fields_file_sha256`` (the exact file bytes' lowercase SHA256).
    Leave ``semantic_fields_json`` at its default ``[]``. Likewise use
    ``binding_reviews_file`` + ``binding_reviews_file_sha256`` instead of inline
    ``binding_reviews_json``. Each JSON file is limited to 16 MiB, must contain
    the same array as the inline form, and is read once before validation.
    Files outside this run, links, launch/config files and changed hashes are
    rejected. File data receives all ordinary physical-layout/publication checks;
    a path is not evidence or authority. Do not print/re-serialize large files
    into a tool call. Identical inline/file contents share idempotent identity.

    Stripped original reflection can contain overlapping unknown/uint storage
    placeholders rather than actual typed values. When that original block is
    unusable, the Host may bind this display view to the independently verified
    active replacement's typed reflection. The requested field types must still
    match actual active lanes; typed original captures cannot use this fallback.
    The receipt identifies ``semanticBindingBasis=verified-active-reflection``
    and ``semanticOriginalUnavailable``; the persisted view retains both original
    and active Shader hashes. No reinterpretation or Shader mutation occurs.

    ``operation_id`` is caller-generated on the first call and reused unchanged
    after a timeout. The Host stages every affected layout, rolls all recognized
    targets back on failure, and retains a durable receipt so a process restart
    never repeats an already committed publication.

    ``applied`` means at least one row or block alias was actually written;
    ``partial`` and ``counts`` identify requests that were only partly written.
    Read the per-block receipts and skipped rows before reporting completion.
    """

    try:
        from .shader_workspace.cbuffer_alias_publication import (
            publication_paths as cbuffer_publication_paths,
            publish_transaction as publish_cbuffer_alias_transaction,
            replay_committed_receipt as replay_committed_cbuffer_receipt,
        )
        from .shader_workspace.mutation_jobs import (
            normalize_operation_id,
            start_shader_mutation_job,
            wait_for_shader_mutation_job,
        )
        from .shader_workspace.cbuffer_semantics import normalize_fields, select_physical_layouts
        from .shader_workspace import aliases as cbuffer_aliases

        resolved_operation_id = normalize_operation_id(operation_id, required=True)
        clean_naming_evidence = _cbuffer_naming_evidence(naming_evidence)
        naming_evidence_sha = (
            _canonical_json_sha256(clean_naming_evidence, "CBuffer naming evidence")
            if clean_naming_evidence is not None else ""
        )
        requested = json.loads(str(rows_json or "[]"))
        semantic_requested, semantic_input = _cbuffer_json_argument(
            semantic_fields_json, semantic_fields_file, semantic_fields_file_sha256, "semantic_fields")
        binding_reviews, binding_input = _cbuffer_json_argument(
            binding_reviews_json, binding_reviews_file, binding_reviews_file_sha256, "binding_reviews")
        input_files = [item for item in (semantic_input, binding_input) if item is not None]
        if (not isinstance(requested, list) or not isinstance(semantic_requested, list)
                or not isinstance(binding_reviews, list) or not (requested or semantic_requested or binding_reviews)):
            raise ValueError("provide non-empty rows_json, semantic fields or binding reviews arrays; file inputs use the same array schema as their inline JSON counterparts")
        workspace_status = await asyncio.to_thread(
            _alias_publication_workspace_status, workspace_path
        )
        root = Path(str(workspace_status["workspacePath"])).resolve()
        semantic_source_sha = (
            _strict_lower_hex(semantic_source_sha256, 64, "semantic source SHA256")
            if semantic_source_sha256 else ""
        )
        compiled_receipt_sha = (
            str((compiled_layout_receipt or {}).get("receiptSha256") or "")
            if isinstance(compiled_layout_receipt, Mapping)
            else ""
        )
        caller_request = {
            "tool": "publish_cbuffer_aliases",
            "operationId": resolved_operation_id,
            "workspacePath": str(root),
            "rows": copy.deepcopy(requested),
            "blockAlias": str(block_alias or ""),
            "compiledLayoutReceiptSha256": compiled_receipt_sha,
            **({"semanticFields": semantic_requested,
                "semanticSourceSha256": semantic_source_sha} if (semantic_requested or binding_reviews) else {}),
            **({"namingEvidenceSha256": naming_evidence_sha} if naming_evidence_sha else {}),
            **({"bindingReviews": binding_reviews} if binding_reviews else {}),
        }
        caller_request_sha, compatible_caller_request_shas = (
            workspace_bound_request_hashes(caller_request, root)
        )
        # A committed pre-migration operation may have included the now-ignored
        # authorization object in its caller hash.  Accept that exact historical
        # spelling only for idempotent replay; it is never consulted for a new write.
        if isinstance(asset_alias_authorization, Mapping):
            legacy_request = {
                "tool": "publish_cbuffer_aliases",
                "operationId": resolved_operation_id,
                "workspacePath": str(root),
                "rows": copy.deepcopy(requested),
                "blockAlias": str(block_alias or ""),
                "assetAliasAuthorization": copy.deepcopy(asset_alias_authorization),
            }
            unused_legacy_sha, legacy_compatible = workspace_bound_request_hashes(
                legacy_request, root
            )
            compatible_caller_request_shas = tuple(dict.fromkeys(
                [*compatible_caller_request_shas, unused_legacy_sha, *legacy_compatible]
            ))
        durable_replay = await asyncio.to_thread(
            replay_committed_cbuffer_receipt,
            workspace_root=root,
            operation_id=resolved_operation_id,
            caller_request_sha256=caller_request_sha,
            compatible_caller_request_sha256=compatible_caller_request_shas,
        )
        if durable_replay is not None:
            return _ok(durable_replay)

        source_dependencies_digest = ""
        if semantic_source_sha:
            from .shader_organization_review import _read_bytes
            from .shader_workspace.naming_delivery import source_context
            source_name = str((workspace_status.get("source") or {}).get("path") or "")
            if not source_name:
                raise ValueError("semantic source SHA256 does not match the current saved Shader source")
            _, semantic_source_bytes = _read_bytes(root, source_name, 4 * 1024 * 1024)
            if semantic_source_sha != hashlib.sha256(semantic_source_bytes).hexdigest():
                raise ValueError("semantic source SHA256 does not match the current saved Shader source")
            naming_context = source_context(root, semantic_source_bytes, source_name)
            if not naming_context["complete"]:
                raise ValueError("CBuffer naming include snapshot is unavailable: " + naming_context.get("diagnostic", ""))
            source_dependencies_digest = naming_context["sourceDependenciesDigest"]

        identity = await asyncio.to_thread(
            _shader_organization_cbuffer_alias_identity,
            str(root),
            status=workspace_status,
            status_loader=_alias_publication_workspace_status,
        )
        # The UI can retain captured reflection while a checked replacement
        # executes. Keep its independently verified owner identity separate.
        active_replacement_sha = str(identity.get("activeReplacementShaderRawSha256") or "")
        if active_replacement_sha:
            active_replacement_sha = _strict_lower_hex(
                active_replacement_sha, 64, "active replacement Shader SHA256")
        requested, authorized_block = (
            ShaderOrganizationManager.normalize_cbuffer_alias_rows(
                identity, requested, block_alias
            ) if requested else ([], None)
        )
        semantic_by_block, semantic_active_primary, semantic_original_unavailable = (
            select_physical_layouts(identity, semantic_requested)
        )
        if block_alias and not requested:
            raise ValueError("block_alias requires at least one physical alias row")
        block_alias = str((authorized_block or {}).get("alias") or "")
        binding = {
            "workspaceId": workspace_status.get("workspaceId"),
            "captureId": identity.get("captureId"),
            "captureSessionId": identity.get("captureSessionId"),
            "eventId": identity.get("eventId"),
            "stage": identity.get("stage"),
            "entryPoint": identity.get("entryPoint"),
            "shaderResourceId": identity.get("shaderResourceId"),
            "shaderRawSha256": identity.get("rawSha256"),
        }
        binding["bindingSha256"] = _canonical_json_sha256(
            binding, "current CBuffer alias publication binding"
        )
        compiled_layout = _validate_compiled_cbuffer_layout_receipt(
            compiled_layout_receipt,
            identity=identity,
            rows=requested,
            block_alias=block_alias,
        )
        blocks = [item for item in (identity.get("blocks") or []) if isinstance(item, Mapping)]
        from .shader_workspace.semantic_coverage import binding_coverage
        prior_coverage = None
        prior_path = root / "ai" / "cbuffer-name-publication.json"
        if prior_path.is_file() and not prior_path.is_symlink() and not prior_path.parent.is_symlink():
            try:
                from .shader_semantic_delivery import MAX_RECEIPT_BYTES
                prior_receipt = read_json_object(prior_path, MAX_RECEIPT_BYTES, "CBuffer naming receipt")
                if (semantic_source_sha and prior_receipt.get("semanticSourceSha256") == semantic_source_sha
                        and prior_receipt.get("sourceDependenciesDigest", "") == source_dependencies_digest
                        and prior_receipt.get("shaderRawSha256") == identity.get("rawSha256")
                        and prior_receipt.get("activeReplacementShaderRawSha256", "") == active_replacement_sha
                        and prior_receipt.get("activeDisplayShaderRawSha256") ==
                            (identity.get("activeDisplayShaderRawSha256") or identity.get("rawSha256"))):
                    prior_coverage = prior_receipt.get("bindingCoverage")
            except (OSError, ValueError):
                pass
        skipped: list[dict[str, Any]] = []
        by_block: dict[tuple[Any, Any], list[dict[str, Any]]] = {}
        for item in requested:
            bind, space = item.get("bind"), item.get("space") or 0
            offset = item.get("byteOffset")
            alias = str(item.get("alias") or "").strip()
            target = [block for block in blocks
                      if block.get("bind") == bind and (block.get("space") or 0) == space]
            block = target[0]
            by_block.setdefault((bind, space), []).append(
                {
                    "path": str(item["reflectedPath"]),
                    "offset": int(item["reflectedLeafOffset"]),
                    "alias": alias,
                    "scopeRawSha256": str(identity.get("rawSha256") or ""),
                    "scopeShaderResourceId": str(
                        identity.get("shaderResourceId") or ""
                    ),
                    "scopeStage": str(identity.get("stage") or ""),
                    "scopeBind": bind,
                    "scopeSpace": space,
                    "layoutSha256": str(item.get("layoutSha256") or ""),
                }
            )
        publications: list[dict[str, Any]] = []
        for key in semantic_by_block:
            by_block.setdefault(key, [])
        for (bind, space), entries in by_block.items():
            block = next(item for item in blocks
                         if item.get("bind") == bind and (item.get("space") or 0) == space)
            members = [{"name": member.get("name"), "offset": member.get("offset")}
                       for member in (block.get("members") or []) if isinstance(member, Mapping)]
            publications.append({
                "bind": bind,
                "space": space,
                "block": str(block.get("block") or ""),
                "members": members,
                "entries": entries,
                "shaderScope": {
                    "shaderRawSha256": str(identity.get("rawSha256") or ""),
                    "shaderResourceId": str(
                        identity.get("shaderResourceId") or ""
                    ),
                    "stage": str(identity.get("stage") or ""),
                    "bind": bind,
                    "space": space,
                    "layoutSha256": cbuffer_aliases.layout_sha256(str(block.get("block") or ""), members),
                },
                **({"semanticFields": semantic_by_block[(bind, space)],
                    "semanticSourceSha256": semantic_source_sha,
                    "semanticBindingBasis": "captured-reflection",
                    "semanticCapturedShaderSha256": str(identity.get("rawSha256") or "")}
                   if (bind, space) in semantic_by_block else {}),
                "blockAlias": (
                    block_alias or None
                    if requested and (bind, space)
                    == (requested[0].get("bind"), requested[0].get("space") or 0)
                    else None
                ),
            })

        semantic_mirror_skipped = []
        active_display_raw = str(identity.get("activeDisplayShaderRawSha256") or "")
        active_display_blocks = identity.get("activeDisplayBlocks") or []
        for (bind, space), fields in semantic_active_primary.items():
            display_block = next(block for block in active_display_blocks
                                 if block.get("bind") == bind and (block.get("space") or 0) == space)
            display_members = [{"name": member.get("name"), "offset": member.get("offset")}
                               for member in display_block.get("members", [])]
            publications.append({
                "bind": bind, "space": space, "block": str(display_block.get("block") or ""),
                "members": display_members, "entries": [], "blockAlias": None,
                "semanticBindingBasis": "verified-active-reflection",
                "shaderScope": {"shaderRawSha256": active_display_raw,
                                "shaderResourceId": str(identity.get("shaderResourceId") or ""),
                                "stage": str(identity.get("stage") or ""), "bind": bind, "space": space,
                                "layoutSha256": cbuffer_aliases.layout_sha256(str(display_block.get("block") or ""), display_members)},
                "semanticFields": fields, "semanticSourceSha256": semantic_source_sha,
                "semanticCapturedShaderSha256": str(identity.get("rawSha256") or ""),
            })
        if semantic_by_block and active_display_raw and active_display_raw != identity.get("rawSha256"):
            active_display_raw = _strict_lower_hex(active_display_raw, 64, "active display Shader SHA256")
            active_identity = {"blocks": active_display_blocks}
            for (bind, space), fields in semantic_by_block.items():
                mirrored_fields = []
                for field in fields:
                    try:
                        normalize_fields(active_identity, [{**field, "bind": bind, "space": space}])
                    except ValueError as mirror_error:
                        semantic_mirror_skipped.append({"bind": bind, "space": space, "name": field["name"],
                                                        "reason": str(mirror_error)})
                    else:
                        mirrored_fields.append(field)
                if not mirrored_fields:
                    continue
                display_block = next(block for block in active_display_blocks
                                     if block.get("bind") == bind and (block.get("space") or 0) == space)
                display_members = [{"name": member.get("name"), "offset": member.get("offset")}
                                   for member in display_block.get("members", [])]
                publications.append({
                    "bind": bind, "space": space, "block": str(display_block.get("block") or ""),
                    "members": display_members, "entries": [], "blockAlias": None, "displayMirror": True,
                    "shaderScope": {"shaderRawSha256": active_display_raw,
                                    "shaderResourceId": str(identity.get("shaderResourceId") or ""),
                                    "stage": str(identity.get("stage") or ""), "bind": bind, "space": space,
                                    "layoutSha256": cbuffer_aliases.layout_sha256(str(display_block.get("block") or ""), display_members)},
                    "semanticFields": mirrored_fields, "semanticSourceSha256": semantic_source_sha,
                    "semanticBindingBasis": "verified-active-reflection",
                    "semanticCapturedShaderSha256": str(identity.get("rawSha256") or ""),
                })

        from .shader_workspace.alias_display_mirror import append_display_alias_mirrors
        alias_mirror_skipped = append_display_alias_mirrors(identity, publications)
        display_sha = str(identity.get("activeDisplayShaderRawSha256") or identity.get("rawSha256") or "")
        display_fields = [{**field, "bind": item["bind"], "space": item["space"]}
                          for item in publications
                          if (item.get("shaderScope") or {}).get("shaderRawSha256") == display_sha
                          for field in item.get("semanticFields", [])]
        semantic_coverage = binding_coverage(identity, display_fields, binding_reviews, prior_coverage)
        from .shader_workspace.semantic_usage import attach_usage_reviews
        usage_review_skipped = attach_usage_reviews(
            identity, semantic_coverage, publications, semantic_source_sha,
            {(item["bind"], item.get("space", 0)) for item in binding_reviews})
        request = {
            "tool": "publish_cbuffer_aliases",
            "activeReplacementShaderRawSha256": active_replacement_sha,
            "activeDisplayShaderRawSha256": display_sha,
            **({"sourceDependenciesDigest": source_dependencies_digest} if source_dependencies_digest else {}),
            **binding,
            "requestedRows": requested,
            **({"requestedSemanticFields": semantic_requested,
                "semanticSourceSha256": semantic_source_sha} if (semantic_requested or binding_reviews) else {}),
            "publications": publications,
            "skipped": skipped,
            "semanticMirrorSkipped": semantic_mirror_skipped,
            "aliasMirrorSkipped": alias_mirror_skipped,
            "semanticOriginalUnavailable": semantic_original_unavailable,
            "compiledLayoutReceiptSha256": compiled_layout.get("receiptSha256"),
            **({"namingEvidenceSha256": naming_evidence_sha} if naming_evidence_sha else {}),
            "bindingCoverage": semantic_coverage,
            "usageReviewSkipped": usage_review_skipped,
        }
        request_sha = _canonical_json_sha256(request, "CBuffer alias publication")
        unused_transaction_dir, operation_ledger_path = cbuffer_publication_paths(
            root, resolved_operation_id
        )
        retention: dict[str, Any] = {"complete": False, "requested": False}

        def _build_payload(staged: list[dict[str, Any]]) -> dict[str, Any]:
            published = []
            semantic_mirrors = []
            for publication, result in zip(publications, staged):
                (semantic_mirrors if publication.get("displayMirror") else published).append({
                    "bind": publication["bind"],
                    "space": publication["space"],
                    "block": publication["block"],
                    "requestedRowCount": len(publication.get("entries") or []),
                    "requestedBlockAlias": bool(publication.get("blockAlias")),
                    "semanticBindingBasis": publication.get("semanticBindingBasis"),
                    **result,
                })
            counts = {
                "requestedRows": len(requested),
                "writtenRows": sum(len(item.get("written") or []) for item in published),
                "keptUserRows": sum(len(item.get("keptUser") or []) for item in published),
                "rejectedAliases": sum(len(item.get("rejected") or []) for item in published),
                "skippedRows": len(skipped),
                "unprocessedRows": 0,
                "requestedBlockAliases": int(bool(block_alias)),
                "writtenBlockAliases": sum(
                    item.get("blockAliasWritten") is True for item in published
                ),
                "keptUserBlockAliases": sum(
                    item.get("blockAliasKeptUser") is True for item in published
                ),
                "requestedSemanticFields": len(semantic_requested),
                "writtenSemanticFields": sum(item.get("semanticFieldsWritten", 0) for item in published),
                "keptUserSemanticFields": sum(item.get("semanticFieldsKeptUser", 0) for item in published),
                "requestedDisplaySemanticFields": sum(len(item.get("semanticFields") or []) for item in publications if item.get("semanticBindingBasis") == "verified-active-reflection"),
                "writtenDisplaySemanticFields": sum(item.get("semanticFieldsWritten", 0) for item in published + semantic_mirrors if item.get("semanticBindingBasis") == "verified-active-reflection"),
                "keptUserDisplaySemanticFields": sum(item.get("semanticFieldsKeptUser", 0) for item in published + semantic_mirrors if item.get("semanticBindingBasis") == "verified-active-reflection"),
                "requestedDisplayRows": sum(item["requestedRowCount"] for item in semantic_mirrors),
                "writtenDisplayRows": sum(len(item.get("written") or []) for item in semantic_mirrors),
                "keptUserDisplayRows": sum(len(item.get("keptUser") or []) for item in semantic_mirrors),
                "requestedDisplayBlockAliases": sum(item["requestedBlockAlias"] for item in semantic_mirrors),
                "writtenDisplayBlockAliases": sum(item.get("blockAliasWritten") is True for item in semantic_mirrors),
                "keptUserDisplayBlockAliases": sum(item.get("blockAliasKeptUser") is True for item in semantic_mirrors),
            }
            for item in published:
                row_rejections = sum(
                    rejected.get("path") != str(item.get("block") or "")
                    for rejected in item.get("rejected") or []
                )
                counts["unprocessedRows"] += max(
                    0,
                    item["requestedRowCount"]
                    - len(item.get("written") or [])
                    - len(item.get("keptUser") or [])
                    - row_rejections,
                )
            new_aliases_written = bool(counts["writtenRows"] or counts["writtenBlockAliases"] or counts["writtenSemanticFields"])
            applied = bool(new_aliases_written or counts["keptUserSemanticFields"]
                           or (binding_reviews and semantic_coverage["complete"]))
            partial = applied and (
                counts["writtenRows"] + counts["keptUserRows"] < counts["requestedRows"]
                or counts["writtenBlockAliases"] + counts["keptUserBlockAliases"] < counts["requestedBlockAliases"]
                or counts["writtenSemanticFields"] + counts["keptUserSemanticFields"] < counts["requestedSemanticFields"]
                or counts["writtenDisplaySemanticFields"] + counts["keptUserDisplaySemanticFields"] < counts["requestedDisplaySemanticFields"]
                or bool(semantic_mirror_skipped)
                or bool(alias_mirror_skipped)
                or counts["writtenDisplayRows"] + counts["keptUserDisplayRows"] < counts["requestedDisplayRows"]
                or counts["writtenDisplayBlockAliases"] + counts["keptUserDisplayBlockAliases"] < counts["requestedDisplayBlockAliases"]
            )
            return {
                "schema": "replaylab-cbuffer-alias-publication/v1",
                "schemaVersion": 1,
                "published": published,
                "skipped": skipped,
                "semanticMirrors": semantic_mirrors,
                "semanticMirrorSkipped": semantic_mirror_skipped,
                "aliasMirrorSkipped": alias_mirror_skipped,
                "semanticOriginalUnavailable": semantic_original_unavailable,
                "counts": counts,
                "bindingCoverage": semantic_coverage,
                "usageReviewSkipped": usage_review_skipped,
                "applied": applied,
                "partial": partial,
                "physicalBinding": copy.deepcopy(binding),
                "compiledLayoutEvidence": copy.deepcopy(compiled_layout),
                "namingEvidence": copy.deepcopy(clean_naming_evidence),
                "semanticNameVerification": "agent-provenance-only",
                "semanticHistoryRetention": copy.deepcopy(retention),
                "inputFiles": input_files,
                "semanticSourceSha256": semantic_source_sha,
                "sourceDependenciesDigest": source_dependencies_digest,
                "activeDisplayShaderRawSha256": str(identity.get("activeDisplayShaderRawSha256") or identity.get("rawSha256") or ""),
                "activeReplacementShaderRawSha256": active_replacement_sha,
                "operationId": resolved_operation_id,
                "requestSha256": request_sha,
                "operationLedgerPath": str(operation_ledger_path),
                "facts": {
                    "userAliasesPreserved": True,
                    "newAliasesWritten": new_aliases_written,
                    "hostWorkflowAuthorizationRequired": False,
                    "placeholderAliasesShaderScoped": True,
                    "semanticViewsShaderScoped": True,
                    "semanticViewsChangePhysicalLayout": False,
                    "activeSemanticReflectionIndependentlyVerified": bool(semantic_active_primary),
                    "receiptRows": (
                        "published/skipped and per-block written/keptUser/rejected"
                    ),
                },
                "acceptance": {
                    "noUnprocessedRows": counts["unprocessedRows"] == 0,
                    "noSkippedRows": counts["skippedRows"] == 0,
                    "requestedBlockAliasesAccountedFor": (
                        counts["writtenBlockAliases"]
                        + counts["keptUserBlockAliases"]
                        >= counts["requestedBlockAliases"]
                    ),
                    "requestedSemanticFieldsAccountedFor": (
                        counts["writtenSemanticFields"] + counts["keptUserSemanticFields"]
                        == counts["requestedSemanticFields"]
                    ),
                    "currentDisplaySemanticFieldsAccountedFor": (
                        not semantic_mirror_skipped
                        and counts["writtenDisplaySemanticFields"] + counts["keptUserDisplaySemanticFields"]
                        == counts["requestedDisplaySemanticFields"]
                    ),
                    "currentDisplayAliasesAccountedFor": (
                        not alias_mirror_skipped
                        and counts["writtenDisplayRows"] + counts["keptUserDisplayRows"] == counts["requestedDisplayRows"]
                        and counts["writtenDisplayBlockAliases"] + counts["keptUserDisplayBlockAliases"] == counts["requestedDisplayBlockAliases"]
                    ),
                },
            }

        def _runner() -> dict[str, Any]:
            # Every connection mode reaches this Host-owned publication path.
            # Observe current owners at execution time, not when the Agent began
            # its analysis. Old task receipts are not active naming references.
            effective_publications = copy.deepcopy(publications)
            if any(item.get("semanticFields") or "semanticUsageReview" in item for item in publications):
                from .shader_workspace.alias_retention import collect_alias_retention
                try:
                    project_replay = (_active_project_service().replay_service()
                                      if cbuffer_aliases.project_store_root() is not None else None)
                    observed = collect_alias_retention(
                        root,
                        captured_shader_sha256=str(identity.get("rawSha256") or ""),
                        stage=str(identity.get("stage") or ""),
                        current_shader_sha256s=[active_replacement_sha, display_sha, *[
                            str((item.get("shaderScope") or {}).get("shaderRawSha256") or "")
                            for item in publications]],
                        capture_id=str(identity.get("captureId") or ""),
                        capture_session_id=str(identity.get("captureSessionId") or ""),
                        project_service=project_replay,
                        replacement_state_loader=lambda: ipc.call(
                            "get_shared_shader_replacements", {
                                "expected_capture_id": identity.get("captureId"),
                                "expected_capture_session_id": identity.get("captureSessionId"),
                                "include_all_capture_catalogs": True,
                            }, timeout=30.0),
                    )
                except Exception as exc:
                    observed = {"complete": False, "diagnostic": str(exc)[:400]}
                retention.update(observed, requested=True)
                if observed.get("complete"):
                    for item in effective_publications:
                        if item.get("semanticFields") or "semanticUsageReview" in item:
                            item["semanticRetention"] = {
                                "protectedShaderRawSha256": observed["protectedShaderRawSha256"],
                                "keepPrevious": 0,
                            }
            payload = publish_cbuffer_alias_transaction(
                workspace_root=root,
                operation_id=resolved_operation_id,
                request_sha256=request_sha,
                caller_request_sha256=caller_request_sha,
                compatible_caller_request_sha256=compatible_caller_request_shas,
                publications=effective_publications,
                build_result=_build_payload,
            )
            # This compatibility snapshot is not publication authority: the
            # per-operation ledger above is. Recreate it on an idempotent replay
            # if a crash occurred after commit but before this best-effort write.
            try:
                capture = identity if isinstance(identity, Mapping) else {}
                receipt_path = root / "ai" / "cbuffer-name-publication.json"
                atomic_write_shader_json(receipt_path, {
                    "schema": "replaylab-cbuffer-name-publication-receipt/v1",
                    "schemaVersion": 1,
                    "workspaceId": binding.get("workspaceId"),
                    "captureId": binding.get("captureId"),
                    "captureSessionId": binding.get(
                        "captureSessionId", str(capture.get("captureSessionId") or "")
                    ),
                    "eventId": binding.get("eventId"),
                    "stage": binding.get("stage"),
                    "shaderResourceId": binding.get("shaderResourceId"),
                    "shaderRawSha256": binding.get("shaderRawSha256"),
                    "physicalBindingSha256": binding.get("bindingSha256"),
                    "compiledLayoutReceiptSha256": compiled_layout.get(
                        "receiptSha256"
                    ),
                    "namingEvidenceSha256": naming_evidence_sha,
                    "inputFiles": payload.get("inputFiles") or [],
                    "semanticSourceSha256": payload.get("semanticSourceSha256") or semantic_source_sha,
                    "sourceDependenciesDigest": payload.get("sourceDependenciesDigest", source_dependencies_digest),
                    "activeDisplayShaderRawSha256": payload.get("activeDisplayShaderRawSha256") or "",
                    "activeReplacementShaderRawSha256": payload.get("activeReplacementShaderRawSha256") or "",
                    "acceptance": payload.get("acceptance") or {},
                    "operationId": resolved_operation_id,
                    "requestSha256": request_sha,
                    "counts": payload.get("counts") or {},
                    "bindingCoverage": payload.get("bindingCoverage") or {},
                    "semanticOriginalUnavailable": payload.get("semanticOriginalUnavailable") or [],
                    "semanticViewStorePaths": [{
                        "path": item.get("path"), "bind": item.get("bind"), "space": item.get("space"),
                        "layoutSha256": item.get("layoutSha256"),
                        "semanticBindingBasis": item.get("semanticBindingBasis"),
                        "shaderRawSha256": ((item.get("semanticView") or {}).get("shaderScope") or {}).get("shaderRawSha256"),
                    } for item in (payload.get("published") or []) + (payload.get("semanticMirrors") or [])
                       if item.get("semanticView")],
                    "applied": payload.get("applied") is True,
                    "partial": payload.get("partial") is True,
                    "recordedAt": datetime.now(timezone.utc).isoformat(),
                })
                payload["receiptPersistence"] = {
                    "persisted": True,
                    "path": str(receipt_path),
                    "operationLedgerPath": str(operation_ledger_path),
                }
                # Naming changes presentation metadata only. Its target is
                # the reflection just verified by this publication, not a
                # newer compiled candidate that has never been applied.
                from .shader_semantic_delivery import save_display_identity
                save_display_identity(str(root), {
                    "status": "current", "originalRawSha256": binding.get("shaderRawSha256"),
                    "activeDisplayShaderRawSha256": payload.get("activeDisplayShaderRawSha256") or "",
                    "activeReplacementShaderRawSha256": payload.get("activeReplacementShaderRawSha256") or "",
                    "captureSessionId": binding.get("captureSessionId", str(capture.get("captureSessionId") or "")),
                    "stage": binding.get("stage"), "entryPoint": workspace_status.get("entryPoint") or ""})
            except Exception as receipt_error:
                payload["receiptPersistence"] = {
                    "persisted": False,
                    "operationLedgerPath": str(operation_ledger_path),
                    "error": str(receipt_error)[:800],
                }
            return payload

        target_id = "cbuffer-aliases:%s" % (
            binding.get("workspaceId") or hashlib.sha256(
                canonical_workspace_identity(root).encode("utf-8")
            ).hexdigest()[:16]
        )
        job = start_shader_mutation_job(
            tool="publish_cbuffer_aliases",
            workspace_path=str(root),
            organization_id=target_id,
            request_sha256=request_sha,
            operation_id=resolved_operation_id,
            runner=_runner,
            retry_failed=True,
        )
        waited = max(0.0, min(float(wait_seconds or 0.0), 5.0))
        if waited and job.get("status") not in {"busy", "done", "failed"}:
            job = await asyncio.to_thread(
                wait_for_shader_mutation_job,
                str(job.get("operationId") or ""),
                waited,
            ) or job
        return _ok(_shader_mutation_tool_result(job))
    except Exception as error:
        return _shader_err(error, "publish-cbuffer-aliases")


@mcp.tool()
def submit_shader_asset_resolution(
    event_id: int,
    stage: str,
    asset_id: str,
    confidence: float,
    rationale: str,
    reject: bool = False,
    facets_json: str = "",
    workspace_path: str = "",
    links_json: str = "",
    final_no_supported_match: bool = False,
) -> str:
    """Remember which unpacked asset a captured shader comes from (or does not).

    ``reject=true`` rejects only the named candidate. The Agent may record its
    bounded conclusion that no supported match remains with ``asset_id=""``,
    ``reject=false`` and ``final_no_supported_match=true``; ``rationale`` must
    state the evidence, and ``links_json.searchCoverage`` may preserve what was
    searched. This is reusable investigation memory only. It never builds a
    full-root content manifest, HMAC, authorization, or publication permission.

    ``links_json`` is the index entry for next time: how this draw's pieces
    map onto the asset, e.g. {"textures": {"t0": "T_Hat_D", "t1": "T_Hat_N"},
    "cbuffers": {"cb1": {"name": "MaterialParams", "members": {"16": "Roughness"}}},
    "mesh": "SK_Hat", "shaderFunctions": {"MainPS": "M_Hat::PixelShader"}}. It
    is stored with the decision (per game build, shader hash and shape) and
    mirrored into the workspace, and comes back in ``memory`` on the next
    retrieval so renaming does not start from zero.
    ``links_json.materialHypotheses`` may retain Agent explanations as an array
    of parameter/sourceSymbol/suggestedName/role/reason/evidence objects. A
    previously parsed materialSemanticContext is reused locally, including
    unmatched parameter names and values; no repeated material read is required.

    Records the decision for this game build keyed by the shader's raw hash
    and by its structural shape, so later captures and same-shape shaders
    reuse it instead of searching. ``reject=true`` stores a negative entry
    for one wrong candidate only. Submit more than one positive when several assets
    explain the shader (instance + parent material + shared function), each
    with its own confidence; ``facets_json`` may carry per-facet confidences
    (e.g. {"textures":0.9,"parameters":0.6}) so later use knows which part
    of the match to trust. Decisions are evidence-labelled memory, never ABI
    authority: captured reflection still decides every physical fact. Passing the
    shader's ``workspace_path`` also mirrors the decision into that workspace, so a
    later or interrupted conversation reads it without repeating retrieval.
    """

    try:
        if type(final_no_supported_match) is not bool:
            raise ValueError("final_no_supported_match must be a boolean")
        if isinstance(confidence, bool) or not isinstance(confidence, (int, float)) or not 0.0 <= float(confidence) <= 1.0:
            raise ValueError("confidence must be a number between 0 and 1")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ValueError("rationale must state the evidence behind the decision")
        facets: dict[str, Any] = {}
        if facets_json:
            parsed = json.loads(facets_json)
            if not isinstance(parsed, dict) or len(parsed) > 32:
                raise ValueError("facets_json must be a small JSON object")
            for key, value in parsed.items():
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not 0.0 <= float(value) <= 1.0:
                    raise ValueError("facet %r confidence must be between 0 and 1" % str(key)[:32])
                facets[str(key)[:64]] = float(value)
        links: dict[str, Any] = {}
        if links_json:
            if len(links_json) > 32768:
                raise ValueError("links_json exceeds its bound")
            parsed_links = json.loads(links_json)
            if not isinstance(parsed_links, dict):
                raise ValueError("links_json must be a JSON object")
            links = parsed_links
        if final_no_supported_match:
            if str(asset_id or "").strip() or reject:
                raise ValueError(
                    "final_no_supported_match requires an empty asset_id and reject=false"
                )
            unused_service, active_status, asset_root, database_path = (
                _active_asset_catalog_context(require_catalog=True)
            )
            catalog = AssetCatalogService(database_path)
            catalog_status = catalog.status()
            raw_coverage = links.get("searchCoverage")
            search_coverage = (
                copy.deepcopy(dict(raw_coverage))
                if isinstance(raw_coverage, Mapping) else {}
            )
            search_coverage.setdefault(
                "catalogComplete", catalog_status.get("complete") is True
            )
            if type(catalog_status.get("assetCount")) is int:
                search_coverage.setdefault("catalogAssetCount", catalog_status["assetCount"])
            identity, features = _shader_asset_capture_features(
                int(event_id), stage, pass_hint="", mesh_hint="", extra_tokens=[]
            )
            resolution_store = shader_asset_retrieval.ShaderAssetResolutionStore(
                database_path.parent / SHADER_ASSET_RESOLUTIONS_FILENAME
            )
            game_key = _shader_asset_game_key(active_status, asset_root)
            negative_evidence = {
                "finalNoSupportedMatch": True,
                "decisionKind": "agent-no-supported-match",
                "searchCoverage": search_coverage,
                "shaderIdentity": identity,
            }
            negative_row = {
                "gameKey": game_key,
                "shaderRawSha256": identity["rawSha256"],
                "structuralKey": features["structuralKey"],
                "stage": identity["stage"],
                "entryPoint": identity["entryPoint"],
                "assetRelativePath": "__NO_SUPPORTED_MATCH__",
                "assetContentSha256": "",
                "assetClass": "no-supported-match",
                "catalogSha256": str(catalog_status.get("catalogSha256") or ""),
                "negative": True,
                "confidence": float(confidence),
                "decidedBy": "ai",
                "rationale": rationale[:2000],
            }
            stored = resolution_store.record(
                game_key=game_key,
                shader_raw_sha256=identity["rawSha256"],
                structural=features["structuralKey"],
                stage=identity["stage"],
                entry_point=identity["entryPoint"],
                asset_relative_path="__NO_SUPPORTED_MATCH__",
                asset_content_sha256="",
                asset_class="no-supported-match",
                catalog_sha256=negative_row["catalogSha256"],
                negative=True,
                confidence=float(confidence),
                decided_by="ai",
                rationale=rationale[:2000],
                evidence=negative_evidence,
            )
            record = {
                "negative": True,
                "finalNoSupportedMatch": True,
                "resolutionId": stored["resolutionId"],
                "confidence": float(confidence),
                "decidedBy": "ai",
                "rationale": rationale[:1000],
                "searchCoverage": search_coverage,
            }
            receipt = {
                "schema": "replaylab-shader-asset-no-supported-match-receipt/v1",
                "schemaVersion": 1,
                "identity": identity,
                "resolution": record,
                "semanticAuthority": "agent",
                "hostWorkflowAuthorizationRequired": False,
                "publishingAuthority": False,
                "applied": False,
            }
            workspace = str(workspace_path or "").strip()
            if workspace and Path(workspace).is_dir():
                written = _write_workspace_asset_resolution(
                    workspace,
                    {
                        "noSupportedMatch": record,
                        "resolvedAssets": [],
                        "decidedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                        "shaderRawSha256": identity["rawSha256"],
                        "stage": identity["stage"],
                        "eventId": int(event_id),
                    },
                )
                if written:
                    receipt["workspaceRecordPath"] = written
            return _ok(receipt)
        service, status, asset_root, database_path = _active_asset_catalog_context(require_catalog=True)
        identity, features = _shader_asset_capture_features(int(event_id), stage, pass_hint="", mesh_hint="", extra_tokens=[])
        catalog = AssetCatalogService(database_path)
        found = catalog.query(asset_ids=[str(asset_id)], limit=1, include_relationships=True)
        assets = found.get("assets", [])
        if not assets:
            raise ValueError("asset_id is not present in the active asset catalog")
        asset = assets[0]
        if not str(asset.get("contentSha256") or "").strip():
            try:
                hydrate_paths = [str(asset.get("relativePath") or "")]
                relative = str(asset.get("relativePath") or "")
                if PurePosixPath(relative).suffix.lower() in {".uasset", ".umap"}:
                    hydrate_paths.append(
                        PurePosixPath(relative).with_suffix(".uexp").as_posix()
                    )
                catalog.hydrate(
                    asset_root,
                    [path for path in hydrate_paths if path],
                )
                found = catalog.query(
                    asset_ids=[str(asset_id)], limit=1, include_relationships=True
                )
                assets = found.get("assets", [])
                if not assets:
                    raise ValueError(
                        "asset_id disappeared from the catalog while content-hashing"
                    )
                asset = assets[0]
            except Exception as error:
                return _ok({
                    "schema": "replaylab-shader-asset-resolution-receipt/v1",
                    "schemaVersion": 1,
                    "applied": False,
                    "authorized": False,
                    "hostWorkflowAuthorizationRequired": False,
                    "publishingAuthority": False,
                    "authorizationBlocked": True,
                    "authorizationStatus": _asset_authorization_blocked(
                        code="submit-hydrate-failed",
                        reason=str(error)[:400],
                        relative_path=str(asset.get("relativePath") or ""),
                    ),
                })
        try:
            asset_binding = _asset_resolution_evidence_binding(
                catalog, asset_root, asset
            )
        except Exception as error:
            return _ok({
                "schema": "replaylab-shader-asset-resolution-receipt/v1",
                "schemaVersion": 1,
                "applied": False,
                "authorized": False,
                "hostWorkflowAuthorizationRequired": False,
                "publishingAuthority": False,
                "authorizationBlocked": True,
                "authorizationStatus": _asset_authorization_blocked(
                    code="submit-evidence-binding-failed",
                    reason=str(error)[:400],
                    relative_path=str(asset.get("relativePath") or ""),
                ),
            })
        positive_grounding = None
        if not reject:
            catalog_content = str(asset_binding.get("assetContentSha256") or "").strip()
            if not catalog_content:
                return _ok({
                    "schema": "replaylab-shader-asset-resolution-receipt/v1",
                    "schemaVersion": 1,
                    "applied": False,
                    "authorized": False,
                    "authorizationBlocked": True,
                    "authorizationStatus": _asset_authorization_blocked(
                        code="submit-missing-catalog-content-hash",
                        reason="selected catalog asset still has no contentSha256",
                        relative_path=str(asset.get("relativePath") or ""),
                    ),
                })
            sealed_catalog_proof = _seal_asset_content_proof({
                "assetId": str(asset["assetId"]),
                "relativePath": str(asset["relativePath"]),
                "tool": "submit_shader_asset_resolution",
                "receiptSha256": _canonical_json_sha256({
                    "assetId": str(asset["assetId"]),
                    "relativePath": str(asset["relativePath"]),
                    "assetBinding": asset_binding,
                    "source": "catalog-match",
                }, "catalog-match asset content receipt"),
                "assetBinding": asset_binding,
            })
            positive_grounding = {
                "candidateAssetId": str(asset["assetId"]),
                "assetContentProof": sealed_catalog_proof,
                "assetBinding": asset_binding,
                "source": "catalog-match",
            }
        store = shader_asset_retrieval.ShaderAssetResolutionStore(
            database_path.parent / SHADER_ASSET_RESOLUTIONS_FILENAME)
        game_key = _shader_asset_game_key(status, asset_root)
        asset_class = str(
            (asset.get("metadata") or {}).get("className", "") or ""
        )
        decision_evidence = {
            "boundTextureNames": features["boundTextureNames"],
            "eventId": int(event_id),
            "facets": facets,
            "links": links,
            "assetBinding": asset_binding,
            "readerProof": positive_grounding or {},
            "shaderIdentity": identity,
        }
        semantic_context = None
        if not reject and workspace_path:
            remembered = _read_workspace_asset_resolution(workspace_path) or {}
            previous_context = remembered.get("materialSemanticContext")
            if isinstance(previous_context, Mapping):
                from .shader_asset_semantics import assess_material_semantic_context, with_agent_hypotheses

                try:
                    unused_service, unused_root, manifest = _local_shader_asset_project()
                    previous_binding = previous_context.get("binding") or {}
                    assessed = assess_material_semantic_context(
                        previous_context, identity=identity,
                        project_id=str(manifest.get("workspaceId") or ""),
                        asset_binding=({**asset_binding, "assetRelativePath": str(asset["relativePath"])}
                                       if previous_binding.get("assetContentSha256") else None),
                        asset_root=str(asset_root))
                    old_path = str((previous_context.get("binding") or {}).get("assetRelativePath") or "")
                    if (assessed["reuse"]["scope"] != "stale"
                            and old_path == str(asset["relativePath"])):
                        # Keep the original parameter-document provenance. A new
                        # association is not evidence that historical values were
                        # reread from the current asset bytes.
                        semantic_context = with_agent_hypotheses(
                            assessed, links.get("materialHypotheses") or [])
                        decision_evidence["materialSemanticContext"] = semantic_context
                except (OSError, ValueError, RuntimeError):
                    # Saving an asset association must not discard it because
                    # optional older semantic vocabulary is unavailable.
                    semantic_context = None
        decision_row = {
            "gameKey": game_key,
            "shaderRawSha256": identity["rawSha256"],
            "structuralKey": features["structuralKey"],
            "stage": identity["stage"],
            "entryPoint": identity["entryPoint"],
            "assetRelativePath": str(asset["relativePath"]),
            "assetContentSha256": str(asset_binding["assetContentSha256"]),
            "assetClass": asset_class,
            "catalogSha256": str(asset_binding["catalogSha256"]),
            "negative": bool(reject),
            "confidence": float(confidence),
            "decidedBy": "ai",
            "rationale": rationale[:2000],
        }
        decision_evidence = _seal_resolution_evidence(
            decision_row, decision_evidence
        )
        record = store.record(
            game_key=game_key,
            shader_raw_sha256=identity["rawSha256"],
            structural=features["structuralKey"],
            stage=identity["stage"],
            entry_point=identity["entryPoint"],
            asset_relative_path=str(asset["relativePath"]),
            asset_content_sha256=str(asset_binding["assetContentSha256"]),
            asset_class=asset_class,
            catalog_sha256=str(asset_binding["catalogSha256"]),
            negative=bool(reject),
            confidence=float(confidence),
            decided_by="ai",
            rationale=rationale[:2000],
            evidence=decision_evidence,
        )
        receipt = {
            "schema": "replaylab-shader-asset-resolution-receipt/v1",
            "schemaVersion": 1,
            "identity": identity,
            "resolution": record,
            "document": shader_asset_retrieval._material_document(catalog, asset),
            "assetBinding": asset_binding,
            "applied": False,
        }
        # Mirror the decision next to the shader so a later conversation reads it
        # instead of repeating retrieval.
        workspace = str(workspace_path or "").strip()
        if workspace and Path(workspace).is_dir():
            key = "rejected" if reject else "resolvedAssets"
            existing_resolution = _read_workspace_asset_resolution(workspace) or {}
            existing_matches = (
                str(existing_resolution.get("shaderRawSha256") or "").strip().lower()
                == str(identity["rawSha256"]).strip().lower()
                and normalize_stage(existing_resolution.get("stage"))
                == normalize_stage(identity["stage"])
            )
            try:
                existing_event = int(existing_resolution.get("eventId") or 0)
            except (TypeError, ValueError):
                existing_event = 0
            existing_matches = existing_matches and existing_event == int(event_id)
            old_binding = existing_resolution.get("assetBinding")
            existing_matches = existing_matches and isinstance(old_binding, Mapping) and (
                Path(str(old_binding.get("assetRoot") or "")).resolve()
                == Path(str(asset_binding["assetRoot"])).resolve()
                and str(old_binding.get("catalogSha256") or "").lower()
                == str(asset_binding["catalogSha256"]).lower()
            )
            record_list = list(
                existing_resolution.get(key) or []
            ) if existing_matches else []
            entry = {
                "assetRelativePath": str(asset["relativePath"]),
                "assetClass": str((asset.get("metadata") or {}).get("className", "") or ""),
                "confidence": float(confidence),
                "rationale": rationale[:1000],
                "eventId": int(event_id),
                "stage": identity["stage"],
                "links": links,
                "assetId": str(asset["assetId"]),
                "assetContentSha256": str(asset_binding["assetContentSha256"]),
                "assetEvidenceSha256": str(asset_binding["assetEvidenceSha256"]),
                "resolutionId": int(record["resolutionId"]),
            }
            record_list = [item for item in record_list
                           if (item if isinstance(item, str) else
                               (item.get("assetRelativePath") or item.get("assetPath") or item.get("relativePath"))
                               if isinstance(item, Mapping) else None) != entry["assetRelativePath"]][:31]
            record_list.append(entry)
            written = _write_workspace_asset_resolution(
                workspace,
                {key: record_list,
                 **({"noSupportedMatch": None} if not reject else {}),
                 "decidedAt": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                 "shaderRawSha256": identity["rawSha256"],
                 "stage": identity["stage"],
                 "eventId": int(event_id),
                 "captureId": identity.get("captureId", ""),
                 **({"materialSemanticContext": semantic_context} if not reject else {}),
                 "assetBinding": asset_binding},
            )
            if written:
                receipt["workspaceRecordPath"] = written
                if semantic_context:
                    from .shader_asset_semantics import semantic_context_summary

                    receipt["materialSemanticContextPath"] = written
                    receipt["materialSemanticContextSummary"] = semantic_context_summary(semantic_context, written)
        if not reject:
            try:
                released = ipc.call(
                    "release_texture_fingerprint_cache", {}, timeout=30.0
                )
                if isinstance(released, Mapping):
                    receipt["textureFingerprintRelease"] = dict(released)
            except Exception as release_error:
                receipt["textureFingerprintRelease"] = {
                    "applied": False,
                    "reason": str(release_error)[:400],
                }
        return _ok(receipt)
    except Exception as error:
        return _active_project_error("submit-shader-asset-resolution", error)


