@mcp.tool()
async def import_resource_export_to_unity(operation_id: str, project_path: str, editor_path: str = "",
                                          asset_only: bool = False) -> str:
    """Import an existing finalized Bread draw export to Unity URP in a background job.

    Reuses the exact managed package (no capture/extractor rerun), verifies hashes,
    installs/connects the project as needed, imports mesh/textures/material/converted
    Shader, then returns a job ID to poll. Transfer-spec texture targetProperty,
    explicit sampler settings and material CBuffer target/value mappings are used.
    System matrices are supplied by the Unity Shader. A captured Shader is never
    silently substituted with URP/Lit: that requires strategy target-native-pbr.
    Missing mappings become receipt gaps; they do not discard the exported evidence.
    Functional restoration is the default. Managed begin/bind/check/render/review
    tools are optional evidence aids; equivalent direct project operations and
    real render observations may be used instead. Import alone is not proof of fidelity.
    """
    try:
        from .unity_integration import shared_service
        from .unity_restore import prepare_unity_import
        export = await asyncio.to_thread(_RESOURCE_EXPORT_MANAGER.status, operation_id)
        if export.get("status") != "finalized" or not export.get("packagePath"):
            return _ok_compact({"status": "export-not-finalized", "operationId": operation_id,
                                "exportStatus": export.get("status"), "nextTool": "get_resource_export_status"})
        prepared = await asyncio.to_thread(prepare_unity_import, export["packagePath"], project_path)
        job = await shared_service().start_import(project_path, prepared["requestPath"], editor_path or None)
        return _ok_compact({**job, "importRequest": prepared, "operationId": operation_id,
                            "projectPath": str(Path(project_path).resolve()),
                            "functionalRestorationRequired": not asset_only,
                            "nextTool": "begin_unity_restoration" if not asset_only else "get_unity_integration_job"})
    except Exception as error:
        return _err(error)



